WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[29969] = { title = "Broken Earthen Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.You will receive:", objectives = "Repair the broken figurine using your skill and materials." }
WordHunterWoW_QuestEN[29970] = { title = "Broken Earthen Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.You will receive:", objectives = "Repair the broken figurine using your skill and materials." }
WordHunterWoW_QuestEN[29971] = { title = "The Scouts Return", description = "Hey, while you were out our scouts came back. And get this, they found some Alliance kid.\n\nYou should probably go debrief them.", objectives = "Speak with Shokia in Grookin Hill.", completion = "We may have a problem." }
WordHunterWoW_QuestEN[29981] = { title = "Stemming the Swarm", description = "I'm not from here. I've never even BEEN here before today. But even I can tell you that something's wrong.\n\nThat wall over there was built to keep mantid off of pandaren lands.  Now, the mantid are sending their winged scouts over the top, as if the wall wasn't even there!\n\nThe only reason those spindly scouts aren't dying is because they're attacking farmers, not soldiers. They wouldn't stand a chance against someone like you.", objectives = "Slay 14 Ik'thik mantid in Stoneplow.", progress = "If the flying mantid troops have always been able to fly over, why haven't they before now?", completion = "Lin asked you to help us out? Rather presumptive of her.\n\nStill, we are short-manned. We won't turn down your help... or the girl's. You have our thanks, <class>." }
WordHunterWoW_QuestEN[29982] = { title = "Evacuation Orders", description = "A few farmers remain in the fields... some perilously close to the crumbling wall. I don't want any farmers pretending to be heroes. We will take care of this mantid swarm, and then they can return to their homes.\n\nMy Shado-Pan are too busy defending this town to organize evacuations. You want to prove yourself useful? Get those farmers out of harm's way.", objectives = "Evacuate the Blacksoil Family, the Spadepaw Family, the Greentill Family, and the Marlfur Family.", progress = "Once these mantid are slain, we can get to work repairing the wall and restoring the town to its normal state.", completion = "A few stubborn ranchers want to make my job harder?\n\n<The Watch Commander sighs.>\n\nFine. I will rob no pandaren of his right to defend his land." }
WordHunterWoW_QuestEN[29983] = { title = "The Hidden Master", description = "We should be able to handle the defense of Stoneplow from here on out.\n\n<The Watch Commander motions towards Lin Tenderpaw.>\n\nLin here is searching for someone she calls \"The Hidden Master\". I believe I know who she's talking about, and I have a clue for you.\n\nGo north.", objectives = "Find Master Bruised Paw in the Valley of the Four Winds.", completion = "You seek training?\n\n<The pandaren studies your physique for several seconds, without speaking.>\n\nAlright." }
WordHunterWoW_QuestEN[29984] = { title = "Unyielding Fists: Trial of Bamboo", description = "We will start with a test: The Trial of Bamboo.\n\nYour friend Lin failed this test.\n\nFollow me, and listen carefully to my instructions.", objectives = "Speak with Master Bruised Paw, then successfully strike the Stack of Bamboo Reeds 3 times.", progress = "If you cannot pass this test, then there is probably no reason to continue our training.", completion = "You show promise, <name>. We will continue.\n\nIt is now time for your first round of training." }
WordHunterWoW_QuestEN[29985] = { title = "They Will Be Mist", description = "The mist in this forest is a constant nuisance - one which I'm glad to hand off to trainees like you. Strange creatures lurk in the mist between these trees, and they must constantly be pushed back.\n\nConsider this part of your training.", objectives = "Slay 12 Mist Incarnations.", progress = "Living outside of society has its advantages. I can focus all my energies on training, without being shackled to the societal conventions of modesty, politics, and basic personal hygiene. Here in the woods, I am free to be myself.", completion = "You follow directions well, <name>." }
WordHunterWoW_QuestEN[29986] = { title = "Fog Wards", description = "Trainee.\n\nSeveral wards surround us, hidden in the woods near my home. They are quite effective at dispersing the mist, but they require constant upkeep.\n\nYou will find one to the north, one to the west, and one to the south. Find these wards and light them.", objectives = "Light the Northern Fog Ward, the Western Fog Ward, and the Southern Fog Ward.", progress = "See if you can light one of the wards while one of the mist incarnations is nearby.", completion = "You honor your people, <name>." }
WordHunterWoW_QuestEN[29987] = { title = "Unyielding Fists: Trial of Wood", description = "You have progressed in your training, I think. Come with me, and we will attempt the Trial of Wood.", objectives = "Speak with Master Bruised Paw, then successfully strike the Stack of Wooden Blocks 4 times.", progress = "I'm prepared, <name>. Are you?", completion = "You have the gift of focus, <name>. Not many of my students make it this far." }
WordHunterWoW_QuestEN[29988] = { title = "A Taste For Eggs", description = "I can sense your anxiety, but you are not ready yet. Your training must continue before you perform the final test. As for your task... I need you to fetch me some eggs.\n\nYes, eggs. The marshland atop the hills to the east is home to a number of birds, all of which are generally peaceful in nature. You should have no trouble gathering enough eggs to last me several weeks.", objectives = "Obtain 10 Emperor Tern Eggs, 4 Whitefisher Crane Eggs, and 1 Hornbill Strider Egg.", progress = "How is your egg hunt going?", completion = "Now you know why I don't gather the eggs myself.\n\nShall we continue your training?" }
WordHunterWoW_QuestEN[29989] = { title = "Unyielding Fists: Trial of Stone", description = "You have accomplished much in the short time you have been here, {name}. I would not normally offer this test so soon... but I feel that you're ready.\n\nIt is time you attempted the Trial of Stone.", objectives = "Speak with Master Bruised Paw, then successfully strike the Stack of Stone Blocks 5 times.", progress = "This test will be trying. You will test the strength of your fists against the strength of stone. Steel yourself, <name>.\n\nNot literally, of course.\n\nUnless you normally wear steel gloves... in which case, you may literally steel yourself.", completion = "<Master Bruised Paw bows before you.>\n\nStone quivers and breaks beneath your fists. You have the power to move mountains, if you so desire.\n\nThere is nothing more I can teach you." }
WordHunterWoW_QuestEN[29990] = { title = "Training and Discipline", description = "I told myself that, if I ever made it here to the Hidden Master, I would learn everything I could from him. This is my chance, {name}. I'm not going to let it slip away.\n\nStill, I fear that Stoneplow needs us. I left early, before we were able to push the mantid scouts back. I'd feel better if you would check in with the Watch Commander for me.\n\nOh, and if you run into the others, maybe you should tell them where the Hidden Master is...", objectives = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds.", completion = "I'm glad to hear that Lin is well.\n\nOur defenses are holding, for now. The mantid continue to send their scouts over the wall, but they haven't gotten much farther than that." }
WordHunterWoW_QuestEN[29992] = { title = "Tenderpaw By Name, Tender Paw By Reputation", description = "I'd like to go tell Xiao, Kang, and the others that I've found the hidden master, but now he won't let me leave! He says I have to pass that test of bamboo first.\n\n<Lin whispers:> How'd you do that, by the way?\n\nIt looks like, for the time being, I'm stuck here practicing my punches against this rock. And my knuckles are about to cave in.\n\nIf you could gather some jademoon leaves, I could prepare an ointment and at least numb some of this pain.", objectives = "Gather 18 Jademoon Leaves.", progress = "Ow! Ow! Ow!", completion = "<Lin pauses for a moment to rub the leaves on her swollen paws.>\n\nThank you! I can prepare a proper ointment later, but this will do for now." }
WordHunterWoW_QuestEN[29993] = { title = "Find the Boy", description = "Have you seen my son, Lo? He was here a moment ago and I told him we were leaving today.\n\nI'm sure he's off trying to woo that young Syra Goldendraft. That is the very reason we need to leave!\n\nNo son of mine is going to run off with a Goldendraft!\n\nI'm going to search around here for them.\n\nI do keep catching those two sneaking off to the Arboretum. Any chance you could head out there and look for them?", objectives = "Speak with Inkmaster Wei.", completion = "You seek two lovers blind to the ambitions of their family names. They were here, seeking a way to hold to their path.\n\nSadly they did not find their answers among the trees or art." }
WordHunterWoW_QuestEN[29995] = { title = "Shrine of the Dawn", description = "The \"children\" you seek are not actually children but grown pandaren, despite what their elders might claim. Their love will not be held in check by the feuds of their families.\n\nYou will find both Syra and Lo at the Shrine of the Dawn, ever seeking an answer to their dilemma amongst the pandriarchs of old.", objectives = "Search the Shrine of the Dawn for Syra Goldendraft.", completion = "Oh stranger! Please tell me you can help us. They really hurt my Lo." }
WordHunterWoW_QuestEN[29997] = { title = "The Scryer's Dilemma", description = "Since you were so helpful at the mines, would you be willing to help us with a small problem here at the temple?\n\nWise Mari has been complaining recently of a disturbance in his temple.\n\nThe water elementals have gotten quite playful recently, and made off with his ceremonial staff.\n\nIf you could help him, I would be most grateful. I may even put in a word with the Jade Serpent for you.\n\nJust follow the path to the north.", objectives = "Kill Water Fiends to recover Wise Mari's Staff.", progress = "The pools are clouded. I will need my staff to calm the spirits and speak to the water.", completion = "I am but an old jinyu, and those pesky water sprites were impossible to catch. Thank you, <name>, for returning my staff to me." }
WordHunterWoW_QuestEN[29998] = { title = "The Librarian's Quandary", description = "Lorewalker Stonestep is in charge of the entire temple library. Lately, something has been troubling him and his work.\n\nWith thousands of ancient tomes to be transcribed, I can't afford to have him distracted.\n\nWould you follow the path south to the library and see what ails him?", objectives = "Speak to Lorewalker Stonestep in the temple library.", completion = "The Elder Sage Rain-Zhu sent you?\n\nVery well. You shall help me." }
WordHunterWoW_QuestEN[29999] = { title = "The Rider's Bind", description = "Have you seen the young serpents in the training yard?\n\nThe littles ones tend to be mischievous, and some of them ran off to play before the training session.\n\nThe Mistress will get angry if she discovers they're missing.\n\nWould you go find them and bring them back to me? I don't want them to get into trouble.\n\nThey like to play out in the open, so look for them in courtyards and around the spires.", objectives = "Find 4 Playful Serpents.", progress = "I hope they didn't give you too much trouble.", completion = "You found them and brought them all back!\n\nThey've really taken a liking to you.\n\nThank you so much!" }
WordHunterWoW_QuestEN[30000] = { title = "The Jade Serpent", description = "You came to deliver a message to the Jade Serpent, right?\n\n<The little girl tilts her head up at you inquisitively.>\n\nI guess it's time you met her.", objectives = "Listen to the Jade Serpent.", completion = "Did you deliver your message?" }
WordHunterWoW_QuestEN[30001] = { title = "Moth-Ridden", description = "Moths have infested the library. Moths!\n\nAny librarian worth his letters knows that moths are the most dangerous threat to paper, second only to bookworms.\n\nAs it turns out, my assistants are a useless bunch of insect-fearing cowards.\n\nPlease, you MUST help me get rid of the moths immediately! The works of a thousand pandaren storytellers depend on you!", objectives = "Kill 8 Dappled Moths.", progress = "I can see the moths eating the pages from here!", completion = "Yes, yes, thank you! You've thinned out their numbers wonderfully." }
WordHunterWoW_QuestEN[30002] = { title = "Pages of History", description = "The worst possible thing has happened, {race}.\n\nWe. Have. Bookworms.\n\nThis is a critical situation. All bookworms in the library must be eradicated at once to prevent their spread.\n\nWe must squash this problem, literally! Please examine the infested books in the library and squash any bookworms that you find.", objectives = "Search through the library books for infestations, then squash 12 Bookworms.", progress = "My stomach is too fragile to handle the squashing of bugs. Is it done?", completion = "Oh, wonderful! I am so relieved that we managed to avert disaster.\n\nNo no, don't get too close, please. You still have some squashed bug bits on your shoes." }
WordHunterWoW_QuestEN[30003] = { title = "A Book By Its Cover", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30004] = { title = "Everything In Its Place", description = "You have helped us more than you can ever imagine, {name}.\n\nI do not know what I would do if our precious scrolls were ever to be lost.\n\nPlease return to the Elder Sage Rain-Zhu and tell him that the library is in order.", objectives = "Speak to Elder Sage Rain-Zhu at the Temple of the Jade Serpent in Jade Forest.", completion = "Lorewalker Stonestep is back to work?\n\nRemarkable. You were able to do what the last four priests I sent could not.\n\nI...I think my headache is disappearing." }
WordHunterWoW_QuestEN[30005] = { title = "Lighting Up the Sky", description = "Do you like fireworks, sir?\n\nI love them! In older times we would set them off to frighten away demons, but I just like them because they're pretty!\n\nI think there are still some old launchers lying around the temple.\n\nWould you go set off some big fireworks for me? It would make me so happy!", objectives = "Set off 8 fireworks.", completion = "Yay! I saw the fireworks all the way from over here!\n\nThank you so much, <name>." }
WordHunterWoW_QuestEN[30006] = { title = "The Darkness Around Us", description = "Despite our best efforts, the sha broke the seals around the main temple.\n\nIf we cannot hold them back here, their darkness will spread to the rest of the Jade Forest.\n\nWe need your help immediately. Kill any sha creatures that you see. They should not be difficult to find.", objectives = "Kill 15 sha invaders.", completion = "Thank you, <name>. Every sha slain is another turn in the tide." }
WordHunterWoW_QuestEN[30007] = { title = "Tracking Event: Completed Arrival Phase", description = "", objectives = "" }
WordHunterWoW_QuestEN[30009] = { title = "Muster of Fort Grookin", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30011] = { title = "A New Vision", description = "Please tell the Elder Sage Rain-Zhu that I will begin my work at once.", objectives = "Speak to Elder Sage Rain-Zhu near the courtyard in the Temple of the Jade Serpent in the Jade Forest.", completion = "Wonderful! Knowing that the scryer has returned to his meditations has lifted a great burden from my shoulders." }
WordHunterWoW_QuestEN[30015] = { title = "Dawn's Blossom", description = "Blood and Thunder! My axe hungers!\n\nWe won't return to Orgrimmar until every last Alliance is purged from this land.\n\nI will train these natives myself, if I have to. One way or another, this land will be made ready for Horde settlement.\n\nIn the meantime, their chief gave me this to pass on to you - a map and a message in some fancy script.\n\nDo what you must, but be quick about it.\n\nWar is brewing...", objectives = "Speak with Lorewalker Cho in Dawn's Blossom.\n\nSpeak to the flightmaster in Grookin Hill for passage.\n\nProvided item:", completion = "Greetings, <name>!\n\nWelcome to Dawn's Blossom, a home of my people.\n\nSadly I must depart. Alas, a Lorewalker's work is never done.\n\nMake yourself at home. Our people could surely make use of one with your talents." }
WordHunterWoW_QuestEN[30019] = { title = "A Breach in the Wall", description = "", objectives = "" }
WordHunterWoW_QuestEN[30020] = { title = "Running Out of Options", description = "", objectives = "" }
WordHunterWoW_QuestEN[30021] = { title = "Impenetrable", description = "", objectives = "" }
WordHunterWoW_QuestEN[30027] = { title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a staff from one of the weapon racks below, bring it to me, and show me that you know how to equip it properly.", objectives = "Retrieve and equip a Trainee's Staff.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use." }
WordHunterWoW_QuestEN[30028] = { title = "Grain Recovery", description = "Since you are heading south, can you try to recover some of the grain that these thieves made off with?\n\nWe saw birds and sprites running off with entire bags of our best bulk stock into the fields east and south of here.", objectives = "Bring 8 Sacks of Grain to Grainlord Kai.", progress = "Between birds and sprites we are never going to meet our quota to the Stormstout Brewery.", completion = "Why thank you very much stranger. This has not been a good day, but you certainly have helped us make it better.\n\nPlease, take this, you've earned it." }
WordHunterWoW_QuestEN[30029] = { title = "Wee Little Shenanigans", description = "So... we bought some cheap grains in bulk. It turned out the grain was infested with sprites.\n\nI HATE sprites. With their wee beady eyes and constant smiling.\n\nI would like to resolve this quietly. Can I buy your services to discreetly eliminate some of these grain thieves?", objectives = "Kill 8 Tricky Maizers.", progress = "Oh good, they didn't turn you into a frog yet. I saw them do that once you know.", completion = "Thank you for your help stranger! Hopefully we can deal with the rest on our own from here." }
WordHunterWoW_QuestEN[30030] = { title = "Out of Sprite", description = "Just to be clear, what happened was an accident. What I did, I did for INDUSTRY!\n\nThere was no way I could have known that a sprite invasion would happen at any time, or that one of them would try to eat my new \"Pan's Miracle Gro\" formula.\n\nNow not only do they have a big sprite leading them, but he's one angry beast.\n\nIf I pay you, will you take him out?", objectives = "Defeat Cornan the Barley Barbarian.", progress = "Oh why? Why did I have to tamper with the natural order of things? All I wanted was to make these grains grow faster and more numerous.", completion = "Now that that's over I have some ideas on how to make a new concoction. We'll see.\n\nThank you for your help. Here is your reward." }
WordHunterWoW_QuestEN[30031] = { title = "Taste Test", description = "As long as you're here, you might as well help me out. I'm feeling pretty darn unqualified for the task, seeing as I've never drank a drop of beer in my life.\n\nYou should try a little sample of each of their grains. Let's see if any of this stuff is sweet enough for Uncle Chen.", objectives = "Taste the Aged Grain, Light Grain, Fresh Grain, and Malted Grain.", progress = "None of this seems to taste sweet enough! What's the deal?", completion = "Huh. I guess none of that grain is going to work. Uncle Chen is pretty picky.\n\nMaybe the Grainlord knows where we can find something more... special." }
WordHunterWoW_QuestEN[30032] = { title = "The Quest for Better Barley", description = "Looking for sweet grain? My father once mentioned a malted cave barley that sounds about right.\n\nIf you are willing to brave the peril, there is an ancient cave at the base of the Winds' Edge south of here.\n\nThere is even an old lift my father made when he would travel into the jungle.\n\nIn the cave is a bush as old as my family. From that bush you can pluck a grain so sweet it will humble your senses.\n\nJust watch out for its guardians.", objectives = "Find the Malted Cave Barley at the base of the Winds' Edge.", progress = "That jungle sounds spooky.", completion = "Now THIS smells like the right stuff!" }
WordHunterWoW_QuestEN[30033] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a spellblade and a hand fan from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", objectives = "Retrieve and equip a Trainee's Spellblade and a Trainee's Hand Fan.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use." }
WordHunterWoW_QuestEN[30034] = { title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a crossbow from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", objectives = "Retrieve and equip a Trainee's Crossbow.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use." }
WordHunterWoW_QuestEN[30035] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a mace and a book of prayers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "Retrieve and equip a Trainee's Mace and a Trainee's Book of Prayers.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use." }
WordHunterWoW_QuestEN[30036] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a pair of daggers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "Retrieve and equip a pair of Trainee's Daggers.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use." }
WordHunterWoW_QuestEN[30037] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "Retrieve and equip a Trainee's Axe and a Trainee's Shield.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use." }
WordHunterWoW_QuestEN[30038] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "Retrieve and equip a Trainee's Axe and a Trainee's Shield.", progress = "Picking up your first weapon is also a symbolic gesture. Every <class> that leaves these training grounds must be ready to take up arms in defense of their fellow <race>.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use." }
WordHunterWoW_QuestEN[30039] = { title = "Much to Learn", description = "Freshly arrived for your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength and cunning to be a <class>? Or are you destined to a life working in the fields?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil." }
WordHunterWoW_QuestEN[30040] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the intellect and force of will necessary to be a <class>? Or are you destined to a life scribing in the dusty libraries?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil." }
WordHunterWoW_QuestEN[30041] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the compassion and the keen eye of a <class>? Or are you destined to a life tending to the livestock?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil." }
WordHunterWoW_QuestEN[30042] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the awareness and wisdom necessary to be a <class>? Or are you destined to a life scribing in the libraries?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil." }
WordHunterWoW_QuestEN[30043] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the deftness and cunning necessary to be a <class>? Or are you destined to live the life of a humble merchant?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil." }
WordHunterWoW_QuestEN[30044] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength of will to be a <class>? Or are you destined to a life of tending to the shrines?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil." }
WordHunterWoW_QuestEN[30045] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength and hardiness to be a <class>? Or are you destined to a life working the fields?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil." }
WordHunterWoW_QuestEN[30046] = { title = "Chen's Resolution", description = "You know what? I don't have to take this.\n\nI'll show that Uncle Gao what it means to be a real brewer. I'll brew the best beer he's ever tasted, with ingredients I've never even used before.\n\nI'm Chen Stormstout, and I'm the best brewer alive.", objectives = "Meet up with Chen Stormstout at Halfhill.", completion = "Let's make some beer." }
WordHunterWoW_QuestEN[30047] = { title = "The Chen Taste Test", description = "Uncle Chen is going to love this. Or... he might tell us to find something sweeter. He's kind of dumb like that.\n\nLet's get this grain back to him at Halfhill.", objectives = "Return to Chen Stormstout.", completion = "Ah! Now these are some beautifully malted grains. The two of you have a good eye and nose." }
WordHunterWoW_QuestEN[30048] = { title = "Li Li and the Grain", description = "I'll let you in on my brewing plan, {name}: I'm planning on making an Emperor Stout. Done right, it should be dark, roasty, and high in alcohol.\n\n<A frown appears on Chen's face.>\n\nI just realized... I never told my plans to Li Li. She'll have no idea what type of grain to bring back!\n\nCould you speak with her? I need her to bring back the sweetest malted grains she can find.", objectives = "Speak with Li Li at the Imperial Granary in the Valley of the Four Winds.", completion = "<name>? What are you doing here?\n\nSo, Uncle Chen wants sweet malts? No problem! Let's get to the taste testing." }
WordHunterWoW_QuestEN[30049] = { title = "Doesn't Hold Water", description = "Would you mind checking in on Mudmug? He may need some assistance bringing that water back.\n\nI'm sure he'll appreciate the help of a big, strong {class} like yourself to help him shoulder the load.", objectives = "Speak with Mudmug at the Gilded Fan in the Valley of the Four Winds.", completion = "<name>! You here to help out? That's mighty swell of you." }
WordHunterWoW_QuestEN[30050] = { title = "Gardener Fran and the Watering Can", description = "You want me to just GIVE you some hops? Pfshh! This is the third time today some little {race} like you has come up to me asking for food!\n\nYou want food? Then you'd better work!\n\n<She shoves a watering can into your hand.>\n\nNow go water my plants!", objectives = "Listen to Gardener Fran's orders and water 60 of her vegetables.\n\nYou can water plants while mounted.", progress = "Water my plants you lazy <class>!", completion = "Hmmph!\n\nNice farming." }
WordHunterWoW_QuestEN[30051] = { title = "The Great Water Hunt", description = "Look at it, {name}: the Gilded Fan. I heared lots of good things about the water they got here. Lots of bad things, too.\n\nNo sayin' what kind of water Chen's gonna be needin', so what say we make him a little sampler platter?\n\nCome on, let's get movin'. We'll go scoop up some water together.", objectives = "Guide Mudmug to Swirling Pools within the Gilded Fan, and help him collect 30 pawfuls of Gladewater.\n\nIf you become separated from Mudmug, you can find him next to the giant banana in the Gilded Fan.", progress = "That Stormstout feller says that he's the best brewer that ever was. Might be true, couldn't tell ya one way or the 'nother as of yet.", completion = "Lookee that, neighbor! That is quite the collection of water we got here. With magical water like this, I'm sure that Chen'll make a brew that really shines.\n\nOr possibly a brew that lands someone in the outhouse for a month. I guess we'll just have to wait and see." }
WordHunterWoW_QuestEN[30052] = { title = "Weed War", description = "You want some hops? I've got plenty in the shed out back. I'll gladly share some with you... if you'll help me weed my field.\n\nNow \"hop\" to it! Get it?", objectives = "Pull 100 weeds from Gai Lan's field.\n\nYou can pull weeds while mounted.", completion = "You weed like a champion." }
WordHunterWoW_QuestEN[30053] = { title = "Hop Hunting", description = "With Li Li fetching grain, and Mudmug handling our water, all we need is hops, and some good wood barrels. I'll handle the barrels... but I need you to gather the hops.\n\nI don't know much about the hops from this land, but I'm sure the nearby farmers have something worth brewing with. Go see what you can rustle up.", objectives = "Ask Gardener Fran, Gai Lan, and Den Mudclaw for hops." }
WordHunterWoW_QuestEN[30054] = { title = "Enough is Ookin' Enough", description = "Virmen, they bite too much.\n\nThey bite Mung-Mung's carrot. They bite Mung-Mung's pumpkin. Mung-Mung try to shoo them away, and the dookers bite Mung-Mung's tail and foot.\n\nEnough is ookin' enough.\n\nYou fight way better than Mung-Mung does. Bring back their bitey teeth. Then we see who does the biting.", objectives = "Obtain 100 Virmen Teeth.", progress = "You bring back those teeth, and maybe Mung-Mung will have some hops for you.", completion = "So many teeth! Maybe Mung-Mung will glue them together to make a tiny rake." }
WordHunterWoW_QuestEN[30055] = { title = "Stormstout's Hops", description = "All three farmers have delivered their hops to Halfhill. Perhaps you should check in with Chen to make sure that he received them.", objectives = "Return to Chen Stormstout in Halfhill.", completion = "Look at all these hops! This is quality stuff, too.\n\nWe're making headway, <name>. Soon we'll have all the ingredients to finally start brewing." }
WordHunterWoW_QuestEN[30056] = { title = "The Farmer's Daughter", description = "Brave {class}, you could not have arrived at a better time. My daughter is missing!\n\nI've got a suspicion that the virmen took her down into that stinking little warren of theirs. I'm too old to fight virmen, and my farmhand is already exhausted from fighting them off all morning.\n\nCould you look for her?", objectives = "Find Mina Mudclaw.", completion = "No... no... get back... I don't want...\n\nWait, you're not a carrot. You're not a virmen either. You're here to save me?" }
WordHunterWoW_QuestEN[30057] = { title = "Seeing Orange", description = "Those virmen... they make me do horrible, horrible, silly things. All involving carrots. I couldn't tell you how many carrots they threw at me.\n\nLet's not waste any more time. Get me out of here!", objectives = "Bring Mina Mudclaw back home to her father.", completion = "What's all this fuss about carrots? I don't get it." }
WordHunterWoW_QuestEN[30058] = { title = "Mothallus!", description = "The esteemed Journeyman Chu would appear to have created a monster. It is silken death with wings.\n\nMothallus.\n\nYou have already faced its brood. Now we ask that you help us face the creature itself.\n\nPlease, {class}, venture into the pit and rifle the bait. This will bring the beast to you.\n\nOur mothfighters will assist you as you need, though silk tends to stick to them more than most so you may need to help them, should they become overwhelmed.", objectives = "Bait and defeat Mothallus.", progress = "Have you vanquished the beast?", completion = "We are pursuing perfection in our art and in ourselves. Along the way many mistakes will be made.\n\nI'm sure by tomorrow this field will be swimming with more mistakes. Still, we thank you for your help." }
WordHunterWoW_QuestEN[30059] = { title = "The Moth Rebellion", description = "Oh... oh good! A {class}! Could you help me?\n\nI created a strain of vile monsters during my experiments to improve silk output.\n\nThe result was a full-scale moth rebellion. Can you use your {class}iness and destroy some of these mutants?", objectives = "Kill 6 Mutated Silkmoths and 8 Tiny Mutated Silkmoths.", progress = "Master Goh keeps telling me I need to relax and that failure is part of learning. But this is a dangerous failure.\n\nThe kind that might get people killed.", completion = "It seems like there's not QUITE as many corrupted moths out there. At the very least, you've bought me some more time before I get in big, big trouble." }
WordHunterWoW_QuestEN[30063] = { title = "Behind the Masks", description = "The sha may seem unstoppable, but this is not true.\n\nTheir masks seem to be the source of their power. When a sha and its mask are separated, the creature's essence is banished back to its own realm.\n\nBring me intact masks, for I wish to study them further. Do be careful. I'm sure the sha will not part with them easily.", objectives = "Collect 8 Masks of Doubt.", progress = "Please handle the masks carefully. If you are not careful, they will attempt to consume you.", completion = "I suspect these masks allow the sha to make a physical connection to our world.\n\nI must study them further if we are to banish these creatures forever.\n\nThank you, <name>. Your aid is greatly appreciated." }
WordHunterWoW_QuestEN[30064] = { title = "Saving the Sutras", description = "My adepts had to abandon their studies when the sha invasion began.\n\nUnfortunately, they left their books scattered around the temple grounds. These priceless works of knowledge must be saved!\n\nThe sutras can be found near the Training Pit and the Adept's Ring to the northeast.", objectives = "Collect 6 Ancient Sutras.", progress = "How are the sutras? Are they damaged?", completion = "Thank you! What a relief it is to see these texts are safe." }
WordHunterWoW_QuestEN[30065] = { title = "Arrows of Fortune", description = "Our war supplies grow low, but especially needed are additional arrows.\n\nOur serpent riders are skilled marksmen, but they can do little without ammunition.\n\nWe need someone to brave the battlefields and retrieve any undamaged arrows to refill our stores.\n\nEvery arrow you retrieve will be used wisely.", objectives = "Collect 8 Defender's Arrows.", progress = "Were you able to find any arrows?", completion = "These arrows are still in good shape. They will fly straight and true.\n\nGreat work, <name>." }
WordHunterWoW_QuestEN[30066] = { title = "Hidden Power", description = "Our temple defenders have battled relentlessly for hours. No doubt they grow tired.\n\nI will give you mantras to deliver to our fighters.\n\nDo not be fooled by these pieces of paper. These ancient scriptures hold words of untold power.", objectives = "Deliver Ancient Mantras to 6 Yu'lon Guardians or Yu'lon Adepts.", progress = "Words hold great power. Use them wisely.", completion = "The sha's numbers are unending, and our numbers few. But we are not daunted by difficult odds.\n\nThank you for doing your part to protect our home, <race>." }
WordHunterWoW_QuestEN[30067] = { title = "The Shadow of Doubt", description = "A terrible manifestation of the sha has appeared to the south.\n\nIt is trying to destroy an ancient relic, the Bell of a Thousand Whispers.\n\nThis bell has never been rung in the temple's history, for it is rumored to be an ancient instrument of power.\n\nPlease go and defeat this demon where it stands! We must save this relic!", objectives = "Defeat the Shadow of Doubt.", progress = "The bell is said to contain the voices of a thousand fallen temple priests.", completion = "You have saved us. From what fate, I dare not imagine." }
WordHunterWoW_QuestEN[30068] = { title = "Flames of the Void", description = "Do you see the violent black and white flames erupting all around the temple?\n\nThe greater our doubt, the stronger they rage. Unchecked, they will devour the entire temple.\n\nWe have but one hope.\n\nTake flight on one of our war serpents. Fly it near the pure springs of water, and then douse the fires with water from the pools.", objectives = "Fly your War Serpent near Pure Water Springs, then douse 6 Void Flames with the water carried in its mouth.", progress = "These fires burn unlike anything in our world.", completion = "You have done much to help curb the fires. Thank you for your efforts." }
WordHunterWoW_QuestEN[30069] = { title = "No Plan Survives Contact with the Enemy", description = "Quickly and quietly; that's how SI:7 prefers to operate. That was the plan, at least.\n\nRell Nightwind is already inside Garrosh'ar Point looking for signs of Anduin and Taylor, but it's getting hot in there and he needs support.\n\nFight yer way through these dogs and find Rell!", objectives = "Kill 6 Garrosh'ar Grunts and 6 Garrosh'ar Gear-Greasers.", progress = "This place is crawling with Horde soldiers - we can't advance on their leader with so many at our backs.", completion = "Great work! If you ever decide to give up your life of adventure, the SI:7 could use more talent like you..." }
WordHunterWoW_QuestEN[30070] = { title = "The Fall of Ga'trul", description = "Alright lad. We've taken enough jabs at this warlock army... now it's time to cut off the head.\n\nGa'trul's back there, in that big ol' temple ruin. Give him a good what-for, and the Horde will have lost its last stake here in Pandaria.", objectives = "Slay Ga'trul.", progress = "What's the matter, <name>? Didn't you find Sully? Did Ga'trul elude you?", completion = "Sha...\n\nFighting the Horde on a foreign shore is hard enough." }
WordHunterWoW_QuestEN[30072] = { title = "Where Silk Comes From", description = "Would you like to be a Silkmaster for a day?\n\nThe first thing you'll need are fresh mulberry leaves. You can find them in our grove of mulberry bushes to the northwest.\n\nNext you will need to feed them to a hungry silkworm in our feeding pit to the west.\n\nAnd finally you should get some raw silk from our processing hut on the south side of our farm.\n\nHave fun!", objectives = "Obtain Mulberry Leaves, feed 5 Hungry Silkworms, and get Raw Silk.", progress = "Have you found all of the items? Did you pay close attention to our process?", completion = "Superb specimens. I will see to it they find their way to the right place. Please enjoy this free sample." }
WordHunterWoW_QuestEN[30073] = { title = "The Emperor", description = "We have everything we need. It's time to start brewing.\n\nPay attention, {name}... you might learn a thing or two.", objectives = "Stand by and help Chen Stormstout with his brew.", progress = "It takes more than three seconds to make beer, <name>. Even when your name is Chen Stormstout.", completion = "Thanks for waiting so long. You are as patient as you are brave." }
WordHunterWoW_QuestEN[30074] = { title = "Knocking on the Door", description = "Now, onward to the Stormstout Brewery! It's high time that I was reunited with the rest of the Stormstouts... and what better way to reunite than over a few mugs of ale?\n\nYou know where the brewery is, right? Just follow this road to the west. You can't miss it. Of course, you're free to share the road with us - we'll be leaving any moment now.", objectives = "Meet up with Chen Stormstout at the entrance of the Stormstout Brewery.", completion = "The door... it's boarded up?" }
WordHunterWoW_QuestEN[30075] = { title = "Clear the Way", description = "Are you seeing this? Virmen, hozen, and water sprites... all pouring out of the brewery doors and windows! What the heck is going on in there!?\n\nThere is another entrance, on the eastern side of the brewery. I'm going to run over there and try to figure out what's going on. In the meantime, see if you can't get rid of these creatures. There's nothing worse than a drunken hozen.", objectives = "Slay 10 Ale-Addled Hozen or Mischievous Virmen.", progress = "This brewery - it's a disgrace to the Stormstout name! Something needs to be done!", completion = "I've had just about enough of this brewery. I'm starting to think that you and I should just bust down the wall and clean house." }
WordHunterWoW_QuestEN[30076] = { title = "The Fanciest Water", description = "I've heard lots of cockamamie rumors about this here brewery. I thought they were all false... until I saw that giant hozen.\n\nSo, it got me thinkin', what if the other rumors are true? I heard this one rumor just the other day about some water sprites that run around inside the brewery, causin' a ruckus and whatnot. Their bodies are actually MADE OF WATER.\n\nI reckon a man could make some mighty fine beer with some fancy water like that. If you find any, could you bring me some?", objectives = "Obtain 3 Spritewater Essences.", progress = "This is gonna be great. It'll be just like makin' beer, but instead of water, I'm gonna use water sprite meat.", completion = "Looks like plain ol' water to me. It's hard to believe it's actually the corpse of a real, honest-to-goodness walkin'-around living thing.\n\nCan't wait to turn it into beer and drink it." }
WordHunterWoW_QuestEN[30077] = { title = "Barrels, Man", description = "I can't believe that giant hozen! He's just throwing barrels everywhere!\n\nBarrels, man!\n\nIt looks like he managed to get pretty much all the pandaren that were working out in front of the brewery. If I were you, I'd help some of them break out. Put some of those ridiculous muscles to use.\n\nWe're headed over to the brewery's rear entrance, to the east. Meet you there!", objectives = "Free 7 Barreled Pandaren.", completion = "What is it with monkeys and barrels, anyway?" }
WordHunterWoW_QuestEN[30078] = { title = "Cleaning House", description = "That's it, {name}. I've had enough of this.\n\nIf somebody doesn't do SOMETHING to take care of this brewery, we'll lose it forever. And there's far too much family history - and beer - in there to risk wasting.\n\nSo... we're going to break in through the back door. You, Li Li, Mudmug, and me.\n\nIt's gonna be a brawl in there.\n\nLet me know when you're ready.", objectives = "Defeat Eddy, Jooga, and the Fizzy Yellow Alemental.", progress = "Let's do this.", completion = "Take a look around - it's a lot calmer outside. All the brewery needed was somebody strong to take care of it.\n\nIt's going to take some time to clean this place up, but I don't really mind that so much.\n\nThis is, after all... my home." }
WordHunterWoW_QuestEN[30079] = { title = "What's Eating Zhu's Watch?", description = "Pandaren always welcome travelers with open arms - and open kegs! But this town full of jerks!\n\nEveryone so busy sulking, they won't talk to Ken-Ken at all!\n\nCan you find someone in town who will talk to us? Maybe normal pandaren just hiding in the houses?", objectives = "Speak with the inhabitants in Zhu's Watch and find someone willing to talk to you.", progress = "Something definitely not right! Pandaren supposed to be HAPPY!", completion = "Only one lady-panda who's not crazy? This worse than Ken-Ken thought..." }
WordHunterWoW_QuestEN[30080] = { title = "Finding Yi-Mo", description = "My nephew, Yi-Mo, has always been sort of a downer. When this wave of despair hit the town, he took it harder than most. He sat around for days refusing to eat, just staring off into the horizon.\n\nNow he's wandered off toward the cliffs northeast of here, where the thunderbirds nest and hunt.\n\nPlease, {class}, will you look for him?", objectives = "Look for Yi-Mo Longbrow somewhere northeast of Zhu's Watch.", progress = "<Yi-Mo lets out a long sigh.>", completion = "Let me guess: my aunt sent you?" }
WordHunterWoW_QuestEN[30081] = { title = "Materia Medica", description = "Alright, Ken-Ken pretty sure he knows what wrong with pandaren! Got old, old hozen remedy that do the trick.\n\nNeed to mix honey, fish oil, and salt. Ken-Ken saw lots of beehives in the trees around town, and there must be fish left in the dry ponds.\n\nThat just leave salt... Mei might know where we can find some.", objectives = "Gather 4 Chunks of Honeycomb, 4 Slick Mudfish, and 4 Salty Cores from Zhu Province.", progress = "Can't believe Ken-Ken did not think of this sooner. It's the ONE thing that can ruin his day...", completion = "Pandaren got a case of the spooky-dooks!\n\nDooks get scared sometimes, don't wanna come out. Poor, fluffy mopey-dopes must be ready to explode by now!\n\nThis just the thing to bring 'em out. That make pandaren happy for sure!\n\nJust like ol' gramma used to say: can't THROW if can't GO!" }
WordHunterWoW_QuestEN[30082] = { title = "Cheer Up, Yi-Mo", description = "Ever since this storm began, I've just been... tired.\n\nNot physically... no. It's like my very soul is exhausted. Worthless. Hopeless. I imagine it's what one feels when a mate leaves them for someone with a rounder belly, but I've never had a mate so how would I know?\n\nHow can I claim to know anything? I'm worthless to everyone but these thunderbirds. At least they'll have a good meal out of me.\n\n<Yi-Mo sighs deeply and continues staring off into the sky. It doesn't look like he's going anywhere.>", objectives = "Bring Yi-Mo Longbrow back to Zhu's Watch.", completion = "I can't believe he was actually going to do that... This despair is worse than I had even imagined.\n\nI cannot thank you enough for bringing him back." }
WordHunterWoW_QuestEN[30083] = { title = "Securing the Province", description = "With our grip on the province loosening, saurok from the wilds have already moved in to the cave just north of town.\n\nMost of our hunters are face-down in their own tears, so the saurok just walk in here like they own the place and grab whatever they want!\n\nI want to send a message that Zhu's Watch is not to be crossed.\n\nWill you be my messenger?", objectives = "Kill 10 Wildscale Saurok or Wildscale Herbalists in Zhu Province.", completion = "Thank you, <name>. That should teach those savages to know their boundaries." }
WordHunterWoW_QuestEN[30084] = { title = "Borderlands", description = "Bonfires are surprisingly effective at discouraging beasts from wandering out of the wilds. We have three along the border to the southwest which we normally keep lit at all times.\n\nNobody's been there for days, though, and the fires must be out by now. It's only a matter of time before the wilds creep back in and overtake the land we have kept safe for centuries.\n\nPlease, re-ignite the bonfires. They are critical in keeping the province safe, and they are memorials to the founders of our way of life.", objectives = "Light the Memorial Flame of Zhu, Memorial Flame of Rin, and Memorial Flame of Po along the southwest border of Zhu Province.", completion = "Thank you, <name>.\n\nZhu Province serves as a corridor from the upper tier of the valley down to the sea.\n\nKeeping the province safe requires daily efforts to maintain a border against the savage Krasarang Wilds." }
WordHunterWoW_QuestEN[30085] = { title = "Into the Brewery", description = "We need to find out what's going on inside that brewery, {name}!\n\nWe may have cleared out some of the bigger pests, but I'm certain there's plenty more where they came from. Gather up a few of your friends, and meet me inside!", objectives = "Speak to Chen Stormstout inside the Stormstout Brewery.", completion = "You came! Great!\n\nI'm looking forward to fighting by your side again, <name>." }
WordHunterWoW_QuestEN[30086] = { title = "The Search for the Hidden Master", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs.\n\nI'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I are trying to decide something. We can talk again afterwards.", objectives = "Listen to Xiao and his companions.", completion = "Were you listening in? Don't worry, I don't mind. You're welcome to search for the hidden master as well.\n\nThough, if you do find him, I'd appreciate if you came back here and told me where he was." }
WordHunterWoW_QuestEN[30087] = { title = "FLAG - Kung Fu Intro", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.Upon completion of this quest you will gain:", objectives = "Listen to Xiao and his companions." }
WordHunterWoW_QuestEN[30088] = { title = "Why So Serious?", description = "Okay, so that not work. Well... it cheer Ken-Ken up! But pandaren still sad...\n\nWe try another old hozen remedy - this time, we go back even further than gramma, way WAY back to ancient times. Hozen still do this sometimes... mostly at parties.\n\nKen-Ken got woodworking to do - you bring him teeth! Not yours; big ones, like a panther would have!\n\nOh, and some paint! Mei might know where to find.", objectives = "Collect 18 Huge Panther Fangs and 1 Jar of Pigment from Zhu Province.", progress = "<Ken-Ken is hard at work carving something out of tree bark.>\n\nThis gonna be great, you'll see.", completion = "Just in time! All done... look!\n\n<Ken-Ken holds up a carved wooden mask with a ridiculous face.>\n\nNow we put on finishing touches and we gots a guaranteed FUN MACHINE!" }
WordHunterWoW_QuestEN[30089] = { title = "Apply Directly to the Forehead", description = "Well... THAT was unexpected!\n\nCome to think of it, now Ken-Ken remember why hozen use mask in the first place...\n\nA legend about the Monkey King says he used a mask to cure old pandaren emperor, Shaohao, when he was too sad to lead his people. Then they buried mask--with all his sadness--in the ground.\n\nWe should use the mask on more pandaren, but instead of putting sad away in ground, we gonna PUNCH ITS BUTT.\n\nLet's do this, {name}!", objectives = "Use Ken-Ken's Mask to cure 8 Despondent Wardens of Zhu in Zhu's Watch.", progress = "This must be the emperor's sad coming back! That is some oooold sad.\n\nKen-Ken bet pandaren sad get stronger with age, too, like pandaren booze.", completion = "We saving pandaren, but the land still sad... Look, rain's not stopping at all!\n\n<Ken-Ken shakes his tiny fists at the sky.>\n\nHow many more butts we gotta punch before we fix this town?!\n\n<The sky darkens in response.>" }
WordHunterWoW_QuestEN[30090] = { title = "Zhu's Despair", description = "Hmm... Is that Yi-Mo kid over there?\n\n<Ken-Ken squints against the increasing torrents of rain.>\n\nIt is! He's at the well, and he's not lookin' so good.\n\nKen-Ken got a bad feeling about this...", objectives = "Exorcise the Sha of Despair energy from Yi-Mo Longbrow in Zhu's Watch.", completion = "We did some good work here today, <name>.\n\nMonastery always tell us to leave a place better than we find it." }
WordHunterWoW_QuestEN[30091] = { title = "Tears of Pandaria", description = "All of this started with our ponds. In a single day, all of the water retreated down into the earth. When there was no more water in the ponds, it began to fall from the sky.\n\nDespite endless torrents of rain, the ponds do not fill. It's as if the land itself thirsts and cannot be quenched.\n\nNow the ponds birth horrific manifestations of despair. Elementals made of water from the sky and salt from the earth; the tears of Pandaria.", objectives = "Kill 12 Weeping Horrors in Zhu Province.", progress = "I don't know why this is happening, but I can say for certain that those elementals were the start of it all.", completion = "Thank you, <class>.\n\nIt's time we take back our land from this curse." }
WordHunterWoW_QuestEN[30092] = { title = "Our Man in Gilneas", description = "If you wish to join my cause and slaughter the black dragons in hiding, prove yourself by taking down Hiram Creed. He's amassing an army in Gilneas.\n\nWe haven't been able to slip past his defenders, but we've got a man on the scene keeping an eye on him. Zazzo Twinklefingers, a very crafty arcane mage, is waiting for us to contact him just outside of the ruins of the Gilnean capital.\n\nFind him and he'll direct you to the target.", objectives = "Seek out Zazzo Twinklefingers near the ruins of Gilneas City in Gilneas.", completion = "Ravenholdt sent you? I hope you're a better assassin than the others." }
WordHunterWoW_QuestEN[30093] = { title = "Assassinate Creed", description = "The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, has infected the lot of those dogs with his own draconic blood. Even the Forsaken are having trouble routing him out.\n\nOnly a surgical assassination can end this!\n\nThe bridge behind me is relatively unguarded. Slip in through merchant's square and head south - you'll find Creed in the middle of the military district.\n\nI'll keep an eye on you and pull you out if there's any trouble.\n\n...There WILL be trouble!", objectives = "Stealth into the ruins of Gilneas City and slay Hiram Creed within the military district.", progress = "Hiram Creed. Among the black dragons, he is known as \"Creetharus.\"", completion = "Creed is finished. The Gilneans who followed his lead are on their own now - assuming his corrupted draconic blood works its way out of their system without killing them.\n\nEither way they're no longer a concern of ours." }
WordHunterWoW_QuestEN[30094] = { title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Horde. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", objectives = "Speak with Nozdormu at the End Time.", completion = "<name>, you have arrived. This is good. I apologize for bringing you to this strange place, and under such suspicious circumstances.\n\nI have a good reason for doing so.\n\nWe are going to kill Deathwing. And I require your aid." }
WordHunterWoW_QuestEN[30095] = { title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Alliance. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", objectives = "Speak with Nozdormu at the End Time.", completion = "<name>, you have arrived. This is good. I apologize for bringing you to this strange place, and under such suspicious circumstances.\n\nI have a good reason for doing so.\n\nWe are going to kill Deathwing. And I require your aid." }
WordHunterWoW_QuestEN[30096] = { title = "Murozond", description = "If we are to destroy Deathwing, we will need the power of the Dragon Soul. To obtain the Dragon Soul, I would have to take you back to the Sundering, ten thousand years in the past... but that time passage is blocked to me.\n\nThe creature that blocks us from accessing this time passage is named Murozond. He must be slain, here, in this twisted future, before we can continue our plot to unmake Deathwing.\n\nThis is why you were brought here, {name}.", objectives = "Slay Murozond.", progress = "This is a future of Azeroth, yes... but not an inevitable one.\n\nThis future is what my fellow aspects are trying to avoid.", completion = "Murozond is no more. The timeways are open to me once again." }
WordHunterWoW_QuestEN[30097] = { title = "Archival Purposes", description = "From what I understand, you intend to avoid this future. If this is true, then we must archive data from this timestrand before it is lost to us.\n\nWe believe that the most interesting and valuable elements of this future are the powerful \"echoes\" that roam the dragonshrines.\n\nTake this vessel with you as you silence these echoes. A portion of their energies will be archived within the bronze dragonflight's depository.", objectives = "Slay two of the Echoes within the End Time, then allow Alurmi's Vessel to archive their information.", progress = "Nozdormu is acting with haste. This is something that Nozdormu does not usually do.\n\nNormally I would be more thorough with my archival. However, given the circumstances, we are forced to pick and choose what we record... and to employ the help of mercenaries like you.", completion = "<Alurmi collects the vessel from you.>\n\nI will handle these from here. Of course, they must be properly labeled, documented, and stored." }
WordHunterWoW_QuestEN[30098] = { title = "The Well of Eternity", description = "We must move quickly, before any remaining Infinite agents intervene. Time is precious.\n\nI will now take you from your distant future into your distant past... the War of the Ancients. Our goal is the Dragon Soul, an artifact of immense power... enough power to break Deathwing, and end his reign over your present.", objectives = "Speak with Nozdormu at the Well of Eternity.", completion = "Let us proceed." }
WordHunterWoW_QuestEN[30099] = { title = "In Unending Numbers", description = "Between us and the Dragon Soul lies a legion of demons. They will have to be dispatched before we proceed.\n\nIf my timing is correct - and it usually is - a young night elf named Illidan Stormrage should be crossing our path shortly. He will undoubtedly be of some use when it comes to demon hunting.\n\nHelp Illidan disable the demons' portals, then slay their leader, Peroth'arn.", objectives = "Disable the three demon portals, then slay Peroth'arn.", progress = "You should temporarily lay aside any prejudices you may carry against Illidan. Remember, you are ten thousand years in your past, and he must not be punished for any future crimes.", completion = "Good. We march on." }
WordHunterWoW_QuestEN[30100] = { title = "The Vainglorious", description = "Queen Azshara and her royal guard lie ahead of us. We cannot afford the possibility of any interference with our plan. So we will take the fight to her, before she has a chance to meddle.\n\nIt is quite unlikely that you will kill Queen Azshara today; very few coherent timelines exist along that branch. Consider it a victory if you are simply able to occupy her attention, however temporarily.", objectives = "Dispatch of Queen Azshara.", progress = "Azshara and her fawners have long prepared for this day. She will not take our interference lightly.", completion = "We are but moments away from the Dragon Soul." }
WordHunterWoW_QuestEN[30101] = { title = "The Path to the Dragon Soul", description = "I cannot simply fly up and grab the Dragon Soul. The old gods protect it.\n\nTo make matters worse, their shield is strengthened by the swirling, arcane energies that emanate from the Well of Eternity, and those energies are being focused by the great demon Mannoroth.\n\nDistract Mannoroth, and the link between the Dragon Soul and the Well will be broken. Without the Well's power, the old gods' ward will be weakened, and the Dragon Soul will be vulnerable.\n\nAnd then I will take it.", objectives = "Slay Mannoroth.", progress = "What?", completion = "Thank you for your help, stranger.\n\nYou fight well. I hope to fight with you again in the future." }
WordHunterWoW_QuestEN[30102] = { title = "The Hour of Twilight", description = "There's no need to stand around here forever. Have you forgotten? We can CONTROL TIME. Especially since you got rid of that Murozond fellow, back in the future.\n\nThat Dragon Soul that you just liberated? Thrall already has it, back in your present day. And he's going to need your help.\n\nYou ready to go?", objectives = "Speak with Thrall at the Hour of Twilight.", completion = "You've arrived.\n\nGood, let us begin." }
WordHunterWoW_QuestEN[30103] = { title = "To Wyrmrest!", description = "The Dragon Soul... a weapon with enough power to defeat Deathwing. Thanks to you, it is now safely in our hands.\n\nCome! The aspects await us. We must bring the Dragon Soul to Wyrmrest Temple, in the center of Dragonblight.", objectives = "Escort Thrall safely to Wyrmrest Temple.", progress = "Come, <name>. We do not have much further to travel.", completion = "I owe my life to you, heroes.\n\nNow that we hold the Dragon Soul safely within Wyrmrest, it may be that all of Azeroth owes their lives to you." }
WordHunterWoW_QuestEN[30104] = { title = "Documenting the Timeways", description = "You... {name}, was it? You assisted with our archival in the past. Well, technically it was the future, but I believe you understand. Time is highly relative.\n\nI require more information for our archive. While you and Nozdormu don't intend to overwrite this timestrand, as you did in the End Time, we can still benefit from more data.\n\nI require information on Captain Varo'then, one of Azshara's pretty little handmaidens, and... hmm... oh, how about that big felguard, just down those stairs?", objectives = "Slay a Legion Demon, a Royal Handmaiden, and Captain Varo'then, then allow Alurmi's Vessel to archive their information.", completion = "We rarely enjoy the opportunity to employ a brave <class> like you. Our archive grows more thorough, thanks to your efforts." }
WordHunterWoW_QuestEN[30105] = { title = "The Twilight Prophet", description = "The missive reads as follows:\n\n\"The Hour of Twilight is upon us. The world-shaman Thrall approaches Wyrmrest with the Dragon Soul in hand, feebly whimpering one final threat to destroy our glorious master.\"\n\n\"Stop Thrall, and we win our war. I will be watching you from nearby.\"\n\n   ~ The Twilight Prophet", objectives = "Find and unmask the Twilight Prophet.", progress = "I have my suspicions about this Twilight Prophet.", completion = "It is truly as we foresaw: Benedictus was the Twilight Prophet. And now he is no more.\n\nWe dealt a mighty bow to the Twilight's Hammer today. Let us hope that it was a deathblow." }
WordHunterWoW_QuestEN[30106] = { title = "The Deed is Done", description = "Prince Wrathion will be pleased to hear that you've succeeded. You should report back to him at Ravenholdt Manor.\n\nThe Prince has been known to be extremely generous to those who help him. ", objectives = "Report your success to Prince Wrathion at Ravenholdt Manor in Hillsbrad Foothills.", completion = "That's wonderful news, <name>. Creed was not the most powerful of the remaining black dragons, but his manipulation of the Gilneans was truly diabolical.\n\nI've prepared a reward for you. These blades may not look like much at present, but in the right hands they may yet awaken.\n\nPerhaps in YOUR hands..." }
WordHunterWoW_QuestEN[30107] = { title = "Cluster Clutch", description = "The daggers I have given you are lifeless shells. They can do great things, once they are given a means to contain the power I have in mind.\n\nI need for you to acquire Shadowy Gems for me. The facets of these unusual stones are like windows into the infinite. They are often used by minions of the Twilight's Hammer to control the most powerful of elementals.\n\nA great battle is raging around Wyrmrest Temple. Collect Elementium Gem Clusters from Deathwing's minions and bring the gems to me.", objectives = "Collect 333 Shadowy Gems by looting Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter.", progress = "How many gems have you collected?\n\nAre my father's minions as twisted as he?", completion = "Ah, do you see how they shimmer? Many fine gems sparkle in the light, but only these seem to sparkle with darkness.\n\nI'll perform an enchantment on these while you are on your next mission.\n\nAre you ready?" }
WordHunterWoW_QuestEN[30108] = { title = "Our Man in Karazhan", description = "Your next target is the Black Dragon Nalice, who is engaged in some sort of arcane debauchery beneath the ruined tower of Karazhan.\n\nYour primary mission is to destroy her, but if you can bring me back a vial of her blood, I'll be able to use it to augment the power of the daggers I've given you.\n\nYour accomplice Zazzo has already been dispatched to the scene and awaits you there. He'll have more details.", objectives = "Report to Zazzo Twinklefingers in the ruins just southeast of Karazhan.", completion = "Madness. Insanity!\n\nI don't know what Nalice is up to down there, but the entire basement radiates with diabolical arcane energy. She's got an entire cult worshipping her as a goddess.\n\nIf we're going to take her out, we have to do it soon. I hope you're ready for this!" }
WordHunterWoW_QuestEN[30109] = { title = "Blood of the Betrayer", description = "I've pinpointed Nalice to the Master's Cellar, an extended basement you'll find in the ruins up ahead.\n\nDragon cultists are everywhere, and Nalice has set up some strange arcane storage devices throughout the area. Perhaps you can use those to your advantage?\n\nSneak past the cultists, obliterate Nalice, and grab a vial of her blood for Wrathion.\n\nI'll keep my eyes on you and pull you out if you get into any trouble. But I'm NOT coming in there with you!", objectives = "Sneak into the Master's Cellar in the ruins around Karazhan, defeat Nalice, and acquire a Vial of Black Dragonsblood.", progress = "Nalice. Dead?", completion = "You did it? She's dead? Unbelievable! You're some kind of miracle-worker!\n\nHere, let me see that blood. I can preserve its energies in an arcane matrix for your trip back..." }
WordHunterWoW_QuestEN[30110] = { title = "LFGDungeons - Cataclysm - Raid Finder - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[30111] = { title = "LFGDungeons - Cataclysm - Raid Finder - Nth", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[30112] = { title = "A Score to Settle", description = "Utgarde's forces are organizing under the advisory of Prince Keleseth, a san'layn ambassador of the Scourge.\n\nWe cannot allow the vrykul to benefit from his counsel any further. Silence him.", objectives = "Dark Ranger Marrah wants you to slay Prince Keleseth inside Utgarde Keep.", progress = "Is it done, <name>?", completion = "Revenge feels good.  To think that this is but a taste of what's to come.\n\nArthas will get what he deserves soon enough." }
WordHunterWoW_QuestEN[30113] = { title = "Victory in the Depths", description = "<Zazzo performs an enchantment on the vial of blood, then quickly hands it back to you, as though it's toxic.>\n\nDone! You'll want to get this back to Wrathion as soon as possible, along with those two daggers of yours.\n\nI don't know what he plans to do with this stuff. Between you and me, sometimes that little dragon kid creeps me out. Good luck!", objectives = "Take the Vial of Preserved Dragonsblood, along with your daggers Fear and Vengeance, to Wrathion at Ravenholdt Manor in Hillsbrad Foothills.", progress = "Ah, you've returned! I no longer sense Nalice's presence. Is she dead? Or has she somehow eluded us both?", completion = "You are, indeed, a master of your craft. Nalice is dead, and it is time you are rewarded for your efforts.\n\n<Wrathion takes the vial from you, his face a mask of equal parts reverence and revulsion. He drops the gems you collected one-by-one into the blood, muttering an incantation.>\n\n<Without warning he pours the blood over the blades of the daggers, and the steel seems to writhe and twist as though alive. When the smoke clears, the daggers have altered their shape.>" }
WordHunterWoW_QuestEN[30116] = { title = "Sharpening Your Fangs", description = "Do you understand why I have you assassinate the dragons, yet spare the mortals? It isn't their fault. They must seek out their own destiny, free from the meddling of my kind.\n\nWe are nearing the end of our mission, and it is time for you to seek out your own destiny as well. I can continue to augment your weapons, but collecting shadowy gems won't be enough. My work will require entire clusters. Gather them from my father's minions...", objectives = "Collect 60 Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter.", progress = "How many clusters have you acquired?\n\nThe tenacity of your race continues to inspire me!", completion = "You have done it! No doubt you placed yourself and your allies in great peril to acquire these. Your sacrifices will be rewarded in time. I will use these as the foundation of a powerful enchantment for you.\n\nBut we will need one additional catalyst. Are you ready for your final and most dangerous mission, <class>?" }
WordHunterWoW_QuestEN[30117] = { title = "Stoneplow Thirsts", description = "Excuse me... {name}? Did I hear your name correctly?\n\nI've come from Stoneplow, in the west. They sent me to pick up some emergency beer rations, but the Stormstout Brewery is all boarded up!\n\nIt looks like your handsome friend there - no, not Mudmug, the other one - has a few casks with him. Could you spare a keg for a town in need?", objectives = "Deliver a cask of The Emperor to Loon Mai at Stoneplow in the Valley of the Four Winds.", progress = "Greetings, <class>.", completion = "Finally! Emmi's come through.\n\nI hope all is well at the Stormstout Brewery. My men don't do well without beer." }
WordHunterWoW_QuestEN[30118] = { title = "Patricide", description = "Your next target has claimed the lives of all of my other assassins. I need you to kill my father himself.\n\nYou must destroy Deathwing.\n\nWe are out of time. His madness has already corrupted all the others of my kind, and his darkness will consume the world if he is not stopped.\n\nIf you by some miracle succeed, and can retrieve for me a piece of him - perhaps a fragment of the armor he uses to disguise his true chaotic nature - the reward I give you will be without equal. ", objectives = "Destroy Deathwing and retrieve a Fragment of Deathwing's Jaw.", progress = "What of my father?", completion = "I can feel it - like a dark shadow lifted from the land. Dead. My father is dead!\n\n<Wrathion takes the jaw fragment from you. His hands and face blur as he recites a dark enchantment, the gem clusters you collected earlier orbiting around his head. The jawpiece suddenly shatters, and with a terrible hissing sound your twin daggers awaken.>\n\nYour reward is ready. Take them, quickly. You will need them momentarily..." }
WordHunterWoW_QuestEN[30119] = { title = "Well of Eternity RP Tracker", description = "I am duty-bound to look into your claims immediately, <race>, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the world tree's branch.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover the Branch of Nordrassil from the Firelands.I am duty-bound to look into your claims immediately, <race>, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the world tree's branch.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30120] = { title = "Cleansing Drak'Tharon", description = "'Ey, mon, you be here! Dis is good, mon!\n\nDrak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", objectives = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.\n\nProvided item:", completion = "We done a great thing, mon! And dis just be da beginning....\n\nSeek me out in Zul'Drak when da time be right.\n\nDere be a war to be won, mon!" }
WordHunterWoW_QuestEN[30121] = { title = "Search Party", description = "I sent a diplomat to look for allies in the ruins east of here.\n\nMy diplomat has not returned and now Kang tells me this jungle is filled with a sinister people known as the mogu.\n\nChezin is my friend and Leza's brother. To lose a brother would cause her to give in to despair. She already has enough to worry about with her fever.\n\nCould you investigate the ruins east of here and find out what happened?", objectives = "Search the Krasari Ruins for Chezin Dawnchaser.", completion = "P... poison. Need... warn... Dezco..." }
WordHunterWoW_QuestEN[30122] = { title = "Silver Filigree Flask", description = "You have found a beautiful silver flask decorated with ornate filigree.  With the right materials and your skill in alchemy, it could become quite magical.You will receive:", objectives = "Fill the vial with a potent alchemical mixture." }
WordHunterWoW_QuestEN[30123] = { title = "Skitterer Stew", description = "Leza has a fever. No mother in labor should have a fever.\n\nMama Bramblestaff once told me that Skitterer Stew could heal almost any illness. Let us put this knowledge to the test.\n\nGather some intact skitterer glands for me while I get the herbs we'll need and I'll whip up a batch.", objectives = "Gather 5 Intact Skitterer Glands.", progress = "Even the jungle air is alive with danger.", completion = "Excellent! Nothing clears a sickness like Skitterer Stew.\n\nHere, take this. It's a little memento of Mama Bramblestaff." }
WordHunterWoW_QuestEN[30124] = { title = "Blind Them!", description = "These sunwalkers are a tiresome lot. I need soldiers with horde blood in their veins and honor in their hearts. Not some pacifist sun spirit filth.\n\nThe Alliance are here, {name}. Followed us no doubt, or somehow tracked the same visions Leza had that led us here. It doesn't matter. I don't want them to know how divided we are at the moment. Go kill their scout south of here before it can report back.\n\nHellscream's eyes upon you.", objectives = "Kill the Darnassian Outrider.", completion = "Well done, <name>. You have performed admirably and bought us some time to fortify our defenses. Now if I can just get Dezco to go on the offensive." }
WordHunterWoW_QuestEN[30125] = { title = "Profit Mastery", description = "Two words: Tiger Blood!\n\nThis is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff.\n\nThing is, I ran out of ammo. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain 12 Vials of Tiger Blood." }
WordHunterWoW_QuestEN[30126] = { title = "Crane Mastery", description = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up.\n\nCan't hunt, can't brag. And I like bragging so this is no good.\n\nCan I hire you to go kill me some carp hunters? You'll find them up and down the river west of here.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 8 Carp Hunters." }
WordHunterWoW_QuestEN[30127] = { title = "Threat from Dojan", description = "Mogu? They seem like the elves, ancient and an over developed sense of entitlement. Everyone of Azeroth must learn, sooner or later, that the Horde is not \"visiting\" this world. We are here. We are staying.\n\nTeach them this lesson. Quell their numbers in the ruins south and west of here. Break their amassing forces before they decide to attack.\n\nLearn what you can of how these creatures fight, and how they die.", objectives = "Kill 6 Dojani Reclaimers and 8 Dojani Surveyors, and 4 Dojani Enforcers.", progress = "You found how many? Sounds like a veritable nest of the vile creatures. If they were more civilized I might consider extending them an invitation to join the Horde.", completion = "These are more than just a bandit threat. They are an ancient people beginning to rally under a single banner. Mark my words, soon these lands will know war." }
WordHunterWoW_QuestEN[30128] = { title = "The Pools of Youth", description = "The mogu found the Pools of Youth!\n\nMama Bramblestaff used to tell me old stories about those. During the mogu empire they would use the waters to extend life.\n\nThing is those stories never ended well for some reason. As if the waters were cursed.\n\nEither way, we should investigate. There is a good chance those waters might help Leza.\n\nIt looks like the Pools of Youth are on the northwestern side of the ruins.", objectives = "Recover water from the Pools of Youth.", progress = "Leza's pain is immense. Only powers beyond my own can save her and the baby now.", completion = "At this point I am willing to try anything. This land is claiming my wife and unborn child. I need all the help I can get." }
WordHunterWoW_QuestEN[30129] = { title = "The Mogu Agenda", description = "Mogu don't often gather in numbers like this. We should find out what they are up to.\n\nI thought I heard someone shouting orders near the center of the ruins.\n\nWe should probably see if he has information.", objectives = "Recover the Dojani Orders.", progress = "The mogu once ruled as emperors, subjugating all races they encountered.\n\nIt would seem these particular mogu have aspirations of reliving the past.", completion = "Wait. This document talks about the Pools of Youth!\n\nThe pools exist?!" }
WordHunterWoW_QuestEN[30130] = { title = "Herbal Remedies", description = "Kang's remedy isn't working.\n\nThere is something else at work here. A power deep beneath the soil. It is sapping us of hope, hitting us with depression and despair.\n\nKang tells me this land has lotus plants. I might be able to make a tea that would hopefully lend Leza some strength.\n\nPlease, {name}, search the ruins south and west of here for lotus leaves. I will pay you for your efforts.", objectives = "Find 20 Imperial Lotus Leaves.", progress = "I've been punched, stabbed, thrown off of a cliff, hit in the face by someone's mace, hit in the face by my own mace, and fell off the elevator at Thunder Bluff on more than one occasion.\n\nNone of that pain sounds even half as bad as what Leza is going through. I hope this tea helps...", completion = "Thank you hero. Kor is a brave warrior but he lacks compassion at times. Life must come before death, or there will be none of us left when the fighting is done." }
WordHunterWoW_QuestEN[30131] = { title = "Life", description = "My child is coming. I must help as I may.\n\nStay nearby, hero. If my wife and child survive, I would have them look on the face of the one who saved them.", objectives = "Speak with Sunwalker Dezco, and wait for the newborn.", progress = "I pray to An'she that my wife and child survive this journey.", completion = "She... she died. For all the powers the Light has given me, I was unable to save her.\n\nThanks to your help, however... we saved my sons." }
WordHunterWoW_QuestEN[30132] = { title = "Going West", description = "Leza now walks with the ancestors of this strange land. I must look now to the living.\n\nKor has led a group of our scouts west deeper into the jungle.\n\nI sent a scout of my own to investigate the crane temple. Please, {name}, seek out my scout, get their report, then meet up with Kor and lend what aid you can to him.\n\nWe will join you as quickly as we are able.", objectives = "Find the Sunwalker Scout near the Crane Temple.", progress = "War. It always comes down to war.", completion = "<name>! Well timed!\n\nWe were laying an ambush for the Alliance in the ruins west of here when the mogu ambushed us. They are using mage portals to call in reinforcements." }
WordHunterWoW_QuestEN[30133] = { title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone north. When you reach the temple, find Koro Mistwalker.", objectives = "Locate the missing Zhu's Watch Courier in the northern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker.", completion = "I see... And the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Watch, I have to implore you to help us deal with them here." }
WordHunterWoW_QuestEN[30134] = { title = "Wild Things", description = "Welcome to the Order of the Cloud Serpent, {race}. I can see from the spark in your eye that you wish to join the Order.\n\nLet me get a good look at you.\n\n<Elder Anli gently holds your head and gazes at your face.>\n\nHmm. I see honesty and earnestness in your heart. You have journeyed far to come here, but I am afraid you must go yet further.\n\nYour path into the Order begins now.\n\nSpeak to Instructor Tong at Windward Isle to the northeast to take the first step.", objectives = "Find Instructor Tong at Windward Isle in the Jade Forest.", completion = "Thank goodness, they finally sent someone!\n\nThings have gotten out of control!" }
WordHunterWoW_QuestEN[30135] = { title = "Beating the Odds", description = "At first, the Slitherscale were too frightened to approach the wild serpents.\n\nThen, I caught them snatching the eggs under the cover of night.\n\nNow, they are slaughtering adults and hatchlings alike!\n\nIf we do not do something, these gentle creatures will be completely wiped out. Then there won't even be an Order of the Cloud Serpent to join!\n\nGo and slay these vile Slitherscales, and then we will talk.", objectives = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers.", progress = "The Order rarely meddles with the natural balance on this island, but it is too important to save the serpents.", completion = "Thank you, <race>.\n\nI tried to stop the Slitherscale where I could, but I was no match for their numbers.\n\nYour work today will help preserve an entire generation of cloud serpents." }
WordHunterWoW_QuestEN[30136] = { title = "Empty Nests", description = "When the attacks began, the young hatchlings scattered in terror.\n\nThey are roaming around the island, lost and scared.\n\nIf you want to help, take this rope and leash the lost little ones. Take them back to their nests. Return them home.", objectives = "Leash and return 6 Windward Hatchlings to their nests.", progress = "Did you return the hatchlings to their nests?", completion = "Don't worry. The hatchlings will be safe inside their nests.\n\nI can't thank you enough for arriving when you did." }
WordHunterWoW_QuestEN[30137] = { title = "Egg Collection", description = "Ahhh, I should have known! You have the look of a hungry initiate.\n\nI would gladly help you choose a serpent egg, but the Slitherscale have thoroughly raided the cloud serpent nests.\n\nI'm terribly sorry. I don't know what to tell you.\n\nUnless you're crazy enough to sneak into the saurok camp to the east and retrieve some stolen cloud serpent eggs, I'm afraid I can't help you.", objectives = "Collect 6 Serpent Eggs.", progress = "The saurok keep the stolen serpent eggs in their camp.", completion = "Oh, wonderful!\n\nThese eggs look...well...they look a little on the small side. Are you sure you couldn't find any better ones?\n\nOh well, I suppose with the current situation, we can't be so picky." }
WordHunterWoW_QuestEN[30138] = { title = "Choosing the One", description = "I have examined each egg, {name}. Out of the lot that you brought me, I have chosen the three eggs with the most promise.\n\nYou may choose only one egg to take with you. Are you ready to make your final selection?", objectives = "Speak to Instructor Tong at Windward Isle in the Jade Forest.", completion = "You may choose only one egg to take with you.\n\nChoose carefully. There is no going back." }
WordHunterWoW_QuestEN[30139] = { title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", objectives = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment." }
WordHunterWoW_QuestEN[30140] = { title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", objectives = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment." }
WordHunterWoW_QuestEN[30141] = { title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", objectives = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment." }
WordHunterWoW_QuestEN[30142] = { title = "It's A...", description = "Oh my! This egg is going to hatch at any second!\n\nWell, looks like this little guy is eager to meet you.\n\nAre you ready?", objectives = "Watch your egg hatch.", progress = "What a proud moment for you!", completion = "Congratulations! It's a beautiful hatchling of your own.\n\nPlease take care of it, <name>." }
WordHunterWoW_QuestEN[30143] = { title = "They Grow Like Weeds", description = "Ahh, it is you again, {name}.\n\nInstructor Windblade is looking for you. You can find her on the ridge to the east.\n\nShe has some news about your cloud serpent.", objectives = "Speak to Instructor Windblade at The Arboretum.", progress = "You are doing well, trainee.", completion = "Congratulations, <name>.\n\nThere is great joy in seeing the fruits of your own labor." }
WordHunterWoW_QuestEN[30144] = { title = "Flight Training: Ring Round-Up", description = "Now that your serpent is fully grown, you are ready to begin flight training.\n\nAs with all novices, you must start at the beginning.\n\nYour first task is simple. Fly through 6 of the cloud rings between the spires to the east.", objectives = "Fly through 6 cloud rings while riding your cloud serpent.", progress = "How did your first flight go?", completion = "What have you learned from this lesson?\n\nSpeed. It's all about speed." }
WordHunterWoW_QuestEN[30145] = { title = "Flight Training: Full Speed Ahead", description = "The next task will be a little harder.\n\nAre you ready?", objectives = "Follow Instructor Windblade.", progress = "I hope I do not need to question your dedication.", completion = "You did better than I expected. Not bad for a new trainee." }
WordHunterWoW_QuestEN[30146] = { title = "Snack Time", description = "Cloud serpents love to eat, and one of their favorite treats is the sugar minnow.\n\nThese fish can be found in salt or fresh water anywhere in Pandaria. I trust you have some skill in fishing, and your own fishing pole to catch them?\n\nBring me a fresh catch and I'm sure the hungry beasts around here will be very grateful.", objectives = "Fish 10 Sugar Minnow from any fresh or salt water in Pandaria.", progress = "Did you find a good place to fish?", completion = "Oh wonderful! These fish will do nicely." }
WordHunterWoW_QuestEN[30147] = { title = "Fragments of the Past", description = "The Order of the Cloud Serpent's history stretches back thousands of years, and although we have tried to preserve the old ways, there are ancient techniques that have been lost over time.\n\nYou can help us recover some of this knowledge by searching Pandaria's dig sites for clues to our past.\n\nUse your archaeology skill to survey around Pandaria and bring me whatever you find.", objectives = "Visit archaeology dig sites around Pandaria and use your survey ability to retrieve 6 Serpentrider Relics.", progress = "How did the excavation go?", completion = "Amazing, <name>. These relics are invaluable to our studies. We will learn much from these fragments." }
WordHunterWoW_QuestEN[30148] = { title = "Just a Flesh Wound", description = "Many of the baby hatchlings at Windward Isle have been injured as a result of all the fighting.\n\nI have been told that you may be able to help them, with your access to powerful bandages.\n\nPlease go northeast and use some of the best bandages you can acquire to save the injured hatchlings.", objectives = "Use Windwool Bandages or Heavy Windwool Bandages to heal 8 Injured Hatchlings at Windward Isle. These can be made by Tailors or bought on the Auction House.", completion = "Wonderful! It is a good thing you are trained in the arts of first aid." }
WordHunterWoW_QuestEN[30149] = { title = "A Feast for the Senses", description = "I have heard that you know a thing or two about cooking.\n\nAs it so happens, serpents love to eat Fish Cakes.\n\nIf you use your culinary skills and bring me 5 of these dishes, the cloud serpents around here will be very happy.", objectives = "Collect 5 Fish Cakes.", progress = "Were you able to find the necessary ingredients?", completion = "Oh these do look quite delicious. You are quite the cook!" }
WordHunterWoW_QuestEN[30150] = { title = "Sweet as Honey", description = "<The hatchling scampers about, then whines and whimpers.>\n\nFrom the cloud serpent's behavior, you have a hunch that it wants a sweet treat.\n\nThe fragrant trees in The Arboretum are home to many honey hives.\n\nIt will be a simple matter to collect combs from the nearby honeykeepers.", objectives = "Collect 30 Honeycomb from Angry Honeykeepers in The Arboretum.", progress = "<The hatchling spins around in glee as you return.>", completion = "The hatchling leaps for your hand. It winds its long, serpentine tail around you and begins to lick the honey from your fingers.\n\nThat tickles!" }
WordHunterWoW_QuestEN[30151] = { title = "Catch!", description = "<The hatchling looks up at you with a bored, listless expression.>\n\nYou have a feeling the serpent is tired of being cooped up all day.\n\n How about playing a little game of catch?", objectives = "Use the Bouncy Ball. Then, catch and return the ball to your hatchling 8 times.", progress = "<The serpent watches you curiously.>", completion = "Oh my, I see you and your serpent are having a great time! Well done, <name>. Playtime will greatly increase your serpent's mental and physical acuities." }
WordHunterWoW_QuestEN[30152] = { title = "The Sky Race", description = "The time for the great race is upon us!\n\nTraverse the course among the spires and pass through the checkered flags on each of the 10 balloon checkpoints.\n\nMake sure to pass underneath the finish line when you are done.\n\nThe competition will be fierce, but I wish you luck. Speak to me when you are ready to begin.", objectives = "Complete the Sky Race by flying through 10 checkpoints, then passing underneath the Finish Line at The Arboretum.", completion = "Wonderful! How does it feel to finish the Sky Race?\n\nYou must be eager to collect your prize!" }
WordHunterWoW_QuestEN[30153] = { title = "Full Speed Ahead", description = "It is time for our training session.\n\nFollow me around the spires. Let's see if you can keep up while staying mounted.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Follow Instructor Windblade." }
WordHunterWoW_QuestEN[30154] = { title = "The Easiest Way To A Serpent's Heart", description = "<The hatchling scowls at you.>\n\nUh-oh, looks like someone is in a bad mood today!\n\nLuckily, you know just the thing that will cheer up the little beast.\n\nCloud serpents love the taste of tiger meat, but the tender flanks can be... challenging... to acquire.\n\nLuckily, you recall there are some fat, juicy tigers to the northeast, on Windward Isle.\n\nSure, you might suffer some scratches and a little mauling, but it's all worth it for your serpent, right?", objectives = "Collect 5 Tiger Flanks.", progress = "Looks like the task is done.", completion = "I see you have been hard at work, gathering food for your hungry little serpent. Well done. It may not seem worth it now, but your serpent will know of your efforts, and it will love you for it." }
WordHunterWoW_QuestEN[30155] = { title = "Restoring the Balance", description = "The situation at the islands remains dire, {name}.\n\nThe Slitherscale saurok have not responded to our attempts at peace, so only one option remains.\n\nIn order to protect the wild cloud serpents, we must rid the island of their presence. Only then can the cloud serpents be left to live in peace.", objectives = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers.", progress = "The poachers will wipe out the cloud serpents completely if they are not stopped.", completion = "If the poachers will not listen to diplomacy, then they will surely listen to our blades. Thank you, <name>." }
WordHunterWoW_QuestEN[30156] = { title = "Feeding Time", description = "<The serpent darts forward and bites your fingers.>\n\nOuch! It seems, without a doubt, that the little beast is hungry. You recall that some meaty-looking turtles can be found on the wild cloud serpent island to the northeast.\n\nPerhaps some turtle meat will fill the hatchling's voracious appetite.", objectives = "Collect 3 Saltback Meat and feed them to your hatchling companion.", progress = "<The serpent looks at you with hungry eyes.>", completion = "You are learning well, young trainer. Saltback meat is tough, but loaded with the nutrients that a young hatchling needs to grow." }
WordHunterWoW_QuestEN[30157] = { title = "Emptier Nests", description = "Oh, thank goodness, another cloud serpent trainer!\n\nI just received word that the wild hatchlings at Windward Isle to the northeast are in serious trouble!\n\nWhile the adults fight those terrible saurok, who is watching the cute little babies? No one, that's who!\n\nWE HAVE TO SAVE THEM!\n\nI'm sending every trainer I can find to go and help. If you aren't too busy, can you make sure the hatchlings are safely delivered back to their mothers' nests?", objectives = "Leash and return 6 Windward Hatchlings to their nests.", completion = "I see you have been taking good care of the young hatchlings out there. Well done." }
WordHunterWoW_QuestEN[30158] = { title = "Disarming the Enemy", description = "If we are to stop the poachers, we need to take more aggressive action.\n\nIf we can remove the enemies' primary tools for killing and capturing serpents, we may be able to stop their operation altogether.\n\nI need you to go into their territory on the eastern end of Windward Isle and steal their weapons.\n\nA cat without claws cannot strike.", objectives = "Collect 5 Slitherscale Harpoons.", progress = "Is it done?", completion = "We have weakened them, but we cannot celebrate completely. A toothless tiger still has claws." }
WordHunterWoW_QuestEN[30159] = { title = "Preservation", description = "Oh no! We must stop them! {name}, is it? The Order needs your help!\n\nDo you know what those horrible Slitherscale saurok are doing?\n\nThey have the audacity to steal cloud serpent eggs straight from the matriarch's nests!\n\nWhile the cloud serpents become ever rarer, those brutes are... are...\n\n<Suchi takes a deep breath.>\n\n...they're eat their eggs for dinner! It's horrible!\n\nGo to Windward Isle to the northeast and recover any unbroken eggs that you can. As students of the Order, it's our duty!", objectives = "Collect 8 Stolen Eggs.", progress = "Will those nasty Slitherscale saurok never give up?", completion = "Well done, <name>. As soon as Suchi told me she sent you to recover the stolen eggs, I knew you would accomplish the task.\n\nOur instructors will make sure to return these eggs to a safer place." }
WordHunterWoW_QuestEN[30160] = { title = "A Ruby Shard for Ella", description = "", objectives = "Why <name>, it's nice to see you again.", progress = "Why <name>, it's nice to see you again.", completion = "Oh, is this for me? I-I don't know what to say.\n\nIt's very pretty, thank you!" }
WordHunterWoW_QuestEN[30163] = { title = "For the Tribe", description = "We fell back to the refuge when the mogu attacked but lost a number of our people along the way.\n\nTravel west and north of here and look for any captives you can rescue that could help us in our fight.\n\nLeave any Alliance you find to their fate.", objectives = "Rescue 8 Dawnchaser Captives.", progress = "Hellscream's eyes upon you.", completion = "We've already lost so many. I refuse to lose any more." }
WordHunterWoW_QuestEN[30164] = { title = "The Stoneplow Convoy", description = "I tried to save as many of the Stoneplow envoys as I could but these \"mantid\" dragged many of them off into the jungle.\n\nThese are civilians in need of our help.\n\nPlease take the herbs you gathered earlier. I've infused them with what gifts of the Light are still granted me. Use them on as many of the Stoneplow envoys as you can.", objectives = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys.", progress = "A sunwalker's first duty is to preserve and protect life.", completion = "The civilians are trickling in thanks to you. These \"mantid\" creatures are a serious threat. We will need to rally our forces soon to help.\n\nOne of the envoys asked me to give this to you as a token of thanks." }
WordHunterWoW_QuestEN[30165] = { title = "Tracking Event: Picked Blue Serpent", description = "", objectives = "" }
WordHunterWoW_QuestEN[30166] = { title = "Tracking Event: Picked Green Serpent", description = "", objectives = "" }
WordHunterWoW_QuestEN[30167] = { title = "Tracking Event: Picked Gold Serpent", description = "", objectives = "" }
WordHunterWoW_QuestEN[30168] = { title = "Thieving Raiders", description = "Saurok!\n\nThese vile creatures are obsessed with killing and stealing. They attacked our settlement without provocation or warning.\n\nPlease, {class}, can you aid us?\n\nHelp us recover our lost possessions from these Riverblade raiders that march along the river and we will gladly reward you.", objectives = "Recover 5 pieces of Pillaged Jinyu Loot.", progress = "I think they even stole my holy spittoon.", completion = "Not many would stop to help a village in need... especially so deep in the wilds.\n\nYou are a champion to our people, <name>." }
WordHunterWoW_QuestEN[30169] = { title = "Raid Leader Slovan", description = "The raiders are led by a particularly violent saurok known as Slovan. The Crane Temple usually comes to our aid when he attacks but now we find ourselves outmatched and outmaneuvered.\n\nPlease, {class}, aid us by destroying this raid leader.\n\nYou can find him in his den behind the Krasari Falls.", objectives = "Kill Slovan.", progress = "Slovan has always been a nuisance, but with the Crane Temple's defenses down he has become a true threat.", completion = "You have done us a great service today. On behalf of my people I thank you.\n\nPlease, accept this token of our gratitude." }
WordHunterWoW_QuestEN[30172] = { title = "Barreling Along", description = "No, no, no, don't you worry about pickin' 'em up. I can hold these here barrels.\n\nI may not be the handsomest pandaren, or the smartest, or any fun to be around in the slightest, but I'm stronger than a mushan beast.\n\nI'mma just need you to lead the way.", objectives = "Lead Mudmug back to Halfhill.\n\nIf you become separated from Mudmug, you can find him next to the giant banana in the Gilded Fan.", progress = "Where's Mudmug?", completion = "Good! The water's here!" }
WordHunterWoW_QuestEN[30173] = { title = "War Pigs!", description = "", objectives = "" }
WordHunterWoW_QuestEN[30174] = { title = "For Family", description = "Kor should have caught up by now. He said he was going to secure the Ruins of Korja east of here and meet us to help with the mantid threat.\n\nHe may need help against Groundbreaker Brojai. Could you assist him? Kang and I will follow shortly.", objectives = "Search for Kor Bloodtusk.", progress = "This land claims so much.", completion = "I thank you for avenging my friend, <name>. We did not always see eye to eye, but I will mourn him.\n\nI know he would have wanted you to carry one of his items with you as a token of his memory and gratitude." }
WordHunterWoW_QuestEN[30175] = { title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", objectives = "Kill 10 Ik'thik Precursors.", progress = "It has been many thousands of years since mantid were seen on this side of the Great Wall.", completion = "Thank you for your help, <class>! I've never seen anybody stand up to the mantid like that before.\n\nWell, other than the Shado-Pan, of course..." }
WordHunterWoW_QuestEN[30177] = { title = "Daily Heroic Random (1st) (Cataclysm)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30178] = { title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone south. When you reach the temple, find Koro Mistwalker.", objectives = "Locate the missing Zhu's Watch Courier in the southern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker.", completion = "I see... And the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Watch, I have to implore you to help us deal with them here." }
WordHunterWoW_QuestEN[30179] = { title = "Poisoned!", description = "The... mogu. Do not trust. Poison. Get sample... sample blades. Bring to Dezco... in Thunder Cleft, west of here.", objectives = "Gather 5 Mogu Poisoned Blades.", progress = "You have news of Chezin?", completion = "Chezin is dead? This is very bad news indeed. Kor, Chezin and I have fought dragons, undead, and Alliance on nearly every shore that has a name.\n\nTo lose him like this...\n\nThank you for recovering these weapons. It should teach us much about our new enemy." }
WordHunterWoW_QuestEN[30180] = { title = "Labor for Labor", description = "My wife, Leza, is going into labor but she is very very sick. I need to keep her warm but we've exhausted our supply of dry firewood.\n\nCould you grab some twigs and branches from the nearby trees for me? Time is of the essence!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather 8 pieces of Fire Wood." }
WordHunterWoW_QuestEN[30181] = { title = "Mushan Mastery", description = "Mushan! Would ya look at the size o' 'em. Old as the dirt they walk on probably. A fine trophy.\n\nIf you are lookin' to test your mettle as a big game hunter, start with them.", objectives = "Kill 15 Dustback Mushans.", progress = "They didn't send ya' runin' did they?", completion = "Well done <name>.\n\nMy father travels across the sea to a new continent and all he can seem ta' want to hunt is old borin' wolves.\n\nMe, I like to hunt stuff with meat on its bones." }
WordHunterWoW_QuestEN[30182] = { title = "Fox Mastery", description = "So, when I was scouting east of here I saw a collection of foxes. That's what I first learned to hunt when back on the Wandering Isle.\n\nIf you want to see the challenge a young pandaren hunter faced when growing up, head east and face off against a bunch of foxes. They tend to be clever and cunning so be on your guard. ", objectives = "Kill 15 Sly Foxes.", progress = "I used to go on fox hunts with my father. If he could see me now! Hunting in Pandaria!", completion = "Well done! You outfoxed the foxes. I will talk to Mr. Pleeb about getting you another trophy made." }
WordHunterWoW_QuestEN[30183] = { title = "Stalker Mastery", description = "Tigers! No matter what land I go to I hear about these big fanged beasts. And yet I haven't had a chance to hunt any of them.\n\nLet's go hunt some tigers. I'll go east, you go west. I think I saw some near Dustback Gorge. I'm sure there are tons near those mushan.", objectives = "Kill 15 Gorge Stalkers.", progress = "What's your count up to?", completion = "Wow! You really racked up a count. I'll chat with Mr. Pleeb about getting the best one converted to a trophy for you." }
WordHunterWoW_QuestEN[30184] = { title = "Mushan Mastery: Darkhide", description = "My boy here is a talented hunter... in training. Let's show him an old 'Nessy style hunt shall we?\n\nI saw a mighty big mushan east of here with a hide dark as night. It looked like it had taken down a number of hunters in its day.\n\nIf you want a big game hunt, go try an' take it on.", objectives = "Obtain Darkhide's Head.", progress = "Puttin' the \"big\" into \"Big Game Hunter.\"", completion = "Now that's a proper trophy right there." }
WordHunterWoW_QuestEN[30185] = { title = "Tortoise Mastery", description = "Granted, tortoises are not big game but they can be mean game. They also work as the perfect bait for bigger game!\n\nGotcher found some ol' tablets sayin' that the Torjari Pit is a sacrificin' site. The old empire used ta' feed unruly sorts to the waters as it were.\n\nWell ah mean to see me what's down in that water. Gather up some fresh tortoise shells and meet me at the pit.\n\nLet's see if ol' legends be true.", objectives = "Gather 5 Intact Tortoise Shells.", progress = "I've always been livin' in me father's shadow. But after today, folks are gonna remember the name of Nesingwary, Jr.!", completion = "Thank ye. This one aught ta' one up me pop." }
WordHunterWoW_QuestEN[30186] = { title = "Parental Mastery", description = "If them tablets were correct, all ay got ta do is a small dance ritual and the big thing o' the deep will be summoned.\n\nWhen it comes out, we'll get 'em and show me pop we are both true big game hunters like him.", objectives = "Destroy Torjar's Bane.", progress = "Now that is how ya big game hunt.", completion = "You saved me son! I canno' ever thank ye enough. Please! Take this fer your efforts." }
WordHunterWoW_QuestEN[30187] = { title = "Flight Training: In Due Course", description = "Now that you have learned the basics of the race, you should go learn the course.\n\nExplore the spires and collect a race flag from each of the checkpoints.\n\nFly through each checkered flag to collect it.", objectives = "Fly through 10 Race Flags at the Checkpoints floating above the Mistveil Sea.", progress = "Do you have what it takes to compete... and win?", completion = "Well done. If you hadn't been capable of finding the checkpoints, I fear you would never have done well in the Sky Race." }
WordHunterWoW_QuestEN[30188] = { title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", objectives = "Join the Order of the Cloud Serpent.", completion = "Today, we become brethren. Congratulations on joining the Order of the Cloud Serpent. Let us ride together!" }
WordHunterWoW_QuestEN[30189] = { title = "A Lovely Apple for Ella", description = "", objectives = "How are you today, <name>?", progress = "How are you today, <name>?", completion = "Really? For me?\n\nSuch a lovely apple shouldn't be eaten alone.\n\nHere, please have half." }
WordHunterWoW_QuestEN[30190] = { title = "Sprite Plight", description = "Sprites again! I hate these things. We need to stop them before they hurt someone or burn down half of the village!\n\nIf you see any of the pests, please deal with them! ", objectives = "Kill 8 Slateskin Troublemakers.", completion = "We need to figure out where these things are coming from. We're dealing with this near daily and it's getting out of hand.\n\nThank you for your help." }
WordHunterWoW_QuestEN[30191] = { title = "Steer Clear of the Beer Here", description = "Someone left some beer out up on the southern rise and now the sprites have developed a taste for our brew. They've been sneaking into town all morning, stealing whatever kegs they find.\n\nBring back what you can. A pandaren worker without brew is just... it won't be very productive. We need the men in good spirits.", objectives = "Recover 10 Stolen Mistfall Kegs.", progress = "Did you find any of the stolen kegs?", completion = "The workers will love you for this!" }
WordHunterWoW_QuestEN[30192] = { title = "My Town, It's on Fire", description = "I don't know if you noticed, but my town is burning...\n\nThe sprites have started kicking the braziers! They're going to set fire to the whole town!\n\nPlease help us! Stamp out any fires you see!", objectives = "Put out 30 Brazier Fires.", completion = "I really wish you guys would stop throwing the buckets at the fire too� just the water would have been fine.\n\nReally though, it's a relief that you're here to help. Thank you." }
WordHunterWoW_QuestEN[30193] = { title = "Meating Expectations", description = "Hard workers deserve hearty meals, but I'm all out of good meat!\n\nCan you head out into the forest and get me some fresh gazelle meat?", objectives = "Retrieve 10 slabs of Fairlands Gazelle Meat.", progress = "No shortage of mouths to feed, that's for sure!", completion = "Doesn't get much fresher! Thank you, <class>." }
WordHunterWoW_QuestEN[30194] = { title = "Encroaching Storm", description = "The villagers have lost another yak this morning to one of the thundermaw wolves from across the river. The wolves grow bold.\n\nThis is a sign that they are breeding beyond the vale's ability to sustain them. It's time to thin their numbers again.\n\nIf you are willing to aid me in this, you would have my sincere appreciation.", objectives = "Kill 8 Thundermaw Wolves.", completion = "Your act is one of a responsible hunter. I respect you for it." }
WordHunterWoW_QuestEN[30195] = { title = "Blooming Blossoms", description = "Would you do a humble merchant a favor? I've been needin' to refresh my stock of eternal blossoms. They grow in the woods nearby.\n\nCould you help me out, perhaps?", objectives = "Collect 10 Eternal Blossoms.", progress = "Was your flower-gathering bountiful?", completion = "Aha! You are quite the kind patron.\n\nThank you... thank you." }
WordHunterWoW_QuestEN[30196] = { title = "Lushroom Rush", description = "Building a new village makes for hungry workers it seems!\n\nI have a hearty stew recipe prepared, but I need some lushrooms from the Tu Shen Burial Ground to the east. Apparently there are roused spirits causing trouble up there though, and I'm not very well suited for the violent life.\n\nIf you're heading up the burial grounds today, could you collect some lushrooms for me?", objectives = "Collect 12 Lushrooms.", progress = "I can hear the hungry bellies rumbling throughout the village!", completion = "Good timing! The stew's almost ready.\n\nYou have my thanks." }
WordHunterWoW_QuestEN[30197] = { title = "Cart Ride", description = "The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Ride a delivery cart to XXX Village.The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30198] = { title = "NOT USED", description = "", objectives = "" }
