WordHunterWoW_QuestEN[30200] = { title = "In Ashen Webs", description = "We used to have the trainees clear out the ruins of spiders as part of their training, but now we send them straight to the mogu front. The spiders have gotten out of control.\n\nCare to put things back in control?", objectives = "Kill 8 Ashweb Spiders.", completion = "You're quicker than the trainees, but I would have been disappointed if you weren't. Thanks." }
WordHunterWoW_QuestEN[30201] = { title = "NOT USED", description = "", objectives = "" }
WordHunterWoW_QuestEN[30202] = { title = "NOT USED", description = "", objectives = "" }
WordHunterWoW_QuestEN[30203] = { title = "NOT USED", description = "", objectives = "" }
WordHunterWoW_QuestEN[30204] = { title = "That's Not a Rock!", description = "Okay, these spiders are seriously creeping me out. Especially those egg sacs they leave lying around that I keep accidentally stepping on only to be covered in very little but very creepy spiderlings. Ug, makes me shudder just thinking about it.\n\nI say you burn them. Burn them all.", objectives = "Kill 50 Ashweb Spiderlings. Use Kun's torch to burn them inside their pods.", completion = "Thank you. I'd say I have about a week of Anji making fun of me for the screaming, and then I should be in the clear." }
WordHunterWoW_QuestEN[30205] = { title = "Runelocked", description = "Hello, friend.\n\nOne of Leven's men brought word to me of a mogu artifact in the eastern ruins, but said he couldn't figure out how to retrieve it. I suspect it's guarded by one of their rune locks.\n\nIf you go to the artifact, you should find four runes somewhere nearby that when activated will release the lock. If you could bring the artifact back to me, I would be very grateful.", objectives = "Retrieve the Ancient Mogu Artifact.", progress = "Did you find the runes I was telling you about?", completion = "This is marvelous... very well perserved. Thank you very much, friend! I owe you for this." }
WordHunterWoW_QuestEN[30206] = { title = "Runes in the Ruins", description = "In the walls of the ruins themselves, there are precious runestones that we can make use of back in the eastern vale.\n\nIf you see any while you are within the ruins, would you be so kind as to bring them back to me?", objectives = "Collect 12 Guo-Lai Runestones.", progress = "These runestones were used as sources of power long ago, when the mogu still ruled the vale.", completion = "These are lovely! Thank you, kind <class>." }
WordHunterWoW_QuestEN[30207] = { title = "Tracking Event: 1st Place", description = "", objectives = "" }
