WordHunterWoW_QuestEN[30225] = { title = "The Ashweb Matriarch", description = "My dear Kun spotted more spiders pouring out of the Guo-Lai Halls this morning, and when he went to investigate, he uncovered another spider matriarch inside.\n\nI need you to kill it.", objectives = "Kill Bloodtip, the Ashweb Matriarch.", completion = "You've got a follow-through I can respect, <class>. Thanks." }
WordHunterWoW_QuestEN[30226] = { title = "Blood on the Rise", description = "A small group of mogu have been sighted on Ruin's Rise, to the north.\n\nExtinguish them.", objectives = "Kill 8 Shao-Tien mogu on Ruin's Rise.", completion = "As it should be. Thank you." }
WordHunterWoW_QuestEN[30227] = { title = "Wulon, the Granite Sentinel", description = "One of the quilen statues in Guo-Lai Halls came to life and nearly killed my precious Kun. I won't have it! No one threatens my Kun.\n\nI want you to go in there and smash the thing to pieces. I'd do it myself, but I need to attend to my lover's wounds first.", objectives = "Kill Wulon, the Granite Sentinel.", completion = "Thanks. I owe you one, <class>." }
WordHunterWoW_QuestEN[30228] = { title = "Troubling the Troublemakers", description = "The wood sprites are back. I need you to kill them before they cause anymore trouble.", objectives = "Kill 8 Stonebark sprites.", completion = "Some peace and quiet. Thank you." }
WordHunterWoW_QuestEN[30229] = { title = "The Greater Danger", description = "I apologize for my harsh words earlier. Dezco might have been right to wait and move west with a unified strength.\n\nThe mogu hit us hard when we were searching the ruins west of here. They ambushed us using summoning portals and some dark magics. I haven't seen such evil sorcery used since Outland. \n\nWe need a respite. Head west, kill their summoners, cut their supply line.", objectives = "Kill 8 Korjani Reclaimers.", progress = "Did you break their reinforcements?", completion = "With their reinforcements severed we can begin to mount an offensive against their Lord Reclaimer." }
WordHunterWoW_QuestEN[30230] = { title = "Re-Reclaim", description = "Mogu are thugs. They have always been thugs.\n\nOnly when they ruled their empires in the old stories did they ever know any kind of magic.\n\nBut these mogu are using arcane portals and spells. We need to stop them!\n\n{name}, look for any artifacts the mogu are using to cast their magics with. I saw a number of their collectors and reclaimers to the west and north that were gathering these items.", objectives = "Recover 10 Mogu Artifacts.", progress = "Every artifact in our possession is one less weapon in mogu hands.", completion = "Well done <name>. You have removed the sword from the child's hands." }
WordHunterWoW_QuestEN[30231] = { title = "Pomfruit Pickup", description = "I need more pomfruit! Go knock some loose from the trees for me, would you?\n\nTake this, I use it when I go harvesting. Things go quicker when the fruit comes to you!", objectives = "Gather 12 Pomfruit.", progress = "I always misjudge how much juice I can get out of these things.", completion = "Delicious! I am indebted to you, my friend." }
WordHunterWoW_QuestEN[30232] = { title = "Ruffling Some Feathers", description = "The hawk numbers in the vale are thriving. This is opportune for our fletchers, for we will need a great number of feathers if we are to keep the archers upon the wall stocked with arrows.\n\nIf you would not mind, could you aid us in gathering these feathers?", objectives = "Gather 80 Silken Feathers.", progress = "I hesitate to continually ask such menial things of one so accomplished as you, but we are in desperate times.", completion = "You have my most gracious thanks, young one." }
WordHunterWoW_QuestEN[30233] = { title = "Cracklefang", description = "Hi! So, I have a dilemma. I've only got one good wolf name.... wait for it... Cracklefang! I know, amazing right?! But now there are TWO big nasty wolves in the forest, which is all kinds of confusing.\n\nI need you to kill one of them so I can free up the name. Should be simple enough, yeah? Especially for someone of your incredibleness.\n\nSo, are you on board? I'm hoping for yes!", objectives = "Kill Cracklefang.", completion = "Yes! Only one Cracklefang remains to terrorize the goats and yaks of the Vale of Eternal Blossoms. As it should be! Thank you for that!\n\nI sure hope no more big nasty wolves turn up. I really don't think I'm going to be able to come up with another name that can live up to that one." }
WordHunterWoW_QuestEN[30234] = { title = "Vicejaw", description = "Vicejaw! Sounds absolutely violent, does it not? I came up with it myself, and I think it's very suiting. I tried to wrestle my staff away from him for hours, but he simply would not let go!\n\nOkay, it was really more like a few seconds. I like to be truthful to my friends, even if it makes my stories significantly more boring.\n\nAnyway, would you be so kind as to release your oh-so-potent wrath upon this crocolisk with a vice-like jaw, and then kindly bring my staff back? Preferably in-tact!", objectives = "Kill Vicejaw and return Ren's Longstaff.", completion = "My staff! My gorgeous staff! We shall never part again. I shall lean on you, and you will always be there. And I promise not to poke crocodiles with you anymore.\n\nThank you, friend. Your staff retrieval skills have proved invaluable today!" }
WordHunterWoW_QuestEN[30235] = { title = "Quid Pro Quo", description = "Quid is a very powerful and very ancient water spirit, though you might not know it with his child-like ways.\n\nThis morning, Quid nearly killed several villagers in the bar when he jokingly caused several of the water kegs to explode.\n\nAs long as the water flows, Quid will remain. He cannot be slain. But he can be reminded that we do not take his dangerous antics in jest.\n\nWould you be willing to carry this message to him on behalf of the village?", objectives = "Defeat Quid, the Spirit of the Misty Falls.", completion = "For the sake of the villagers, I hope he remains at bay for some time.\n\nThank you, my friend." }
WordHunterWoW_QuestEN[30236] = { title = "Aetha", description = "It seems Aetha has been levitating the livestock and dropping them into the river again. The mayor has requested that we remind her that these kinds of jokes are not welcomed.\n\nWould you be so generous as to travel to the ridge above the village and teach her this lesson? You cannot kill her, you can only send her away for a time, but this should prove a potent reminder.", objectives = "Defeat Aetha, the Spirit of the Golden Winds.", completion = "The spirits may be childlike, but they possess generous mounts of strength for their size. Your victory is no small thing, and is very appreciated." }
WordHunterWoW_QuestEN[30237] = { title = "The Pandaren Uprising Relived", description = "In the Tu Shen Burial Ground to the east, the spirits of ancient mogu are locked in battle with the spirits of our pandaren ancestors that rose up against them. The spirits have seen no rest since the return of the mogu to the valley.\n\nIf you would be willing to go to the graveyard and force the mogu to relive their defeat again, we might offer some lasting peace to the spirits of our ancestors.", objectives = "Kill 8 Ancient Mogu Spirits.", completion = "The spirits of the pandaren monks seem invigorated by the deaths of their mogu oppressors.  It is a small victory, but it shows respect to great heroes of the past." }
WordHunterWoW_QuestEN[30238] = { title = "Return to Rest", description = "The spirits of our ancestors are reliving one of the most revered battles in our history at the Tu Shen Burial Grounds to the east.\n\nDo as I ask, {race}, and honor their gravestones. Remind them that they are respected even these many years later, and that they are deserving of peaceful rest.", objectives = "Honor 6 Pandaren Gravestones.", completion = "Thank you, my friend. You respect for our ancestors means a great deal." }
WordHunterWoW_QuestEN[30239] = { title = "Lao-Fe the Slavebinder", description = "You can hear the spirit of Lao-Fe, the Slavebinder shouting taunts from the cave at the top of Tu Shen Burial Mound.\n\nDefeating him will surely serve to ensure victory for the spirits of the pandaren monks.", objectives = "Kill the Spirit of Lao-Fe, the Slavebinder.", completion = "Lao-Fe the Slavebinder was one of the most spiteful and vicious mogu of his time. May defeating his spirit act as a reminder to all the mogu in the vale of the fate that awaits them if they seek to defile the sacred pools again.\n\nYour strength is unquestionable. You have my respect, <class>." }
WordHunterWoW_QuestEN[30240] = { title = "Survival Ring: Flame", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", objectives = "Enter the Survival Ring and survive for 60 seconds without leaving.", progress = "The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", completion = "Not bad, <class>. Not bad at all." }
WordHunterWoW_QuestEN[30241] = { title = "Warn Stoneplow", description = "So much death. And more to come, if Ambassador Han's stories of the mantid are to be believed.\n\nWe must help. We must do our part to save lives.\n\nTravel to Stoneplow. Warn them of the coming mantid attack.\n\nI will join you with what forces I can muster once I have laid Kor's body to rest.", objectives = "Travel to Stoneplow Village in Valley of the Four Winds.", completion = "Mantid from the south? This is not a good day." }
WordHunterWoW_QuestEN[30242] = { title = "Survival Ring: Blades", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", objectives = "Enter the Survival Ring and survive for 60 seconds without leaving.", progress = "The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", completion = "Not bad, <class>. Not bad at all." }
WordHunterWoW_QuestEN[30243] = { title = "Mantid Under Fire", description = "The mantid are attacking again, and we're a bit short-handed up on the wall. In hopes that you'd help, I saved one of the more fun posts for you: the hot oil!\n\nIt's a bit more violent and a bit less scandalous than it sounds.\n\nIt's simple really. Get up on the wall, find one of the oil stations, and dump it on any of the mantid pouring up against the wall. It's very effective.", objectives = "Use a Hot Oil Cauldron to kill 80 mantid near the Gate of the Setting Sun.", progress = "The hard part is the cleanup. Fortunately, you're not responsible for that.", completion = "You've done devastating damage to the mantid forces. The wall defenders should be able to get things under control." }
WordHunterWoW_QuestEN[30244] = { title = "Along the Serpent's Spine", description = "There are mantid on top of the wall. The defenders on the ramparts are calling for help!", objectives = "Kill 10 Krik'thik mantid on the Gate of the Setting Sun.", completion = "The mantid forces on the wall have been thinned." }
WordHunterWoW_QuestEN[30245] = { title = "Lost Scouts", description = "We sent some scouts towards the Five Sisters to the north to try and find whatever mogu leader has risen up to direct their movements in the valley. Few have returned.\n\nI'd like to think they're just off downing too much ale or being irresponsible with some young pandaren, but they may actually be in some trouble.\n\nCan you scout for the scouts? And see if they've turned up any information on that leader while you're at it?", objectives = "Recover 3 Shado-Pan Scout reports.", completion = "The scout reports have pinpointed the mogu leader's position." }
WordHunterWoW_QuestEN[30246] = { title = "Upon the Ramparts", description = "Some of the mantid have made it on top of the wall. There's some risk they'll route the soldiers we have posted there if their numbers are large enough.\n\nI need you to get on top of the wall and help clear out any that have broken through.", objectives = "Kill 10 Krik'thik mantid on top of the Gate of the Setting Sun.", completion = "The mantid forces on the wall have been thinned." }
WordHunterWoW_QuestEN[30247] = { title = "Roll Club: Vale of Eternal Blossoms", description = "Follow the flags. Make the checkpoints. Round the loop. Get back to me before your time is up.\n\nSpeak to me when you're ready to roll.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Complete the Vale of Eternal Blossoms roll course." }
WordHunterWoW_QuestEN[30248] = { title = "The Butcher", description = "Scouts reports place the displaced Shao-Tien Imperion at the north end of the wall.\n\nAngi Autumnlight spelled out your goal in no uncertain terms: find this leader and kill him.", objectives = "Kill Bai-Jin the Butcher.", completion = "Look at you! All proactive and assertive. Looks good on you." }
WordHunterWoW_QuestEN[30249] = { title = "Under the Setting Sun", description = "A giant beast has burrowed under the gate into the courtyard. The defenders need your help!", objectives = "Kill Kri'chon, the Corpse-Reaver.", completion = "I heard you performed some heroics in the courtyard! Your name will be remembered on the wall for some time. Well done, <name>." }
WordHunterWoW_QuestEN[30250] = { title = "Survival Ring: Thunder", description = "This is one of the challenges I put upon my warriors during peaceful times to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 90 seconds without getting pushed out or killed. Stay on your toes.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter the Survival Ring and survive for 90 seconds without leaving." }
WordHunterWoW_QuestEN[30251] = { title = "Vyraxxis, the Krik'thik Swarm-Lord", description = "A giant mantid is terrorizing the inside of the wall. It seems doubtful that the defenders will be able deal with it without you.", objectives = "Kill Vyraxxis, the Krik'thik Swarm-Lord.", completion = "I like your initiative. Good work." }
WordHunterWoW_QuestEN[30252] = { title = "A Helping Hand", description = "I've been pushing and shoving and hammering all morning, but it's hopeless.\n\nThese rocks won't budge!\n\n\"It will be a breeze,\" Grandpa said. \"Farming's like breathing!\" he said. Maybe for him, but not for me!\n\nHow am I supposed to succeed at this whole FARMING thing if I can't even clear my farm for planting?\n\nHey, wait a minute. You look like you've got some muscle on you.\n\nWould you be willing to help me out? Just until I can catch my breath.", objectives = "Destroy 8 Unbudging Rocks.", progress = "I really wasn't cut out for this type of work. I didn't exactly grow up in the country.", completion = "What? You cleared the rocks? That's great news!\n\nMaybe now I can actually start growing something on this farm!" }
WordHunterWoW_QuestEN[30253] = { title = "The Family Farm", description = "D-did you hear what they said?\n\nIt's almost like they don't want me here. Like...I'm not good enough.\n\nSure I've never run a farm before, but I know how to plant a seed and how to pick a turnip.\n\n<Farmer Yoon's eyes light up.>\n\nYou know what? I'm going to show them that I can also become a master farmer!\n\nI'm going to turn this farm into one of the most prosperous in the Valley!\n\nIt's too much work for one pandaren, though. Come on! Will you help me?Upon completion of this quest you will gain:", objectives = "Join Farmer Yoon." }
WordHunterWoW_QuestEN[30254] = { title = "Learn and Grow II: Tilling and Planting", description = "Okay, now we've got our seeds, it's time to plant them.\n\nFirst, we have to prepare the soil! You gotta till the soil and break it up to make a nice bed for our little sprouts.\n\nTill those two plots of soil over there, then plant the seeds in them.", objectives = "Till 2 plots of Untilled Soil to create Tilled Soil. Then, use the EZ-Gro Green Cabbage Seeds on 2 plots of Tilled Soil.", completion = "Nicely done.\n\nNotice how those seeds sprouted immediately? That's part of what makes this valley so ideal for farming - something about the soil here just makes veggies grow like crazy!\n\nThe work's not done yet, though." }
WordHunterWoW_QuestEN[30255] = { title = "Learn and Grow III: Tending Crops", description = "My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on her and take her to market to show her off to your frie-\" look, he was from a different time, okay?\n\nThe point is, now that our cabbages have sprouted, they need attention! Today they look a little dry, so you should water them.\n\nHere's the old watering can grandpa left. It will always be near the field if you need it.", objectives = "Use the Rusty Watering Can to water 2 Parched EZ-Gro Green Cabbages at Sunsong Ranch.", progress = "Come to think of it, grandpa said a lot of really offensive things.\n\nMaybe I should avoid quoting him from now on...", completion = "Great, the cabbages are tended and looking good!\n\nToday they were thirsty, but you never know what they might need. Pay close attention to your crops and tend them accordingly.\n\nI got all kinds of advice from my grandpa, so if you're ever unsure of how to take care of something, feel free to ask!\n\nJust make sure it's strictly related to farming..." }
WordHunterWoW_QuestEN[30256] = { title = "Learn and Grow IV: Harvesting", description = "It's time for our hard work to pay off! Normally we'd have to wait a day before the crops are ready to harvest.\n\nFortunately, those seeds Greenfield gave us were specially designed to grow FAST. The yield won't be worth much, but they're good for stepping new farmers through the process.\n\nOur cabbages should be ready to harvest. I'll let you do the honors, of course!", objectives = "Harvest 2 EZ-Gro Green Cabbages from your field and bring them to Farmer Yoon in Sunsong Ranch.", progress = "Look at those... err, what do they say around here? Oh yeah, b'yoots!\n\nLook at those b'yoots!\n\nI think I'm getting the hang of this farmer thing.", completion = "Well, those are the basics!\n\nTill the soil, plant the seeds, tend to any threats, then wait for the results!\n\nToday was easy, but stay on your toes: my grandfather told me all kinds of crazy stories about farming at Sunsong Ranch.\n\nFarming ain't all giant turnips and roses, you know." }
WordHunterWoW_QuestEN[30257] = { title = "Learn and Grow V: Halfhill Market", description = "All right friend, all of that farming was just for practice!\n\nAre you ready to try the real thing?\n\nThere's a lady by the name of Gina Mudclaw who runs the Halfhill Market, which is across the street to the south.\n\nI heard she's looking to buy some vegetables. Since it's your first time meeting her, you shouldn't go empty-handed.\n\nWhy don't you look around the ranch and see if there are any items hiding around?\n\nMight be that we'll find a good gift to take to our new neighbor!", objectives = "Investigate the Dark Soil underneath Farmer Yoon's house, then give a gift to Gina Mudclaw at the Halfhill Market.", progress = "Hey, haven't seen your face around here before! What's your name?", completion = "Oh my, a marsh lily!\n\nHow did you know that these are my favorite? I just might take a liking to you, stranger.\n\nThank you!" }
WordHunterWoW_QuestEN[30258] = { title = "Mung-Mung's Vote I: A Hozen's Problem", description = "I've been thinkin' about how to get into the Tiller's good graces, {name}.\n\nNow, the Tiller's Union accepts new farmers each year, and there are five members on the voting council.\n\nWe already got Gina's vote, but we'll have to prove ourselves to the other four members of their board.\n\nWhy don't you go over and say hello to Mung-Mung? He works with Mr. Mudclaw out on the Mudclaw's farm to the northwest.", objectives = "Speak to Mung-Mung at Haohan Mudclaw's House in the Valley of the Four Winds.", completion = "Yes?" }
WordHunterWoW_QuestEN[30259] = { title = "Mung-Mung's Vote II: Rotten to the Core", description = "Dem virmen's back!\n\nThey been biting Mr. Mudclaw's carrots. Ruining his crop. And who is gonna pay? Mung-Mung, that's who!\n\nYou go get the chewed up carrots before Mr. Mudclaw sees. They all over the fields to the southwest, and down under the ground in the virmen's tunnels, too.\n\nOtherwise, Mung-Mung in big trouble.\n\nYou do this for me?", objectives = "Collect 10 Partially Chewed Carrots.", progress = "I don't see no chewed up carrots. You don't see no chewed up carrots. Mr. Mudclaw never know, okay?", completion = "What do you mean, no virmen chewed them up? Teeth marks too small? WHAT? Then who else do this?" }
WordHunterWoW_QuestEN[30260] = { title = "Growing the Farm I: The Weeds", description = "Hey {name}, I've been thinkin' recently about expanding my farm.\n\nSee that plot there that's just covered in weeds? If we can get rid of those weeds, we could use that land for planting.\n\nI heard there's a farmer by the name of Gai Lan who knows a thing or two about weed whackin'.\n\nHis farm is just out west. Go talk to him and see if he'd be willing to help us.", objectives = "Speak to Gai Lan at The Heartland in the Valley of the Four Winds.", completion = "Oh yeah, Farmer Yoon. I've seen him around town.\n\nSeems like a nice enough fella." }
WordHunterWoW_QuestEN[30261] = { title = "Roll Club: Serpent's Spine", description = "Get to the bottom of the wall in the fastest time possible.\n\nSpeak to me when you're ready to roll.", objectives = "Complete the Serpent's Spine roll course.", progress = "Ready to roll?", completion = "When they built the wall, I don't think they knew we'd be using it for this." }
WordHunterWoW_QuestEN[30262] = { title = "NOT USED", description = "", objectives = "" }
WordHunterWoW_QuestEN[30263] = { title = "Clearing in the Forest", description = "The Shao-Tien are on their heels. Most of them retreated to Winterbough Glade after their last defeat. We should press the advantage.\n\nTake the fight to these mogu in the clearing to the northwest. Let us leave them no minute of rest as long as they remain in the Vale.", objectives = "Kill 6 Shao-Tien mogu in Winterbough Glade.", completion = "We must seize our advantage when an opportunity presents itself. We must make the Shao-Tien pay for every moment they remain in the Vale.\n\nYou've done well this day, <class>." }
WordHunterWoW_QuestEN[30264] = { title = "Enemy at the Gates", description = "The mantid forces are pouring against the wall. I've arranged for some flying serpents to cut away at their forces from the air.\n\nWould you be willing to take the reigns on one of them?", objectives = "Use a Shado-Pan Sky Serpent to kill 60 Krik'thik attackers, 3 Krik'thik War Wagons, and 3 Krik'thik Catapults.", completion = "Kun tells me you were amazing out there. You impress my man, you impress me.\n\nGood work." }
WordHunterWoW_QuestEN[30265] = { title = "Sparkle in the Eye", description = "I've been staring down into the waters of the lake, pondering life, love, and everything beautiful, and suddenly I realized that the sparkles in the water aren't just a reflection of my radiant personality, there are actually some sort of shining objects down there! Surely valuable.\n\nWould you mind taking a drip and relieving the lake's depths of its mysterious sparkles? Pretty please?", objectives = "Recover 8 Shining Rubies.", progress = "What were these mysterious sparkles? I've been dying with curiosity. Coins? Goblets? A dozen discarded wedding rings?", completion = "Rubies! Valuable, yes! Suggestive of an interesting backstory involving a dozen broken-hearted brides? Likely not. Still, quite the find!\n\nThank you my marvelously benevolent friend! You have saved me some awkwardly wet robes with your generous aquatic ways." }
WordHunterWoW_QuestEN[30266] = { title = "Bloodied Skies", description = "We have cannons set up on the top of the towers flanking the main gate. They are our best method to clear the skies when the flying mantid try to pass over the wall, like they are now.\n\nLooks like you're on, {name}.", objectives = "Kill 30 Krik'thik Swarmers using a Setting Sun Turret.", completion = "You've got good aim, <class>. I'll remember that the next time the fliers come." }
WordHunterWoW_QuestEN[30267] = { title = "Watery Woes", description = "I love fishing. I'd be enjoying myself much more, however, if I had my bait and my lures. They were thrown away in a... a misunderstanding with my wife, Rin.\n\n<Gladecaster Lang sighs.>\n\nShould I let a whole day of fishing be ruined, just because of a little domestic squabble? No! All I need is bugs and feathers, after all, and this glade is filled with those two things.\n\nCare to help a fisherman out?", objectives = "Obtain 18 Glade Glimmers and 5 Spindly Bloodfeathers.", progress = "I refuse to not fish. Fishing's who I am!", completion = "Finally, someone who understands me. Fishing is what it's all about, right?\n\nMaybe I should leave New Cifera... just pack up my things and join the Anglers, down in the south. Of course, I couldn't leave my family behind...\n\nBut still... a pandaren can dream, right?" }
WordHunterWoW_QuestEN[30268] = { title = "The Murksweats", description = "Take a good look. The river nearby is swarming with these snakes. Their venom causes a condition the locals call \"the murksweats.\"\n\nSeveral refugees were bitten as they fled the temple and have already begun to show symptoms: nausea, vomiting, and intense sweating as the body rejects all fluids, causing dehydration and potentially death.\n\nWe are administering anti-venom as quickly as possible, but we'll need more venom glands. Don't bother removing the glands yourself - just bring back the whole head.", objectives = "Gather 6 Murkscale Heads from Murkscale Strikers in Krasarang River.", progress = "<Anduin is focused intently on his hands, swiftly carving venom glands from the snakes.>\n\nInside the jaw... two inches behind the second set of fangs...", completion = "Thank you, <class>. I knew you'd be hardy enough to handle it.\n\nJudging by the sounds coming out of these refugees, I would not wish the murksweats on my worst enemy." }
WordHunterWoW_QuestEN[30269] = { title = "Unsafe Passage", description = "As we say at the temple: \"Never fight a tiger with a hozen on your back.\"\n\nWe will deal with the sha, but first we must see to the more immediate... nuisance.\n\n<Koro slams the writhing saurok HARD against the stone.>\n\nGroups of refugees from the temple are heading for a camp to the north, but they're being ambushed by saurok. Help me see the next group to the camp and we'll figure out our next move from there.", objectives = "Help Koro Mistwalker escort a group of refugees from the Temple of the Red Crane to Crane Wing Refuge. Speak with Koro first to begin.", completion = "Thank you, <name>. We would not have made it without your help." }
WordHunterWoW_QuestEN[30270] = { title = "Blinding the Riverblades", description = "\"A hooded falcon catches no quarry.\"\n\nThis is one of the first mantras we teach young monks at the temple. It means that even a foe as swift and lethal as a falcon can be neutralized by depriving its senses.\n\nThe saurok have scouts all over the region acting as eyes for their raiding parties.\n\nIt's time we put their eyes out, don't you think?", objectives = "Kill 8 Riverblade Pathstalkers in the areas surrounding Crane Wing Refuge.", completion = "Well done. I only wish I could have accompanied you...\n\nThe blood on these hand-wraps is not my own, you know." }
WordHunterWoW_QuestEN[30271] = { title = "Sha Can Awe", description = "The sha have the mysterious ability to evoke powerful, often overwhelming, emotional responses in their victims.\n\nAs we fled the temple, senior members of the Crane Wing order stayed behind to cover our escape. They are no doubt being subjected to intense emotional trauma, and I fear they are not all strong enough to resist falling into despair.\n\n{name}, we have to show them there is still hope! Show them that despair CAN be defeated!", objectives = "Kill sha near 10 Hopeless Monks or Acolytes to inspire them.", progress = "Look for Crane Wing pandaren who are falling to despair and slay sha near them while I support you!", completion = "Honestly, I'm a little surprised that worked.\n\nPandaria is proving to be a land where the lines between metaphor and reality are blurred." }
WordHunterWoW_QuestEN[30272] = { title = "Striking the Rain", description = "Now as for that \"striking the rain\" part... well, sometimes you have to.\n\n\"Hope is the sun behind a stormy sky - ever in the heart, but veiled to the eye.\"\n\nThere seems to be no end to the sha pouring out of the temple. But in order to see beyond the veil of despair, you must carve through it.\n\nWith any luck, you'll find a sun behind the clouds...", objectives = "Kill 18 Haunts of Despair at the Temple of the Red Crane.", progress = "We shouldn't press further into the temple before clearing out some of the sha presence outside.", completion = "You know something, <name>? We make a pretty good team!" }
WordHunterWoW_QuestEN[30273] = { title = "In the House of the Red Crane", description = "\"Broken are the bodies wherein hopeless hearts reside - the blight of despair strikes forth from inside.\"\n\nThis was the last piece of wisdom the Red Crane imparted to me, just hours before the Sha outbreak.  It makes sense now...\n\n{name}, when the Sha attacked, they broke forth from the temple's basement...\n\nAll of his teachings - the very Way of the Crane itself... it's all been preparation for facing the Sha of Despair.\n\nThe Red Crane has been expecting this conflict for centuries!", objectives = "Enter the basement of the Temple of the Red Crane and defeat the Sha of Despair.", completion = "You have vanquished the Sha of Despair. My order can handle the remaining cleanup from here.\n\nIt seems the time has finally come to face the consequences of Shaohao's actions.\n\nThis conflict has been a long time coming - the arrival of your people was merely a catalyst. Now, your help will be necessary if Pandaria is to survive." }
WordHunterWoW_QuestEN[30274] = { title = "The Arcanic Oubliette", description = "An Alliance member? Here? Elune be praised.\n\nMy team has encountered a snag. We opened a portal to this land using some ancient scrolls we had found that predated Azshara's rule.\n\nUnfortunately, the coordinates provided on the tablets were warded and the portal that meant to take us to our destination landed us in this oubliette.\n\nWe have been trapped here for days, and it is slowly leaching our energies to power itself.\n\nCan you find the nearby shackles that bind the oubliette and disable them?", objectives = "Find and disable the 3 Oubliette Shackles.", completion = "Fabulous! Your timing was impeccable. Another day in there and I think we would have wasted away to nothing.\n\nNow we can continue our search for the Pools of Youth!" }
WordHunterWoW_QuestEN[30275] = { title = "A Crocolisk Tale", description = "How could this crocolisk have grown so large?\n\nCertainly, rumors exist of very old crocolisks that have grown to enormous sizes... but this female can't be more than a dozen years old.\n\nPerhaps someone in New Cifera can shed some light on the subject.", objectives = "Bring the Enormous Crocolisk Tail to Yan at New Cifera in the Valley of the Four Winds.", progress = "What's that you've got there?", completion = "This tail came from a crocolisk? Funny, we don't get many crocs this far upstream.\n\nHave you seen some of the enormous fruits and vegetables that our farmers can grow? Your crocolisk grew so large for the same reason - there's something in the water.\n\nWhat it is, we're not quite sure... but we count it among our blessings. Humongous vegetables are great. The odd giant crocolisk every now and again is really just a side effect." }
WordHunterWoW_QuestEN[30277] = { title = "The Crumbling Hall", description = "An ancient mogu artifact has been uncovered in the Guo-Lai Vault, beyond the Hall of Statues. We've made repeated attempts to retrieve it, but none have been successful.\n\nWe cannot let this artifact fall into the hands of the Shao-Tien. I need someone capable to retrieve it, and quickly.\n\nAre you in?", objectives = "Retrieve the Ancient Guo-Lai Artifact.", progress = "Have you recovered the artifact yet?", completion = "When everyone else lets me down, you follow through. That's why I like you.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[30278] = { title = "REUSE FOR PROGRESSION", description = "", objectives = "" }
WordHunterWoW_QuestEN[30279] = { title = "REUSE FOR PROGRESSION", description = "", objectives = "" }
WordHunterWoW_QuestEN[30280] = { title = "The Thunder Below", description = "Roars have been echoing out from inside the Guo-Lai Halls. The mogu have awakened some ancient beast, and it will not be long before they attempt to release it upon my men.\n\nFind your way to the Hall of the Serpent and slay the beast before it can be unleashed upon us. I would trust no other with such a dangerous and important task.", objectives = "Slay Milau.", progress = "Have you slain the beast?", completion = "You accomplish what I doubt I could even overcome myself. I am humbled by your valor." }
WordHunterWoW_QuestEN[30281] = { title = "The Silent Approach", description = "<He leans over and draws a picture of what can only be a mogu, points towards the lake to the west, drags the blunt side of his dagger across his throat, and looks at you expectantly. It seems he wants you to kill mogu at Whitepetal Lake.>", objectives = "Kill 6 Shao-Tien mogu at Whitepetal Lake.", completion = "The mogu numbers seem to be sufficiently thinned." }
WordHunterWoW_QuestEN[30282] = { title = "Burning Away the Filth", description = "The mogu have erected their filthy banners around the lake to the west, claiming it as their own. Take this torch and show them what we think of their banners.", objectives = "Burn 10 Shao-Tien Banners.", completion = "I'll take the smoke on the horizon to mean that they've received our message. Good." }
WordHunterWoW_QuestEN[30283] = { title = "A Smashing Impression", description = "Sometimes I feel sorry for these mogu... maybe ripping out the spirits of other races is just their way of coping with family issues at home? Maybe we should be more sympathetic to where all this aggression stems from?\n\nOr we could just smash all their soul-stealing ritual objects down at the lake. That sounds more fun to me personally.", objectives = "Destroy the Shao-Tien Ritual Statues.", completion = "If they come asking who rudely crushed all their little statuettes, I'll tell them it was you.\n\nNot that I don't appreciate your help. You're lovely." }
WordHunterWoW_QuestEN[30284] = { title = "A Thousand Pointy Teeth", description = "The water has been frothing with danger this day! Some sort of swarming, meat-eating fishy nastiness has taken up residence in our lake! Deplorable. And just when I was considering stripping down to my nothings to take a mid-day dip!\n\nYou are adept in the ways of slaughtering any manner of nasty, are you not? Would you put your skills to use this day, in the name of pandaren everywhere desiring a swim?\n\nIt's a truly noble cause, especially with me among their ranks!", objectives = "Kill 9 Knifetooth Swarmers.", completion = "Aren't you just the sweetest thing?! I do rather like you.\n\nI'm going to take that afore-mentioned dip now. I'll be modest and delay my disrobing until you depart, as a repayment for your kindness.\n\n...you're missing quite the sight though, I must say." }
WordHunterWoW_QuestEN[30285] = { title = "Wu Kao Scouting Reports", description = "There were some scouting reports unaccounted for after the attack. If we're lucky, they're still out in the village, but the mogu may have gotten their hands on some of them as well.\n\nIf you could bring back any scouting reports you find, it would definitely put my mind at ease. We can't afford to let the mogu in on our positions or any of the artifacts we've found, lest the men be in even more danger than they already are.", objectives = "Recover 3 Wu Kao Scouting Reports.", progress = "Any luck finding those reports?  I'm worried for the safety of our men in the field if too much information falls into mogu hands.", completion = "You are very kind, <name>. Thank you for putting my mind at ease." }
WordHunterWoW_QuestEN[30286] = { title = "Backed Into a Corner", description = "Many villagers are cornered and scared, unable to defend themselves. You will need to defend them. Rescue them.\n\nGo quickly friend, save as many as you can!", objectives = "Rescue 6 Cornered Mistfall Villagers.", completion = "We've holed up everyone we can in the bar. We should be able to protect them for now.\n\nThank you again for your help, <name>. You always seem to be there right when we need you." }
WordHunterWoW_QuestEN[30287] = { title = "Mogu Make Poor House Guests", description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone.\n\nYou help?  Rook will tell Leven you helped.  Promise.", objectives = "Kill 6 Shado-Tien attackers in Mistfall Village.", completion = "Rook can handle rest of mogu.  Thanks for help.  Good man." }
WordHunterWoW_QuestEN[30288] = { title = "My Town, It's On Fire Again", description = "I don't know if you noticed, but my town is on fire... again.\n\nWe have water buckets all over town, but no one can get out to put out the fires. Please, please, help us!", objectives = "Use Mistfall Water Buckets to douse 60 fires.", completion = "We owe you so much... thank you, <class>." }
WordHunterWoW_QuestEN[30289] = { title = "Freeing Mind and Body", description = "Mogu stealing peoples minds! Making them do evil things.\n\nDon't kill them, just kill the mogu, then they forget about all the mogu mind stealing and stop being evil. You should fix people like Rook is.", objectives = "Free 6 Dominated Guards by killing their controllers.", completion = "Lots of villagers inside and safe now. You do good work." }
WordHunterWoW_QuestEN[30290] = { title = "Stonebound Killers", description = "Mogu stone dog creatures chasing villagers and hurting them. Rook try to smash some, but they too fast.\n\nYou help smash some too?", objectives = "Kill 8 Stonebound Quilen.", completion = "Yes! You faster than rook. Do good!\n\nThank you, friend." }
WordHunterWoW_QuestEN[30291] = { title = "Stunning Display", description = "I've been talking to Tantan here... again... and he insists that fishing is some kind of fabulous. I was skeptical, but I gave it another go. I'm not a big fan of that whole holding a stick and waiting method though, so I tried something a bit more direct.\n\nWould you be a doll and go collect any of the still intact fish floating belly up in the lake for me?", objectives = "Collect 12 Stunned Whitepetal Carp.", progress = "As an added bonus, my method ensures they're already cooked! If that's not a marvel of modern efficiency, I don't know what is.", completion = "Marvelous! You're quite the efficient fetcher.\n\nI'm grateful that you don't mind getting that fancy armor of yours wet." }
WordHunterWoW_QuestEN[30292] = { title = "Rude Awakenings", description = "The mogu are taking over the minds of the saurok at the lake to our west and turning them against us! The thing is, they were already against us, so I'm not sure they really thought this thing through fully.\n\nAnyway, Anji's the fighter in this pair, I'm more the lover, so I'm looking for someone to do all the weapon swinging and spell flinging and war crying and such.\n\nCan you go kill some saurok for me?", objectives = "Kill 8 Dominated Paleblade Flesheaters.", completion = "You smell of saurok and mogu. Not a terribly pleasant mix, my friend. But it suggests to me that your task is done, and for that I thank you.\n\nMay we meet again soon under better-smelling terms." }
WordHunterWoW_QuestEN[30293] = { title = "In Enemy Hands", description = "The Shao-Tien Mindbenders have taken over the minds of our defenders down at Whitepetal Lake to the west. Get down there and kill the mogu that are controlling them, but don't kill the defenders! Killing their captors should free them from their mind control.\n\nSooner would be better. Anji might try to go down there to help soon, and her ability to restrain herself when in the heat of things is not one of the qualities I married her for.", objectives = "Beat 8 Possessed Whitepetal Defenders until they're freed of mogu possession.", completion = "More than one pandaren is thankful for your help today, that's for sure." }
WordHunterWoW_QuestEN[30294] = { title = "Small Comforts", description = "The mindbenders at Whitepetal Lake are pulling the spirits from the corpses of the dead to inflict who-knows-what kind of torments upon them.\n\nI've written on this scroll a rite that will release their spirits from their bodies and send them on their way. Where they go and what happens to them from there I don't know, but it will at least free them from the cruel hands of the mogu.\n\nRead this rite over any of the fallen you find. We'll recover their bodies later.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Read the Rite of Release at the bodies of 6 Fallen Golden Lotus Defenders.The mindbenders at Whitepetal Lake are pulling the spirits from the corpses of the dead to inflict who-knows-what kind of torments upon them.\n\nI've written on this scroll a rite that will release their spirits from their bodies and send them on their way. Where they go and what happens to them from there I don't know, but it will at least free them from the cruel hands of the mogu.\n\nRead this rite over any of the fallen you find. We'll recover their bodies later.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30295] = { title = "Turn-in Quest Test Case", description = "", objectives = "" }
WordHunterWoW_QuestEN[30296] = { title = "Gaohun the Soul-Severer", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", objectives = "Kill Gaohun the Soul-Severer.", completion = "Leader gone. People safe. Rook save village. And friend save village too. Thank you, friend!" }
WordHunterWoW_QuestEN[30297] = { title = "Baolai the Immolator", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", objectives = "Kill Baolai the Immolator.", completion = "Leader gone. People safe. Rook save village. And friend save village too. Thank you, friend!" }
WordHunterWoW_QuestEN[30298] = { title = "Painting the Ruins Red", description = "The mogu think they can inhabit these ruins uncontested. Let's show them the error in their ways.", objectives = "Kill 8 mogu in the Ruins of Guo-Lai.", completion = "Their foothold in these ruins shall not last the night." }
WordHunterWoW_QuestEN[30299] = { title = "No Stone Unturned", description = "The mogu have forced spirits into their old statues to bring them to life, control them, and turn them against us.\n\nThe only way to free the bound spirits is to destroy their vessels.", objectives = "Destroy 6 Mogu Statues.", completion = "Your efforts here make all the difference. Thank you so much for your help, friend." }
WordHunterWoW_QuestEN[30300] = { title = "The Key to Success", description = "The mogu have taken prisoners. They'll be tortured or worse.\n\nFind any way you can to free them from their cages.", objectives = "Find a Shao-Tien Cage Key and free 6 Golden Lotus Prisoners.", progress = "I'd rather die than live as a mogu prisoner. They are not kind captors.", completion = "Many of those you saved are back here in camp recovering. You surely have their gratitude, and mine." }
WordHunterWoW_QuestEN[30301] = { title = "Offering a Warm Welcome", description = "There is no more sure message we can send them then to burn the tents the sleep in.\n\nScour the ruins. Destroy every tent you find.", objectives = "Burn 6 Mogu Tents in the Ruins of Guo-Lai.", completion = "Smoke in the distance tells me that you were successful. Good work, <class>." }
WordHunterWoW_QuestEN[30302] = { title = "The Imperion Threat", description = "Scouts spotted a Shao-Tien Imperion entering the Guo-Lai Halls. I need someone I can trust to make sure he doesn't come out of there alive.\n\nI think you're the {class} for the job.", objectives = "Kill the Shao-Tien Imperion.", completion = "You haven't let me down.  I won't forget that." }
WordHunterWoW_QuestEN[30303] = { title = "NOT USED", description = "", objectives = "" }
WordHunterWoW_QuestEN[30304] = { title = "Hard as a Rock", description = "Hey! You know what awesome thing happened to me this morning?\n\nI was strolling through the ruins with Anji, eyes on the ground so I wouldn't step on anymore of those creepy spider pods, when one of the statues came to life and tried to smash me!\n\nAnji ended up doing the smashing. But I'm not satisfied. I think that you should go out there and smash all the statues, whether they're moving or not. It's the only way to be sure.", objectives = "Destroy 10 Mogu Statues.", completion = "Your ruins vandalizing efforts are appreciated, friend." }
WordHunterWoW_QuestEN[30305] = { title = "He Knows What He's Doing", description = "You know He Softfoot? Sneaky guy, don't talk much. He put traps all over ruins for mogu. He said Rook just need to trick mogu into traps. Rook don't really know how.\n\nMaybe you do it? You find traps, you get bad guys into traps? Can you not tell He though, please?", objectives = "Lure 8 enemies into He's Poison Traps.", completion = "You really good friend. Rook like you. Thank you, good friend!" }
WordHunterWoW_QuestEN[30306] = { title = "The Battle Ring", description = "We have some fresh trainees that are far from being a danger to you, but in numbers, they may prove enough of a challenge. And if not, they could use the lesson in humility.\n\nStep into the battle ring when you're ready. Don't go easy on them.", objectives = "Defeat 20 Shado-Pan Trainees in the Battle Ring.", progress = "Step into the ring. Show them how a real <class> fights.", completion = "Very impressive. It seems they have much learning to do. I'll see to that." }
WordHunterWoW_QuestEN[30307] = { title = "The Eternal Vigil", description = "Good to have you with us, {class}. If you're joining the fight, I need more men out up at the Golden Stair to clear out the mogu setting up base there.\n\nCan I count on you?", objectives = "Kill 8 Shao-Tien mogu on the Golden Terrace.", completion = "We hold this line. It does not matter how long they come, we hold this line." }
WordHunterWoW_QuestEN[30308] = { title = "Stone Hard Quilen", description = "Leven always says the only good quilen is a dead quilen, and I'm inclined to agree. You here to aid the cause?", objectives = "Kill 6 Granite Quilen.", completion = "Less of those beasts on the field always cheers my day up a bit. Thanks." }
WordHunterWoW_QuestEN[30309] = { title = "Set in Stone", description = "The mogu have been sending their narcissistic stone effigies onto our battlefield today. They're brining them to life up on the Golden Stair.\n\nThe bigger they are, the harder we hit'm. You in?", objectives = "Destroy 6 Mogu Effigies.", completion = "There's a satisfying amount of ruble strewn across the field today. A sign of your good work." }
WordHunterWoW_QuestEN[30310] = { title = "Thundering Skies", description = "The mogu have bent the will of sky serpents and turned them against us.\n\nThe defenders won't fare well against them, but you would. Head northwest towards the Golden Stair and remove them from the sky.", objectives = "Kill 3 Subjugated Serpents.", completion = "Quite the battle! I think your feat has boosted morale among the troops a bit." }
WordHunterWoW_QuestEN[30311] = { title = "High Standards", description = "If I had to pick the most important quality for a battle standard, it would be that it's standing up... and not on fire, but mostly the first one. So needless to say, I'm a bit concerned about our standard situation at the moment.\n\nIf some unknown <class> were to be so kind as to take a walk out on the battlefield to our northwest and stand our standards back up, both myself and my extremely sexy yet somewhat commanding wife would be very grateful.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Erect 6 Golden Lotus Standards." }
WordHunterWoW_QuestEN[30312] = { title = "Given a Second Chance", description = "A foolish contingent attempted to mount an offensive on the Golden Stair through the eastern pass, and were bombarded by cannons. Those that made it back are in bad shape, and there are still wounded out in the field.\n\nHere are some bandages. Use these, or any other healing skills you possess, and help get our wounded defenders back to safety.\n\nPlease hurry, there is little time.", objectives = "Heal 6 Wounded Defenders.", completion = "The men you healed made it back safely.\n\nThank you, kind friend. Truly." }
WordHunterWoW_QuestEN[30313] = { title = "The Moving Mists", description = "<He looks down at the dead fog creature at his feet, looks up at you, then points out into the mists surrounding the lake. It seems he wants you to find and kill more of these fog creatures.>", objectives = "Kill 8 Fog Walkers.", completion = "<He pats you on the shoulder and nods his thanks.>" }
WordHunterWoW_QuestEN[30314] = { title = "The Displaced Paleblade", description = "<He looks down at the dead saurok at his feet, looks up at you, then points out down the lake shore. It seems he wants you to find and kill more of these saurok.>", objectives = "Kill 8 Paleblade Saurok.", completion = "<He smiles at you and nods his thanks.>" }
WordHunterWoW_QuestEN[30315] = { title = "Normal Quest Test Case", description = "Yes?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Give me stuff." }
WordHunterWoW_QuestEN[30316] = { title = "Longshot", description = "I would not normally ask this of grizzle <class> such as you, but since you are to be on the battlefield below the Golden Stair anyway, would you recover spent arrows for the archers?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover 12 Spent Shado-Pan Arrows." }
WordHunterWoW_QuestEN[30317] = { title = "Water, Water Everywhere", description = "How'd you like to make yourself useful?\n\nThe season's been awful dry lately. I need someone to water the crops out in the Heartland. Here's the thing: I need you to water ALL of the crops.\n\nI keep a few kites with Wing Nga, the flightmaster across the way. Grab one of those kites, then throw water on any areas that look dry and dusty.", objectives = "Speak with Wing Nga to borrow a kite, then throw water onto 35 Dusty Spots in the Heartland.", progress = "Just come back when you're done. And don't break any of my kites.", completion = "Hmph! I knew you were a good waterer when I first saw you. You've got good watering arms." }
WordHunterWoW_QuestEN[30318] = { title = "Chasing the Chicken", description = "Say, you there! {name}, was it? I've got a problem, and I need someone with better legs than mine to help me solve it.\n\nMy prize-winning chicken has flown the coop! Now she's out in the open, mingling with the other hens, wild birds, and... <gulp> ill-intentioned roosters.\n\nMy farm is west of here, south of the Skyrange. Could you find her, and bring her back to me?", objectives = "Pick up Hillpaw's Chickens until you find his Prize-Winning Chicken.", progress = "I swear, she's never done this before.", completion = "You found her! You've got an eye for fowl, kid.\n\nI'll hold onto her for now. Don't worry, I'll make sure she's punished later." }
WordHunterWoW_QuestEN[30319] = { title = "Pest Problems", description = "One of my farmhands, Wika-Wika, has been tilling the soil in my westernmost field. I understand he's had some problems with pests.\n\nHe's got plenty of pesticide to spray the bugs that eat my crops, but I'm afraid he has no way to deal with the marmots.\n\nWould you lend him a hand? With rampant hozen and virmen attacks, I can't afford to lose crops to simple pests.", objectives = "Speak with Wika-Wika, then stomp on 25 Black-Nose Marmots.", completion = "Well, good. That that's taken care of. Neatly done, <race>." }
WordHunterWoW_QuestEN[30320] = { title = "Free Spirits", description = "I came upon one of the Shao-Tien Soul-Render's daggers. It radiates a strong magic. I've been told it should allow you to enter their spirit vortexes.\n\nThe mogu use these to harvest spirits and bind them to their will, but I'm hoping you can use it to free the spirits.\n\nEnter any of the spirit vortexes you can find up on the Golden Stair, and free all the captive spirits you find.", objectives = "Enter Spirit Vortexes and free 15 pandaren spirits inside.", completion = "Very good! I'll hold onto this dagger. Perhaps we will get the chance to make more use of it later.\n\nThank you so much, my friend. You have a good heart." }
WordHunterWoW_QuestEN[30321] = { title = "Weed War II", description = "Ssshhay... d'you know that guy over on the farm, with the... the *hic*... the weed problem? Gai Lan, I think his name was. I love that guy, man.\n\nAnywayshh, he said that if I *hic* sent an adventurer over to go pick his weeds, he'd get me some ale.\n\nIt's jusht a few weeds, not too many, probably.\n\n*hic*", objectives = "Speak to Gai Lan, then pick 100 Weeds on his farm. You can pick Weeds while mounted.", completion = "Thanks, mishter *hic* <name>." }
WordHunterWoW_QuestEN[30322] = { title = "Money Matters", description = "I love working in the market, although there's one aspect of this job I really dislike: collecting debts.\n\nWhile most pandaren debts are simply due to laziness, there are a few unsavory characters around town who simply don't want to pay, and there's some who are just too poor.\n\nA few people here in town owe me money. Could you go talk to them, and remind them about what they owe?", objectives = "Obtain Spicemaster Jin Jao's Payment, Trader Jambeezi's Payment, Innkeeper Lei Lan's Payment, and Lolo Lio's payment.", progress = "You know, it's kind of nice having a thug... er, I mean, <class>... like you around.", completion = "I'm glad that nasty business is over with. Nobody gave you any trouble, did they?" }
WordHunterWoW_QuestEN[30323] = { title = "They Don't Even Wear Them", description = "A few weeks ago, a group of those jumpy little Springtail virmen broke into my lockbox and stole several handfuls of my jewelry. I've since found a few pieces, but they still have most of my collection.\n\nIf you're headed up to the Springtail Crag, in the cliffs to the north, you should keep an eye out for them. I'd love to get my jewelry back.", objectives = "Obtain a Stolen Circlet, a Ransacked Ring, and a Burglarized Bracelet.", progress = "Can you believe how irresponsible and juvenile those virmen are? Don't they know how much that jewelry COST?", completion = "Oh, <name>! I'd kiss you right here and now if you weren't... well, if you weren't covered in virmen dust.\n\nThanks, though!" }
WordHunterWoW_QuestEN[30324] = { title = "Not in Chee-Chee's Backyard", description = "Not all hozen are the same. Chee-Chee's tribe was forest hozen... came from Jade Forest. Pretty easy to get along with.\n\nThe Kunzen invaders... they come from mountains, far to the north. Not nearly as nice as Chee-Chee.\n\nThey come into our green land, take our things, leave big mess behind.\n\nChee-Chee wants to kill them. You like to help?", objectives = "Kill 8 members of the Kunzen tribe in the Kunzen Village.", completion = "Great! Chee-Chee knew you could do it!" }
WordHunterWoW_QuestEN[30325] = { title = "Where It Counts", description = "I've been watching those Kunzen hozen, and I've noticed a consistent pattern. Whenever they're getting ready to attack, they participate in strange, barbaric rituals around their totem.\n\nIf we can disrupt this ritual, not only will we put off any impending attacks, we can deal a huge blow to their morale! So get in there, rough them up, and make as much of a mess as possible!", objectives = "Throw 8 Kunzen Ritual Candles, kick 4 Blazing Embers, and slay 1 Kunzen Ritualist.", progress = "What are you waiting for? Get up there and have some fun!", completion = "Hah! They'll be cleaning that mess up for days." }
WordHunterWoW_QuestEN[30326] = { title = "The Kunzen Legend-Chief", description = "I've heard people talk about the hozen like they're just some tribe of barely-functional idiots... but that's not true! They have brains, too - they just don't all like to use them that much.\n\nI've heard that the Kunzen tribe has two chiefs - one in charge of fighting, and one in charge of stories, lore, and history.\n\nWhat I wouldn't give to see what kind of stories they tell...", objectives = "Obtain a Kunzen Legend-Book from a Kunzen Legend-Chief.", progress = "I'll bet hozen legends aren't that much different than our own.", completion = "Wow! Look at this! It's...\n\n<Fish flips through the pages, and her face sours.>\n\nOh, I think that's a dirty picture. But the rest of this is very interesting! I just love learning how other creatures think. Thanks, <name>!" }
WordHunterWoW_QuestEN[30327] = { title = "You Have to Burn the Ropes", description = "I, umm... well...\n\nOh, never mind. It was a stupid idea.\n\nIt's just that, I was thinking that maybe we can stop the Kunzen hozen from attacking us without having to, you know... KILL anything. I noticed a few ropes on the side of the mountain. I think they're using them to climb down to our farms and...\n\nNo, forget it. It was a silly idea anyways.", objectives = "Burn 6 Kunzen Ropes.", completion = "<Ella's face lights up.>\n\nYou did it? For me? Oh, thank you, thank you, thank you, thank you!" }
WordHunterWoW_QuestEN[30328] = { title = "The Thousand-Year Dumpling", description = "One of my most popular recipes is the Thousand-Year Dumpling, which is filled with preserved vegetables.\n\nI normally let the vegetables ferment in a hole underneath my house, but when I looked for them this morning, they were gone!\n\nI blame those thieving virmen.\n\nBring them back, and I'll let you help me cook!", objectives = "Obtain 7 jars of Preserved Vegetables.", progress = "Try not to open any of the jars. If you do open one, you might not want to smell it too closely.", completion = "Now, my student, lean in closely. Let me show you the secret of the Thousand-Year Dumpling..." }
WordHunterWoW_QuestEN[30329] = { title = "Cindergut Peppers", description = "A certain few pandaren around here prefer their dishes unbearably spicy. Unfortunately, my access to such peppers is limited.\n\nThe Kunzen hozen, in the mountains to the west, often carry cindergut peppers. A few of those and I'll be set for a few days.\n\nSay, could you collect some for me? You might want to wear gloves if you'll be handling them directly.", objectives = "Obtain 4 Cindergut Peppers.", progress = "Just put the peppers down on the cutting board, here. I'd prefer not to touch them myself.", completion = "I don't know how the hozen manage to carry these things on their bodies... let alone eat the things." }
WordHunterWoW_QuestEN[30330] = { title = "The Truffle Shuffle", description = "I like to bake with truffles... when I can find them. They only grow up on the Skyrange, and in very, very scarce amounts.\n\nThey're a fantastic ingredient, but we can't risk over-farming them. That's why we need to replace what we've taken. Bring me a handful of adult truffles, and plant some of these spores in their place.", objectives = "Obtain 8 Shadelight Truffles, and plant 8 Shadelight Spores.", progress = "We won't need many truffles. They're for flavor only, really.", completion = "These will do nicely.\n\nNow, <name>... stand closer. Let me show you a thing or two about baking..." }
WordHunterWoW_QuestEN[30331] = { title = "The Mile-High Grub", description = "Have you ever tried Mushan Tail Stew? Chances are, if you have, that it was stringy and tasteless. You see, there's a trick to making the perfect Mushan Tail Stew: you need to cook it at high elevation.\n\nI've already gathered the ingredients. Take this pot up to the Kunzen Village, up in the mountains to the west, and prepare the stew over their bonfire.", objectives = "Prepare 20 bowls of Mushan Tail Stew over the bonfire in the Kunzen Village.", progress = "I used to make daily trips into the mountains, just to practice making this stew.\n\nI was younger, then.", completion = "This is fantastic! You are quite the aspiring cook, <race>." }
WordHunterWoW_QuestEN[30332] = { title = "Fatty Goatsteak", description = "You know what? I think I want to grill up some goatsteak today.\n\nNo, not from the puny little shaghorns they keep around here. They don't have nearly enough fat on them.\n\n<The chef pats his voluminous belly.>\n\nYou think I got to this size eating no-fat-havin' goats?\n\nNow, the shaghorns up on the Skyrange, to the west... those'll do just fine.", objectives = "Obtain 4 Fatty Goatsteaks.", progress = "<The chef is busy preparing spices and sauces for his imminent steaks.>", completion = "Good choice of steaks, <name>. You've got a future as a butcher. You probably make a better <class>, though." }
WordHunterWoW_QuestEN[30333] = { title = "The Lesser of Two Evils", description = "Like any farming community, we have the occasional virmen troubles.\n\nThe most powerful Springtail virmen live high up in the cliffs to the north, and only come down when they run out of veggies to nibble on.\n\nFrankly, I've dealt with virmen before. They're nothing but a pest that must be kept in check, and there's no better way to do that than by killing their warren-mother. Easy as that.", objectives = "Slay the Springtail Warren-Mother.", progress = "I've had plenty of experience with virmen in the past. Just show them you're stronger than they are, and they'll back off.", completion = "There, that's done with. Now we shift our focus back to farming, for a change." }
WordHunterWoW_QuestEN[30334] = { title = "Stealing is Bad... Re-Stealing is OK", description = "The hozen, up in the mountains to the west, continue to steal vegetables from my fellow farmers. Being so close to Halfhill, I very rarely suffer hozen attacks, but my friends have not been so lucky.\n\nSeems to me like they steal way more than they can eat. If you can find any intact vegetables up there in those mountains... steal them back!", objectives = "Re-steal 16 Stolen Vegetables.", progress = "Have you got them?", completion = "Thanks! I'll make sure these are distributed out to my fellow farmers." }
WordHunterWoW_QuestEN[30335] = { title = "Stalling the Ravage", description = "The Kunzen hozen, up in the mountains to the west, have been acting up, lighting their fires and shouting their chants. Based on what I've heard and seen around here, that means that a ravage is coming.\n\nThere's not much we can do to stop the ravage, but we can at least thin their numbers before they attack.", objectives = "Slay 12 Kunzen Hozen.", progress = "The ravage could come any time now. We have to be prepared.", completion = "They'll be attacking, but my farm - and the farms of my friends - should not be in any danger.\n\nNot if we can help it, anyways. Right, <name>?" }
WordHunterWoW_QuestEN[30336] = { title = "The Kunzen Hunter-Chief", description = "From what I've gathered, the Kunzen hozen have two chiefs. One is harmless - he deals with potions, medicines, and ancient fables. The other one is in charge of the Kunzen's hunters - and the only thing they've been hunting lately is our crops.\n\nThe Hunter-Chief is a problem waiting to be solved. I'm sure the local farmers would be grateful if you went up there and, you know, \"took care\" of him.", objectives = "Slay the Kunzen Hunter-Chief.", progress = "Mm-hmm.", completion = "No doubt the hozen will have a big ritual tonight, promoting a new Hunter-Chief.\n\nI'm just happy that my fellow farmers can rest easy in the meantime." }
WordHunterWoW_QuestEN[30337] = { title = "Simian Sabotage", description = "The hozen steal from us, and we keep stealing our stuff back. It has to stop sometime.\n\n<Farmer Yoon hands you a barrel of fireworks.>\n\nFind some of our stolen supplies in their mountain camp to the west, and place these fireworks beside them. Hopefully, if they see the explosions, they'll think our supplies are defective and stop stealing altogether.\n\nIt's worth a shot, right?", objectives = "Use the Barrel of Fireworks near the Pile of Stolen Weapons, the Pile of Stolen Tools, the Pile of Stolen Beer, and the Pile of Stolen Grain.", progress = "Good luck up there, <name>.", completion = "Hopefully they're put off from stealing any more of our supplies. I know I personally wouldn't want to drink any explosive beer, or use an explosive rake." }
WordHunterWoW_QuestEN[30338] = { title = "A Weighty Task", description = "For the life of me, I can't figure out why the mogu would have built all their statues and such down in that lake. I'm sure there wasn't always water down there, but it still seems wickedly inconvenient should it ever have rained.\n\nAh well, who's to fathom the strange intentions of the mogu...\n\nWould you be so kind as to swim down there and bring back any artifacts that seem even vaguely carry-able? I'd certainly appreciate it.", objectives = "Recover 8 Mogu Artifacts.", progress = "Have you find a pretty stone thing or two for me? I have a hug waiting for you should you have been so kind!", completion = "Well look at you! Not only can you swim in all that very ornate and heavy-looking gear, you can carry half-a-dozen awkwardly large gilded weapons while you do it! Of all your feats, this is surely one of the most impressive, no?\n\nThank you, you marvelously adept swimmer you." }
WordHunterWoW_QuestEN[30339] = { title = "Getting your Hands Dirty", description = "Some of the best fishin' in all of pandaria in this lake right here. I brought enough brew to last me all day, but I didn't think to bring any bait.\n\nWho can really remember such things?\n\nIf you'd be willing to gather me some bait along the shore, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", objectives = "Gather 12 Fresh Whitepetal Worms.", progress = "So much fishin' in store! I can hardly wait to start my waitin'.", completion = "I like a <race> who isn't too lofty to help a humble merchant out. Thank you." }
WordHunterWoW_QuestEN[30340] = { title = "Stick in the Mud", description = "I came out for a beautiful day of fishin', but I didn't think to bring a pole. There are so many things to remember for fishin', I just can't keep it all in my head.\n\nThose reeds along the river look alright for makin' a pole out of. If you'd gather me some number of them, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", objectives = "Gather 12 Whitepetal Reeds.", progress = "So much fishin' in store! I can hardly wait to start my waitin'.", completion = "I like a <race> who isn't too lofty to help a humble merchant out. Thank you." }
WordHunterWoW_QuestEN[30341] = { title = "Under Watchful Eyes", description = "<He looks down at the dead mogu scout at his feet, looks up at you, then points out out down the lake shore. It seems he wants you to find and kill more of these mogu scouts.>", objectives = "Kill 8 Shao-Tien Surveyors.", completion = "<He bows thankfully.>" }
WordHunterWoW_QuestEN[30342] = { title = "Fiery Tongue, Fragile Feet", description = "I was kicking the water for fun again when one of those vicious crocolisks lunged out to try to bite my foot off! Rude! I have proceeded to rest my weary soles a few feet farther from the water, but I already look back on my water-kicking days longingly.\n\nWould you be so kind as to kill a crocolisk or eight for me? I assure you they deserve it for frightening me though.", objectives = "Kill 6 Stillwater Crocolisks.", completion = "Do you hear that, my beautiful feet? You can rest easy now, your water-kicking days have returned!\n\nYou've been oh so lovely, friend. Do share the fruits of your labors and spend a second or two by the water with me someday. We can exchange tales of that one time when you so generously slaughtered a ravaging band of vicious limb-snatching reptiles for the sake of my frightened and innocent feet. What a grand day that was." }
WordHunterWoW_QuestEN[30343] = { title = "To the Waterline!", description = "This is Sky-Reaver Stormhowl, captain of the airship Fist of Garrosh and commander of this operation.\n\nYour first task is to burn the 7th Fleet to the waterline while it's still at anchor\n\nCaptain Drok's marines will hold the harbor entrance while your team works.\n\nRig powder barrels in the hold of every ship and then regroup at the harbor entrance to inform Blastmaster Sparkfuse, who will trigger the exposives and signal the airship forward.", objectives = "Rig powder barrels in the hold of all six ships." }
WordHunterWoW_QuestEN[30344] = { title = "The Lost Dynasty", description = "I wonder if I could bother you for another task. My daughter, the good Sentinel Commander Lyalia here, refuses to let me go into the field.\n\nI have spent everyday in that oubliette staring at the ruins to our north, itching to investigate.\n\nIf we are where I suspect we are those ruins could contain the key we need to finding the fabled Pools of Youth!\n\nPlease, {class}! Go to those ruins and salvage any tablets that still have writing on them.", objectives = "Obtain 6 Dynastic Tablets.", progress = "It is one thing to research the lost dynasties. It is quite another to visit their ancient ruins.\n\nI am giddy as I have not felt in centuries!", completion = "Oh! Fabulous! Fabulous!\n\nYour one trip has advanced my research more than ten years of reading dusty tomes and decaying scrolls...\n\nAnd those \"mogu\" you saw. I have been doing some research as well as speaking to Kang on the subject.\n\nI suspect now that they were the race of the lost dynasties that my research is derived from.\n\nOf course, that also means that they are the ones who used to control the Pools of Youth." }
WordHunterWoW_QuestEN[30345] = { title = "Poisoned!", description = "Poison... I... I can feel it... burning. Please, $p... grab... grab some of the mogu swords. We need... need poison samples. For an... ant... antidote.You will receive:", objectives = "Gather 5 Mogu Poisoned Blades from Mogu Reavers in the Lost Dynasty." }
WordHunterWoW_QuestEN[30346] = { title = "Where are the Pools", description = "Perhaps these mogu know where the pools are.\n\nOur scouts have reported seeing a commander along the southern side of the Ruins of Dojan.\n\nKill him and take whatever information he is carrying. They should lead you to the pool.", objectives = "Obtain the Dojani Orders.", progress = "<You sense the presence of Lorekeeper Vaeldrin, then hear his voice within your mind.>\n\nHmm. I'm still not sure about these references to \"torture\" regarding the Pools of Youth.", completion = "Well done, <name>. Hmm, it looks like the mogu are here to collect ancient relics and weapons from their forgotten dynasty. That is a problem we can face later though.\n\nAh! Here is a reference to the Pools of Youth." }
WordHunterWoW_QuestEN[30347] = { title = "The Pools of Youth", description = "North! Go north to the Pools of Youth. Get some of the water but be on your guard.\n\nThe mogu list this as a \"high value\" target. Kang Bramblestaff will meet you there if he has not already arrived by your side.", objectives = "Obtain some of the Water of Youth.", progress = "Nothing like being mortal to give one a sense of urgency.", completion = "You... you found the pools! The waters do exist!\n\nSomething is wrong though. I feel equal parts shadow and light swirling in this vial." }
WordHunterWoW_QuestEN[30348] = { title = "Immortality?", description = "Something is... off. The water feels strange.\n\nWhen we arrived here I felt the presence of the Light, strong and vibrant, far to the north.\n\nI thought it would be the Pools of Youth. But this... this water is tainted somehow. Stained with mogu magics.\n\nI think it best I try only a sip and we see what happens.", objectives = "Observe Vaeldrin as he tests the water of youth.", completion = "Wha... what happened? The water... it... it only transfers life. It will not make new life." }
WordHunterWoW_QuestEN[30349] = { title = "Threat from Dojan", description = "While you were at the ruins dusting off tablets for my father I lost five scouts to wandering mogu patrols.\n\nThese creatures apparently have little interest in peace and are about as trustworthy as the Horde.\n\nThey are too numerous and we are too weak, however.\n\nGo to the ruins west of here and cull the mogu numbers. They won't be expecting a {class}.", objectives = "Kill 6 Dojani Reclaimers, 8 Dojani Surveyors, and 4 Dojani Enforcers.", progress = "Kang has been sharing stories with me about these mogu.\n\nApparently ages ago they ruled as emperors subjugating all free races of Pandaria and the surrounding regions. Now they are little more than hoodlums.\n\nTo see these mogu fight though, I suspect they are trying to rekindle some of their older ideals and ambitions.", completion = "Well done, <name>. Another few missions like that and we might have to make you an honorary sentinel." }
WordHunterWoW_QuestEN[30350] = { title = "Squirmy Delight", description = "The hidden master may have to wait. Look at these people, {name}.\n\nThey are so THIN! They must be starving.\n\nYou know what we need? A big steaming bowl of Squirmy Delight.\n\nIf you find yourself near a river, try rounding up some intact skitterer glands and I'll cook up a batch.", objectives = "Gather 5 Intact Skitterer Glands.", progress = "Mama Bramblestaff always said Squirmy Delight will cure any hunger one way or another.", completion = "Ha! With this I can make a stew potent enough to knock these waifish elves on their feet." }
WordHunterWoW_QuestEN[30351] = { title = "Lotus Tea", description = "The mogu really like their poisons and curses. Mama Bramblestaff always said lotus tea cures any mogu curse.\n\nI saw some imperial lotus plants in the nearby Ruins of Dojan. We should go gather some of their leaves and keep them on hand just in case the mogu get unruly.\n\nAlso, this will give me a chance to introduce my fists to some mogu faces.", objectives = "Gather 20 Imperial Lotus Leaves.", progress = "I have never seen the mogu this numerous before. They have always been a nuisance but never this bad.", completion = "That's it! You pick, I punch!" }
WordHunterWoW_QuestEN[30352] = { title = "Crane Mastery", description = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up.\n\nCan't hunt, can't brag. And I like bragging so this is no good.\n\nCan I hire you to go kill me some carp hunters? You'll find them up and down the river west of here. There are a bunch of them so don't hesitate to hunt while doing other stuff.", objectives = "Kill 12 Carp Hunters.", completion = "Fantastic. Only thing that would make this hunting trip more entertaining is a chair. Here is the reward I promised you." }
WordHunterWoW_QuestEN[30353] = { title = "Profit Mastery", description = "Two words: Tiger Blood!\n\nThis is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff.\n\nAnd this jungle is just full of tigers. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.", objectives = "Obtain 12 Vials of Tiger Blood.", progress = "I like hunting with Nesingwary and all but he's in it for the hunting. I'm in it for the profit, and he doesn't pay us.", completion = "Great! This stuff is gonna make me a mint back in Kalimdor. Here's your cut." }
WordHunterWoW_QuestEN[30354] = { title = "No Sister Left Behind", description = "We were searching the ruins south of here when the mogu fell upon us out of nowhere.\n\nSome of us were able to retreat to this encampment but many others were captured. The mogu have also caught a number of the Horde who happened to be in the area as well.\n\nPlease, {name}, rescue any sentinels that you can.\n\nLeave the Dawnchasers to their fate.", objectives = "Rescue 8 captives of the mogu.", completion = "There are so few of us, it is a great relief to see such help." }
WordHunterWoW_QuestEN[30355] = { title = "Re-Reclaim", description = "Mogu do NOT use arcane magics.\n\nThey are thugs. They have always been thugs. Only when they ruled their empires in the old stories did they ever know any kind of magic.\n\nBut these mogu are using arcane portals and old artifacts. We need to stop them!\n\n{name}, look for any artifacts the mogu are using to cast their magics with. I saw piles of these items being collected near the Ruins of Korja south of here.", objectives = "Recover 10 Mogu Artifacts.", progress = "Every artifact in our possession is one less weapon in mogu hands.", completion = "Well done <name>. You have removed the sword from the child's hands." }
WordHunterWoW_QuestEN[30356] = { title = "Sever Their Supply Line", description = "The mogu reclaimers are using portals to connect to Kun-Lai Summit, bringing in reinforcements and supplies.\n\nWhat is worse, they are sending their captives through these portals.\n\nGo to the Ruins of Korja and destroy as many of these Korjan Reclaimers as you can find.", objectives = "Kill 8 Korjan Reclaimers.", completion = "You have bought us some much needed breathing room to lick our wounds and prepare a counter-attack." }
WordHunterWoW_QuestEN[30357] = { title = "The Stoneplow Convoy", description = "Help me, {name}. These poor pandaren are in need of healing, and my powers are weakened.\n\nI did find an old tome in my collection that allowed me to convert the herbs you collected earlier into a healing poultice.\n\nUse this on the injured pandaren and it should get them back on their feet.", objectives = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys.", progress = "These mantid are a much bigger threat than I think even the pandaren give them credit for.", completion = "It has been a long time since I rolled up my sleeves and helped the needy. In my lust for immortality I forgot why I became a priest.\n\nThank you for reminding me there is good in this world worth fighting for, <name>." }
WordHunterWoW_QuestEN[30358] = { title = "Gryphon, Down", description = "The Fist of Garrosh will hold position over the harbor until all other threats from the ground are eliminated.\n\nYour next target: Baldruc, Theramore's gryphon master. That mad dwarf and his beasts can't be allowed to attack the airship from above.\n\nSlay Baldruc, along with his winged charges.", objectives = "Slay Baldruc and his gryphons." }
WordHunterWoW_QuestEN[30359] = { title = "The Lord Reclaimer", description = "They have my daughter! Brojai... that Lord Reclaimer! I can see him clearly through Lyalia's eyes.\n\nThat foolish girl must have tried to take him head on.\n\nPlease, {name}! Go to the Ruins of Korja and try to free her.\n\nI'll get Kang and try to draw out Brojai from the ruins with a distraction.", objectives = "Find Lyalia and kill Groundbreaker Brojai.", progress = "Lyalia is the only family I have left. I had to bury her mother during the war of Ahn'Qiraj.", completion = "Thank you for avenging my daughter. I am not willing to let her stay dead however.\n\nI still have the waters of youth." }
WordHunterWoW_QuestEN[30360] = { title = "Warn Stoneplow", description = "My father gave me his life. Tyrande gave me her trust. My sentinels gave me their allegiance.\n\nIt is time I repaid them all.\n\nWith Brojai dead we can mop up the remaining mogu. The next threat is the mantid.\n\nGo north to Stoneplow and lend them your help. Tell them I will be bringing what sentinels I can muster to aid in the defense of their city against the mantid.", objectives = "Travel to Stoneplow Village in Valley of the Four Winds.", completion = "Mantid from the south? This is not a good day." }
WordHunterWoW_QuestEN[30361] = { title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", objectives = "Kill 10 Ik'thik Mantid.", completion = "Thank you for your help, <class>! I've never seen anybody stand up to the mantid like that before.\n\nWell, other than the Shado-Pan, of course..." }
WordHunterWoW_QuestEN[30362] = { title = "Tanks for Nothing!", description = "The last threat to the airship is Theramore's arsenal of steam tanks.\n\nDestroy any active tanks and set bombs on any unmanned vehicles.", objectives = "Destroy any manned tanks and bomb any unmanned ones." }
WordHunterWoW_QuestEN[30363] = { title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nI want you to look for my scout. I sent her to investigate the Crane Temple but she hasn't returned.\n\nGet her report and rendezvous with us at the Sentinel Basecamp further west.", objectives = "Get Incursion Sentinel's Report.", progress = "Did you find the scout?", completion = "<name>, well timed as usual. It turns out the mogu know how to use portals as well." }
WordHunterWoW_QuestEN[30364] = { title = "Fly, Spy!", description = "The First of Garrosh is going the level Theramore Isle... but not until we free the spy whose intelligence made this operation possible.\n\nEnter Foothold Citadel and slay Captain Evencane for his shackles key.\n\nOur spy, the Sunreaver mage Thalen Songweaver, is being held beneath the barracks.", objectives = "Slay Hedric Evencane and free Thalen Songweaver in Foothold Citadel." }
