WordHunterWoW_QuestEN[30375] = { title = "Sea Snakes", description = "The rivers here are crawling with venomous aquatic snakes. Several evacuees were bitten as they fled from the temple, and already some are beginning to succumb to the poison.\n\nWe are administering anti-venom as quickly as possible, but we'll need more venom glands.\n\nI won't ask you to remove the glands in the field - that would take too long. Just bring back the heads and I'll take care of the rest.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather 6 Murkscale Heads from Murkscale Strikers in Krasarang River." }
WordHunterWoW_QuestEN[30376] = { title = "Hope Springs Eternal", description = "The Shado-Pan are likely dealing with similar outbreaks elsewhere in Pandaria.\n\nSeek out Loon Mai, the Shado-Pan Watch Commander in Stoneplow on the western end of the Valley of the Four Winds. Let him know that we have the situation here under control; the Shado-Pan need not send any aid.\n\nQuite the opposite, in fact - I will be sending many of my followers on pilgrimage, to bring a message of hope to those in need.\n\nThank you again, {name}. Farewell.", objectives = "Speak with Loon Mai in Stoneplow.", completion = "Finally, some good news. I will send a falcon to Winter's Blossom right away and let them know the Temple of the Red Crane is safe.\n\nBetween the sha outbreak and the increasing aggression of the mantid, our forces are being stretched thin." }
WordHunterWoW_QuestEN[30377] = { title = "Minimum Safe Distance", description = "As soon as you and your companions are clear, we're delivering our payload and reducing Theramore Isle to rubble.\n\nReturn to the Sea Wolf and Captain Drok as soon as possible.", objectives = "Return to the Sea Wolf and report to Captain Drok." }
WordHunterWoW_QuestEN[30378] = { title = "The Blastmaster", description = "Regroup at the harbor entrance to inform Blastmaster Sparkfuse of your success.\n\nHe will trigger the powder barrels and signal the airship forward.\n\nMake certain that none of your group is on those ships when they go up!", objectives = "Inform Blastmaster Sparkfuse at the harbor entrance that the powder barrels have been rigged." }
WordHunterWoW_QuestEN[30379] = { title = "A Ruby Shard for Gina", description = "", objectives = "Don't just stand there gawking. Spit it out.", progress = "Don't just stand there gawking. Spit it out.", completion = "Oh my, this is a flawless jewel!\n\nIf you keep giving me gifts like these, I may have to retire early!" }
WordHunterWoW_QuestEN[30380] = { title = "A Lovely Apple for Gina", description = "", objectives = "It's busy at the market today. What can I do for you?", progress = "It's busy at the market today. What can I do for you?", completion = "Oh, what a lovely apple! These sweet fruits are quite the treat around here." }
WordHunterWoW_QuestEN[30381] = { title = "A Jade Cat for Ella", description = "", objectives = "Do you have any pets? I like cats, but dogs are nice, too.", progress = "Do you have any pets? I like cats, but dogs are nice, too.", completion = "Oh, a jade cat!\n\nMy father and I used to hunt for these in the fields. He always said they were lucky." }
WordHunterWoW_QuestEN[30382] = { title = "A Blue Feather for Ella", description = "", objectives = "It's a lovely day out, don't you think?", progress = "It's a lovely day out, don't you think?", completion = "Oh, thank you. This beautiful feather is just lovely." }
WordHunterWoW_QuestEN[30383] = { title = "A Marsh Lily for Ella", description = "", objectives = "Hmm? Oh hello. How are you today?", progress = "Hmm? Oh hello. How are you today?", completion = "Oh my, these are quite rare. Thank you for giving it to me." }
WordHunterWoW_QuestEN[30384] = { title = "Blind Them!", description = "Horde sunwalkers! We saw one of their scouts patrolling by the oubliette not long before you arrived.\n\nI don't know how he got here but I can guarantee you he isn't alone. They never are.\n\nKill the sunwalker scout before he reports our position.", objectives = "Kill the Sunwalker Scout.", completion = "Sunwalkers are not to be trusted. They are the most militant branch of the tauren armies within the horde.\n\nThank you for your help in this, <name>. Please accept this token as a reward." }
WordHunterWoW_QuestEN[30385] = { title = "Setting Sun Garrison", description = "I offer you my heartfelt appreciation for your aid. Anji awaits you in the Setting Sun Garrison to the west.\n\nMay the day favor you, young {class}.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", completion = "Welcome. Che send you?" }
WordHunterWoW_QuestEN[30386] = { title = "A Dish for Ella", description = "A good day to you, neighbor.", objectives = "A good day to you, neighbor.", progress = "A good day to you, neighbor.", completion = "Oh my, Shrimp Dumplings? My favorite!\n\nThank you." }
WordHunterWoW_QuestEN[30387] = { title = "A Jade Cat for Gina", description = "", objectives = "Better to have many customers than none at all. How can I help you?", progress = "Better to have many customers than none at all. How can I help you?", completion = "What an interesting little figurine. It's quite lovely. Thank you, dear." }
WordHunterWoW_QuestEN[30388] = { title = "A Blue Feather for Gina", description = "", objectives = "What have you got there, neighbor?", progress = "What have you got there, neighbor?", completion = "Such a pretty feather would fetch a nice price at market, but I'm not selling this one. Thank you for the gift." }
WordHunterWoW_QuestEN[30389] = { title = "A Marsh Lily for Gina", description = "", objectives = "Hello <name>. Are you getting to know everyone in town?", progress = "Hello <name>. Are you getting to know everyone in town?", completion = "Oh wonderful! You've brought me a Marsh Lily.\n\nHow did you know that these are my favorite?" }
WordHunterWoW_QuestEN[30390] = { title = "A Dish for Gina", description = "I've been on my feet all day. You'd be surprised how busy this place gets.", objectives = "I've been on my feet all day. You'd be surprised how busy this place gets.", progress = "I've been on my feet all day. You'd be surprised how busy this place gets.", completion = "Bringing food to me on the busiest market day? What a sweetheart you are!" }
WordHunterWoW_QuestEN[30391] = { title = "A Ruby Shard for Old Hillpaw", description = "", objectives = "I got my own share of troubles at my farm. I don't need any of yours.", progress = "I got my own share of troubles at my farm. I don't need any of yours.", completion = "Oh, for me? Well, I guess that's mighty nice of you." }
WordHunterWoW_QuestEN[30392] = { title = "A Lovely Apple for Old Hillpaw", description = "", objectives = "Dang monkeys been at my farm again. Sure puts me in a foul mood.", progress = "Dang monkeys been at my farm again. Sure puts me in a foul mood.", completion = "Well ain't that sweet of ya. Hmph." }
WordHunterWoW_QuestEN[30393] = { title = "A Jade Cat for Old Hillpaw", description = "", objectives = "Whaddaya want today, <race>?", progress = "Whaddaya want today, <race>?", completion = "Hmph, well that is mighty fine of you to think of me like that.\n\nThank ye." }
WordHunterWoW_QuestEN[30394] = { title = "A Blue Feather for Old Hillpaw", description = "", objectives = "Can't an old man get some peace and quiet around here?", progress = "Can't an old man get some peace and quiet around here?", completion = "...\n\nMy son, Tai...he used to collect these as a little boy.\n\nWhen his mother died, I told him they were messages from her, fallen from the heavens.\n\n<Old Hillpaw falls into a quiet silence.>" }
WordHunterWoW_QuestEN[30395] = { title = "A Marsh Lily for Old Hillpaw", description = "", objectives = "Got a harvest coming up and my back's been giving me trouble again. Oh well, we all have to make do around here.", progress = "Got a harvest coming up and my back's been giving me trouble again. Oh well, we all have to make do around here.", completion = "Oh, these flowers are quite rare.\n\nYou know that these are considered lucky? Maybe my harvest will go well after all. Thank you." }
WordHunterWoW_QuestEN[30396] = { title = "A Dish for Old Hillpaw", description = "My wife used to make the most delicious braised turtle in four counties! I miss that woman.", objectives = "My wife used to make the most delicious braised turtle in four counties! I miss that woman.", progress = "My wife used to make the most delicious braised turtle in four counties! I miss that woman.", completion = "I haven't had this dish since my wife died. Somehow, she must have sent you to me.\n\nThank you, <race>." }
WordHunterWoW_QuestEN[30397] = { title = "A Ruby Shard for Chee Chee", description = "", objectives = "What you want?", progress = "What you want?", completion = "Pretty stone! You silly for giving away. Oh well, mine now!\n\nThanks, <race>!" }
WordHunterWoW_QuestEN[30398] = { title = "A Lovely Apple for Chee Chee", description = "", objectives = "Me not same as mountain monkeys. You get that straight.", progress = "Me not same as mountain monkeys. You get that straight.", completion = "For me? Red apple? So shiny! So juicy! Thanks, boss!" }
WordHunterWoW_QuestEN[30399] = { title = "A Jade Cat for Chee Chee", description = "", objectives = "Chee Chee was first hozen Tiller. If I could do it, so could you.", progress = "Chee Chee was first hozen Tiller. If I could do it, so could you.", completion = "Ooh, very old, very valuable. Me like kitties. Got one from girl Ella." }
WordHunterWoW_QuestEN[30400] = { title = "A Blue Feather for Chee Chee", description = "", objectives = "Ookin' mountain hozen! They not know how hard little Chee Chee workin'. Bad monkeys!", progress = "Ookin' mountain hozen! They not know how hard little Chee Chee workin'. Bad monkeys!", completion = "Oh my. You know what this is? A frikfrak! Frikfrak for chief only!\n\nWhich mean...you must think me is chief? We boss buddy now, <name>." }
WordHunterWoW_QuestEN[30401] = { title = "A Marsh Lily for Chee Chee", description = "", objectives = "Little Chee Chee lived here all my life. This is my home.", progress = "Little Chee Chee lived here all my life. This is my home.", completion = "Oh! Pretty flower! No takebacks boss, okay? Thank you, bye!" }
WordHunterWoW_QuestEN[30402] = { title = "A Dish for Chee Chee", description = "Chee Chee work in fields all day, so tired!", objectives = "Chee Chee work in fields all day, so tired!", progress = "Chee Chee work in fields all day, so tired!", completion = "Oh, Valley Stir Fry. Thanks!" }
WordHunterWoW_QuestEN[30403] = { title = "A Ruby Shard for Sho", description = "", objectives = "Yes, <class>. What can I do for you?", progress = "Yes, <class>. What can I do for you?", completion = "For me? Why thank you." }
WordHunterWoW_QuestEN[30404] = { title = "A Lovely Apple for Sho", description = "", objectives = "Shhh, listen. Always be on the alert.", progress = "Shhh, listen. Always be on the alert.", completion = "Thank you." }
WordHunterWoW_QuestEN[30405] = { title = "A Jade Cat for Sho", description = "", objectives = "The first step to disciplining your mind is to discipline your body.", progress = "The first step to disciplining your mind is to discipline your body.", completion = "I appreciate the sentiment, <race>." }
WordHunterWoW_QuestEN[30406] = { title = "A Blue Feather for Sho", description = "", objectives = "The watch is never finished.", progress = "The watch is never finished.", completion = "I appreciate your gesture, <race>. Thank you for thinking of me." }
WordHunterWoW_QuestEN[30407] = { title = "A Marsh Lily for Sho", description = "", objectives = "I have been hard at work, eliminating hozen up on the mountain.", progress = "I have been hard at work, eliminating hozen up on the mountain.", completion = "I have never been one to dwell on pretty, useless things, but I know you give me this gift out of friendship. For that, I thank you. Whenever I look at this flower, I will think of you." }
WordHunterWoW_QuestEN[30408] = { title = "A Dish for Sho", description = "Do not let your strength waver.", objectives = "Do not let your strength waver.", progress = "Do not let your strength waver.", completion = "Ah, this is the best gift you could have given me! A warrior needs her strength." }
WordHunterWoW_QuestEN[30409] = { title = "A Ruby Shard for Haohan", description = "", objectives = "Have you ever been to the Tiller's Union building in Halfhill?", progress = "Have you ever been to the Tiller's Union building in Halfhill?", completion = "Oh yes, this ruby will go nicely with the rest of my collection." }
WordHunterWoW_QuestEN[30410] = { title = "A Lovely Apple for Haohan", description = "", objectives = "How are things going at the farm?", progress = "How are things going at the farm?", completion = "Mmm, I do like a lovely apple." }
WordHunterWoW_QuestEN[30411] = { title = "A Jade Cat for Haohan", description = "", objectives = "What is it? I'm a busy man.", progress = "What is it? I'm a busy man.", completion = "Oh, this is exquisite craftsmanship. Where did you find such a thing?" }
WordHunterWoW_QuestEN[30412] = { title = "A Blue Feather for Haohan", description = "", objectives = "Howdy, <race>.", progress = "Howdy, <race>.", completion = "Hmm, this is a very lustrous feather. I'll add it to my collection of rare things." }
WordHunterWoW_QuestEN[30413] = { title = "A Marsh Lily for Haohan", description = "", objectives = "A good farmer keeps his soil tilled for planting. Untilled soil ain't no good for nobody, right <name>?", progress = "A good farmer keeps his soil tilled for planting. Untilled soil ain't no good for nobody, right <name>?", completion = "Hmm, I guess these flowers are supposed to be pretty lucky. I'm honored that yer giving it to me." }
WordHunterWoW_QuestEN[30414] = { title = "A Dish for Haohan", description = "A good farmer knows when to work and when to eat! You have to enjoy the fruits of your labor, right?", objectives = "A good farmer knows when to work and when to eat! You have to enjoy the fruits of your labor, right?", progress = "A good farmer knows when to work and when to eat! You have to enjoy the fruits of your labor, right?", completion = "Charbroiled Tiger Steak for me? How did you know this was my favorite dish?" }
