WordHunterWoW_QuestEN[30416] = { title = "A Ruby Shard for Farmer Fung", description = "", objectives = "Hey, it's the citypaw!", progress = "Hey, it's the citypaw!", completion = "Oh, that's a very nice stone." }
WordHunterWoW_QuestEN[30417] = { title = "A Lovely Apple for Farmer Fung", description = "", objectives = "How are you, <race>?", progress = "How are you, <race>?", completion = "Such a nice red apple for me?" }
WordHunterWoW_QuestEN[30418] = { title = "A Jade Cat for Farmer Fung", description = "", objectives = "What can I do for you?", progress = "What can I do for you?", completion = "Hmmm, a very interesting little statue." }
WordHunterWoW_QuestEN[30419] = { title = "A Blue Feather for Farmer Fung", description = "", objectives = "Howdy do, <race>!", progress = "Howdy do, <race>!", completion = "This is a very rare blue feather. Thank you." }
WordHunterWoW_QuestEN[30420] = { title = "A Marsh Lily for Farmer Fung", description = "", objectives = "Nothing feels better than knowing your planting's done.", progress = "Nothing feels better than knowing your planting's done.", completion = "Why this is a rare flower, indeed." }
WordHunterWoW_QuestEN[30421] = { title = "A Dish for Farmer Fung", description = "I think I hear my stomach grumbling.", objectives = "I think I hear my stomach grumbling.", progress = "I think I hear my stomach grumbling.", completion = "How did you know that this is my favorite dish? Thanks." }
WordHunterWoW_QuestEN[30422] = { title = "A Ruby Shard for Fish", description = "", objectives = "I been roundin' up yaks all mornin'.", progress = "I been roundin' up yaks all mornin'.", completion = "Ooh, now I never seen such a purty red stone. Thank ya, <name>!" }
WordHunterWoW_QuestEN[30423] = { title = "A Lovely Apple for Fish", description = "", objectives = "I been chasin' virmen all morning!", progress = "I been chasin' virmen all morning!", completion = "My stomach's been rumbling all mornin'! This is a perfect gift." }
WordHunterWoW_QuestEN[30424] = { title = "A Jade Cat for Fish", description = "", objectives = "I been wrestlin' pigs all mornin'.", progress = "I been wrestlin' pigs all mornin'.", completion = "Oh, a pretty jade cat! This makes me real happy, <name>!" }
WordHunterWoW_QuestEN[30425] = { title = "A Blue Feather for Fish", description = "", objectives = "I been diggin' up worms all mornin'.", progress = "I been diggin' up worms all mornin'.", completion = "Whoa, I never seen such a purty color before. Thanks, <name>!" }
WordHunterWoW_QuestEN[30426] = { title = "A Marsh Lily for Fish", description = "", objectives = "I been swimmin' with the fishes all mornin'.", progress = "I been swimmin' with the fishes all mornin'.", completion = "My pappy always said these flowers bring lotsa luck. Thanks, <name>!" }
WordHunterWoW_QuestEN[30427] = { title = "A Dish for Fish", description = "I been climbin' trees all mornin'.", objectives = "I been climbin' trees all mornin'.", progress = "I been climbin' trees all mornin'.", completion = "Oh boy, this is my favorite! Thanks, <name>!" }
WordHunterWoW_QuestEN[30428] = { title = "A Ruby Shard for Tina", description = "", objectives = "How are you today, <race>?", progress = "How are you today, <race>?", completion = "Oooh, a shiny sparkly gem! I love it!" }
WordHunterWoW_QuestEN[30429] = { title = "A Lovely Apple for Tina", description = "", objectives = "How do I look today, <name>?", progress = "How do I look today, <name>?", completion = "Oh why thank you, <name>." }
WordHunterWoW_QuestEN[30430] = { title = "A Jade Cat for Tina", description = "", objectives = "You know, it's hard work looking this good all the time.", progress = "You know, it's hard work looking this good all the time.", completion = "Why this is just lovely! Thank you so much, <name>." }
WordHunterWoW_QuestEN[30431] = { title = "A Blue Feather for Tina", description = "", objectives = "Would you like to sit down for a bit, <race>?", progress = "Would you like to sit down for a bit, <race>?", completion = "Oh, this blue feather will really bring out my eyes. Thank you, <name>." }
WordHunterWoW_QuestEN[30432] = { title = "A Marsh Lily for Tina", description = "", objectives = "How are things going over at the farm?", progress = "How are things going over at the farm?", completion = "Oh, this will bring me much luck! Thank you, <name>." }
WordHunterWoW_QuestEN[30433] = { title = "A Dish for Tina", description = "Please say hello to Farmer Yoon for me.", objectives = "Please say hello to Farmer Yoon for me.", progress = "Please say hello to Farmer Yoon for me.", completion = "Oh this is my favorite dish! Yum!" }
WordHunterWoW_QuestEN[30434] = { title = "A Ruby Shard for Jogu", description = "", objectives = "Spare a copper for a drink?", progress = "Spare a copper for a drink?", completion = "Oh, a pretty stone! I will look at this while I'm drinking." }
WordHunterWoW_QuestEN[30435] = { title = "A Lovely Apple for Jogu", description = "", objectives = "Buy a jinyu a drink?", progress = "Buy a jinyu a drink?", completion = "Hey, this is my favorite food! Thanks, <name>." }
WordHunterWoW_QuestEN[30436] = { title = "A Jade Cat for Jogu", description = "", objectives = "It's hard work you know, interpreting all these visions.", progress = "It's hard work you know, interpreting all these visions.", completion = "Thanks." }
WordHunterWoW_QuestEN[30437] = { title = "A Blue Feather for Jogu", description = "", objectives = "Tomorrow's crop will be... oh, I can't see it yet. I need something to drink, first.", progress = "Tomorrow's crop will be... oh, I can't see it yet. I need something to drink, first.", completion = "A nice blue feather for me? Thanks, <race>." }
WordHunterWoW_QuestEN[30438] = { title = "A Marsh Lily for Jogu", description = "", objectives = "The watersh shay that I will have great fortune today.", progress = "The watersh shay that I will have great fortune today.", completion = "The watersh were right! Thish flower will bring me luck." }
WordHunterWoW_QuestEN[30439] = { title = "A Dish for Jogu", description = "You know what goes with a good drink? A good meal.", objectives = "You know what goes with a good drink? A good meal.", progress = "You know what goes with a good drink? A good meal.", completion = "Nothing like a delicious cold brew, and some Sauteed Carrots to wash it down." }
WordHunterWoW_QuestEN[30442] = { title = "Blanche's Boomer Brew", description = "Brew Blanche's Boomer Brew by Protecting the Brewkegs.", objectives = "Help create the Boomer Brew. If the Brewkegs catch on fire, fix them!" }
WordHunterWoW_QuestEN[30443] = { title = "Walking on Sunwalkers", description = "The tauren!\n\nI refuse to let those flea bitten beasts claim the Pools of Youth for the Horde. None of their races have earned the right to immortality. They are by nature a series of short lived mortals who lack the humility and knowledge of how to properly support a long lived society.\n\nThey have infiltrators hunting for the pool. Kill those infiltrators before they find it. Their numbers are small so it shouldn't be that hard to cripple their eyes and ears.You will receive:", objectives = "Kill 3 Sunwalker Infiltrators." }
WordHunterWoW_QuestEN[30444] = { title = "No Reprieve", description = "We've been granted a brief respite from the mogu attacks as they attempt to recoup near the Five Sisters to our north. I would like you to see to it that they not be granted a similar reprieve.\n\nShow no mercy.", objectives = "Kill 8 Shao-Tien mogu near the Five Sisters.", completion = "That should keep them off balance for a while. Thanks." }
WordHunterWoW_QuestEN[30445] = { title = "The Waters of Youth", description = "She is headstrong, my little Lyalia. I should have known she would try to challenge the Lord Reclaimer.\n\nSince her mother died, I forsook much of the time I should have spent with her in search of immortality, insisting that we could live forever, together.\n\nAnd now my obsession has cost my little Lyalia her life.\n\nPlease, {name}, when she wakes, tell her I love her.", objectives = "Give Vaeldrin's message to Lyalia.", completion = "He... he shouldn't have done that! He shouldn't have paid for my mistake!" }
WordHunterWoW_QuestEN[30449] = { title = "Darkmoon Crane Deck", description = "Now that you have gathered all of the Crane cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Crane Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Crane deck!   Congratulations!", completion = "So you have put together a Crane deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[30450] = { title = "Darkmoon Ox Deck", description = "Now that you have gathered all of the Ox cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Ox Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Ox deck!   Congratulations!", completion = "So you have put together a Ox deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[30451] = { title = "Darkmoon Serpent Deck", description = "Now that you have gathered all of the Serpent cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Serpent Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Serpent deck!   Congratulations!", completion = "So you have put together a Serpent deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[30452] = { title = "Darkmoon Tiger Deck", description = "Now that you have gathered all of the Tiger cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Tiger Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Tiger deck!   Congratulations!", completion = "So you have put together a Tiger deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[30453] = { title = "Binan Village Intro Event Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[30454] = { title = "Pandaren Alliance Tracking Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30455] = { title = "Pandaren Horde Tracking Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30457] = { title = "Call Out Their Leader", description = "Clearly, you are a hero come to aid us.\n\nSlay the Bataari Tribe in the Kun-Lai Pass to the northwest until the Bataari Fire-Warrior is angered enough to appear.  Dispatch him.", objectives = "Slay 10 Bataari Tribe Members in the Kun-Lai Pass until the Bataari Fire-Warrior appears. Then kill him.", progress = "If the war leader of the yaungol is slain, surely our village will be saved and the refugees will be able to return to their farms.", completion = "We are delivered! I was right about you, <class>." }
WordHunterWoW_QuestEN[30458] = { title = "The Scouts Return", description = "{name}, your friends have returned from their scouting mission. They need to see you immediately.\n\nI'm afraid...\n\nWell, I'd better say no more. You will see for yourself.", objectives = "Speak to Rell Nightwind at the Glassfin Village in the Jade Forest.<name>, your friends have returned from their scouting mission. They need to see you immediately.\n\nI'm afraid...\n\nWell, I'd better say no more. You will see for yourself.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30459] = { title = "All of the Arrows", description = "As soon as their reinforcements arrive, the yaungol are going to overrun our position here. If they do that, the village will be lost.\n\nWould you be willing to retrieve as many arrows off the battlefield as you can carry? I have a plan that just might save us with your help.", objectives = "Collect 12 Arrows for Commander Hsieh.", progress = "How many arrows do you have?", completion = "Thank you, <name>. You've saved our defensive line here.\n\nThis next attack wouldn't have been possible without you." }
WordHunterWoW_QuestEN[30460] = { title = "Hit Medicine", description = "Our warriors are fighting to keep the yaungol at bay in the Kun-Lai Pass to the northwest.\n\nTake this liniment.  It is a powerful medicine that has been passed down in my family over the generations.\n\nUse the dit da jow to heal the injured warriors if you do not have healing powers of your own to use on them.", objectives = "Use the Dit Da Jow or your own healing to aid 8 Injured Binan Warriors.", completion = "You have my thanks, <name>. You have shown great honor through your actions.\n\nI hope that my family's dit da jow was of some use to you." }
WordHunterWoW_QuestEN[30461] = { title = "Into the Wilds", description = "Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", objectives = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", completion = "I see... So the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Bastion, I have to implore you to help us deal with them here." }
WordHunterWoW_QuestEN[30462] = { title = "Into the Wilds", description = "Deep in the wilds rests the  Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", objectives = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", completion = "I see... So the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Bastion, I have to implore you to help us deal with them here." }
WordHunterWoW_QuestEN[30464] = { title = "Going West", description = "Leza now walks with the ancestors of this strange land. I must look now to the living.\n\nKor has led a group of our scouts west deeper into the jungle.\n\nTrack him down and lend what aid you can to him. We will join you as quickly as we are able.", objectives = "Travel to Dawnchaser Retreat.", completion = "<name>! Well timed!\n\nWe were laying an ambush for the Alliance in the ruins west of here when the mogu ambushed us. They are using mage portals to call in reinforcements." }
WordHunterWoW_QuestEN[30465] = { title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nWe are pressing westward and could use your help.\n\nMeet us at the Sentinel Basecamp further west when you are ready.", objectives = "Speak with Lyalia at the Sentinel Basecamp in the Krasarang Wilds.", completion = "<name>, well timed as usual. It turns out the mogu know how to use portals as well." }
WordHunterWoW_QuestEN[30466] = { title = "Sufficient Motivation", description = "Training these savages has been quite a task, {name}.\n\nFinding ways to motivate them was easy enough; the problem is keeping them motivated.. and focused... and awake.\n\nNow that you're back, you can help me in getting the less disciplined Hozen moving, if you catch my drift. I'll leave the method up to you.", objectives = "Motivate 10 Lazy Hozen.", progress = "Are the Hozen ready to deploy?", completion = "Hrmm, I'll be surprised if we can keep these creatures focused enough to employ any tactics at all, <name>.\n\nThey'd better not get in my way when blades begin to fly!" }
WordHunterWoW_QuestEN[30467] = { title = "My Son...", description = "My son - can you find my son?\n\nWhen the Jinyu attacked, he ran off in the confusion. I don't know if they've done anything with him, or if he's still alive, even.\n\nNothing else matters if I can't find him. \n\nI'd ask Mei... but something's wrong with her. She seems too... impulsive since the attack. I just can't trust that she'd bring him back safely.", objectives = "Find Wu-Peng in the Inkgill Mere.", completion = "So horrible... When I saw the killing, I just ran. My father, Mei... are they alive?" }
WordHunterWoW_QuestEN[30468] = { title = "Enraged Vengeance", description = "<The Swordmistress does not look well. There's a darkness to her eyes uncharacteristic of the pandaren.>\n\nI don't think I've ever been as... as furious as now. What betrayal!\n\nI fought them off when they attacked, killed a few here, but Merchant Shi is too much of a coward to let me go and finish the job!\n\nYou, do it for me. Kill them. Kill them all.", objectives = "Kill 15 Enraged Jinyu.", completion = "It is satisfying to hear that our enemies are dead. Perhaps you can use one of my bodyguard's weapons." }
WordHunterWoW_QuestEN[30469] = { title = "Repossession", description = "Of course, the first priority is finding my son. But, if we save ourselves only to starve, then what have we accomplished, in the end?\n\nPlease, I need you to recover some of the supplies that the Jinyu took from our caravan.", objectives = "Collect 8 Stolen Supplies.", progress = "Have you found the supplies?", completion = "Thank you... we will eat now, at least." }
WordHunterWoW_QuestEN[30470] = { title = "A Gift For Tina", description = "That Tina Mudclaw is in the Halfhill Market today, visiting her sister. She's really nice, but she's really hard to get gifts for!\n\nThere's a little jewel that can be found in the cliffs to the north. It's called a chrysoberyl, and it changes color when you hold it. I'll bet she doesn't have one of THOSE!\n\nLook inside the virmen caves. I bet you'll find one really fast.", objectives = "Obtain an Uncut Chrysoberyl.", progress = "Hey there, <name>! Nice to see you again.", completion = "<Tina holds the gem in her hands, and watches it change from a pale blue to a bright red.>\n\nA chrysoberyl? That's so sweet! Was this Andi's idea?\n\nOf course I already have several... but this one is beautiful, too. I'll add it to the collection." }
WordHunterWoW_QuestEN[30471] = { title = "A Gift For Chee Chee", description = "That crazy Chee Chee is actually pretty neat. Mah always said that hozen were nothing but trouble, but... I guess he's just a better hozen then the rest of them.\n\nWe should do something nice for him! Those mountain hozen in the west make some really fancy stir fry, and keep bowls of it inside their little hozen houses.\n\nI bet Chee Chee would love some!", objectives = "Obtain an Authentic Valley Stir Fry.", progress = "Mmm?", completion = "For me? Me, Chee Chee?\n\nThis brings Chee Chee back to when Chee Chee was little wikkin' baby. Chee Chee's mama used to make it just like this." }
WordHunterWoW_QuestEN[30472] = { title = "A Gift For Sho", description = "Sho - that girl who lives up in the mountains - is in town today. I saw her walking toward the Halfhill Market.\n\nSuch a long walk... she must be hungry! And I think I know just the thing that she'll like.\n\nThe hozen up on the Skyrange cook a soup out of fish and apples. It sounds gross, I know... but it's awesome. You'll find it near their big, scary totem.", objectives = "Obtain a bowl of Yu-Ping Soup.", progress = "Oh! Hello, <name>.", completion = "I was famished! How'd you know? Who told you?\n\nAndi, huh? That kid's gonna grow up to be a real heartbreaker someday..." }
WordHunterWoW_QuestEN[30473] = { title = "A Gift For Fish", description = "That Fish Fellreed is kind of weird. First of all, her name's Fish. That's weird.\n\nOnce you talk to her, though, she's really a nice lady. Did you know that she's an animal lover?\n\nI've got an idea! The Kunzen hozen, in the mountains to the west, make little animal statues and put them in their huts to scare off bad guys. I bet Fish would LOVE something weird like that!", objectives = "Obtain a Yak Statuette from the inside of a Kunzen hozen hut.", progress = "Hey, <name>! What's up?", completion = "Aww, look at him! He's ADORABLE! With his fuzzy little tail, and his...\n\n<She composes herself.>\n\nI mean, ah... thanks, dude. It's pretty cool." }
WordHunterWoW_QuestEN[30474] = { title = "A Gift For Ella", description = "That poor Ella. She's so shy! I saw her standing in the Halfhill Market, looking really hungry, but afraid to talk to any of the chefs.\n\nWe should bring her some food! And not any boring food - something special.\n\nThe Kunzen hozen make spicy shrimp dumplings from ingredients they've stolen from our farms. I don't like spicy food, but Ella might!", objectives = "Obtain Spicy Shrimp Dumplings.", progress = "Oh, umm... hi.", completion = "You didn't have to do this! I didn't need any... any...\n\n<Ella eyes the dumplings, and her mouth begins to water.>\n\nWell, maybe I was a little hungry. Thanks, <name>. And give my thanks to Andi, as well." }
WordHunterWoW_QuestEN[30475] = { title = "A Gift For Fung", description = "Farmer Fung is pretty mean, and just a little scary. Mah always said that he was one of the best farmers in the valley, though.\n\nI think I know the perfect gift for a mean, kind of scary guy like him.\n\nThere's some big plainshawks that circle the hills to the west of here. You should get one, find a big piece of meat, and then ask Kol Ironpaw to grill it up!", objectives = "Obtain a Bloody Plainshawk Leg from a Monstrous Plainshawk, and then bring it to Kol Ironpaw in the Halfhill Market.", progress = "Harrumph!", completion = "Hey! Where'd you get that? I thought they were out of plainshawk!\n\nAndi asked you to get this for me? Huh. Maybe I underestimated that kid." }
WordHunterWoW_QuestEN[30476] = { title = "A Gift For Old Hillpaw", description = "Old Hillpaw has about a million chickens on his farm... but that's not what he REALLY loves.\n\nI saw. He collects blue feathers.\n\nI don't realy know where to get a blue feather around here, but I do know where to find some blue pearls!\n\nCheck the oysters in Cattail Lake to the northwest. I'm sure a blue pearl will look nice with his feather collection!", objectives = "Find a Blue Freshwater Pearl.", progress = "<name>! You startled me.", completion = "Well would you look at that! I'll have to keep this somewhere that the chickens can't get to.\n\nDid Andi tell you to get this for me? Funny kid, that one." }
WordHunterWoW_QuestEN[30477] = { title = "A Gift For Haohan", description = "Haohan Mudclaw is the big boss of the Tillers union and the richest guy in the Valley! He's been nice to let me stay here, so I want to do something nice for him.\n\nHe likes expensive stuff, like ruby shards, but I don't have a lot of money, so I need to get him something else.\n\nI know! I've seen a great big fish in Cattail Lake! We should get one of its teeth as a gift!", objectives = "Obtain an Enormous Cattail Grouper Tooth.", progress = "Need something, <class>?", completion = "Well, would you look at that! You don't see a tooth like THAT everyday.\n\nYou been hunting sharks, <class>?\n\nThank you, <name>. And send my thanks to Andi, as well." }
WordHunterWoW_QuestEN[30478] = { title = "A Gift For Jogu", description = "Sometimes I feel sad for Jogu. He's the only jinyu around, and I don't think he has any friends. Other than his smelly bottle, of course.\n\nYou know what? I've got an idea. Farmer Yoon has a basket of craneberries inside his house, and a few apples as well. I'm sure you could bring them to the stillmaster in the Halfhill Market and get him to brew something special for Jogu.", objectives = "Obtain 8 of Yoon's Apples and 50 of Yoon's Craneberries, then bring them to Bobo Ironpaw to brew into Apple-Berry Hooch.", progress = "Hmm?", completion = "<Jogu takes a long swig from the hooch.>\n\nThat'sh it! I've got a new favorite drink. An' it'sh this one!\n\nYou know what, <name>? You're alright. I mean it, man!" }
WordHunterWoW_QuestEN[30479] = { title = "A Gift For Gina", description = "Have you seen Gina Mudclaw, the market girl? She has it all - looks, brains, and nice big tummy. Could you deliver a gift for me?\n\nI wanted to pick some orchids that grow on top of the big hills to the west, but I can't climb that high. Could you pick a few and bring them to Gina?\n\nOh, and when you see her... tell her I said \"hi\".", objectives = "Obtain a Goldenfire Orchid.", progress = "Hey there!", completion = "These are beautiful! Did you get these for me?\n\nAhh... so they're from Andi, are they? I think I know somebody who's getting a kiss on the forehead later this afternoon..." }
WordHunterWoW_QuestEN[30480] = { title = "The Ritual", description = "From the moment I first rose from the river, I knew I was destined to be Waterspeaker.\n\nI was taught many rituals, and have performed all of them, save one.\n\nThere was one, an extremely ancient one, that we were told to call upon if our people ever turned against us. \n\nThis must have happened in our people's distant past, because we haven't needed to use it in our village's memory.\n\nI suppose now is the time to do so.", objectives = "Speak with Waterspeaker Gorai, and then complete the Ritual.", progress = "That... was not what I expected.", completion = "I see now that this ritual rips whatever was controlling the minds of these creatures from them. I now know what we must do." }
WordHunterWoW_QuestEN[30481] = { title = "Carved in Stone", description = "You see the shiny stones in the walls? Rook wants some. The mogu been collecting them, so they have some to take too maybe.\n\nIf you find stones, you please bring them to Rook? Rook will be your friend.", objectives = "Collect 12 Guo-Lai Runestones.", progress = "You find stones for Rook? Please?", completion = "So many!  And so shiny! You did real good!\n\nThank you, little friend. Rook like you a lot." }
WordHunterWoW_QuestEN[30482] = { title = "The Soul-Gatherer", description = "A single large mogu performing a ritual on the lake caught your attention while you were killing the other mogu in the area. It seems unwise to let his ritual complete.", objectives = "Kill Shadowmaster Sydow and recover the beads from his corpse.", progress = "<He looks at you expectantly.>", completion = "<As you hand the beads to He, his smile suggests that he understands perfectly what they symbolize. He nods approvingly.>" }
WordHunterWoW_QuestEN[30483] = { title = "NOT USED", description = "", objectives = "" }
WordHunterWoW_QuestEN[30484] = { title = "Gauging Our Progress", description = "The time for war is at hand, {name}!\n\nWe've been training these natives non-stop since you left, and I believe they're as good as they're going to get.\n\nSee for yourself. Check in with the others and return with your findings.\n\nWe must rely on our enemy being somehow... even less prepared.", objectives = "Check in with Shademaster Kiryn, Rivett Clutchpop, Shokia, and Riko.", progress = "How is our combat training coming along?", completion = "At least they're confident.\n\nThat might count for something." }
WordHunterWoW_QuestEN[30485] = { title = "Last Piece of the Puzzle", description = "These hozen are behaving most unnaturally, {name}. Marching in formation? In armor?\n\nThis troubles me. We must discuss it at another time, however. I have come to ask for your assistance.\n\nThe ancient fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor wanted us to remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.\n", objectives = "Use Cho's Heirloom at Cho's Family Shrine on Serpent's Overlook.\n\nSpeak with Mishi for transportation.", completion = "<Lorewalker Cho shudders, in spite of himself.>\n\nThe legends... they're true!" }
WordHunterWoW_QuestEN[30486] = { title = "Jade Dragon Phased Terrain Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[30487] = { title = "Comin' Round the Mountain", description = "The mountain pass is very dangerous. You need much luck to survive. Nephew Bentnail will show you the way.\n\nPerhaps today is a lucky day to travel though. Wind blows from the east; this is good sign. Grummles always travel best when east wind blows.\n\nClimb in the cart when you are ready to leave.", objectives = "Escort the cart and guides safely up Neverest Mountain.", progress = "You must be very lucky to survive the pass!", completion = "You've arrived just in time, <class>! I was starting to think I would die up here!" }
WordHunterWoW_QuestEN[30488] = { title = "The Missing Muskpaw", description = "What the heck are you supposed to be? a {class}? Never heard of one of them. You here to help or to steal my yaks?\n\nLook, if yer' insistin' on helpin' out, go find my boy. He got himself grabbed by a bunch of sprites and probably doesn't even know we lost the ranch.\n\nThey dragged him off to Pranksters' Hollow south east of here. Go rescue him an' I'll see about giving you a reward of some sort.", objectives = "Find Muskpaw Jr. in Pranksters' Hollow.", completion = "Thank you for the save, stranger!" }
WordHunterWoW_QuestEN[30489] = { title = "Fresh Needle Scent", description = "Say, if you really are here to help, I could use me some needles off them sprites in Pranksters' Hollow.\n\nThe grummles don't believe in luck they can't smell. They'll pay better for yaks that have that fresh needle scent.", objectives = "Gather 100 Pungent Sprite Needles.", progress = "Mmm. Nothing like the fresh scent of needle.", completion = "You just earned me a handsome bonus. Getting those needles is a pain in the paw but worth it when we take our yaks to market. Here, for your troubles." }
WordHunterWoW_QuestEN[30490] = { title = "Yakity Yak", description = "Yaungols! They come through here taking what they want and destroying whatever's left.\n\nI can't have these thugs destroy the last pieces of the Yak Wash here. It's all my boy and I have left.\n\nHead over to our old ranch and dish out some pain on them yaungols. I bet if you kill enough of them they'll think twice before attacking anything in this area.", objectives = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch." }
WordHunterWoW_QuestEN[30491] = { title = "At the Yak Wash", description = "Look, my father is crazy. I love him, but he's crazy.\n\nThese yaungol managed to completely obliterate our ranch and scattered our yaks every which way.\n\nIf I know my father though, he's going to try to go head to head with the yaungol to get the yaks back.\n\nCan you help us round up some of the yaks so my father doesn't do anything stupid?\n\nJust ride them over to the Yak Wash so we can clean them up and sell them to the grummles.", objectives = "Bring 6 Escaped Yaks to the Wash Entrance at Lao & Son's Yak Wash.", progress = "The grummles always insist they have better luck with cleaned yaks.\n\nAs long as they pay more I'm not going to argue. We need the gold. Now more than ever.", completion = "Well done, stranger! Hopefully we'll be able to cash these in and recoup some of the damages the yaungol inflicted." }
WordHunterWoW_QuestEN[30492] = { title = "Back in Yak", description = "I wasn't lying about your reward. Here, take these washed yaks to the grummle caravan master Eightcoins.\n\nYou can find him at the Grummle Bazaar west of here. He'll credit us and give you a delivery fee.\n\nHe may be short, but he is our biggest customer.\n\nReturn to me if you lose the yaks. More often than not they just come right back here anyway. Once they've been cleaned that is.", objectives = "Bring the Washed Yaks to Lucky Eightcoins at the Grummle Bazaar in Kun-Lai Summit. Return to Muskpaw Jr. if you lose your yaks.", progress = "And what have we here?", completion = "Ah! I can smell the luck from here. The Muskpaws always have good yaks for sale." }
WordHunterWoW_QuestEN[30495] = { title = "Love's Labor", description = "Can I trouble you for another favor?\n\nWe're way behind schedule, and this jade shipment is the last we need to finish the great statue.\n\nI've got my hands full, so could you run this ore over to the other foremen?\n\nHistorian Dinh, Surveyor Sawa, and Kitemaster Shoku can all be found around the base of the statue. Taskmaster Emi is directing production at the top of the statue.\n\nWe're on a deadline, so make sure you do it fast! Time's a wasting!", objectives = "Deliver the jade to Historian Dinh, Surveyor Sawa, Kitemaster Shoku, and Taskmaster Emi.", progress = "Did you deliver the jade in time?", completion = "What, done already? You're quite the runner, <class>. You ever thought about making a living out of this?" }
WordHunterWoW_QuestEN[30496] = { title = "The Waterspeaker's Staff", description = "There is great dissent in Inkgill, {race}. Elder Shai Hu drank the sha-corrupted waters of the mere, and forced the others to do the same. When I protested, Orachi of the town guard confiscated my ritual staff and banished me.\n\nNow, I am not only an exile, I am unable to speak with the waters that once gave me guidance!\n\nI am not a fighter. But if you are, perhaps you can recover my staff from Orachi? He is in town to our north.", objectives = "Recover Waterspeaker Gorai's Stolen Inkgill Ritual Staff from Orachi in Inkgill Mere.", progress = "Have you found the staff?", completion = "Good. Now we have some hope of redeeming this situation." }
WordHunterWoW_QuestEN[30498] = { title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", objectives = "Report to Admiral Taylor in Pearlfin Village.\n\nProvided item:", completion = "Welcome back, <name>. I trust your journey has been insightful, particularly in regards to the layout of the land. There is still much to do before we march into battle." }
WordHunterWoW_QuestEN[30499] = { title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", objectives = "Return to General Nazgrim at Grookin Hill.\n\nProvided item:", completion = "Throm-Ka, <name>!\n\nI hope you were able to gather useful information while on your journey through the forest.\n\nOur preperations are almost complete, but your help is needed." }
WordHunterWoW_QuestEN[30500] = { title = "Residual Fallout", description = "Pandaria is a mystical land, traveler.\n\nIt bears repeating that some of its secrets remain hidden, even to Lorewalkers.\n\nSealing those fissures did not mend what has been broken. If the legends are true, it will take much more to release this land from the grasp of the Sha.\n\nThe aggression of that battle awakened a host of living negative emotions. What you see here is likely the first of many such manifestations.\n\nFor now, we can only try to diminish their presence here.", objectives = "Destroy 10 Sha Echoes.", progress = "This, it seems, is only the tip of the iceberg, <name>.", completion = "This is terrible...\n\nWe must find a way to undo what has been done here." }
WordHunterWoW_QuestEN[30501] = { title = "Gossip Accept Quest Test Case", description = "", objectives = "" }
WordHunterWoW_QuestEN[30502] = { title = "Jaded Heart", description = "The more powerful remnants of that horrible manifestation may be too much for you to handle on your own, {name}.\n\nI fear I'd be of little help in terms of actual combat, but I can suggest a solution.\n\nThe great jade statue was soon to become a living serpent - one of our revered celestials. Its construction imbued it with special powers that may sufficiently weaken these adversaries.", objectives = "Use Celestial Jade Chunks to defeat 6 Sha Remnants.", progress = "Do you have the jade, <name>?", completion = "<Cho looks at you despondently.>\n\nThis jade was meant for... so much more." }
WordHunterWoW_QuestEN[30504] = { title = "Emergency Response", description = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", objectives = "Use Cho's Fireworks near General Nazgrim, Shademaster Kiryn, Shokia, and Rivett Clutchpop.", completion = "My thoughts will be with your fallen companions, traveler.\n\nMay their wounds mend well." }
WordHunterWoW_QuestEN[30506] = { title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", objectives = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", completion = "<name>, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway." }
WordHunterWoW_QuestEN[30507] = { title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", objectives = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", completion = "<name>, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway." }
WordHunterWoW_QuestEN[30508] = { title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", objectives = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", completion = "<name>, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway." }
WordHunterWoW_QuestEN[30509] = { title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", objectives = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", completion = "Where have you been, <name>? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they." }
WordHunterWoW_QuestEN[30510] = { title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", objectives = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", completion = "Where have you been, <name>? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they." }
WordHunterWoW_QuestEN[30511] = { title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", objectives = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", completion = "Where have you been, <name>? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they." }
WordHunterWoW_QuestEN[30512] = { title = "Westwind Rest", description = "<Admiral Taylor winces in pain.>\n\nJade Forest was a disaster. \n\nAnduin's gone. We lost some good people. We didn't stop the Horde from advancing into the continent. \n\nBut I think I've found a way to get the locals on our side. You just helped fight off some of these \"yaungol\", no?\n\nI hear yaungol sacked Westwind Rest, a local village. We've been told that two groups of survivors have camped out along the road west out of town.\n\nWe help them out, maybe they'll consider siding with the Allliance.", objectives = "Speak with Farmhand Bo and Elder Tsulan in the Yaungol Advance.", progress = "I will not rest until our people are returned and this village rebuilt.", completion = "Well... we are alive, and that is better than we could have hoped for without your help.\n\nBut, if this is truly to become a base of operations for you, and if we are to join your Alliance, there is one more thing you must do to guarantee our security." }
WordHunterWoW_QuestEN[30513] = { title = "Eastwind Rest", description = "I am injured, but we can't stop here.\n\nThe hozen were... unreliable. The pandaren would be much better allies.\n\nYou have seen the refugees in this village, and heard of the yaungol invasion, no?\n\nWell, we've heard from the locals that Eastwind Rest, a nearby village, was destroyed by the Yaungol.\n\nApparently some survivors have gathered along the road out of town.\n\nGo. Take the road west. Gather the survivors. \n\nWe'll help them rebuild. Then, they will see the advantage of joining the Horde!", objectives = "Speak with Farmhand Ko and Elder Shiao in Kun Lai Summit.", progress = "I will not rest until our people are returned and this village rebuilt.", completion = "Well... we are alive, and that is better than we could have hoped for without your help.\n\nBut, if this is truly to become a base of operations for you, and if we are to join your Horde, there is one more thing you must do to guarantee our security." }
WordHunterWoW_QuestEN[30514] = { title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", objectives = "Set the Yaungol Banner ablaze to summon Ur-Bataar, and then defeat him in combat.", completion = "You did it! At the very least, we have justice, and safety, though in the process we have lost so much.\n\nRegardless, it has been decided. We will join the Alliance, and with your help, rebuild this village." }
WordHunterWoW_QuestEN[30515] = { title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", objectives = "Set the Yaungol Banner at Fire Camp Bataar ablaze to summon Ur-Bataar, and then defeat him in combat.", progress = "As long as Ur-Bataar lives, we cannot have peace.", completion = "You did it! At the very least, we have justice, and safety, though in the process we have lost so much.\n\nRegardless, it has been decided. We will join the Horde, and with your help, rebuild this village." }
WordHunterWoW_QuestEN[30516] = { title = "Growing the Farm I: A Little Problem", description = "So you need to whack some wily weeds?\n\nNo problem, neighbor! Only thing is, I'm running low on weed killer.\n\nI make my own concoction - very potent, totally organic and good for the earth. Plants love it! Well... except for those pesky weeds. They hate the stuff!\n\nIf you bring me some Spideroot from the terraces just west of us, I'll make a fresh batch and go down to Yoon's farm myself.\n\nI would gather some myself but... well... I hate spiders. You'll see what I mean.", objectives = "Gather 6 Spideroot for Gai Lan.", progress = "How did the root gathering go?", completion = "Well what do we have here? You harvested enough to last me a while.\n\nMany thanks!" }
WordHunterWoW_QuestEN[30517] = { title = "Farmer Fung's Vote I: Yak Attack", description = "The next voting member on the Tiller's council is Farmer Fung, and it's easy to see why.\n\nThat man's vegetables are the biggest in the valley! I only hope that someday I can grow pumpkins as big as his.\n\nIf we hope to join the Tillers, he would be the next person to convince.", objectives = "Speak to Farmer Fung at The Heartland or the Halfhill Market in the Valley of the Four Winds.", completion = "Oh? You're with that new farmer in town, aren't you?" }
WordHunterWoW_QuestEN[30518] = { title = "Farmer Fung's Vote II: On the Loose", description = "You want my vote for Farmer Yoon? Ha! You're joking, right?\n\nListen, I'm not going to vote for some citypaw with no lick a' knowledge about farming the earth.\n\nIt would be an embarrassment to farm alongside you or that Yoon shmuck.\n\nNow let me deal with my own problems. Some devil let my prize yaks loose, and now they're running wild northwest of Halfhill.\n\nIf I could just get my yaks back, then maybe I'd be able to sleep at night.", objectives = "Return 5 Escaped Shagskins to Farmer Fung's yak pen at the very north end of the Verdant Belt.", completion = "<Farmer Fung stares at you with his jaw on the floor.>\n\nI... I can't believe... YOU recovered all of my prized shagskins!\n\nDo you... do you know what this means to me?\n\nMy family's only been good at two things - raising enormous vegetables and raising yaks.\n\nThe shagskins you see are the result of generations of work.\n\nYou have saved my family's legacy, <name>." }
WordHunterWoW_QuestEN[30519] = { title = "Nana's Vote I: Nana's Secret Recipe", description = "The next vote we'll need is from Nana Mudclaw. She's Haohan's grandmother, and she's been a Tiller longer than you and I have been alive!\n\nShe's still working at the Tillers building in Halfhill. Why don't you pay her a visit?", objectives = "Speak to Nana Mudclaw at Halfhill in the Valley of the Four Winds.", completion = "Yes, Nana Mudclaw... that is me. I may be old, dear, but I haven't lost my memory. Old Man Whitewhiskers, on the other hand, is another story." }
WordHunterWoW_QuestEN[30520] = { title = "Tummy Trouble", description = "I like Farmer Yoon just dandy as a neighbor, but getting my vote is another matter entirely. He does know that my father is the head of the Union, right?\n\nAnyway, I've got bigger problems to worry about. Lotta folks been getting sick from eating bad vegetables.\n\nSince they bought the produce from my market, my reputation is in jeopardy.\n\nNow I've got an idea to cure the stomach rumbles, but it ain't pretty.\n\nIf you'd be willing to... um... hurry things along, I just might be indebted to you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Gooseberries to cure sick Halfhill Villagers." }
WordHunterWoW_QuestEN[30521] = { title = "Haohan's Vote I: Bungalow Break-In", description = "This is going to be tough, {name}.\n\nThe last vote we need comes from Haohan Mudclaw, the head of the Tillers Union.\n\nI know he wasn't too keen on us to start, but we've learned so much about farming, I'm sure he'll have a change of heart!\n\nGo speak to him. You can be very convincing, right?", objectives = "Speak to Haohan Mudclaw at The Heartland or at Halfhill Market in the Valley of the Four Winds.", completion = "What do you want?" }
WordHunterWoW_QuestEN[30522] = { title = "Haohan's Vote II: The Real Culprits", description = "What are YOU doing here, citypaw?\n\nLook, I've got my hands full with a break-in at my shed to the west. Some rascals came in the middle of the night and ransacked the place.\n\nI've got missing seeds, broken tools, and eaten inventory to deal with.\n\nI'll just add it to my list of other troubles: a whole wagon of melons stolen, a broken water pump, animals ruining my harvest...\n\nI wish that I could just get to the bottom of all this already!", objectives = "Investigate 8 Suspicious Footprints.", completion = "Hmmm, I'm sorry to hear that Haohan's up to his neck in trouble. Thank you for bringing me this news. Maybe we can help him out." }
WordHunterWoW_QuestEN[30523] = { title = "Growing the Farm II: The Broken Wagon", description = "Hey {name}. I've been looking at that wagon every day, day in and day out, since the day I moved in. Quite an eyesore, don't you think?\n\nI heard in town that Fish Fellreed is quite handy with tools. She might be able to fix it up, and then we could turn that patch of land into a plot for farming.\n\nWhy don't you talk to her and see if she'd be willing to do the job?", objectives = "Speak to Fish Fellreed at Cattail Lake or the Halfhill Market in the Valley of the Four Winds.", completion = "You need my help fer somethin'? You came to the right gal!" }
WordHunterWoW_QuestEN[30524] = { title = "Growing the Farm II: Knock on Wood", description = "Sure! I know just the wagon that you're talkin' about!\n\nI can fix it right up, but I'll need wood.\n\nThere's a whole lot of it down at the bottom of the lake. If you fish it right out - haha, get it? Fish? Oh I just crack myself up sometimes.\n\nAnyway, you bring me here some 'o that wood and then I'll get right to work!", objectives = "Collect 100 Waxed Planks.", progress = "That lake is plum full o' treasures! You just gotta know what to look for.", completion = "Aww yeah, this wood'll do jus' fine. You did good, <name>." }
WordHunterWoW_QuestEN[30525] = { title = "Haohan's Vote III: Pure Poison", description = "All right, {name}. This is our big chance!\n\nMr. Mudclaw's farm is in big trouble. Those mountain hozen are coming down at night, wrecking his crops and eating his hard-earned harvest.\n\nWe've got to get rid of them for good, and I know just how to do it.\n\nBack in the day, my grandpa showed me how to mix a wounding poison to deal with the pests on the farm.\n\nThe virmen warrens to the north hold the key ingredients for my mixture.\n\nDon't look so worried, {name}! I'm pretty sure this is going to work.", objectives = "Collect 1 Bloodbloom, 1 Cave Lily, 1 Ghostcap, and 1 Violet Lichen.", progress = "The hozen are going to get a big surprise!", completion = "You got the ingredients? Good work!\n\nNow I just need to make the concoction." }
WordHunterWoW_QuestEN[30526] = { title = "Lost and Lonely", description = "The starving, mangy dog whines piteously and attempts a brief wag of its tail.\n\nIt looks like it could use a good meal right about now.", objectives = "Collect 20 Tasty T-Bone from the Skyrange Mushan on the Skyrange in the Valley of the Four Winds.", progress = "A light comes into the dog's eyes. It seems to recognize you.", completion = "The dog perks its ears up at the sight of the juicy steak.\n\nAs soon as you throw it down, the dog starts eating ravenously." }
WordHunterWoW_QuestEN[30527] = { title = "Haohan's Vote IV: Melons For Felons", description = "All right, now I happen to know that those mountain hozen love a delicious, sweet melon.\n\nMr. Haohan's last harvest of melons got stolen, so we're going to have to grow some of our own.\n\nOnce we have our harvest, we'll use them to lure the nasty hozen's leader out of its cave!", objectives = "Plant and harvest 4 Striped Melons, then deliver 20 Striped Melons to Farmer Yoon.\n\nStriped Melon Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Striped Melons.", progress = "Let's make sure we grow some good melons, <name>. Those crafty hozen only like the sweetest melons.", completion = "Wow, <name>! Those are some big melons. Those are hard to grow, and I should know because I've tried! \n\nI don't know how I would run this place without you, <name>." }
WordHunterWoW_QuestEN[30528] = { title = "Haohan's Vote V: Chief Yip-Yip", description = "You ready for the final step of the plan?\n\nThe leader of the Kunzen hozen is a brute by the name of Chief Yip-Yip. It's said that he is nearly impervious to pain.\n\nI've injected the melons with a toxic mixture, so don't try eating them!\n\nOnce you get his attention, throw these melons onto the ground. Yip-Yip won't be able to resist a sweet striped melon.\n\nWhen he takes a bite, he'll be temporarily weakened, and you should find yourself an opening to attack.", objectives = "Kill Chief Yip-Yip at Kunzen Cave to the northwest.", completion = "The hozen chief is dead? Our plan worked, <name>!" }
WordHunterWoW_QuestEN[30529] = { title = "Growing the Farm III: The Mossy Boulder", description = "Now that we're officially members of the Tillers Union, Mr. Mudclaw said he'd be happy to help us upturn this big ole' rock in the middle of our field.\n\nOnce we clear away that stone, I've got something special planned.\n\nRun down and give him a holler to let him know that we're ready.", objectives = "Speak to Haohan Mudclaw in The Heartland or at Halfhill Market in the Valley of the Four Winds.", completion = "Yoon needs a neighbor to lend a hand, eh? Well I'll be plenty happy to oblige." }
WordHunterWoW_QuestEN[30530] = { title = "Tracking Event: Started First Expansion", description = "", objectives = "" }
WordHunterWoW_QuestEN[30531] = { title = "Tracking Event: Finished First Expansion", description = "", objectives = "" }
WordHunterWoW_QuestEN[30532] = { title = "Tracking Event: Started Second Expansion", description = "", objectives = "" }
WordHunterWoW_QuestEN[30533] = { title = "Tracking Event: Finished Second Expansion", description = "", objectives = "" }
WordHunterWoW_QuestEN[30534] = { title = "A Second Hand", description = "Despite your best efforts, the work is starting to pile up around here.\n\nPerhaps you could ask one of your best friends if they'd like to help out at Sunsong Ranch.", objectives = "Speak to one of your best friends and ask them to work on Sunsong Ranch.", progress = "It's a sturdy rake.", completion = "The talismans on the shrine tinkle softly in the wind." }
WordHunterWoW_QuestEN[30535] = { title = "Learn and Grow I: Seeds", description = "Well, first things first! I'm going to need lots of help 'round here.\n\nIf we're going to be partners, you've got to learn how to harvest crops, and if you wanna harvest crops you gotta plant seeds!\n\nNow it's my understanding that a mister, uh... Grainfell? No, that wasn't it... Greedfill? That doesn't sound right...\n\nGreenfield! That's his name! He's the man to see for seeds.\n\nGreenfield's got a stall over at Halfhill Market, directly southeast of here - go see him and pick up some vegetable seeds.", objectives = "Speak with Merchant Greenfield at Halfhill Market and acquire a Packet of Green Cabbage Seeds.", progress = "How'd it go, partner? Did you get those seeds from Groanfur?\n\nErr... Greenfield?", completion = "He waved at me! And he gave you the first pack of seeds for free?\n\nWell, what a nice guy!\n\nYou're doing a great job so far. Here's a little... seed money. Hah!" }
WordHunterWoW_QuestEN[30536] = { title = "FLAG - Weed War Training", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.Upon completion of this quest you will gain:", objectives = "Listen to Xiao and his companions." }
WordHunterWoW_QuestEN[30537] = { title = "A Fizzy Fusion", description = "", objectives = "" }
WordHunterWoW_QuestEN[30538] = { title = "Fun for the Little Ones", description = "", objectives = "" }
WordHunterWoW_QuestEN[30564] = { title = "Tracking Event: Talked to Dog at Farm", description = "", objectives = "" }
WordHunterWoW_QuestEN[30565] = { title = "An Unexpected Advantage", description = "Things seem to be goin' our way more and more lately, {name}. I was out doin some explorin' when I came upon this little beauty.\n\n<Sully gestures to the ballista to his right.>\n\nProblem is she's one of a set and the other one is still in pieces. I'd have gotten it together by now if those pesky Grimleers hadn't ambushed me and taken some of the gears and bolts.\n\nHey, ye seem to be pretty good at handlin' the natives. Ye wouldn't mind goin' and helpin' ol'Sully out would ye? ", objectives = "Retrieve the missing Water-Damaged Gears and Rusty Locking Bolts from the Hozen Ambushers to the East.", progress = "Did ye find my missing gears and bolts?", completion = "Well these aren't as good as she deserves, but it will have to work.\n\n<Sully pats the dismantled ballista.>\n\nI'll get 'er up and runnin' in no time, just ye watch!" }
WordHunterWoW_QuestEN[30566] = { title = "FLAG - Pest Problems Training", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.Upon completion of this quest you will gain:", objectives = "Listen to Xiao and his companions." }
WordHunterWoW_QuestEN[30567] = { title = "Blanche's Boomer Brew", description = "Can you smell it in the air? A storm is brewing! And so am I!\n\nMeet me at the hilltop when the storm hits and together we'll whip up a keg of my most famous brew. Can I count on your help?\n\n", objectives = "Complete the \"Brewing Storm\" Scenario.", completion = "None too shabby, my <class> friend! We've saved the monastery and still have half a keg left.\n\nThank you for your help!" }
WordHunterWoW_QuestEN[30568] = { title = "Helping the Cause", description = "Welcome back, {name}! It seems the Jinyu have taken to our training even better than I had hoped. We're in the final stages of our preparations now.\n\nI need someone to go check in with Amber, Bold Karasshi, and Mishka. See if they need any help to complete their training.\n\nYou'll find Karasshi and Mishka here in Pearlfin Village. Amber is training recruits in Slingtail Pits to the northwest.", objectives = "Check in with Bold Karasshi, Amber Kearnen, and Mishka.", progress = "Is everyone in order and ready to move?", completion = "Impressive work, <name>. We should be ready to move out shortly. With our allies at our side, there is no way we can be defeated." }
WordHunterWoW_QuestEN[30569] = { title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him out. Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", objectives = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit.", completion = "You're a sight for sore eyes, <class>.\n\nI'll be glad to help you Alliance fellas out. First though, you need to help me get my farm back." }
WordHunterWoW_QuestEN[30570] = { title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him... Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", objectives = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit.", completion = "You're a sight for sore eyes, <class>.\n\nI'll be glad to help you Horde fellas out. First though, you need to help me get my farm back." }
WordHunterWoW_QuestEN[30571] = { title = "Farmhand Freedom", description = "Those Ordo yaungol are working my farmhands to death! It just ain't right.\n\nPlease, {class}, save them before it's too late.", objectives = "Free 12 Farmstead Slaves by killing Ordo Overseers.", progress = "Look, mister, I don't mean to be telling you your business, but I can still see a lot of my farmhands still out there.", completion = "Now ain't you just the thing?\n\nThough, I guess it's not fair to force these here workers to stay with us, now that we don't have much work for 'em..." }
WordHunterWoW_QuestEN[30573] = { title = "Tracking Event: Started Third Expansion", description = "", objectives = "" }
WordHunterWoW_QuestEN[30574] = { title = "Tracking Event: Finished Third Expansion", description = "", objectives = "" }
WordHunterWoW_QuestEN[30575] = { title = "Round 'Em Up", description = "Mobility is going to be key to maintaining our foothold in this new land. Problem is, there's no way to maintain mobility without mounts, and... well, we don't have many of those here, now do we?\n\nThe local yaks seem to make good mounts. At least, the local pandaren say they do. Why don't you go round some up for us?", objectives = "Round up 3 Wild Plains Yaks and return them to Westwind Rest.", progress = "It's going to take more yaks than that to get this place back into fightin' condition, <name>, yes it is.", completion = "These yaks will do the trick nicely. Good work, <name>. I'm feeling better about this whole situation already." }
WordHunterWoW_QuestEN[30581] = { title = "... and the Pot, Too!", description = "Sure, I'm willing to help you guys out. But we need to eat, too! I don't even have a pot to cook in! Let alone ingredients to put in it!\n\nHere's a list of the things that I need. Now get!", objectives = "Collect 12 Root Vegetables and 1 Cast Iron Pot.", progress = "Do you have everything from the list?!", completion = "Well there you go. We should be plenty good, now." }
WordHunterWoW_QuestEN[30582] = { title = "The Late Mrs. Muskpaw", description = "This well worn trinket has several markings on it confessing love and adoration from the late Mrs. Muskpaw.\n\nPerhaps Lao would like his wife's trinket back.", objectives = "Bring the Muskpaw Keepsake to Lao Muskpaw.", progress = "Oh, and what have you there.", completion = "Ya never know how much you can lose until you've lost it. My wife passed a few seasons ago, but I can tell you this is a day when I could use her smile the most.\n\nAt least she doesn't have to see what these yaungol did to her beloved ranch." }
WordHunterWoW_QuestEN[30583] = { title = "Blue Dwarf Needs Food Badly", description = "Oi!\n\nWe need ta' get us some food, if we're gonna survive here for long!\n\nYe' may not know it, but I'm somethin' of a cook me'self. Why don'tcha go out there and fetch us some meaty bits. I can cook 'em up and feed us for weeks! Or, days, at least.", objectives = "Collect 160 Kun-Lai Meaty Bits.", progress = "Well... ya' got my meat?", completion = "Good work! I'm telliin' ye, these Kun-Lai meaty bits are grade A goodness!" }
WordHunterWoW_QuestEN[30584] = { title = "Shocking!", description = "Have you ever had a fresh dojani eel {name}?  No?\n\nWell you have not lived then!  Head north up to the dojani river and fish up a few for us.   Be careful, those eels can zap you if you're not careful!", objectives = "Fish up 7 Dojani Eels from the Dojani River in Krasarang Wilds.", progress = "Were you able to catch the eels?", completion = "These look like some tasty eels <name>!  I'm sure you will love them!" }
WordHunterWoW_QuestEN[30585] = { title = "What Lurks Below", description = "Legend tells of a great beast in the forest to the north.  My son is missing and I fear he may have wandered too near its lair....\n\nHead northwest to Krasari Falls and look for a mysterious whirlpool - this is the key to revealing what is hidden there.  Kill the wretched beast and recover any clues to my son's whereabouts.", objectives = "Find an Ancient Fishing Pool at Krasari Falls to the northwest and fish in it to lure the beast out of hiding.", progress = "What news of my son?", completion = "My son's ring?  What does this mean?\n\n<Rassan appears thoughtful.>\n\nThe situation is grim, but not without hope.  My son is careless with his belongings, so perhaps he simply threw it into the pool?  Thank you for your help <name>, I will not soon forget this great favor you have done for me." }
WordHunterWoW_QuestEN[30586] = { title = "Jagged Abalone", description = "Pandaren have been harvesting jagged abalone in this area for generations.  Now it's time for you to learn the ritual.\n\nThe abalone can be found just northeast of here in narsong trench.  Be careful, we have noticed increased shark activity in that area recently.", objectives = "Harvest 9 Jagged Abalone Meat from the Jagged Abalone in Narsong Trench to the northeast.", progress = "Did you see any sharks down there?", completion = "Oh!  Looks like you found plenty of abalone out there.  Great job <name>!" }
WordHunterWoW_QuestEN[30587] = { title = "Yakity Yak", description = "For now, the yaungol invaders seem content to steal yaks. Surveying the area, however, you notice they could easily move on the Yak Wash at any moment.\n\nThinning their numbers may help show the yaungol that this area is protected.", objectives = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch.", progress = "Them yak stealing, ranch smashing, bad breath yaungols gotta learn a thing or two about attacking decent folk.", completion = "Well then, I am mighty grateful for you culling some of those yaungols for us.\n\nHopefully your little display of authority will be enough to discourage them from coming over here." }
WordHunterWoW_QuestEN[30588] = { title = "Fishing for a Bruising", description = "The riverblade saurok clan is attacking one of our local fishing expeditions!  They need help right away!\n\nThin those saurok out and help that expedition return safely!", objectives = "Kill 8 Riverblade Beach Raiders at Anglers Expedition, just west of Anglers Wharf.", completion = "The expedition is safe.  Thank you <name>." }
WordHunterWoW_QuestEN[30589] = { title = "Wrecking the Wreck", description = "To dislodge the alliance ship, we need to find our engineer. He parted ways with us when we were escaping the wreckage.\n\nYou should be able to find him somewhere in the western forest. Tell him Korga sent you and he'll get in line to help.", objectives = "Speak to Makael Bay in the Pei-Wu Forest.", completion = "Korga sent you, eh? Well, I wouldn't mind doing a number on that ship for my own reasons anyway, but it's going to take some work.\n\nGive me a moment to think..." }
WordHunterWoW_QuestEN[30590] = { title = "Handle With Care", description = "We can help you get your ship free, but we'll need more of the explosives we were trying to take back from the Alliance to make it happen.\n\nI ordered the men to grab all the explosives they could before making our escape. If you sift through the wreckage and bodies to our south, there should be some explosive bundles among them, those that didn't already blow up anyway.\n\nGet me enough of them and I think I can put something together for ya.", objectives = "Recover 6 Packed Explosive Charges.", progress = "You're in one piece. That's a good sign.\n\nDid you get your hands on what I asked for?", completion = "More than enough. I've got the main control panel constructed. We should be ready very soon!" }
WordHunterWoW_QuestEN[30591] = { title = "Preying on the Predators", description = "The forest has become far more dangerous ever since Shen-zin Su began shaking. The tigers are agitated and have begun attacking the refugees, and on occasion, me as well.\n\nIf these injured and weak survivors are to make it to safety here at the hut, we need to help clear the forest for them.", objectives = "Kill 9 Pei-Wu Tigers.", progress = "Grim work. I've lived in peace with these tigers for as long as I can remember.", completion = "These survivors are in your debt, <class>." }
WordHunterWoW_QuestEN[30592] = { title = "The Burlap Trail: To Burlap Waystation", description = "Bad fortune for grummles today. Hozen have begun to ravage! They attack our supply line to the Serpent's Spine.\n\nCan you help? We are not fighters. We are grummles. Good fortune to those who help grummles.\n\nGo with a group of grummles to the Burlap Waystation. Keep them safe. Make sure at least one grummle survives.\n\nGrummles shall reward. Grummles always reward.", objectives = "Protect a group of grummles travelling to the Burlap Waystation. At least one grummle must survive.\n\nIf you lose your grummles, you can search the Burlap Trail or return to One Keg and wait for the next group to leave.", progress = "Good fortune to friends of grummles.", completion = "Many thanks and fortune to you, friend of grummles. But the journey to the Serpent's Spine is not safe yet." }
WordHunterWoW_QuestEN[30593] = { title = "Deanimate the Reanimated", description = "The admiral's asked me to take care of a major problem, but my specialty's in healing, not fighting!\n\nThe pandaren in the camp here have told me that something is animating the statues to the northeast at Mogujia.\n\nWill you help me out, {name}? We can't afford to have a fight with an army of statues right now.", objectives = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", completion = "Alright! Looks like we won't have a bunch of statues to worry about any more. Good work, <name>!" }
WordHunterWoW_QuestEN[30594] = { title = "Deanimate the Reanimated", description = "I've got much to do here, {name}. I could use your help.\n\nThere's a place to the northwest. The pandaren here call it Mogujia. Something's causing the statues there to animate, and our pandaren friends here are pretty spooked about it.\n\nIf they're not dealt with soon, we might have a serious problem. We just moved in. It's not like we can afford to fight a war with an army of statues right now.", objectives = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", progress = "Weren't you going to destroy all of those mogu statues so that we don't, you know, get overrun by them?", completion = "Oh, you dealt with the statues? Good work. Here's something for your trouble." }
WordHunterWoW_QuestEN[30595] = { title = "Profiting off of the Past", description = "Let me guess, you're here to deal with the mogu statues that are being reanimated. What a coincidence, I'm here to, um... conduct research on the mogu.\n\nI tell you what, if you bring me as many of the mogu relics in there that you can carry, I'll give you a cut. Of the research... funding.", objectives = "Collect 12 Mogu Relics.", progress = "Where am I going to be able to put all of the relics?", completion = "Wow! I mean, wow! Thank you, <name>!\n\n\n\nNow that you've softened them up, I'm thinking that I might head in. Just a few more relics from around the outskirts. Nothing dangerous." }
WordHunterWoW_QuestEN[30596] = { title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", objectives = "Kill the Zandalari Soulraiser." }
WordHunterWoW_QuestEN[30597] = { title = "Strange Spherical Stone", description = "This beautiful stone clearly has magical potential... at least to one trained in alchemy.  You are certain that with the right herbs native to Pandaria, this stone could become very useful.You will receive:", objectives = "Infuse the stone with several Golden Lotus." }
WordHunterWoW_QuestEN[30598] = { title = "Who Knew Fish Liked Eggs?", description = "Great cranes have been nesting in this area for generations.  The Narsong Spires provide a sheltered area to rear their young.\n\nTheir pristine eggs are revered as bait for catching the silver goby.  Retrieve a crane egg and see if you can catch a goby!", objectives = "Collect a Pristine Egg from the Narsong Spires and use it to catch a Silver Goby.", progress = "Did you catch a silver goby?", completion = "The elusive silver goby!  You truly are becoming an angler <name>!" }
WordHunterWoW_QuestEN[30599] = { title = "A Monkey Idol", description = "Before, grummles keep hozen from ravaging by bribing with food.\n\nBut now the Broketooth hozen south of here have their big magic idols. The Ook of Dook has trained them to use their idols to get power from sacrifices.\n\nThey are using them to kill grummles!\n\nYou must destroy these idols!\n\nFor every idol, there is a chief. Kill the chief and throw corpse on their altar.", objectives = "Use the Corpses of Tak Tak, Dak Dak, and Ko Ko on their respective altars.", progress = "Hozen are learning that it is most bad fortune to get sacrificed on one's own altar.", completion = "A confident hozen is a dangerous hozen.\n\nThank you for your help, friend of grummles." }
WordHunterWoW_QuestEN[30600] = { title = "No Pack Left Behind", description = "The Broketooth hozen south of here killed all of my grummles. What is worse, their packages are undelivered.\n\nFortune frowns on a grummlepack undelivered.\n\nPlease, give my grummles peace on the great trail of beyond and bring their grummlepacks to me.\n\nI will see they are delivered.", objectives = "Recover 8 Grummlepacks from Camp Broketooth or The Deeper.", progress = "Grummles are a simple people. We are made to explore and deliver.", completion = "You are good fortune for grummles.\n\nWhen we are back at a proper camp I must buy you the smelliest, luckiest incense I can find." }
WordHunterWoW_QuestEN[30601] = { title = "Instant Courage", description = "It is very bad fortune to travel mountain paths without a good guide. We grummles make the best guides, but many have run away. They fear the mountain pass now. Many good grummles disappear up there.\n\nGrummles are good at many things, but are not very brave. Maybe with fire lotus incense you can make them brave. Then they will show you the way. \n", objectives = "Inspire 3 Hiding Guides in Howlingwind Cavern to help you.", progress = "Did you find the hiding guides?", completion = "Incense works like a charm! Effects will not last long, so you must hurry!" }
WordHunterWoW_QuestEN[30602] = { title = "The Rabbitsfoot", description = "The Broketooth hozen stole our Rabbitsfoot! He was the grummle with the biggest luckydo.\n\nThis is very bad fortune indeed. Please, {race}, we need our Rabbitsfoot back. We need his good fortune back.\n\nCan you search the Broketooth Outpost for him?", objectives = "Rescue Brother Rabbitsfoot from the Broketooth Outpost.", completion = "Look what Broketooths and Knucklethumps did to grummle waystation. Hardly a luckydo to be found.\n\nGrummles had a deal with the hozen. We give them food, and they don't ravage. Whenever they think to ravage, Shado-Pan remind them not to ravage.\n\nBut all of Shado-Pan are away defending the wall now. And the hozen want more food than the grummles have." }
WordHunterWoW_QuestEN[30603] = { title = "The Broketooth Ravage", description = "They took my luckydo! Their leader hozen here, Mo Mo, stole my rabbitsfoot.\n\nThis is most bad fortune for grummles. My rabbitsfoot is a big luckydo for grummles everywhere. If hozen learn how to get luck from my rabbitsfoot then all is lost.\n\nPlease can you get it back?", objectives = "Retrieve Rabbitsfoot's Luckydo from Mo Mo.", progress = "Grummles named for the luckydo that gives the most fortune to specific grummle. It is most important that hozen not steal a grummle's luck.", completion = "My luckydo! Oh happy day of good fortune! Many thanks!" }
WordHunterWoW_QuestEN[30604] = { title = "Breaking Broketooth", description = "Hozen only ravage when they think their supplies are too few for their number of mouths.\n\nProblem is, hozen always have more mouths than food.\n\nWe have very few grummles these days.\n\nIt is a hard thing to ask, but can you be a friend to grummles, and destroy some of the Broketooth hozen south of here? It is the only way to prevent them from destroying the landscape.", objectives = "Kill 8 Broketooth Chargers and 6 Broketooth Tossers.", completion = "Thank you, <name>! Hopefully that will slow the Broketooth ravage." }
WordHunterWoW_QuestEN[30605] = { title = "Lucky Yakshoe", description = "While you were gone, I saw a group of grummles coming down the Burlap Trail. It was led by my Brother Yakshoe.\n\nBut then the Knucklethumps attacked. They took my brother and his grummles north.\n\nPlease, {name}! Save my brother. He always has bad fortune and no luck, but he is my brother. Look for him at the alter in front of Fort Silverback.", objectives = "Rescue Brother Yakshoe.", completion = "Good fortune for me to be saved by a luckydo like you.\n\nAnd Brother Rabbitsfoot always say I not have good fortune. Bah!" }
WordHunterWoW_QuestEN[30606] = { title = "Thumping Knucklethump", description = "The Knucklethump hozen have new chief, the Ook of Dook.\n\nHe sees fear in the west, anger in the south, hatred in the north, and yaungols in the east.\n\nAnd so he sets his hozen to ravage, gathering food and supplies for coming famine.\n\nThey are many Knucklethumps and dangerous.\n\nPlease, Luckydo, can you defeat their fighters?", objectives = "Slay 8 Knucklethump Smashers or Jibstabbers at Knucklethump Hole.", progress = "It is sad so many hozen must die.", completion = "You are a true luckydo." }
WordHunterWoW_QuestEN[30607] = { title = "Hozen Love Their Keys", description = "The hozen have a yeti! They call it Old Poot Poot and keep it at the back of their cave.\n\nHozen are normally scared of yeti, but now they feed it grummles.\n\nThey have a Hunter Chief, Cho Cho the Wicked. Can you see if he has a key on him to the yeti shackles?\n\nBad fortune for hozen if a yeti is loose in their fort.", objectives = "Get the Yeti Shackle Key from Cho Cho the Wicked and release Old Poot Poot.", progress = "A luckydo would be wise to never travel near a yeti on a dirty yak.", completion = "Oh wow that looked like one wild ride!" }
WordHunterWoW_QuestEN[30608] = { title = "The Snackrifice", description = "They took my grummles! Hozen don't eat grummles, but yeti do. And the Knucklethumps have a yeti.\n\nPlease rescue my grummles. Cut them down or let them out of cages. Rescue them any way you can.\n\nMany fortunes and rewards if you do this.", objectives = "Rescue 5 Imprisoned Grummles by cutting them down or releasing them from cages.", completion = "Today is a day of many good and bad fortunes. Bad fortune that hozen stole my grummles. Good fortune that my <race> saves my grummles. Bad fortune that so many hozen must die to learn lesson. Good fortune that humans are luckydos and know how to fight.\n\nGrummles are not fighters. We carry, we explore, and we are content." }
WordHunterWoW_QuestEN[30609] = { title = "Exit Strategy", description = "", objectives = "" }
WordHunterWoW_QuestEN[30610] = { title = "Grummle! Grummle! Grummle!", description = "Now that grummles are rescued, we need to rescue our supplies.\n\nThe Ook of Dook is only chief because he has supplies.\n\nGo to the Dooker Dome area north west of here. Take some grummles with you. Keep them safe and get them near supply crates.\n\nGrummles know what to do from there.\n\nRabbitsfoot and I will meet you there.", objectives = "Lead 5 Packless Grummles to Supply Crates near the Dooker Dome.", progress = "Grummles are good at carrying things.", completion = "Now that hozen king is going to learn why it is bad fortune to cheat grummles." }
WordHunterWoW_QuestEN[30611] = { title = "Unleash The Yeti!", description = "Your yeti ride gave me an idea. The Ook of Dook has a pet yeti he named Chomp Chomp.\n\nHe uses this yeti to scare other hozen in to making him the leader hozen. We need to get rid of that yeti.\n\nGo to Dooker Dome northwest of here and defeat some of the Cagemasters so Chomp Chomp is not tied up as much.\n\nYakshoe and I will meet you there with lots of incense and a dirty yak.", objectives = "Kill 4 Cagemasters.", progress = "We found a yak. Did you take out some hozen?", completion = "Ready for the yeti?" }
WordHunterWoW_QuestEN[30612] = { title = "The Leader Hozen", description = "The time has come to face the Ook of Dook. We beat him, and the hozen won't have someone telling them to ravage.\n\nHere is the plan: Yakshoe will lead Tassle in to arena and scare away Chomp Chomp.\n\nThen, you sneak in and fight the Ook of Dook while his hozen are distracted by the yeti rampaging through their home.\n\nWe'll meet you back at Kota Basecamp with a big reward. Good fortune to you, friend of grummles.", objectives = "Enrage Chomp Chomp and then defeat the Ook of Dook.", completion = "The Ook of Dook is dead! Hurray!" }
WordHunterWoW_QuestEN[30613] = { title = "Armored Carp", description = "Armored Carp are a delicacy around these parts.\n\nUnfortunately we can't fish them up since they snap our hooks with their powerful jaws.  Take this fishing spear and see if you can catch a few for us.", objectives = "Use the Fishing Spear to catch 5 Armored Carp in the waters south of Anglers Wharf.", progress = "Any luck with that fishing spear?", completion = "Careful with that carp, <name>.  They have been known to bite fingers off!" }
WordHunterWoW_QuestEN[30614] = { title = "Oil Stop", description = "When the yaungols came, they began to dig up oil. What is this \"oil\", I wonder? Perhaps it is thing of much undiscovered luck. This I must know.\n\nHere, take this vial, and fill it with yaungol oil from one of their windmills. I will give you many fortunes if you bring me some.", objectives = "Fill the Empty Oil Vial at a Yaungol Oil Derrick.", progress = "Yaungols are scary. Yaungols with a luckydo like this \"oil\" are more scary.", completion = "Happy day! Your reward. May these coins bring you good fortune." }
WordHunterWoW_QuestEN[30615] = { title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", objectives = "Kill the Zandalari Soulraiser." }
WordHunterWoW_QuestEN[30616] = { title = "Traffic Issues", description = "Yaungols are attacking our Burlap Trail. This is most bad fortune for grummles.\n\nWe use that trail to carry supplies to the Serpent's Spine. Without supplies, the defenders of the wall are in danger.\n\nGrummles are packers and explorers, not fighters. Could you be a luckydo for us and stop the yaungol blockade?", objectives = "Defeat 8 Fire Camp Ruqin Yaungols.", completion = "It is good fortune that a <race> comes to help grummles. Good fortune to friend of grummles." }
WordHunterWoW_QuestEN[30617] = { title = "Roadside Assistance", description = "A luckydo remembers to bring incense on a journey in to the mountains. The smellier the luck the better.\n\nCan you journey up the road to One Keg and light the incense you find along the way?\n\nThis will give good fortune to grummles that must travel the road.\n\nBrother Lintpocket can give you many rewards. Speak to him when you arrive.", objectives = "Light 8 Lucky Burlap Incense sticks along the road to One Keg.", progress = "The pungent smell of lucky burning burlap in the morning is a big Luckydo.", completion = "Welcome to One Keg! Gateway to Burlap Trail and Mount Neverest." }
WordHunterWoW_QuestEN[30618] = { title = "Resupplying One Keg", description = "If you're looking for the best supplies in Kun-Lai you've come to the right place! Oh sure, it looks a bit empty. Don't let appearances deceive you..\n\nOh, who am I kidding?! Between the hozen attacks, and the sprites pillaging what few supplies we do get, my stock has dwindled to a dangerous level.\n\nIf you could help me recover some of my supplies I should have enough to contribute to your journey.", objectives = "Recover 8 Stolen Supplies from Howlingwind Cavern.", progress = "Did you manage to get some of my supplies back?", completion = "Oh thank you, <name>! If I just cut off the nibbled pieces and repair the minor damage, I may still be able to sell these.\n\nOnce your cart is ready to go I'll have the supplies I promised loaded up!" }
WordHunterWoW_QuestEN[30619] = { title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the mogu behind the trouble!", objectives = "Kill the Mogujia Soul-Caller.", progress = "Did you find him? Is he dead? No? Oh, man. Don't make me worried!", completion = "Oh, thank goodness! You've saved all of our skins, believe me.\n\nYou have no idea how much trouble those guys can stir up.\n\nErr, or, I guess you do, now. Kind of. Almost.\n\nImagine that, but a lot worse, and for a couple thousand years." }
WordHunterWoW_QuestEN[30620] = { title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are Mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say Mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the Mogu behind the trouble!", objectives = "Kill the Mogujia Soul-Caller.", completion = "Oh, thank goodness! You've saved all of our skins, believe me.\n\nYou have no idea how much trouble those guys can stir up.\n\nErr, or, I guess you do, now. Kind of. Almost.\n\nImagine that, but a lot worse, and for a couple thousand years." }
WordHunterWoW_QuestEN[30621] = { title = "They Stole My Luck!", description = "My journeys through Kun-Lai have taught me two things. First, never sneak up on a sleeping yak. Second, having luck on your side is both necessary and hard to come by.\n\nThe grummles believe in carrying a lucky trinket at all times. In my mind, if one trinket can sometimes bring luck, then many trinkets would guarantee it!\n\nAfter arriving in One Keg my lucky trinkets were stolen by those little menace sprites. I'd be truly grateful if you could retrieve them for me.", objectives = "Return Ji-Lu the Lucky's Lucky Virmen's Foot, Yak Shoe, Four Winds Clover, and Gold Coin.", progress = "Were you able to find my lucky trinkets? One can never have too much good luck.", completion = "Thank you! It appears my trinkets were lucky for you too, <class>. While you were gone I did not gamble and lose my cart.\n\nI would be happy to lend it to you for your journey. Besides, I have some goods to win back from this shady grummle!" }
WordHunterWoW_QuestEN[30622] = { title = "The Swarm Begins", description = "Without the wall to protect us, we barely stand a chance. If you hadn't gathered so many people to help us, we wouldn't have a prayer.\n\nCheck in with Captain Oakenshield - he should be up near the break in the wall. Kill as many mantid as you can on the way there.\n\nIf we win, we win. If we lose, we go down fighting. For Pandaria!", objectives = "Slay 15 Ik'thik Warriors or Ik'thik Infestors.", progress = "Look at the SIZE of that thing...", completion = "My wall... I spent my life atop that wall..." }
WordHunterWoW_QuestEN[30623] = { title = "The Mantidote", description = "<Mei motions towards the battlefield.>\n\nYou see those huge mantid commanders out there? They have a strange aura about them. It reminds me of the sadness we saw at Zhu's Watch.\n\nPerhaps... they're under the influence of the sha, too?\n\nI kept Ken-Ken's mask - the one he used to remove the sha from Yi-Mo. I believe that, if we use it on the mantid, we can convince them to turn back.", objectives = "Use Ken-Ken's Mask on 5 Ik'thik Wing Commanders, then defeat the Manifestations of Fear that come out." }
WordHunterWoW_QuestEN[30624] = { title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", objectives = "Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the night elf settlers." }
WordHunterWoW_QuestEN[30625] = { title = "Students No More", description = "Those five students - the ones who were looking for the Hidden Master - they went up to the front lines, alone. I'd send Shado-Pan to aid them, but I haven't got any left.\n\nThere's dangerous creatures up there near the wall. If you find those students, make sure that they haven't fallen to any of them.", objectives = "Find the martial arts students, then help them defeat an Ik'thik Bloodrager, Egg-Matron, Tendon-Slicer, and Fearmonger.", completion = "They can't keep fighting like this forever. Those kids are downright heroic, but I don't want them to die as heroes.\n\nIt's time to throw in the towel." }
WordHunterWoW_QuestEN[30626] = { title = "Retreat!", description = "I'm going to withdraw what few forces I have. We may have to fall back to the Stormstout Brewery, or even Halfhill. That call is Commander Loon Mai's to make.\n\nYou go ahead. Deliver word to the Commander. My Shado-Pan will be shortly behind.", objectives = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds.", completion = "I see.\n\nWell, we gave it our all. It's time to evacuate, save lives, and reassess our strategy, before these mantid take over the entire valley." }
WordHunterWoW_QuestEN[30627] = { title = "The Savior of Stoneplow", description = "That commander speaks hastily. He has the weapon he needs to win this battle. He has YOU.\n\n\"But it's too hard,\" you might say.\n\nYou would be wrong. It is not too hard. NOTHING IS TOO HARD.\n\nGo now, {name}. Go, and save Stoneplow!", objectives = "Speak with Miss Fanny at Stoneplow. Then, with her help, defeat the Mantid Colossus.", progress = "All is lost, <name>. Pack up your things. We're headed to Halfhill.", completion = "I can't believe it! You - a foreign-born <race> - have succeeded where the Shado-Pan have failed. You've succeeded where the WALL has failed.\n\nWe may hold this farming village after all." }
WordHunterWoW_QuestEN[30628] = { title = "The Gratitude of Stoneplow", description = "One last thing, {name}. Don't worry, it's not another favor. You've killed enough mantid today.\n\nWe recently received a shipment of high-quality armor from Kun-Lai Summit. I was planning to keep them for my men... but I can't think of anybody more deserving than you. You'll find them on the second floor of the inn, here in town.", objectives = "Find the Commander's Cache and collect your reward.", completion = "Peering inside, you find..." }
WordHunterWoW_QuestEN[30629] = { title = "FLAG - Player Began Finale", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.Upon completion of this quest you will gain:", objectives = "Listen to Xiao and his companions." }
WordHunterWoW_QuestEN[30630] = { title = "Into the Vale", description = "Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Matron Vi Vinh at the Shrine of Seven Stars.\n\nShe should be able to settle you in.", objectives = "Speak to Matron Vi Vinh at the Shrine of Seven Stars in the Vale of Eternal Blossoms.Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Matron Vi Vinh at the Shrine of Seven Stars.\n\nShe should be able to settle you in.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30631] = { title = "The Shrine of Seven Stars", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the southeast. Go and speak to the leaders. Make sure they are safe.", objectives = "Speak to Jaluu the Generous, Kuru the Light-Hearted, Lucky Lin, and Matron Vi Vinh in the Vale of Eternal Blossoms.", completion = "Good work, <name>. It sounds as though they are getting on quite well at the city.\n\nHowever, in order to ensure their safety, we must be even more vigilant than before." }
WordHunterWoW_QuestEN[30632] = { title = "The Ruins of Guo-Lai", description = "According to Zhi the Harmonious, the mogu are moving into the Vale from the Ruins of Guo-Lai to the west.\n\nI sent Anji and Kun to investigate the situation, but they have not yet returned.\n\nI need a capable {class} like you to go check on them.", objectives = "Speak to Anji Autumnlight at the Ruins of Guo-Lai in the Vale of Eternal Blossoms.", completion = "Leven sent you? I hope you're ready for a fight." }
WordHunterWoW_QuestEN[30633] = { title = "Out with the Scouts", description = "We'd been briefed on mogu sightings in the Vale, but the situation is worse than we had anticipated.\n\nScouts are swarming all over the ruins to the northwest, gathering intel and stealing treasures.\n\nYour objective is clear - dispatch of any scouts you see. An army cannot move if we take out its eyes.", objectives = "Kill 8 Shao-Tien Precursor.", completion = "Well done, <race>. That should send a clear message to the mogu - we are not to be trifled with." }
WordHunterWoW_QuestEN[30634] = { title = "Barring Entry", description = "Lao Softfoot and I scouted up the ruins to the north.\n\nIt looks like the mogu are infiltrating the valley through a cave just up the hill, and already they are sending formidable reinforcements through.\n\nThere are too many enemies to take them head on, so you'll have to meet Lao Softfoot at the entrance to the ruins.\n\nHe'll help you sneak in under the cover of stealth. Then, plant this keg of explosives at the mouth of the cave.\n\nThe rest should take care of itself.", objectives = "Speak to Lao Softfoot at the entrance to Ruins Rise and follow him up the trail. Then, plant the Explosive Keg at the Ruins Rise Cave Entrance.", completion = "Wonderful, <name>!\n\nYou and He have single-handedly crippled the mogu advance.\n\nThat is called working smarter, not harder." }
WordHunterWoW_QuestEN[30635] = { title = "Killing the Quilen", description = "We've taken care of the scout problem for now, but there are still advance mogu forces inside the Guo-Lai Halls down the hill.\n\nUnfortunately, their vicious guard dogs are protecting their operations deeper in the ruins.\n\nGo and dispatch of their beasts. Be on your guard - they can be quite good at blending into their surroundings.", objectives = "Kill 9 Stone Guardians.", completion = "Good. Those dogs know no mercy, so it's good that you showed them none." }
WordHunterWoW_QuestEN[30636] = { title = "Stones of Power", description = "Many thousands of years ago, the rulers of the Vale sought energy from a powerful crystal known as Revelite.\n\nWith this substance, they were able to power cities, factories, and engines of war.\n\nZhi the Harmonious has asked us to collect some crystals and bring them back to the city.\n\nKeep an eye out for them while you are in the ruins.", objectives = "Collect 7 Revelite Crystals.", progress = "Did you find the crystals?", completion = "Mmmhmm. These will do nicely.\n\nI'll have them sent back to camp immediately." }
WordHunterWoW_QuestEN[30637] = { title = "The Guo-Lai Halls", description = "As you pass by the great door, you hear sounds from deep inside.\n\nAnji mentioned that advance mogu scouts had been sighted in this area. Perhaps they made their way down to the depths below.\n\nYour senses tingling, you decide to investigate.", objectives = "Investigate the mogu presence in the Guo-Lai Halls.", completion = "Your instincts were correct, <name>.\n\nIn ancient times, the Guo-Lai Halls were home to powerful treasures.\n\nWe must do everything we can to stop this mogu warlord from accessing those sealed crypts." }
WordHunterWoW_QuestEN[30638] = { title = "Leaving an Opening", description = "This is serious.\n\nKun and I will keep an eye on things here, but you should go to the Golden Pagoda.\n\nGo, swiftly!", objectives = "Speak to Leven Dawnblade at the Golden Pagoda in the Vale of Eternal Blossoms.", completion = "To arms, <name>! I thought we would have more time to set up our defenses, but the mogu are proving to be a deadly and intelligent enemy.\n\nWe've moved the refugees and our supplies into the city behind us.\n\nIt's up to us to protect the front. We must not let the mogu gain a single foothold here in the Vale." }
WordHunterWoW_QuestEN[30639] = { title = "The Secrets of Guo-Lai", description = "I just received information from a guard stationed near the Ruins of Guo-Lai that the Shado-Tien leader entered the halls, killing two of my men in the process. They're intent on something inside. We need to stop them.\n\nHe Softfoot has already followed them in. He should be waiting for you at the entrance to the western chambers.\n\nMove quickly, {name}. I don't like the thought that the mogu may be a step ahead of us.", objectives = "Meet with He Softfoot in the Guo-Lai Halls and uncover the mogu's purpose in the western chamber.", completion = "The Shao-Tien were spotted marching out of the halls with a hundred jade statues. The mogu now have an immense jade army to turn against us, and we've yet to uncover their other goals in the Vale. We are all in danger.\n\nI had thought you and He dead. It's good that I was mistaken on the last part at least. Rest. Recover. There will be much fighting ahead." }
WordHunterWoW_QuestEN[30640] = { title = "Battle Spear of the Thunder King", description = "I have received some troubling news, {name}.\n\nThe mogu are plotting to steal three artifacts of power from the Vale.\n\nWe must retrieve the artifacts immediately and hide them for safekeeping.\n\nThe first artifact is the Battle Spear of the Thunder King.\n\nUpon emperor Lei Shen's death, the spear was placed in an ancient shrine to the northwest.\n\nBring the spear back to me.", objectives = "Retrieve the Battle Spear of the Thunder King.", progress = "It was said that the most powerful of ancient mogu could call the powers of the elements.\n\nThe Thunder King himself could channel the forces of lightning onto his spear.", completion = "Well done, <name>, although it pains me to lay my eyes upon that wretched spear.\n\nThis foul weapon murdered thousands of innocents.\n\nAs long as I live, the mogu shall never have possession of it again." }
WordHunterWoW_QuestEN[30641] = { title = "Battle Helm of the Thunder King", description = "The second artifact of power is the Battle Helm of the Thunder King.\n\nEmperor Lei Shen wore the helm into every battle. It became so well-known that his enemies would flee at the mere sight of it.\n\nWhen the Emperor died, they placed the helm in the very bottom of the Guo-Lai Halls to the west, surrounded by thousands of terracotta soldiers.\n\nThus, they could look upon their leader and follow him into death.", objectives = "Retrieve the Battle Helm of the Thunder King.", progress = "History claims that Lei Shen feared no enemy except for one. And in the end, it was death that finally defeated him.", completion = "Thank you, <name>.\n\nWhile our soldiers fight the mogu on the battlefield, I work to strip away the power of their legends.\n\nIn time, Lei Shen shall be no more than the shadow of a memory." }
WordHunterWoW_QuestEN[30642] = { title = "Battle Axe of the Thunder King", description = "The final artifact is the Thunder King's axe.\n\nLei Shen charged into battle with his spear in one hand, and his axe in the other.\n\nIt is said that he could throw his axe with brutal accuracy, and when it hit its target, it made a sound like crashing thunder.\n\nAfter his death, the axe was placed in a ceremonial chamber to the southwest.\n\nNeedless to say, we must not let it fall into the mogu's hands.", objectives = "Retrieve the Battle Axe of the Thunder King.", progress = "Did you find the axe?", completion = "Such modesty, <name>. I witnessed what you did to retrieve the axe. Well done." }
WordHunterWoW_QuestEN[30643] = { title = "The Mogu's Message", description = "The battle against the mogu rages fiercely with neither side giving quarter.\n\nWe cannot hold our position forever. Something must be done to strike a blow at the mogu, a blow from which they cannot recover.\n\nGo check in with Zhi the Harmonious at The Silent Sanctuary. I wish to hear his thoughts on this matter.", objectives = "Speak to Zhi the Harmonious at The Silent Sanctuary in the Vale of Eternal Blossoms.", completion = "Zhi the Harmonious and the defenders were slaughtered mercilessly.\n\nYour senses tingle. You realize that the Thunder King's treasures are gone!" }
WordHunterWoW_QuestEN[30644] = { title = "What Comes to Pass", description = "You had better report back to the Golden Pagoda immediately.", objectives = "Speak to Sun Tenderheart at the Golden Pagoda in the Vale of Eternal Blossoms.", completion = "What? Zhi the Harmonious... is dead? Oh...\n\nYou did very well, given the circumstances. I'm sure a lesser <class> would have succumbed to those assassins.\n\nThings are happening... so quickly. We must all keep ourselves together." }
WordHunterWoW_QuestEN[30645] = { title = "The Might of Three", description = "This is it, {name}. This is the end.\n\nIf we don't drive the mogu from the valley, they will seize the remnants of their ancient power and use it to break Pandaria to their will.\n\nBut our forces are few, and tired, and small. We bleed, while their warriors are made of stone.\n\n{name}, although all odds are against us, still I must ask you to go and help our forces slay the mogu invaders.\n\nI have prayed to the Celestials, begging their aid. I can only hope that they answer our call.", objectives = "Slay 100 mogu invaders at the Summer Fields in the Vale of Eternal Blossoms.", completion = "What? You have slain how many mogu?\n\nRemarkable! If we survive this, you must tell me everything that happened." }
WordHunterWoW_QuestEN[30646] = { title = "The Final Power", description = "I never thought it would come to this!\n\nLeven went to face Warlord Zhao-Jin the Bloodletter at the top of the palace steps, but our reinforcements cannot get through!\n\nWe are the only ones who stand between him and the Vale's greatest... and most deadly... powers.\n\nPlease, {name}, you must find a way to stop him!", objectives = "Kill Warlord Zhao-Jin the Bloodletter.", completion = "What you have accomplished today will live on in stories for ages to come.\n\nWith your help, we have saved the Vale from a terrible enemy.\n\nToday, we dealt a painful blow to the mogu. They will never stop their attempts to seize the Vale, but it will be a long time before they try a full scale attack again." }
WordHunterWoW_QuestEN[30647] = { title = "Tracking Quest: Opened the Golden Valley", description = "", objectives = "" }
WordHunterWoW_QuestEN[30648] = { title = "Moving On", description = "Your journey in this land has already proven most eventful, traveler. And mine, it appears, is destined to continue for a time.\n\nA chain of events began when your people arrived here, and while some of those happenings are traumatic to behold, I feel there must be a larger purpose behind your presence.\n\nFor now it is wisest that you leave this place and explore Pandaria's other regions.\n\nSpeak to me when you are ready to leave.", objectives = "Speak to Fei and travel to Valley of the Four Winds.", completion = "Be wise, traveler.\n\nProve to these inhabitants that there is more to your people than war and destruction." }
WordHunterWoW_QuestEN[30649] = { title = "The Shrine of Two Moons", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the northeast. Go and speak to the leaders. Make sure they are safe.", objectives = "Speak to Jaluu the Generous, Mokimo the Strong, Elder Liao, and Madam Vee Luo in the Vale of Eternal Blossoms.", completion = "Good work, <name>. The city should be safe for now." }
WordHunterWoW_QuestEN[30650] = { title = "Pandaren Prisoners", description = "Look, I know the Alliance needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the northwest, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Alliance.\n\nWhat do you say, {name}?", objectives = "Free 8 Pandaren Prisoners.", completion = "Well, if it isn't our hero, <name>.\n\nI really wasn't sure we stood a fighting chance out here, you know?\n\nThese guys may be a little rough around the edges, but we'll be able to whip 'em into shape. And when we do, we'll have a real fighting chance at holding our own here in Kun-Lai.\n\nGood work." }
WordHunterWoW_QuestEN[30651] = { title = "Barrels of Fun", description = "Oh, well now, let's have us some fun, boyo!\n\nThose Ordo yaungol to the northwest have saved us the trouble o' havin' to make some bombs. They already have them there.\n\nLet's put their explosive barrels to good use and destroy their oil-pumpin' machines, shall we?", objectives = "Use Explosive Barrels found in Fire Camp Ordo to destroy the West, South, and East Oil Rigs.", completion = "Ho ho, that were a fine sight to see. I knew I should have gone up there with ya, <name>!" }
WordHunterWoW_QuestEN[30652] = { title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are a dire threat. I need you to head northwest and take out their leader.\n\nUnfortunately, his four subordinates are maintaining a fire barrier that prevents us from getting to him in the adjoining cave.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", objectives = "Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster." }
WordHunterWoW_QuestEN[30653] = { title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", objectives = "Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the tauren settlers." }
WordHunterWoW_QuestEN[30654] = { title = "The Guo-Lai Halls", description = "The mogu are up to something, I can feel it.\n\nThey've been sending scouts down into the Guo-Lai Halls.\n\nAccording to the caretakers, the Halls are home to ancient treasures of emperors past. Not only riches, but artifacts of great power.\n\nWe must prevent the mogu from accessing these treasures! Go down the ramp to the northwest and stop them!", objectives = "Investigate the mogu presence in the Guo-Lai Halls.", completion = "It looks like you may have averted a great disaster, <name>.\n\nIf this mogu warlord seeks the treasures of the Guo-Lai Halls, we must do all that we can to stop him." }
WordHunterWoW_QuestEN[30655] = { title = "Pandaren Prisoners", description = "Look, I know the Horde needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the west, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Horde.\n\nWhat do you say, {name}?", objectives = "Free 8 Pandaren Prisoners.", completion = "Well, it looks like we've got ourselves a little army, here, thanks to you.\n\nThey may not look like much yet, but a little Horde discipline and we'll have them in fighting shape in no time.\n\nBy the way, <name>... good work." }
WordHunterWoW_QuestEN[30656] = { title = "Barrels of Fun", description = "I love blowing stuff up. It's in my blood!\n\nThe yaungol to the west at Fire Camp Ordo have a ton of explosive barrels just lying around.\n\nI say we put them to good use and destroy their oil-pumpin' machines while having some fun!", objectives = "Use Explosive Barrels found in Fire Camp Ordo to destroy the East, South, and West Oil Rigs.", progress = "Um, I don't think the job's done yet.", completion = "You can't tell me that wasn't fun, <name>! I knew I should have gone over there with you!" }
WordHunterWoW_QuestEN[30657] = { title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are the worst threat we're facing. I need you to head west and take out their leader.\n\nThe coward is hiding in a cave, which is protected by a fire shield cast by his four underlings.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", objectives = "Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster." }
WordHunterWoW_QuestEN[30658] = { title = "Huff & Puff", description = "Have you heard of the prickly puffer fish {name}?  Of course you haven't, you're new around these parts!\n\nThey can be found in the sarjun depths, due west of here.  Take this fishing spear and see if you can bring me back of few of their poison tipped spines.", objectives = "Use the Fishing Spear to kill 5 Prickly Puffer fish in Sarjun Depths and return with their spines.", progress = "Careful with that spear, <name>.", completion = "Ahh, I see you recovered some spines <name>.  These will certainly work well on my spear tips!" }
WordHunterWoW_QuestEN[30660] = { title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo yaungol!>", objectives = "Kill Ordo Warbringer.", completion = "You've done it, <name>! I'm in your debt!\n\nAgain!" }
WordHunterWoW_QuestEN[30661] = { title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo!>", objectives = "Kill the Ordo Warbringer.", completion = "Once again you've accomplished what no one else could.\n\nWas there any doubt?" }
WordHunterWoW_QuestEN[30662] = { title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Go back there before the shield goes up again.\n\nTime to head into the cave and slay their chief!", objectives = "Kill the Ordo Warbringer.", progress = "<name>, what are you doing here? The Ordo Warbringer isn't dead yet!", completion = "You've done it, <name>! I'm in your debt!\n\nAgain!" }
WordHunterWoW_QuestEN[30663] = { title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Get back over there before they get that shield up again.\n\nSlay the Warbringer of the Ordo!", objectives = "Kill the Ordo Warbringer.", completion = "Once again you've accomplished what no one else could.\n\nWas there any doubt?" }
WordHunterWoW_QuestEN[30665] = { title = "The Defense of Shado-Pan Fallback", description = "I sent for reinforcements from the Shado-Pan Monastery, but have heard nothing back. We have already lost the town.\n\nA few lucky villagers may have survived, but we are pinned down here.\n\nWe do not have time to entertain strangers. If you can fight, help my men defend this tower. If not, leave, for you will not survive long here.", objectives = "Kill 15 Sha-Infested Yaungol.", progress = "Have you dealt with the yaungol yet?", completion = "You have bought us some time to breathe. We must not despair - instead, we must act." }
WordHunterWoW_QuestEN[30666] = { title = "Sudden, Unexpected Crocolisk Aggression", description = "Normally, my day consists of catching fish, and then eating the fish I caught, followed by sleeping. Note that I did not include \"fight with a crocolisk\" in that list of activities.\n\nYou look like a handy {class}. Can you go get rid of some of these crocolisks, so I can get back to my regular routine? The crocolisks normally keep to themselves up at Kea Krak, to the northwest.", objectives = "Slay 8 Mortbreath crocolisks at Kea Krak.", progress = "What would make the crocs attack like this?", completion = "Yesterday, we were fishing happily. Today, the crocs just started... tryin' to eat us.\n\nStrange." }
WordHunterWoW_QuestEN[30667] = { title = "Particular Plumage", description = "When the crocs started attacking, they scared a bunch of the lories out of their nests, up in that island to our northwest.\n\nI can use those lories' feathers to make some specialized lures, which will come in handy if and when I get to stop defending my brethren from these reptiles.\n\nYou up for some feather hunting?", objectives = "Obtain 6 Emerald Tailfeathers, 6 Crimson Tailfeathers, and 6 Dusky Tailfeathers.", progress = "<A bead of sweat twinkles in the fur above Tony's brow.>", completion = "Thanks, <name>. You've made my day. I always hate to see such a prime feather-gathering opportunity go to waste." }
WordHunterWoW_QuestEN[30668] = { title = "Build Your Own Raft", description = "<Jay looks off in the direction of Kea Krak.>\n\nHmm. They don't seem to be... calming down. We're going to have to try something different.\n\nYou'll need a raft. Go grab some wood planks and seaweed, and bring them over to me. I'll put something together for you.", objectives = "Obtain 4 Spare Planks and some Tough Kelp.", progress = "You got the stuff? I'll build your raft, I just need materials.", completion = "<Jay deftly weaves the planks together into a surprisingly seaworthy-looking vessel, then tosses them down into water below.>" }
WordHunterWoW_QuestEN[30669] = { title = "The Lorewalker on the Lake", description = "Your raft is down in the water below. Take it out to the middle of the lake, where you should find a woman. Her name is Ana  Wu.\n\nWhenever I have a question that I can't figure out on my own, I'll ask her. She should be able to tell us why these crocolisks won't stop attacking.", objectives = "Board your raft, then report to Wise Ana Wu in the middle of Nayeli Lagoon.", completion = "You appear troubled, child.\n\nHow can this Lorewalker serve you? What is it that you seek?" }
WordHunterWoW_QuestEN[30670] = { title = "Turnabout", description = "Our true enemies are the sha, not the yaungol.\n\nThe sha are emotion manifest. Destructive, yes. But undisciplined. Undisciplined force cannot last. The flood, in dispersion, loses its force. The wildfire burns its fuel.\n\nAnd, discipline and wisdom can turn their destructive energy against themselves.\n\nBring me the essences of the sha in the village, and I will explain further.", objectives = "Collect 5 Blind Rage Essences from Blind Rages in Firebough Nook.", progress = "Have you harvested their essences?", completion = "Good. Now you will see how to defeat unbridled rage.\n\nI will craft these into a trap for Kobai, the leader of the yaungol. Though he will be snared, and we will defeat him, he is not our ultimate target..." }
WordHunterWoW_QuestEN[30671] = { title = "Wisdom Has A Price", description = "<Ana listens to your story, and nods.>\n\nCrocolisks attacking? I know a story about that. And I will share it with you, but first... I grow hungry.\n\nShark meat should do the trick. You should find enough sharks in the water beneath us.", objectives = "Obtain 5 Shark Fillets.", progress = "My hunger is great, <race>. I have been on this lagoon for several days, without food.", completion = "You've brought me more meat than I could ever hope to eat.\n\nNow, I suppose I owe you a story..." }
WordHunterWoW_QuestEN[30672] = { title = "Balance", description = "The story did not end happily. The Narsong crocolisk is no more.\n\nThis time, however, you may have a chance to change the ending.\n\nThe hozen to the south are overfishing these waters. With the fish gone, the crocolisks are hungry and desperate - and so they attack Marista.\n\nGo now, {race}! Stop those hozen from their reckless fishing!", objectives = "Slay 10 Unga Fish-Getters.", completion = "<Jay listens to your account of the day's events.>\n\nI see. We'll keep an eye on the Ungas from here. And we'll do our best not to fish these waters too heavily, either. No doubt we're part of the problem, too.\n\nUntil next time, <name>." }
WordHunterWoW_QuestEN[30673] = { title = "Holed Up", description = "Thank the heavenly spirits for you, {class}! I don't know how much longer I could've lasted.\n\nThere are other Firebough Nook survivors, I'm sure of it. Will you help rescue them and get us to the safety of Shado-Pan Fallback?", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong." }
WordHunterWoW_QuestEN[30674] = { title = "Balance Without Violence", description = "Some of the fish that the Unga hozen have gathered don't seem do be dead yet. There may still be time to throw them back into the water.", objectives = "Throw 6 Flailing Carp into Nayeli Lagoon." }
WordHunterWoW_QuestEN[30675] = { title = "Buried Hozen Treasure", description = "The map you hold is crinkled, dirty, and poorly drawn, but you can see a big X on a beach.\n\nIs there buried treasure somewhere on this island?", objectives = "Find the Buried Hozen Treasure." }
WordHunterWoW_QuestEN[30677] = { title = "Shuttle Service", description = "", objectives = "" }
WordHunterWoW_QuestEN[30678] = { title = "Like Bombing Fish In A Barrel", description = "Turns out these rays are not as easy to catch as I thought! You seem like a pretty smart guy, think you can help me out?\n\nI made the bombs but have been having trouble using the raft with my hurt leg. The rays are common in the shallows just west of here. Take the bombs and use my raft to bring me back their stingers!\n\nOh yeah, watch out for the hammerheads!", objectives = "Use the Goblin Fishing Bombs to kill 3 Sting Rays and bring back their stingers to Fiznix. The Rays can be found in the shallows west of Anglers Wharf.", progress = "Find any sting rays in the shallows?", completion = "Looks like you're pretty handy with those bombs!" }
WordHunterWoW_QuestEN[30680] = { title = "Holed Up", description = "Oh thank you, thank you, thank you. If you hadn't come along...\n\nWait! There must be other survivors in the Nook like me!\n\nPlease, {class}, I beg you. Rescue the rest of my citizens and deliver us safely to Shado-Pan Fallback.", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong." }
WordHunterWoW_QuestEN[30681] = { title = "Holed Up", description = "Oh, thank you! There's no way I could have made it back on my own.\n\nCome to think of it, there must be others around Firebough Nook that need to be rescued. Shall we go collect them and then head to the safety of Shado-Pan Fallback?", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong." }
WordHunterWoW_QuestEN[30682] = { title = "Holed Up", description = "I can't believe you made it here!\n\nI don't know how much longer I could have stayed hidden in here.\n\nI'm sure that there are others. {class}, we have to rescue them! Then we can go to Shado-Pan Fallback. The master there will know what to do!", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", completion = "We didn't know that there were any survivors out there.\n\nThank you for bringing them to safety, <name>." }
WordHunterWoW_QuestEN[30683] = { title = "One Traveler's Misfortune", description = "Did you have to throw our supplies at them?! Why not use your weapon? Maybe fancy spells or kicks? Why the supplies?!\n\nNow we don't have enough to last us, especially with Nephew Bentnail here. His appetite is like a yeti's!\n\nYou threw it, you get us more. There is wreckage down the path. Maybe you will find supplies there.", objectives = "Search the Abandoned Wreckage for supplies.", progress = "Nephew Bentnail has already eaten two days worth of food. I hope you found us more!", completion = "You were attacked by a mogu? That sounds terrible!\n\nI hate to ask, but did you manage to pick up any supplies while you were fighting for your life?\n\nNo?! This is very bad luck." }
WordHunterWoW_QuestEN[30684] = { title = "Seeker's Folly", description = "I'm sure your pandaren friend has some ideas about what the mogu are after.\n\nHe headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific:\n\n\"The {class} must endure the trek alone, with only his thoughts. He will honor each shrine before meeting me at the top.\"\n\nThe path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", objectives = "Brave the path of Seeker's Folly to find Lorewalker Cho, stopping to reflect at the three shrines along the way.", progress = "There are two shrines on the path below us, and one more just behind us.", completion = "Ah, you made it, and you honored the shrines.\n\nI knew you could handle it." }
WordHunterWoW_QuestEN[30690] = { title = "Unmasking the Yaungol", description = "Simply killing Kobai will accomplish nothing, as he is possessed by a particularly powerful and destructive Sha - Malevolent Fury.\n\nYou will use the trap I have fashioned from the Blinding Rage Essences you brought. Lure him into the trap, and then steal his mask. Once you put it on, Malevolent Fury will appear and attempt to take control of you.\n\nDefeat him, and we will have made a victory of this tragic situation. You can find him to the north of the retreat, where he taunts us in insane rage.", objectives = "Lure Kobai into the Blinding Rage Trap, steal the Mask of Malevolent Fury from him, and then defeat Malevolent Fury.", progress = "Is Malevolent Fury gone?", completion = "I should feel shame at the loss of the village. I should feel great pride in your success. \n\nI should feel many things, but must not allow myself to. Until our struggle with the sha is complete, we must maintain total control of our emotions." }
WordHunterWoW_QuestEN[30691] = { title = "Misery", description = "While you are in the water below, you should slay Nahassa, the mortbreath patriarch. He suffers. I can feel his death cries ululating up to the surface of the lagoon.\n\nFind his cave, and put him out of his misery. Not because it will solve Marista's crocolisk problem. Simply out of mercy.", objectives = "Put Nahassa out his misery.", progress = "Please, <name>. Even the great beasts of this world have a right to die in dignity.", completion = "Nahassa's fevered suffering has come to an end." }
WordHunterWoW_QuestEN[30692] = { title = "The Burlap Trail: To Kota Basecamp", description = "This here's hozen lands. Very dangerous. But grummles must trek through. Supplies must reach the Serpent's Spine.\n\nGo, protect the next wave of grummles on their trek to Kota Basecamp.\n\nIf at least one survives, good fortune will find its way to you.", objectives = "Protect a group of grummles from the Burlap Waystation to the Kota Basecamp. At least one grummle must survive.\n\nIf you lose your grummles, you can search the Burlap Trial or return to the Burlap Waystation and wait for the next group to leave.", progress = "Welcome to Kota Basecamp, friend of grummles.", completion = "Ha ha! Hero of grummles! Welcome to Kota Basecamp. Enjoy good fortune for most happy grummle delivery." }
WordHunterWoW_QuestEN[30694] = { title = "Tread Lightly", description = "My students tell me the surrounding area is littered with deadly traps, no doubt set by the saurok. Stumbling into one gets you a face full of spikes.\n\nAs the saying goes: \"The Way is rife with danger - tread lightly, and with scrutiny.\"\n\n<Koro hands you a long tree branch.>\n\nHere, this is scrutiny.\n\nIt should be long enough to set the traps off at a safe distance.", objectives = "Use \"Scrutiny\" to set off 10 Riverblade Spike Traps from a safe distance.", progress = "Well, I don't see any spikes in your face. That's a good sign.", completion = "Every trap you sprang is a life saved, be it pandaren, beast, or otherwise. Nobody deserves an honorless death like that." }
WordHunterWoW_QuestEN[30695] = { title = "Ahead on the Way", description = "Huge maws of despair are spewing out sha from the pagodas on either side of the temple. Meanwhile, your impromptu training in the Way continues.\n\n\"She who mends torn umbrella will be more dry than she who strikes at rain.\"\n\nWhile I take issue with that particular lesson--sometimes punching the rain can be quite effective--the meaning holds true in this case.\n\nTake out those maws of despair and give my order a chance at reclaiming the temple grounds.", objectives = "Kill the Maw of Despair in both the eastern and western pagodas at the Temple of the Red Crane.", progress = "Koro said there's a pagoda on either side of the temple. Let's find them and wipe out the sha presence in both.", completion = "Koro's metaphors can get a little tiring, but there's always true wisdom behind them." }
WordHunterWoW_QuestEN[30698] = { title = "Scavenger Hunt", description = "YOU!  You're just who I have been looking for!\n\nI need more parts for my goblin fishing bombs but I hurt my leg and can't collect them myself.\n\nYou see those shipwrecks nearby?  I bet they have just what I need if you can get to it and fish it out.  Take my fishing raft and see what you can find!  My buddy has been trying to help me out too so you might find some extra rafts near the wreckage, feel free to use em' too.", objectives = "Use the Goblin Fishing Raft to fish up 15 Rusty Shipwreck Parts out of the floating debris near the shipwrecks.", progress = "Did you find the shipwrecks?", completion = "Looks like you found plenty of parts, another set of fishing bombs coming right up!  Thanks <name>!" }
WordHunterWoW_QuestEN[30699] = { title = "To Winter's Blossom", description = "The battle against the Sha is eternal - we can not leave this place. \n\nBut I am troubled by the absence of reinforcements from the Monastery given that we sent for them days ago. \n\nYou have performed admirably, perhaps you could travel to Winter's Blossom, our base camp on the way to the Shado-Pan Monastery. Speak with Lin Silentstrike once you arrive - he should know what is happening. To get there, travel north of the village and follow the road through Shado-Li Basin to Winter's Blossom.", objectives = "Speak with Lin Silentstrike at Winter's Blossom in Kun-Lai Summit.", completion = "Shado-Master Chong sent you, hmm?\n\nYes, we received his request for reinforcements.\n\nWe are in no position to grant it, however. We've just concluded a battle of our own, and the monastery's been locked up tight. \n\nWe can't even get reinforcements here, and we're just down the hill!" }
WordHunterWoW_QuestEN[30700] = { title = "Snapclaw", description = "A giant, poisonous crab is wrecking havoc on our local abalone stores.  I need you to go down into narsong trench and take it out!", objectives = "Kill Snapclaw in a cave at the bottom of Narsong Trench and return with his claw as proof.", progress = "Did you take out that nasty crawler?", completion = "That is quite the claw, Snapclaw must be bigger than I thought!  No matter, job well done <name>!" }
WordHunterWoW_QuestEN[30701] = { title = "Viseclaw Soup", description = "Nothing tastes quite like viseclaw soup.  It's a krasarang specialty!\n\nI was just about to start up on a new batch when I realized I am missing a key ingredient, the eyes!\n\nI need you to kill the viseclaw fishers on the beach and return with their eyes for the soup!", objectives = "Kill Viseclaw Fishers on the beach and return with 16 eyes to make some yummy soup.", progress = "How many of their beady little eyes did you get?", completion = "Thanks <class>, this might be my best batch of soup yet!" }
WordHunterWoW_QuestEN[30704] = { title = "Hozen in the Mist", description = "", objectives = "" }
WordHunterWoW_QuestEN[30705] = { title = "Captain's Log", description = "", objectives = "" }
WordHunterWoW_QuestEN[30706] = { title = "Angry Scribblings", description = "", objectives = "" }
WordHunterWoW_QuestEN[30710] = { title = "Provoking the Trolls", description = "We've managed to push them back this far, but I doubt that we will remain safe for long if we do not deal with them once and for all.\n\nMy husband, coward or fool that he is, does not wish to provoke them. I will not be cowed so.\n\nWe will do just that. Slay their forward scouts. Perhaps we can provoke - and then defeat - their leader.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 10 Zandalari Stalkers and 5 Zandalari HexersWe've managed to push them back this far, but I doubt that we will remain safe for long if we do not deal with them once and for all.\n\nMy husband, coward or fool that he is, does not wish to provoke them. I will not be cowed so.\n\nWe will do just that. Slay their forward scouts. Perhaps we can provoke - and then defeat - their leader.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30714] = { title = "Destroy the Leaders", description = "And, now they fear you.\n\nTheir leaders, a Blademaster and a Mage, lie deeper in the ruins. Kill them.\nMake them hurt. For us.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill the Zandalari Blademaster and Zandalari MageAnd, now they fear you.\n\nTheir leaders, a Blademaster and a Mage, lie deeper in the ruins. Kill them.\nMake them hurt. For us.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30715] = { title = "A Line Unbroken", description = "When we regrouped after their initial attack, we numbered three less. You can fight, and we must plan our defense should these cursed yaungol attack again. \n\nIf you would help us, grant our fallen comrades their last rites, and recover their armor. You will find their bodies to the west, near the gate.\n\nAnd try to keep the birds off them.", objectives = "Lay Shado-Master Zhiyao, Liu of the Thousand Blows and Shiya Boldblade to rest.", progress = "Our comrades, are they at rest?", completion = "Good. I will see to it that the armor is returned to their pupils." }
WordHunterWoW_QuestEN[30716] = { title = "Chasing Hope", description = "Chi-Ji is always with us. Even when he is not here in the Cradle, pieces of his spirit run through the forests and beaches of the island, watching us and testing us.\n\nProve your dexterity in the eyes of Chi-Ji, {name}. Find and catch the spirits of the crane.", objectives = "Touch 3 Spirits of the Crane.", progress = "Return when you are finished, <name>. Now go!", completion = "Chi-Ji smiles on you." }
WordHunterWoW_QuestEN[30717] = { title = "Gifts of the Great Crane", description = "The cranes of Krasarang are a gift from Chi-Ji. Even the very feathers they leave behind are a gift for us to appreciate.\n\nWe use these feathers to adorn our garments and to fletch arrows. But first... they must be gathered.", objectives = "Obtain 10 Gifts of the Great Crane.", progress = "Even the smallest, flimsiest feather is proof enough that Chi-Ji loves us.", completion = "Thank you, <name>.\n\nReturn to us again soon." }
WordHunterWoW_QuestEN[30718] = { title = "Students of Chi-Ji", description = "Our order prides itself on excellence in combat. We hone these combat skills by dueling one another, here on the Cradle of Chi-Ji.\n\nProve yourself in the eyes of the Red Crane. Venture south, into the center of the island, and duel with your fellow students.", objectives = "Duel 10 Students of Chi-Ji.", progress = "Your trial is not yet complete, <name>.", completion = "With every battle - a win or a loss - you improve. You become faster, hardier, cleverer... better." }
WordHunterWoW_QuestEN[30719] = { title = "FLAG - Cradle of Chi-Ji Progress Bit 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[30720] = { title = "FLAG - Cradle of Chi-Ji Progress Bit 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[30721] = { title = "FLAG - Cradle of Chi-Ji Progress Bit 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[30722] = { title = "FLAG - Cradle of Chi-Ji Progress Bit 04", description = "", objectives = "" }
WordHunterWoW_QuestEN[30723] = { title = "Honor, Even in Death", description = "Hmm... If Shado-Master Chong trusted you, perhaps you can help us.\n\nThe yaungol are our enemies.\n\nStill, we must prove we are better than they. We will show them honor in death.\n\nAs after most battles, the carrion birds have begun gathering. Thin their numbers, so the bodies of our foes will not be desecrated. They've gathered at the battlefield to the west.", objectives = "Kill 12 Kun-Lai Scavengers.", progress = "Killing those birds may not soothe my anger, but at least it proves that we are better than our enemies. They would not do such a thing.", completion = "Good. After what they have done, I would not show the Yaungol kindness in life. But neither will I allow their bodies to be eaten by the birds." }
WordHunterWoW_QuestEN[30724] = { title = "To the Wall!", description = "They are attacking again!\n\n<Lin looks to the Ox Gate.>\n\nArchers... on the wall!\n\nI need you to get up there. My wife Suna went to scout the wall with that fool Lao-Chen. Perhaps if he had spent more time preparing defenses and less building that ridiculous ale lift contraption...\n\nIt matters not. Get a kite from Len, to the west, and then get up there and find my wife. She'll know what to do next.", objectives = "Speak to Kite Master Len at Winter's Blossom in Kun-Lai Summit to take a kite up to the Ox Gate. Once there, speak to Suna Silentstrike.", completion = "Wow, that was quite a bit of kite-flying there. Good job getting up here and not dying.\n\nIt's good you're here, too. Lao-chen's got an idea he's working on, but in the meantime we've got yaungol to deal with." }
WordHunterWoW_QuestEN[30725] = { title = "Ellia Ravenmane", description = "We regularly organize one-on-one duels with trainees that we think are well-suited for one another. We have found one such trainee for you, {name}.\n\nHer name is Ellia Ravenmane. This will be her first duel, too. She will be waiting for you at the pavilion just to the south of here.", objectives = "Defeat Ellia Ravenmane at the Angkhal Pavilion.", completion = "Very good!\n\nThe next time you return, you will face a new challenger. Continue winning, and your favor in the eyes of Chi-Ji will increase." }
WordHunterWoW_QuestEN[30726] = { title = "Minh Do-Tan", description = "Your next challenger is another relatively new trainee. His name is Minh Do-Tan, and he has won his last two matches.\n\nHe will be waiting for you near the crane statue to the south.", objectives = "Defeat Minh Do-Tan.", progress = "Fight hard, <name>.", completion = "Well done, <name>. You are beginning to make a name for yourself." }
WordHunterWoW_QuestEN[30727] = { title = "Ellia Ravenmane: Rematch", description = "Ellia Ravenmane requested a rematch with you. She seems to identify you as her \"rival\".\n\nWe discourage rivalries here within the Cradle of Chi-Ji, but we rarely decline a rematch request. You will find Ellia near the Pedestal of Hope, on the island's eastern side.", objectives = "Defeat Ellia Ravenmane near the base of the Pedestal of Hope.", completion = "Twice fought, twice defeated. It stands to reason that Ellia will not be requesting more rematches anytime soon." }
WordHunterWoW_QuestEN[30728] = { title = "Fat Long-Fat", description = "You have been matched with a... special trainee. His name is Fat Long-Fat.\n\n<Thelonius chooses his words carefully.>\n\nFat Long-Fat... operates outside of the normal rules of combat. He does not fight every day, and when he does, he chooses his competitor. Today, for some reason... he has selected you.\n\nYou will find him atop Angkhal Pavilion.", objectives = "Defeat Fat Long-Fat at the top of Angkhal Pavilion.", completion = "Of course you won. Fat Long-Fat does not fight to win. He fights for... other reasons.\n\nI fear I've spoken too much about this subject already. From now on... no more questions about Fat Long-Fat." }
WordHunterWoW_QuestEN[30729] = { title = "Julia Bates", description = "We welcome all kinds here within the Cradle, as long as they recognize and subscribe to the ideologies of the Red Crane. One of our new, more exotic trainees comes from the human kingdoms to the northeast. She goes by the rather foreign-sounding name of Julia Bates.\n\nShe is your next challenger. You will find her on the island's western shore.", objectives = "Defeat Julia Bates.", completion = "Another fight handily won. I anxiously await your next match, <name>." }
WordHunterWoW_QuestEN[30730] = { title = "Dextrous Izissha", description = "Jinyu normally avoid our order, but every few years, we find one that subscribes to the way of the Crane. One such jinyu is Dextrous Izissha.\n\nIzissha is your next challenger. He waits for you on the island's southwestern shore.", objectives = "Defeat Dextrous Izissha.", completion = "Excellent work, <name>! You continue to gain favor in the eyes of Chi-Ji.\n\nYour next battle will be one to remember. You will not be fighting a trainee. Instead, you will face one of your trainers." }
WordHunterWoW_QuestEN[30731] = { title = "Kuo-Na Quillpaw", description = "Most of the duels within the Cradle take place between two trainees. Rarely, when a trainee exhibits a rare amount of skill, they will have an opportunity to duel their trainer.\n\nToday, you duel against Kuo-Na. She will be waiting for you at the Pedestal of Hope.", objectives = "Defeat Kuo-Na Quillpaw.", completion = "You continue to impress, <name>.\n\nCome again soon. Your training is not over yet." }
WordHunterWoW_QuestEN[30732] = { title = "Ellia Ravenmane: Revenge", description = "Your \"rival\" has appeared again. Ellia Ravenmane has been avoiding her duties on the island, instead focusing on personal training, with the intent to defeat you in battle.\n\n\"I will destroy {name},\" she said.\n\nI have honored her request for a rematch, but I will be keeping a close eye on her. Her motives may be shifting in a dangerous direction.", objectives = "Defeat Ellia Ravenmane at Dome Balrissa.", completion = "I will consult directly with Chi-Ji about Ellia's behavior. She treads on thin ice." }
WordHunterWoW_QuestEN[30733] = { title = "Tukka-Tuk", description = "You are making a name for yourself, {name}. I received a challenge from one of our more skilled competitors. He believes you are not as strong as you seem.\n\nHis name is Tukka-Tuk, the hozen. If you've ever fought against hozen before, you know that their apparent juvenility belies their battle acumen. Good luck.", objectives = "Defeat Tukka-Tuk.", completion = "Well done, as usual.\n\nI trust I will see you again soon." }
WordHunterWoW_QuestEN[30734] = { title = "Huck Wheelbarrow", description = "Usually our trainees are adventurers like yourself, or monks from Tian Monastery, or occasionally retired Shado-Pan. Very rarely, though, we will greet trainees that have no fighting experience whatsoever.\n\nHuck Wheelbarrow is one such trainee. He has requested a duel with you. Look for him on the island's western shore.", objectives = "Defeat Huck Wheelbarrow.", completion = "There remains only one trainee ranked higher than you.\n\nI have a feeling that you will be facing him when you return." }
WordHunterWoW_QuestEN[30735] = { title = "Mindel Sunspeaker", description = "Our highest-ranked trainee is an outsider like you. It is both strange and exciting to live in a time when so many foreigners have embraced the way of the Crane.\n\nYour challenger's name is Mindel Sunspeaker, and he awaits you within Angkhal Pavilion.", objectives = "Defeat Mindel Sunspeaker.", completion = "You are now our highest-ranked trainee. You are no longer obligated to participate in trainee duels. Congratulations!\n\nOf course, there are still other ways to prove yourself. I have the feeling I will be seeing you again..." }
WordHunterWoW_QuestEN[30736] = { title = "Yan Quillpaw", description = "You have already defeated Kuo-Na Quillpaw. You have not yet fought her brother, Yan.\n\nHe will meet you at the Pedestal of Hope, and he will not hold back. His reputation as a trainer is at stake.", objectives = "Defeat Yan Quillpaw at the Pedestal of Hope.", completion = "And with that victory, I suppose we've run out of challengers for you to fight! Other than me, of course.\n\nBut... I don't fight. I mean, you wouldn't want to fight me. It would... not go well for you." }
WordHunterWoW_QuestEN[30737] = { title = "Fat Long-Fat: Rematch", description = "Fat Long-Fat has requested another match with you. I find this strange. And concerning.\n\nHe will be waiting atop the Dome Belrissa.", objectives = "Defeat Fat Long-Fat atop Dome Belrissa.", completion = "I believe I understand why he wanted to fight you a second time, though I need to speak with Chi-Ji before I can be sure.\n\nCome back soon, <name>. I think it is time you learned the true nature of Fat Long-Fat." }
WordHunterWoW_QuestEN[30738] = { title = "Thelonius", description = "When we last spoke, I promised to tell you the secret of Fat Long-Fat. I still plan to tell you that secret... after I determine your worth.\n\nI will meet you on the western shore, and we will duel.", objectives = "Defeat Thelonius.", completion = "You are truly worthy of the secret of Fat Long-Fat. Here it is:\n\nFat Long-Fat and Chi-Ji are one and the same. Fat Long-Fat is the Red Crane.\n\nHe believes that the Cradle is in great danger.\n\nHe believes there is one person that can save it.\n\nHe believes that you are that person, <name>.\n\nStay in touch." }
WordHunterWoW_QuestEN[30739] = { title = "Ellia Ravenmane: Redemption", description = "Ellia Ravenmane, your rival, has returned. She demands that you meet her atop the Pedestal of Hope.\n\nYou need to understand, {name}... something horrible has happened to her. She has changed. You will see for yourself when you arrive at the pedestal.\n\nGood luck, {name}.", objectives = "Defeat Ellia Ravenmane atop the Pedestal of Hope.", completion = "The Cradle of Chi-Ji has long been a bastion of hope; a place free of despair. Ellia Ravenmane tried to plant the seeds of despair on our island... and you stopped her.\n\nWe owe you a debt of gratitude, <name>. You are welcome to return whenever you like." }
WordHunterWoW_QuestEN[30740] = { title = "Champion of Chi-Ji", description = "While you will always hold a place of honor among our order, you are still welcome to participate in our duels.\n\nOne of our current champions awaits you in the Dome Balrissa. I know that they would be honored to duel with you.", objectives = "Defeat a Champion of Chi-Ji.", completion = "Done masterfully, as always.\n\nWe hope to see you again soon, <name>." }
WordHunterWoW_QuestEN[30742] = { title = "Shut it Down", description = "I mussed up. Bad.\n\nIt's hard work cutting seeds out of kafa berries! But I noticed goots eat the berries up and give back the seeds... in a day or so.\n\nI fed everything I had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", objectives = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.", completion = "Thank you, friend. Let this be a lesson to you: never feed the goots." }
WordHunterWoW_QuestEN[30743] = { title = "Gourmet Kafa", description = "It was genius: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my invention--Kafa'goot--is GOURMET.\n\nBut it's over now. Uncle is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so I can find it easily when the mountain is safe again.", objectives = "Mark 15 Kafa'goot \"Deposits\" on Kota Peak.", completion = "Great, I'll get up there and... harvest them soon.\n\n<Cousin Gootfur begins wrapping long strips of linen around his hands.>\n\nCan't believe I thought this was a good idea." }
WordHunterWoW_QuestEN[30744] = { title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nI pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", objectives = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves." }
WordHunterWoW_QuestEN[30745] = { title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen they ate the goots full of kafa...\n\n<Keenbean shoots Gootfur a mean glance.>\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", objectives = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", progress = "Don't wanna fight yetis? Can't say I blame you.", completion = "You made it!\n\nYeti's are tough enough on their own - can't imagine what a cranky kafa-addict yeti must be like. You brave. Or lucky. Or dumb.\n\nMaybe all three." }
WordHunterWoW_QuestEN[30746] = { title = "A Fair Trade", description = "<The roar bellows out again, louder and more fierce than any of the yetis you've encountered so far. Again, a grummle voice replies...>\n\nEep! Please, great Kota Kon, forgive grummle. Let me go, I'll bring lots of kafa right away! Promise!\n\n<The beast called Kota Kon answers with another meaty roar.>", objectives = "Bring the Bundle of Kafa'kota Berries to the Lair of Kota Kon, near the top of Kota Peak.", progress = "Kota Kon wants more kafa, but I already fed her all I have! Then I tried giving her a nice bow, but she's not satisfied!\n\n<The terrified grummle gulps and leans in close to whisper.>\n\nI think she can smell the kafa I drank for breakfast...", completion = "You brought kafa?!\n\nYou...\n\nMagnificent...\n\nLuckydo...\n\nHurry, let's give it to her! Maybe she won't have us both for snack..." }
WordHunterWoW_QuestEN[30747] = { title = "The Burlap Grind", description = "Okayyy... well, she's not eating anybody. That's a good start.\n\nShe must want more kafa, but we gotta give her somethin' to do with all the extra energy...\n\nI got it! The Burlap Trail! She can smash hozen out there all day!\n\n<Burrberry turns to the massive beast.>\n\nWhat do you think, pretty girl? Wanna smash hozens?!\n\nI think so. Here, feed her my emergency flask of kafa. She likes you.", objectives = "Feed the Flask of Kafa to Kota Kon at Kota Basecamp, then kill 100 Hozen along The Burlap Trail.", progress = "Don't push our luck... we promised her hozens-smashies.", completion = "Wow! That was VIOLENT.\n\nNot sure what I was expecting...\n\nThanks to you, I think we may have just formed a mutually beneficial relationship with the Terror of Kota Peak." }
WordHunterWoW_QuestEN[30750] = { title = "Off the Wall!", description = "The yaungol on the wall here are providing covering fire for the ones below. I don't know what Lao-chen is thinking, but I want you to deal with these archers.\n\nThe good news is, up here we've got the spirit of the Ox helping us. When they're weakened, the ox spirit will stun them and you can use it to knock 'em off the wall.\n\nYou'll find the archers just out that door.", objectives = "Kill 12 Osul Veteran Archers or Osul Fire-Warriors.", progress = "Come on, come on.", completion = "Ha! I could see them flying. Good work." }
WordHunterWoW_QuestEN[30751] = { title = "A Terrible Sacrifice", description = "I have an idea, and... am prepared to make a terrible sacrifice.\n\nAs much as I know that we need my stout brew, to fortify our defenders for the long-term security of the Ox Gate...\n\nIt is too painful to discuss details now, but please - while you are up here defending the wall, gather the barrels of oil they are using to light their arrows. We will need them.", objectives = "Gather 6 Barrels of Yaungol Fire Oil.", progress = "Do you have the oil?", completion = "Alright. I am off to prepare our next move. Good luck, friend." }
WordHunterWoW_QuestEN[30752] = { title = "Unbelievable!", description = "I simply refuse to believe the guards will not grant us entry to the monastery should we impress upon them the seriousness of the situation.\n\nFriend, go east, to the sentinel in front of the Monastery, and demand admittance. I will come with you.", objectives = "Speak to the Shado-Pan Monastery Sentinel to gain entrance to the Shado-Pan Monastery.", progress = "Unbelievable!", completion = "No... this is worse than I could have possibly imagined. The monastery itself has been compromised..." }
WordHunterWoW_QuestEN[30753] = { title = "Jumping the Shark", description = "There is only one way to kill sharks where I come from, with your bare hands!\n\nI dumped a good amount of chum in the water just off the dock here, this place should be crawling with the local reef sharks in no time.  Hop on the first one you see and take it out!", objectives = "Kill a frenzied reef shark with your bare hands.", progress = "Did you show that shark who's boss?", completion = "That was a huge shark you took out <name>!  Color me impressed!" }
WordHunterWoW_QuestEN[30754] = { title = "Bright Bait", description = "Certain fish are only attracted to bright lights.  The forest north of here is home to a local pandaren firefly called a suncrawler.\n\nYou should be able to find them on the base of the tree trunks all around that area.  Bring me back a handful of them and I can use them for bait!", objectives = "Collect 7 Suncrawlers in the forest north of Anglers Wharf.", progress = "Any luck with those suncrawlers?", completion = "These should do nicely <name>.  Thanks for the help!" }
WordHunterWoW_QuestEN[30757] = { title = "Lord of the Shado-Pan", description = "Our lord, Taran Zhu, has been overcome by a sha of pure hatred. The whole monastery has been lost!\n\n{class}, you must find a way to free him of this possession. Last I knew, he was meditating in the Grove of Falling Blossoms.", objectives = "Rid Taran Zhu of his possession by the Sha of Hatred.", completion = "Thank you, <class>. I am cleansed of all hatred.\n\nKnow that you are a hero of the Shado-Pan." }
WordHunterWoW_QuestEN[30759] = { title = "Sotelo's Quest", description = "Push the plunger.\n\nPUSH IT!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Sotelo's Plunger." }
WordHunterWoW_QuestEN[30763] = { title = "Piranha!", description = "Certain fish are very difficult to catch.  The wolf piranha falls squarely into this category.\n\nLucky for me that you showed up!  Put those fishing skills to the test and bring me back a few from the krasarang river due northwest of here.", objectives = "Fish up 5 Wolf Piranha from the Krasarang River in Krasarang Wilds.", progress = "Any luck?", completion = "I see you still have all your fingers, nice work." }
WordHunterWoW_QuestEN[30765] = { title = "Regaining Honor", description = "{name}, the yaungol warchief, Humongous, killed Shado-Master Zhen. He has his banner.\n\nYou have to kill Humongous and regain Zhen's honor! If you don't, I will.", objectives = "Retrieve Zhen's Banner." }
WordHunterWoW_QuestEN[30766] = { title = "Profiting off of the Past", description = "<A relic drops off of the statue. Hmm, these could prove to be valuable to the right person.>\n\n<There's a collector on the outskirts of the ruins. Perhaps he'd be interested in purchasing them from you?>", objectives = "Collect 11 more Mogu Relics.<A relic drops off of the statue. Hmm, these could prove to be valuable to the right person.>\n\n<There's a collector on the outskirts of the ruins. Perhaps he'd be interested in purchasing them from you?>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30767] = { title = "Risking It All", description = "Wait, what?! How could he be so reckless? Blowing the ship free is insane! They could kill Shen-zin Su, and all of us with it. \n\nI know we don't have much time, but we need to think of another way...", objectives = "Remove the thorn from Shen-zin Su.", completion = "The first step is done, but now we must save Shen-zin Su!" }
WordHunterWoW_QuestEN[30768] = { title = "My Husband...", description = "Lin...\n\nI don't care what Ban, Lao-Chin, or even Taran Zhu says. I'm moving ahead into Townlong. I may not be able to save Lin myself, but I'm not going to sit around waiting for everyone else to catch up.\n\nOnce Taran Zhu opens the doors to his precious monastery, we'll save Lin. Until then, I'll scout ahead and make sure he's alright.", objectives = "Meet up with Suna Silentstrike at Longying Outpost in the Townlong Steppes.", completion = "Good. Looks like the rest of the Shado-Pan decided it was a good time to catch up." }
WordHunterWoW_QuestEN[30769] = { title = "First Assault", description = "Now that we have had time to assess our enemies' weaknesses, it is time for us to deal the yaungol a direct blow.\n\nGo and confront the Osul Sharphorn up the mesa to the west.\n\nLet them know that we are here, and that we are not scared of their threats.", objectives = "Kill 6 Osul Sharphorns.", completion = "Well done, <name>. I hope you showed those cretins no mercy." }
WordHunterWoW_QuestEN[30770] = { title = "Running Rampant", description = "There is one thing that every army needs, and that is a supply line.\n\nThe enemy camp to the west contains a large beast herd, which serves as the yaungol army's main source of food.\n\nLuckily for us, the yaks and mushan beasts of this region are easily scared.\n\nSneak in, give the beasts a good slap, and watch the results.", objectives = "Scare 8 Long-Haired Yaks or Steppebeasts.", completion = "Ohohoho! I saw those animals trailing dust from up here.\n\nThose yaungol are probably still wondering what happened." }
WordHunterWoW_QuestEN[30771] = { title = "Perfect Pitch", description = "When the Osul tribe goes to war, they coat their spears and arrows with a highly flammable, ever-burning pitch.\n\nThey use this terrible weapon to shed not only blood, but to raze the homes of their enemies.\n\nI need you to collect some of this pitch while you are in their camp.\n\nWe will use it to show the yaungol that when you play with fire, you can get burned.", objectives = "Collect 8 Dark Pitch.", progress = "The yaungol are not content merely to defeat their enemies. No, they would rather destroy and decimate them.", completion = "It still smells fresh.\n\nGood job, <name>." }
WordHunterWoW_QuestEN[30772] = { title = "Seeing Red", description = "Ahead of us is the main thrust of the yaungol army.\n\nHere, they prepare their vast army to attack the villages of Kun-Lai.\n\nIf we strike at the Osul now, we can cut them at their very core.\n\nRemember, for every of their number that we strike down here, we save one of our own back at home.", objectives = "Kill 8 Osul Marauders or Osul Spitfires.", completion = "That should put a serious dent in their numbers.\n\nI doubt they will be able to recover from such losses." }
WordHunterWoW_QuestEN[30773] = { title = "Pitching In", description = "The yaungol's siege weapons - those ballista spearthrowers down there - are tearing apart our defenses both at Longying Oupost and in Kun-Lai Summit.\n\nThose terrible weapons must be destroyed.\n\nTake these explosives. I've covered them in the pitch that you collected.\n\nToss them at those ballistas, and we'll give the yaungol a little taste of their own medicine.", objectives = "Use Ban's Explosives to destroy 6 Osul Ballistas.", progress = "Fire is a cruel weapon. Luckily, we are only using it to destroy weapons of war.", completion = "Good, <class>.\n\nNow that they cannot hide behind their siege weapons, they have no choice but to face us." }
WordHunterWoW_QuestEN[30774] = { title = "Ranger Rescue", description = "I must ask a most important task of you, {name}.\n\nSomewhere among the cages in the Osul camp is my husband, Lin. He is the light of my world.\n\nPlease find him and return him to me, and save as many of our fellow Shado-Pan as you can as well.\n\nYou should find keys to those cages on the Osul Marauders.", objectives = "Unlock Drywood Cages to save 4 Longying Rangers and Lin Silentstrike.", progress = "How did it go?", completion = "I am truly sorry to hear that Lin did not make it.\n\nSuna is taking the news quite hard. She will forgive me in time.\n\nAs for the rest of the Shado-Pan that you saved, well, I am very grateful to see them returned safe and sound." }
WordHunterWoW_QuestEN[30775] = { title = "The Exile", description = "What is there to say, stranger?\n\nI fought Jung Duk and lost. I was the fool to believe he would fight fairly.\n\nNow, my own brothers turned against me, and here I am, speaking to our enemies.\n\nI know you have come for Osul blood.\n\nI only ask that you hunt down the three who betrayed me.\n\nUrang, who poisoned my drink. Ku-Tong, who bent my spear. And Battat, whose dagger slipped into my side as my victory was assured.\n\nDo this, and I can die in peace.", objectives = "Kill Urang, Ku-Tong, and Battat.", progress = "How could they have betrayed me? They were once my brothers!\n\nWhy did they turn on me? WHY?\n\nI hate them! I will slaughter them all!", completion = "It pleases me to know those cowards died at your hands.\n\nPerhaps now, this burning tide in my heart will ebb." }
WordHunterWoW_QuestEN[30776] = { title = "Jung Duk", description = "THIS. IS. WAR.\n\nI will have the heads of everyone who took Lin from me. EVERYONE!\n\nWe will begin with the Osul leader, Jung Duk.\n\nTake this Shado-Pan war banner and place it at the center of their camp.\n\nJung Duk will have no choice but to face you.\n\nShow him no mercy, {name}.", objectives = "Plant the Shado-Pan Banner on the Ceremonial Pile, then kill Jung Duk.", progress = "Jung Duk's legacy is written in the blood of innocents.", completion = "Jung Duk is dead at last.\n\nHundreds, perhaps thousands, lost their lives due to his violent aggression.\n\nThough they are not here to witness his demise, they owe deep gratitude to your bravery today." }
WordHunterWoW_QuestEN[30777] = { title = "In Search of Suna", description = "I have bad news. When I returned, Suna was already gone.\n\nThe others say that she took her things and headed down the road to the east, muttering about hunting down the source of the yaungol aggression.\n\nI cannot allow her to venture into dangerous territory alone.\n\nI've already prepared a group of soldiers to push further east.\n\nWe are leaving shortly. Hop on the caravan if you wish to travel with the Shado-Pan. You can also meet us there if you wish.", objectives = "Speak to Ban Bearheart after arriving at Hatred's Vice.", completion = "Well, we made it." }
WordHunterWoW_QuestEN[30778] = { title = "Dust to Dust", description = "If we are to make camp here, we cannot leave all of these yaungol bodies lying to rot.\n\nTake this torch and set fire to the villagers' corpses.\n\nThe incense from the torch should purify the earth and air around them as well.\n\nEven our enemies deserve to be laid to rest.", objectives = "Use the Shado-Pan Torch on 20 Palewind Villagers.", progress = "The stench of death is overpowering.", completion = "Good work, <name>.\n\nHopefully, their spirits are in a better place." }
WordHunterWoW_QuestEN[30779] = { title = "Slaying the Scavengers", description = "The rotting corpses are attracting hyena scavengers.\n\nIn addition to spreading diseases from feeding on the dead, the feral creatures will attack us on sight.\n\nGo and eradicate the beasts. It is unfortunate, but ultimately for the best.", objectives = "Kill 8 Ashfang Hyenas.", completion = "Thank you, <name>. It was an unpleasant task, but it had to be done." }
WordHunterWoW_QuestEN[30780] = { title = "Totemic Research", description = "As we entered the village, I couldn't help but notice yaungol totems lying around this camp.\n\nI have a suspicion that there are dark forces at work here, and those totems may be the key to drawing them out.\n\nCould you bring me some of these totems for further inspection? I would like to study them.", objectives = "Collect 9 Palewind Totems.", progress = "I do believe the totems could be of use to us.", completion = "I was right! These totems were once used to store and conduct immense magical energies.\n\nI do believe I can use them once again to do the same." }
WordHunterWoW_QuestEN[30781] = { title = "Last Toll of the Yaungol", description = "Ban has asked me to explore the village to determine what happened here.\n\nI noticed smoke rising up from the east, the west, northwest, and the south.\n\nI need someone I trust to watch my back.\n\nWhat do you say? Want to help me on my first scouting mission?", objectives = "Take Xiao Tu to the smoke trails at Hatred's Vice.", progress = "Something terrible must have happened here.", completion = "Thank you for your help, <name>.\n\nWe cannot know exactly what happened here, but it's clear that something caused the yaungol to turn on one another.\n\nWhat kind of power could do this?" }
WordHunterWoW_QuestEN[30782] = { title = "Spiteful Spirits", description = "The spirits of the fallen villagers have risen! I can feel the hatred emanating from the spirits.\n\n{name}, if we are to survive here, we must defend ourselves. This is the only way we can put them to rest.", objectives = "Kill 10 Spiteful Spirits.", progress = "The air is thick with their malicious intent.", completion = "Well done. We cannot bring them retribution, but at least we can end their rage." }
WordHunterWoW_QuestEN[30783] = { title = "Hatred Becomes Us", description = "I should have suspected a sha presence earlier!\n\nWe are safe as long as we stand inside the Totem of Harmony's protective wards, but many of our people were not so lucky.\n\nThey were trapped outside the camp when the sha's powers manifested, and now they turn upon each other!\n\nTake one of my totems with you. Place the totem near a crazed ally to purify them, but beware.\n\nYou may have to face the darkness that gripped them.", objectives = "Use the Totem of Harmony to exorcise sha spirits from 8 Crazed Shado-Pan Rangers. Defeat the Seething Hatreds to purify your allies.", progress = "Our people are possessed by hatred. We must help them come to their senses!", completion = "Thank you.\n\nThe sha preys upon the weak and the vulnerable.\n\nIf we are not vigilant, even the strongest of us can succumb to the sha's dark influence." }
WordHunterWoW_QuestEN[30784] = { title = "The Point of No Return", description = "One of our rangers reported seeing Suna up the hill to the northwest.\n\nI am relieved to find her safe. I had feared what she would do in her grief.\n\nWould you go speak to her on my behalf?\n\nTake this totem with you. If you encounter any danger along the way, you may find it useful.", objectives = "Find Suna Silentstrike.", progress = "If I could change the past, I would. If I could take Lin's place, I would.\n\nIn a thousand lifetimes, I will never be able to repay Suna's loss, or share even a measure of her grief.", completion = "What? She was possessed by the Sha of Hatred?\n\nNo. NO!\n\nDespite our differences, she was one of us. Today, the Shado-Pan has lost a dear sister.\n\nHer death will not be in vain. I will not rest until I have defeated the Sha of Hatred!\n\nSuna, I swear this to you!" }
WordHunterWoW_QuestEN[30785] = { title = "Gao-Ran Battlefront", description = "With your help, we have quelled the spirits of this place.\n\nAt last, they may rest in peace.\n\nOur journey into this cursed land, I am afraid, has only begun.\n\nI have some important matters to finish up here, but we will be moving out soon.\n\nI need someone to go ahead and tell Lord Taran Zhu that we are joining him.\n\nFind him at the Gao-Ran Battlefront. Tell him what has transpired here.", objectives = "Speak to Lord Taran Zhu at the Gao-Ran Battlefront in the Townlong Steppes.", completion = "Did the northern expedition go well, then? What news do you have to report?" }
WordHunterWoW_QuestEN[30786] = { title = "A Spear Through My Side, A Chain Through My Soul", description = "My fate is sealed. The yaungol put this spear in my side. The wound will kill me.\n\nThe yaungol hold me in place with their twisted, corrupted magic. The indignity of it hurts worse than my spear-wound.\n\nMy death, I cannot stop. My imprisonment... you may be able to help me with this.", objectives = "Slay Dmong Naruuk, the shaman who holds Orbiss hostage.", progress = "I will not die before having my revenge.", completion = "I am freed.\n\nThe yaungol must be stopped." }
WordHunterWoW_QuestEN[30787] = { title = "The Torches", description = "Until recently, the yaungol shaman would come here to work alongside us. Now, they bend my people to their will.\n\nIf we refuse, they kill us. Even if we oblige... they kill us.\n\nThe yaungol mist-shaman's magic flows through his torch. Take his torch away, and he has nothing.", objectives = "Obtain 6 Mist-Shaman's Torches.", progress = "I can use these torches in my revenge.\n\nI have not succumbed to this wound yet. I can still have my revenge before I die.\n\nThere is time yet.", completion = "This torch... the yaungol once used these to communicate with me, with my people.\n\nNow, they use them to undo us." }
WordHunterWoW_QuestEN[30788] = { title = "Golgoss", description = "The leader of the yaungol mist-shaman is named Jahesh. He is known for his strength.\n\nOne of my kind is also known for his strength. His name is Golgoss.\n\nGolgoss sleeps within the mists of the Upper Sumprushes. Help me to summon him, and he will join me in avenging our people.", objectives = "Summon Golgoss by planting the Mist-Shaman's Torches into the Peat Clump in the Upper Sumprushes.", progress = "Golgoss is no coward. He will relish the opportunity for revenge.", completion = "Golgoss does not speak your language, other than a few words. I suppose I am unique in this regard.\n\nHe thanks you for summoning him." }
WordHunterWoW_QuestEN[30789] = { title = "Arconiss", description = "If I am to fight Jahesh, leader of the yaungol mist-shaman, I must have Arconiss by my side. Arconiss' ferocity is second to none.\n\nHe rests beneath the mists of the Upper Sumprushes. Find his resting place, and then use these torches to awaken him.", objectives = "Summon Arconiss by planting the Mist-Shaman's Torches into the Peat Mound in the Upper Sumprushes.", completion = "It will be difficult to lose with Arconiss by my side." }
WordHunterWoW_QuestEN[30790] = { title = "Golgoss Hungers", description = "Golgoss' strength is great, but he requires nutrition before he can use it.\n\nThe snarlthorn bushes in the Upper Sumprushes have heavy, fibrous branches. These should sate his appetite.", objectives = "Obtain 10 Snarlvines.", progress = "Golgoss' hunger is great.", completion = "We are one step closer to my goal." }
WordHunterWoW_QuestEN[30791] = { title = "Arconiss Thirsts", description = "Arconiss fights with unmatched fury, but his extended stay beneath the mists has left him weakened.\n\nThe rodents of the swamp are plentiful, and their bodies are filled with nourishing blood. Return with blood enough to reignite Arconiss' spirit.", objectives = "Obtain 4 Clotted Rodent's Blood.", progress = "Our preparation will not take much longer.", completion = "Yet another step closer to completing my mission." }
WordHunterWoW_QuestEN[30792] = { title = "Orbiss Fades", description = "I knew death would come. I did not know that it would come this fast.\n\nI must buy time. The mist of the Upper Sumprushes is warm and fragrant. Such mist is nutritive to my kind.\n\nGather this mist however you can... in jars, in vials, within the interior of your bags. Bring it back to me, and I can use it to remain corporeal for a bit longer.", objectives = "Obtain 8 Gushing Mists by walking through mist geysers in the Upper Sumprushes.", progress = "I require more mist. I am fading...", completion = "I told you earlier, this wound would be my death. While you have bought me a bit more time, it is not long now." }
WordHunterWoW_QuestEN[30793] = { title = "Mists' Opportunity", description = "Now is the time to strike.\n\nGolgoss, Arconiss, and I will go east, into Jahesh's domain. Meet us there, and prepare for battle.\n\nToday, we restore the pride of our people.", objectives = "Slay Jahesh of Osul.", completion = "My name will be forgotten, but my actions will not.\n\nNor will yours, <name>." }
WordHunterWoW_QuestEN[30794] = { title = "Emergency Care", description = "I... am alive... but barely. They killed the rest. My friends... and family...\n\nI must return to the village... But, I do not have long, and cannot move on my own... are you a healer? I... have a healing potion in my hut... search my belongings. You can use your magic, if you have it.", objectives = "Heal Sage Liao to get him back on his feet.", completion = "Thank you. I suppose... I'll need to ask you to do a bit more before I can return to the village. I cannot leave the bodies of my friends and family here." }
WordHunterWoW_QuestEN[30795] = { title = "Staying Connected", description = "The Tongue of Ba-Shon should allow us to communicate from long distances, {name}.\n\nIf the relic works the way I think it will, I should be able to stay here and continue my meditations while you do some scouting in the Valley of Emperors.\n\nMishi will take you to the edge of the valley so that we can test my theory. I would hate for you to be in the tombs with no way to contact me. That would be horrible!", objectives = "Use the Tongue of Ba-Shon in the Valley of Emperors.", completion = "Very good! The relic works!\n\nIt appears there is more going on in the Valley of Emperors than I had anticipated. It is crucial we figure out why the Mogu are opening the tombs." }
WordHunterWoW_QuestEN[30796] = { title = "An End to Everything", description = "These spirits must have been released when the tombs were opened... \n\nDeath was not final for the Mogu. Instead, death was merely a stop over on the path to a new body. Spiritbinders used a foul magic to transfer spirits from one shell to the next.\n\nYears of being trapped in the tombs has left them confused. They need to be destroyed before their confusion turns to anger or worse, they find a new shell.", objectives = "Destroy 5 Tormented Spirits.", progress = "Have you disposed of the spirits yet?", completion = "You have done them a great service, <name>.\n\nIt is a cruel fate to be stuck between the living world and the afterlife." }
WordHunterWoW_QuestEN[30797] = { title = "It Was Almost Alive", description = "A ritual took place here, and from the looks of it wasn't successful.\n\nAmong the abandoned items a book lies open. The text on the pages is foreign to you.\n\nCarrying the whole book may be difficult, but a single page might be enough. If you can get the page to Lorewalker Cho he may be able to tell you what it says.", objectives = "Tear a page from the open book to give to Lorewalker Cho.", progress = "What have you found, <name>?", completion = "This text is curious indeed, <name>...\n\nIt appears to have been written in the Meng dynasty, but some of the symbols are wrong. I don't think the Mogu wrote this, although it is oddly close.\n\nIt will take me some time to translate. Keep moving and see if you can find anything else." }
WordHunterWoW_QuestEN[30798] = { title = "Breaking the Emperor's Shield", description = "The Mogu have been scattered and sparse in number for many years. Their purpose in the valley makes sense now.\n\nWith this many restless spirits they can build themselves an army using the guardians buried in each tomb. Combined with the Zandalari forces this would be devastating!\n\nThe Tomb of Secrets houses elite warriors called the Emperor's Shield. They must not be resurrected! You'll find the tomb on the highest rise to the southwest. ", objectives = "Stop the Spiritbinding Ritual in the Tomb of Secrets.", progress = "Have you gone to the Tomb of Secrets yet?", completion = "The Mogu and the Zandalari intend to resurrect the Thunder King?!\n\nWe cannot let this happen, <name>! The Thunder King will rain destruction on this land with his return." }
WordHunterWoW_QuestEN[30799] = { title = "The Tomb of Shadows", description = "Given the artifacts you found on the altar, I would guess they were attempting to perform a Spiritbinding ritual.\n\nMost of the texts involving Spiritbinding were locked away in the Tomb of Shadows. Perhaps we will find the answers we seek there.\n\nLook for anything that might help us. You'll find the tomb on the first rise closest to the ritual altar.", objectives = "Collect a rubbing of the Shen Dynasty Tablet, the Wai Dynasty Tablet, and the Qiang Dynasty Tablet in the Tomb of Shadows.", progress = "Did you find anything in the Tomb of Shadows?", completion = "These tablets recount the history of the Mogu and Zandalari alliance dating back to the time of the first Mogu emperor.\n\nBy the looks of things they have rekindled their alliance. But why now?" }
WordHunterWoW_QuestEN[30800] = { title = "Stealing Their Thunder King", description = "Our only hope is to find the Thunder King's remains before they do. He must be buried within the Tomb of Conquerors.\n\nGetting to his remains will not be easy, {name}. The tomb will no doubt be defended by guardians and other unfriendly surprises intended to ward off thieves.\n\nOnce inside we will need to figure out where his remains have actually been placed.", objectives = "Find the Bottom Fragment of Lei Shen's Tablet and restore the Tablet of Thunder.", progress = "Have you figured out where the Thunder King's remains are hidden?", completion = "We are fortunate they haven't gotten to Lei Shen's remains... yet.\n\nThe Zandalari will not give up until they have what they want." }
WordHunterWoW_QuestEN[30801] = { title = "Lessons from History", description = "The Thunder King was a vicious Emperor and with the Zandalari at his side he was unstoppable. His return would surely return this land to turmoil and misery.\n\nYou must locate his remains and take them somewhere safe. The Tablet of Thunder should help you figure out how to access his tomb.", objectives = "Read the Tablet of Thunder in the Tomb of Conquerors.", progress = "Have you read the tablet?", completion = "They will need to move the remains to a secure location. We must go after them!" }
WordHunterWoW_QuestEN[30802] = { title = "Chasing the Storm", description = "We need to figure out where they are taking the Thunder King's remains. It won't be possible for them to resurrect him in the Valley of the Emperors. They would need to be somewhere remote and secure.\n\nIt appears that getting out of here may also prove to be a challenge....\n\nFight your way out and look for information concerning the location of the remains.", objectives = "Find the Blood-Revealed Map on a Zandalari Warrior.", progress = "Were you able to find any information on their location?", completion = "This is dark Zandalari blood magic. Once we're done with the map it should be burned.\n\nThe map indicates they have headed for the coast just outside of a tiny fishing village called Zouchin. The villagers there may be able to help us find the Zandalari. We just have to hope the village is still standing..." }
WordHunterWoW_QuestEN[30804] = { title = "The Fearmaster", description = "I am not gonna take this anymore. My wife, bless her, poured her heart and soul in to that ranch making it what it is today.\n\nThem yaungol got a leader over there being all smug and what not. I'll pay you handsomely if you knock that smug smile off his filthy, stinking, good for nothing face.", objectives = "Kill the Fearmaster.", progress = "So many strangers in these lands these days. Luckily you <class> seem to be all right.", completion = "Yee haw! I knew you humans might be good for somethin'. He must of made a very satisfying \"thump\" when he hit the ground." }
WordHunterWoW_QuestEN[30805] = { title = "Justice", description = "After the mercenaries robbed us, most left.\n\nBut one of them... after the others took all we had, he ran the rest of us through. For sport!\n\nGet justice for the fallen. Perhaps news of their death will raise my spirits enough to go on.\n\nYou'll find them just west of here.", objectives = "Kill Captain Ripflesh and 6 Blackmane Mercenaries.", completion = "Ahh.. they are dead. Already, I can feel my spirits lifting. Soon I will have the strength to return to the village." }
WordHunterWoW_QuestEN[30806] = { title = "The Scent of Life", description = "Many have perished here. We will need to honor them properly, which means gathering the makings of incense of life. \n\nIt doesn't just smell nice - it has restorative properties, and can even help plants grow. Maybe I can get a whiff of the ingredients to get me back on my feet.\n\nThe materials can be found on creatures around here - except for the spices, which were stolen by the mercenaries who pillaged the village. ", objectives = "Gather an Opalescent Blue Crab Shell and 8 Stolen Pandaren Spices.", progress = "Are those the ingredients for Incense of Life I smell on you? Or... perhaps you haven't bathed recently.", completion = "Beautiful, beautiful. Better to not need to bury our friends, but if we must, it is good they will have a fitting ceremony." }
WordHunterWoW_QuestEN[30807] = { title = "By the Falls, For the Fallen", description = "I do not wish to dishonor my friends and leave them in unmarked graves.\n\nYet, we have never needed to bury so many at once, and I am in no condition to gather materials.\n\nPlease, visit the lakes that hug the mountains edge along the road to the south. Underneath the waterfalls there, you will find stones that have been polished to a sheen by the falling water. They will make suitable headstones.", objectives = "Gather 3 Waterfall-polished Stones.", progress = "The stones - have you brought them?", completion = "Good. Thank you. After this, I cannot imagine leaving my fellows to less than a proper burial." }
WordHunterWoW_QuestEN[30808] = { title = "A Grummle's Luck", description = "The yaungols stole our luckydos! Mean riders with spears took them from our caravan of brothers coming down the Burlap Trail.\n\nThis is very bad fortune. If the yaungol discover the secrets of luckydos all grummles will be in big trouble.\n\nRecover our luckydos from Fire Camp Ruqin north of here and we will pay many fortunes to you.", objectives = "Find 8 Stolen Luckydos.", progress = "A luckydo is a thing of much good fortune. Yaungol know nothing of how to use luckydos... yet.", completion = "Hurray! Our Luckydos. Many thanks and fortune to friend of grummles!" }
WordHunterWoW_QuestEN[30814] = { title = "A Foot in the Door", description = "<Lord Taran immediately pins you down with his steely gaze.>\n\n{class}, you bear the marks of many a past battle.\n\nGood! We need more seasoned people like you to hold back the front.\n\nWe've managed to secure a foothold here, but the yaungol are desperate to remove our presence.\n\nIf you wish to prove your worth, go down the hill and show the yaungol that we will not back down.", objectives = "Kill 8 Osul Chargers.", progress = "We are slowly gaining ground.", completion = "Good. I can see that you are capable.\n\nI hope to rely on your talents for what is to come." }
WordHunterWoW_QuestEN[30815] = { title = "The Death of Me", description = "I have resolved to remove this spear from my side.\n\nFor this, I require your assistance. Your grasping hands are stronger than mine.", objectives = "Remove the spear from Orbiss.", completion = "By removing this spear, I have truly guaranteed my own death.\n\nThis does not frighten me.\n\nI would sooner die than live carrying the weapon of my enemy." }
WordHunterWoW_QuestEN[30816] = { title = "Checking In", description = "When the trolls came, they brought their mercenary... friends with them. I saw them go past us, to the fishing camp in the northwest. My cousin, a healer, lives there - can you check in with him and make sure he and his village are well?", objectives = "Check on Sage Liao at the Zaochin Strand in Kun-Lai Summit.", completion = "Ahh... My cousin is wise to be worried... I am not well..." }
WordHunterWoW_QuestEN[30817] = { title = "The Healing of Shen-zin Su", description = "This is what comes of such recklessness. How could he think this was even a possibility?\n\nNevermind, there's no time for that now. We need to act to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", objectives = "Rescue and defend healers until Shen-zin Su's wound is healed." }
WordHunterWoW_QuestEN[30818] = { title = "A New Fate", description = "{name}, I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", objectives = "Return to the Temple of Five Dawns. A cart is waiting near the Skyfire Crash-Site to take you there.<name>, I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30819] = { title = "Preparing the Remains", description = "Thank you much, friend. After this tragedy, it is good that fortune has smiled on us and sent you.\n\nYou have gotten justice for my fallen friends, and gathered the necessary materials to honor them. I will gather their bodies, prepare the materials for their funerals, and meet you at the graveyard. \n\nIn the meantime, however, please return to my cousin and ask him to gather the villagers for the funeral.", objectives = "Return to Li Hai and tell him about the funeral.", completion = "I see... it is tragic what has happened there. We will meet you at the graveyard to honor them." }
WordHunterWoW_QuestEN[30820] = { title = "A Funeral", description = "As I said, I will gather the town - we will be at the funeral. \n\nAs the one who has done so much to honor our friends, we feel it is only right that you will be the one to light the Incense of Life and usher their spirits to the life beyond.", objectives = "Attend the funeral and light the Incense of Life.", progress = "You must light the incense to honor the dead.", completion = "Good. Let us begin the funeral." }
WordHunterWoW_QuestEN[30821] = { title = "The Burlap Grind", description = "Alright, it's time to take Kota Kon out for her \"walk.\"\n\nWe brewed two fresh pots of kafa just for her and she's all fueled up!", objectives = "Speak with Kota Kon at Kota Basecamp to ride her, then kill 100 Hozen along The Burlap Trail.", progress = "Kota Kon's waiting for you! She won't let anyone else ride her.", completion = "Hah hah! We could hear those monkeys screamin' from over here!\n\n<Burrberry turns to Kota Kon.>\n\nWho's a pretty girl? You are!!" }
WordHunterWoW_QuestEN[30823] = { title = "Shut it Down", description = "My cousin over at Kota Basecamp mussed up. He mussed up bad.\n\nHe was too lazy to cut seeds out of kafa berries by hand, but he noticed goots eat the berries up and give back the seeds... in a day or so.\n\nHe fed everything he had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", objectives = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.", completion = "Thank you for helping to correct my mistake, friend. Let this be a lesson to you: never feed the goots." }
WordHunterWoW_QuestEN[30824] = { title = "Gourmet Kafa", description = "It was a crazy idea: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my cousin's invention--Kafa'goot--is GOURMET.\n\nBut it's over now. Uncle Keenbean is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so we can find it easily when the mountain is safe again.", objectives = "Mark 15 Kafa'goot \"Deposits\" on Kota Peak.", completion = "I'd heard an adventurer was up there marking the deposits. Mussy work for someone with your skills, but I appreciate it.\n\nI'll get up there and... harvest them soon.\n\n<Cousin Gootfur begins wrapping long strips of linen around his hands.>\n\nCan't believe I thought this was a good idea." }
WordHunterWoW_QuestEN[30825] = { title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to our cousin. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nUncle Keenbean will pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", objectives = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves." }
WordHunterWoW_QuestEN[30826] = { title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen stupid Cousin Gootfur over at Kota Basecamp fed kafa to the goots, and the yeti ate them goots.\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", objectives = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", completion = "Ah, hello there! Tallmug sent a messenger yak over explaining that you would be helping us with our yeti problems.\n\nAnd you weren't torn to shreds! Yeti's are tough enough on their own - can't imagine what a cranky kafa-addict yeti must be like. You're brave. Or lucky. Or dumb.\n\nMaybe all three." }
WordHunterWoW_QuestEN[30827] = { title = "What Lies Beneath", description = "If my suspicions are correct, this place still reels from some lingering darkness.\n\nWhatever happened here... it could not have been the natural course of events.\n\nEven the yaungol are not so brutal as to slaughter their own kind to the point of... this.\n\nI will use the totems that you brought me to perform a cleansing ritual.\n\nI need someone to assist me in the ceremony. Let me know when you are ready.", objectives = "Speak to Yalia Sagewhisper to begin the ceremony.\n\nThen, activate the Totem of Kindness, the Totem of Tranquility, and the Totem of Serenity.", progress = "I believe that we must drive the taint from this place.", completion = "We look upon the true face of hatred!\n\nNow it all makes sense. This is the work of the sha." }
WordHunterWoW_QuestEN[30828] = { title = "Cleansing the Mere", description = "Pools of the same murky substance that came out of Mei emerged in the lake recently.\n\nI will travel into the Mere with you. Point out the pools of corruption that you are ready for me to cleanse.\n\nYou will need to deal with whatever comes out and protect me as I complete the ritual.", objectives = "Point out Pools of Corruption in Inkgill Mere to Waterspeaker Gorai to let him know you are ready to defend him while he completes the cleansing ritual.", progress = "Is the lake cleansed?", completion = "The Mere... I can feel the corruption clearing. At least now, this corruption will not spread.\n\nBut, there is one more thing we must do." }
WordHunterWoW_QuestEN[30829] = { title = "The Tongue of Ba-Shon", description = "Thank you for coming, {name}. I am sorry to have been so cryptic, but I could not risk alerting the mogu to my work here.\n\nThey are seeking something in the valley. Plundering the tombs of their old kings for relics of power.\n\nI could not observe them long before having to flee, but I did manage to recover a relic of my own.\n\nThe Tongue of Ba-Shon will let us communicate securely over long distances, but only after I have bound it to myself.\n\nI think I'm ready to begin, if you are.", objectives = "Assist Lorekeeper Cho in performing the Binding of Ba-Shon.", progress = "I'll need to bind my essence to the Tongue, then you can use it to speak with me from anywhere.", completion = "This must be a very powerful relic for Zuan to want it back so badly.\n\nIt frightens me to think of what else they may find in the tombs..." }
WordHunterWoW_QuestEN[30834] = { title = "Father and Child Reunion", description = "They survived? My father is alive!\n\nI thought we would all die here in this horrible mere, at the hands of these insane Jinyu.\n\nI will find my way back - meet me back at camp.", objectives = "Return to Merchant Shi and Wu-Peng at the southeastern shore of Inkgill Mere in Kun-Lai Summit.", progress = "My boy! He is alive!", completion = "You found him! This is all I have to give, but in finding my son, you have more than earned it." }
WordHunterWoW_QuestEN[30854] = { title = "Lha-Po Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[30855] = { title = "The Fall of Shai Hu", description = "I can hear the voice of the Mere - it has been purified.\n\nBut, this chapter in my people's history will never be closed - not until we defeat Shai Hu.\n\nHe has retreated to the central island in the Mere, corrupting our holiest of sites.\n\nBeware - he is strong. But, after all we have done, I am confident we will be stronger.", objectives = "Defeat Shai Hu. He can be found at the Waterspeaker's Sanctuary, the island in the center of Inkgill Mere in Kun-Lai Summit.", completion = "Thank you, <name>. You have assured that this corruption will not spread, and that my people - those who have not been corrupted - will be able to live on and found a new village. \n\nOur history will live on. You have done more for us than we could have ever hoped.\n\nThank you, friend." }
WordHunterWoW_QuestEN[30879] = { title = "Round 1: Brewmaster Chani", description = "Welcome, Challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", objectives = "Defeat Brewmaster Chani.", progress = "Without conflict, there can be no growth.\n\nThe need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", completion = "Well done, challenger." }
WordHunterWoW_QuestEN[30880] = { title = "Round 1: The Streetfighter", description = "Welcome, challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", objectives = "Defeat the Streetfighter.", progress = "Without conflict, there can be no growth.\n\nThe need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", completion = "Well done, challenger." }
WordHunterWoW_QuestEN[30881] = { title = "Round 2: Clever Ashyo & Ken-Ken", description = "You may know your next challengers. They were arguing fiercely when they arrived, so I have charged them with fighting side by side.\n\nThis will teach them the strength of friendship, and possibly entertain me in the process.\n\nGo to the north eastern arena and face this jinyu and hozen.\n\nDo not be gentle, they need to learn to work together.", objectives = "Defeat Clever Ashyo and Ken-Ken.", progress = "Strength can come from an ally as much as from one's self.", completion = "Pity that those two did not learn their lesson yet. No matter. In time I am sure they will come to see wisdom.\n\nIn the meantime, congratulations on your victory." }
WordHunterWoW_QuestEN[30882] = { title = "Round 2: Kang Bramblestaff", description = "Your next challenger is a Bramblestaff. Strength is in their blood. I remember a full century of only Bramblestaff champions.\n\nNo pressure, little {race}.\n\nGo to the eastern arena north of here and face this young challenger. See first hand if strength is earned or inherited. ", objectives = "Defeat Kang Bramblestaff.", progress = "I was once defeated in a match by a Bramblestaff. In my defense, he distracted me with a ball of yarn.", completion = "Ah. The Bramblestaff family have long held the championship generation after generation. I am sure this one will take the title sooner or later as well." }
WordHunterWoW_QuestEN[30883] = { title = "Round 3: The Wrestler", description = "Your next challenger is a favorite of mine. He draws strength from raw force and determination.\n\nPlus he has a mask.\n\nFace him in the western arena when you are ready, and good luck.", objectives = "Defeat The Wrestler.", progress = "Sometimes strength can come from the outside.", completion = "Well fought, challenger. That was a fierce opponent." }
WordHunterWoW_QuestEN[30884] = { title = "Behind the Battlefront", description = "This battlefront has been undermanned and unsupplied for too long during my absence in Kun-Lai. We need to get things back in order here before we can pick up the trail of the Sha of Hatred.\n\nTaoshi is my best. I've sent her north to investigate rumors of mantid that have somehow made it through the battlefront. I need someone I can trust to get out there and work with her to plug any holes in our defenses.\n\nIf my reports on you are correct, I can trust you with this, right {class}?", objectives = "Meet with Taoshi at Dampsoil Burrow.", completion = "You look capable. Taran knows to send me the best. I like that." }
WordHunterWoW_QuestEN[30885] = { title = "Round 3: Master Boom Boom", description = "Your next challenger found his strength on a beach. Particularly in a box labeled \"dynamite.\"\n\nHe proves however that found strength can be as deadly as personal strength.\n\nWhen you are ready, face this Master Boom Boom in the Western Arena.", objectives = "Defeat Master Boom Boom.", completion = "Well fought, challenger. That was a fierce opponent." }
WordHunterWoW_QuestEN[30886] = { title = "Example Pandaren Race Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[30887] = { title = "Unwelcome Intruders", description = "Those are mantid scouts down there. Gao-Ran's Battlefront is meant to keep them out of eastern Townlong Steppes. If we allow them north of the barricade, we may lose our foothold here.\n\nLet's clear them out. I'll be with you.", objectives = "Kill 12 Krik'thik Deep-scouts with Taoshi's help.", completion = "This is where they're getting through, the eastern pass." }
WordHunterWoW_QuestEN[30888] = { title = "Breach in the Defenses", description = "Normally, it only takes a few scouts to hold this pass. Most of this territory is in sight of the wall, so archers would devastate any mantid force attempting to push through here. The problem is, most of the archers are occupied with the onslaught at the gate.\n\nTake this flare - it will help you locate the mantid that are sneaking through the eastern pass under our diminished watch. Kill any you find. We can't let them lay a trail that might lead the mantid swarms farther into the steppes.", objectives = "Use the Shado-Pan Flare to aid in killing 10 Krik'thik Scentlayers.", progress = "The defenders on the wall are stretched thin. The Yaungol are pushing through the gates to Kun-Lai in the north. The mantid are pouring against the gates to the Vale of Eternal Blossoms. I hear that there's been a breach into the Valley of Four Winds in the south too.\n\nWe do not have the men to combat all of these threats.", completion = "There are more getting through than I thought. I may need to stay here and clean up a while.\n\nYou've done more than your part though, <class>. Thank you." }
WordHunterWoW_QuestEN[30889] = { title = "Trap Setting", description = "Good to meet you, {class}. We have traps all along the pass to help us catch mantid that might be sneaking through, but their numbers have been so great that most of the traps have already been triggered.\n\nTaoshi said you might be able to reset some of them while you're out there. Can you help?", objectives = "Rearm 8 Shado-Pan Spike Traps.", progress = "These traps have been very effective, the mantid numbers are just getting out of hand in these past weeks.", completion = "We could use a few more capable men like you around the camp. Thank you for your help, <class>." }
WordHunterWoW_QuestEN[30890] = { title = "The Restless Watch", description = "I'm being told that our scouts have been on duty in Shallowstep Pass for more than 2 days straight, no rest. No wonder mantid are slipping through. Even the most dedicated scouts would slip with those kinds of shifts.\n\nI want you to go out there and deliver orders to the scouts that they are to return to the battlefront immediately for rest and rations. I'll arrange for a new shift to be posted.", objectives = "Deliver return orders to Scout Wei-Chin, Scout Long, Scout Ying, and Scout Jai-Gan.", progress = "This whole battlefront is being worked to the bone. We need more men out here.", completion = "Thank you. I'll have the new scouts at their posts shortly." }
WordHunterWoW_QuestEN[30891] = { title = "Treatment for the Troops", description = "A new face! Pleasure to meet you. I'm Septi. I keep the Shado-Pan fighting.\n\nThe mantid have poison that chews through the skin and infects the blood. It makes for a slow, excruciating death when not treated.\n\nI need pollen from the violet citron flowers. The nearest place to find them is around Dampsoil Burrow just north of the battlefront. If you happen to go in that direction, could you bring some back for me?", objectives = "Collect 10 Violet Citron.", progress = "Mixed properly, the pollen from these flowers can eat away at the poison without doing any lasting damage to the body otherwise.", completion = "Marvelous. And in good condition too!\n\nThank you, kind <class>." }
WordHunterWoW_QuestEN[30892] = { title = "Back on Their Feet", description = "{name}, I could use your help. With their long shifts, our warriors down at the southern front of the battlefront are fighting to the point of exhaustion, and many of them have been exposed to the mantid poison.\n\nWe need more people to tend to the wounded. I've prepared some bandages with the herbs you brought me, but if you have some healing skills, those might work even better.\n\nPlease, {name}, get our men back on their feet so that they can get back here to safety.", objectives = "Heal 8 Injured Gao-Ran Blackguards.", progress = "With the constant mantid attacks, the men are being worked to the bone. We are undermanned on all fronts.\n\nYour help means a lot to us, <name>.", completion = "There are several warriors that owe their lives to you. You have my deepest appreciation, <class>." }
WordHunterWoW_QuestEN[30893] = { title = "The Endless Swarm", description = "Gao-ran's men need help down on the southern front. If you want to stand by the Shado-Pan, that's where you should do it.", objectives = "Kill 12 Krik'thik attackers at the Gao-Ran Battlefront.", completion = "The men of the battlefront are growing to respect you. You clearly know how to fight." }
WordHunterWoW_QuestEN[30894] = { title = "Rummaging Through the Remains", description = "I do have another task for you, {name}, though it's a might grim. I really need to get to the bottom of this mantid poison, but to do that, I need more information directly from the source.\n\nWhile you're down on the southern battlefield, could you bring me back some mantid limbs so that I can examine their intact poison glands.", objectives = "Recover 20 Krik'thik Limbs.", progress = "I'm hoping to find a permanent counter to the mantid poison so that the men won't be afflicted in the first place. It may take some time to piece it together.", completion = "These are in great condition! Thank you, <name>!\n\nYou know, I've managed to distil some of their poison into a form that we can apply readily. I've even come up with some methods for weaving it into spell-casting, if you believe it. Would you like to give some a try?" }
WordHunterWoW_QuestEN[30895] = { title = "Improvised Ammunition", description = "I've got another job for you.\n\nThe dragon cannons we depend on to keep the thicker swathes of mantid back are running low on ammo. The camp's cannoneers developed an improvised explosive that's made from the globe seeds down the western ridge.\n\nThey dispatched a couple initiates to bring some back hours ago, but have heard nothing from them. I want to send someone a bit more capable to make sure that this gets taken care of.\n\nAre you my man for this?", objectives = "Recover 16 Volatile Dread Orbs from the Ambermarsh.", progress = "Back even more quickly than expected. Did you bring the seeds?", completion = "It's good to have a <class> that I can count on." }
WordHunterWoW_QuestEN[30896] = { title = "Thieves and Troublemakers", description = "I can't catch the little buggers for the life of me.\n\nKill any you can get your hands on. And keep a close eye on your valuables, they like to steal anything that isn't tied down.", objectives = "Kill 10 Agitated Nettleskins.", progress = "I haven't hated plants so much since my job back at Halfhill.", completion = "I guess you're a bit faster than me. Well, thanks.\n\nI'll try to finish collecting some orbs and get them back to camp while there's still some face to save." }
WordHunterWoW_QuestEN[30897] = { title = "In the Wrong Hands", description = "Look... um... this is really embarrassing. I set down my sword for like ONE SECOND to gather some orbs, and a big sprite sprung out of nowhere, snatched it, and bounded off down the western gap.\n\nI can't go back to camp without it. Losing your weapon is a sure way to get kicked out of the Shado-Pan. It's sacred.\n\nPlease, can you try to find this big sprite and get my sword back? It would mean a lot to me.", objectives = "Recover Initiate Chao's Sword.", progress = "My mom warned me this was going to happen...", completion = "You... you are a lifesaver! Seriously.\n\nThank you so much!" }
WordHunterWoW_QuestEN[30898] = { title = "Cutting the Swarm", description = "The mantid numbers have been increasing since you left for the cleft. Let's put these orbs you gathered to use.\n\nGet down on the battlefront and man one of the cannons. Let none through.", objectives = "Use a Dragon Launcher to kill 50 swarming mantid.", progress = "I can't remember the last time they swarmed this thickly. They probably haven't within my lifetime.", completion = "We're not done yet..." }
WordHunterWoW_QuestEN[30899] = { title = "In Skilled Hands", description = "{name}, take these crossbow bolts and then bring them to Hawkmaster Nurong at Farwatch Overlook to the southwest.\n\nNurong is praised among all the Wukao for being a flawless shot. His efforts are credited with holding the line here for these many months. I'm hoping you can work with him and judge for yourself. He may be the final Shado-Pan we need for the hunt.", objectives = "Bring the Shado-Pan Crossbow Bolt Bundle to Hawkmaster Nurong.", progress = "Another wave of fliers approaches. Be ready.", completion = "There's a lot of movement on the other side of the chasm... something big is coming." }
WordHunterWoW_QuestEN[30900] = { title = "Terror of the Dread Wastes", description = "That thing is huge!\n\nThe Shado-Pan holding the battlefront were never trained for something like this... let's get down there and take it out ourselves.", objectives = "Defeat Norvakess, the Terror of the Dread Wastes.", completion = "You. You're coming with me.\n\nI've never seen someone handle themselves on the battlefield like that. I need a strong <class> like you with me when we face the Sha of Hatred." }
WordHunterWoW_QuestEN[30901] = { title = "Along the Southern Front", description = "I'm heading westward with Taoshi to gather the strongest I can find to confront the Sha of Hatred.\n\nI would like you to come with me.", objectives = "Ride with Taran Zhu and Taoshi to Dusklight Hollow.", completion = "Let's get this taken care of so we can get down to the bridge." }
WordHunterWoW_QuestEN[30902] = { title = "Round 4: Master Windfur", description = "Well done, challenger. You have reached the final round.\n\nYour last opponent is a powerful master of the winds. He has defended his people for many years and stood as champion on more than one occasion.\n\nFace this Master Windfur in the main arena when you are ready.\n\nAnd challenger... good luck.", objectives = "Defeat Master Windfur.", completion = "Congratulations, champion! The day is yours." }
WordHunterWoW_QuestEN[30907] = { title = "Round 4: The P.U.G.", description = "And now the final round. I have selected three challengers for you to face. This may seem unfair... to a weakling. You are not a weakling, correct?\n\nGo to the main temple, stand in the grand arena, and face these three challengers. Prove you are stronger than their combined power!\n\nGood luck, Challenger!", objectives = "Defeat Hackiss, Healiss and Tankiss.", progress = "Some find strength in numbers. I respect this idea, when it is properly executed.", completion = "Superb! What a battle!\n\nYou have proven yourself champion of this day's tournament. Well done!\n\nYou must return and put on such a show of strength in the future." }
WordHunterWoW_QuestEN[30910] = { title = "Greenstone Village", description = "Please help!\n\nWe paid some adventurers to run off all the elemental spirits and now they're back for revenge!", objectives = "Rescue all the villagers." }
WordHunterWoW_QuestEN[30918] = { title = "Hui's Vengeance", description = "I am ashamed to ask, but for Greenstone's sake... might we now trouble you to face Vengeful Hui on our behalf...?", objectives = "Defeat Vengeful Hui." }
WordHunterWoW_QuestEN[30921] = { title = "The Motives of the Mantid", description = "{class}. You may be of assistance.\n\nThe Shado-Pan wishes to know why the mantid are attacking so violently. We have our suspicions, but we cannot be sure. Furthermore, we do not want the mantid to know that we are investigating them.\n\nThat's where you come in.\n\nI need you to kill the mantid of Kri'vess, in the north. I will lurk behind you in the shadows, and search for clues on their bodies.", objectives = "Slay mantid in Kri'vess so Tai Ho can look for clues on their bodies.", completion = "The abundance of yak hair on that mantid's body suggests one thing... it came from Niuzao Temple. Our journey continues westward, <class>." }
WordHunterWoW_QuestEN[30922] = { title = "Natural Antiseptic", description = "The Shado-Pan are rare, elite, and quite expensive to train and replace. We can't afford to have any falling to a poisoned weapon or an infected cut. That's why I need you to get... something.\n\nLet me be blunt. Mushan urine is a great, natural antiseptic. They produce a large amount of it, which is lucky... because we tend to use a lot.", objectives = "Obtain 5 Full Mushan Bladders.", progress = "It's messy work, certainly.\n\nNowhere near as messy as digging graves.", completion = "Your messy work may have saved a few lives today, <race>." }
WordHunterWoW_QuestEN[30923] = { title = "Set the Mantid Back", description = "Every day, the mantid build up munitions for use on their enemies. We cannot stop them, just you and I... but we can set them back.\n\n<Tai Ho hands you some explosives.>\n\nI need to keep a low profile. Would you do the honors?", objectives = "Use Gunpowder Casks to explode the Kri'thik Weapons and the Kri'thik Supplies in Kri'vess.", progress = "The Shado-Pan are counting on you, <name>.", completion = "We are in your debt, <race>." }
WordHunterWoW_QuestEN[30924] = { title = "The Wisdom of Niuzao", description = "Niuzao, the Black Ox, rests in the temple to the west. He may know why the mantid are attacking.\n\nHe may, in fact, know much more than that.\n\nI will rendezvous with you at Niuzao Temple, {class}.", objectives = "Speak with Ogo the Younger at Niuzao Temple in the Townlong Steppes.", completion = "Your Shado-Pan associate has spoken with me. Yes, Niuzao knows why the mantid are attacking. But he is not ready to tell you.\n\nNot yet." }
WordHunterWoW_QuestEN[30925] = { title = "Niuzao's Price", description = "Niuzao owns a statuette which he values greatly: a small icon, in his image, sculpted by one of his long-since fallen sentinels. This statuette was recently stolen by the Sra'thik mantid, and taken to their encampment to our north.\n\nBring back this statuette. Then we will give you - and your Shado-Pan associate - the answers you seek.", objectives = "Kill the mantid of the Sra'thik Incursion so that Tai Ho can search their bodies for pieces of Niuzao's statuette.", progress = "Niuzao does not move quickly, nor does he make rash decisions. Perform his task, and give him time to decide.", completion = "Niuzao will be pleased.\n\nDespite his size, our patron is a beast of grace and compassion. He treasured this icon... just as he treasures each of his followers." }
WordHunterWoW_QuestEN[30926] = { title = "The Terrible Truth", description = "It is with a heavy heart that I confirm your suspicions. The mantid are indeed under the sway of the Sha of Fear.\n\nIt was OUR sworn duty to confine that creature beneath our temple. Unfortunately, our vigil faltered, our defenses buckled, and the sha escaped. It is with the mantid now.\n\nSee for yourself. The mantid burrowed into the western side of our island.", objectives = "Investigate the Niuzao Catacombs, then slay the Dread Shadow that dwells within.", completion = "Let me make this clear... that creature was NOT the Sha of Fear. Simply a shadow... a fraction of the sha's true power.\n\nNo, the Sha of Fear is with the mantid now. The elders of my order need to be informed of this immediately.\n\nI will handle the rest from here. Thank you for your assistance, <race>. Once again, your kind proves to be an asset to Pandaria." }
WordHunterWoW_QuestEN[30927] = { title = "Give Them Peace", description = "I overheard. Our secret is out, then.\n\nWhen I learned that the mantid had burrowed beneath our temple, I reacted hastily. I sent dozens of guardians to defend what they could, but they were not prepared. They succumbed to fear, and never returned.\n\nA pandaren deserves to die embracing the ground, as he does in sleep... not flat on his back with his eyes transfixed in terror. Please, {name}. Give them the peace they deserve.", objectives = "Give peace to 10 Fear-Stricken Sentinels by closing their eyes and placing them on their bellies.", progress = "I should have gone with them.", completion = "Thank you, <class>.\n\n\n\nI should have been among them." }
WordHunterWoW_QuestEN[30928] = { title = "A Trail of Fear", description = "You now know Niuzao's secret. We are not only the wardens of this temple... we were the wardens of the Sha of Fear that was buried beneath it.\n\nThe Sha itself may have escaped... but it left traces behind. If you're truly going down into the catacombs, you should eliminate those traces, before they escape and cause greater problems than those we already face.", objectives = "Kill 12 Dreadlings within the Niuzao Catacombs.", progress = "Even among our own order, only a few chosen elders knew of our sacred duty to contain the Sha of Fear.\n\nWhy they chose to tell the yak-keeper, I may never know.", completion = "We already have mantid, mogu, and yaungol to worry about. This sha problem needs to be nipped in the bud before even we are overrun." }
WordHunterWoW_QuestEN[30929] = { title = "Bad Yak", description = "Is this the place where they replace defective yaks?\n\nCan anybody help me out, here?", objectives = "Help Bluesaddle replace his defective yak.", progress = "This yak is not a good yak. Not at all.", completion = "I think we made a pretty convincing argument. They'll HAVE to replace my yak now." }
WordHunterWoW_QuestEN[30930] = { title = "Pick a Yak", description = "I can't find a single good yak here. ALL the yaks are bad!\n\nSome are too stinky, some too fight-y, others just scared.\n\nYou look like a lucky {race}. Here, take a lasso. See if you can find a good yak for me.", objectives = "Use the Yak Lasso on Wild Townlong Yaks, then fight against them to see if they are suitable for Bluesaddle.", progress = "See? I told you! No good yaks.", completion = "Well, well! A good yak!\n\nTell you what, <name>. I take this GOOD yak, and you can do whatever you want with this bad, bad one." }
WordHunterWoW_QuestEN[30931] = { title = "My Father's Crossbow", description = "I came here to visit my dad at the temple. As soon as I got here, I saw the most terrifying thing I've ever seen.\n\nIt was a mantid, walking right past me, carrying my father's crossbow.\n\nSomething's happened to my dad! We've got to find out what it is... but first, we'll need his crossbow back. I saw him heading west, behind the temple.", objectives = "Obtain Ku-Yao's Crossbow.", progress = "Did... did you find it?", completion = "Yeah, this is dad's.\n\nLet's head on over to the temple. They'll know what...\n\n<Ku-Mo's voice catches.>\n\n...what happened to him." }
WordHunterWoW_QuestEN[30932] = { title = "Father's Footsteps", description = "Yes, the boy's father - Sentinel Ku-Yao - has gone missing. He could be any number of places... we have no shortage of enemies these days.\n\nYou're free to look around, if you wish. You might start by looking for his yak, or by asking Sentinel Yalo what he knows.", objectives = "Find Father's Bedroll, Father's Shield, Ha-Cha, and Sentinel Yalo.", progress = "Any luck?", completion = "No shield, no crossbow, no yak... something bad has happened to dad." }
WordHunterWoW_QuestEN[30933] = { title = "Seeking Father", description = "I've searched everywhere... but I haven't found my father. I KNOW he's alive still. He just needs his crossbow... then he'll be OK.\n\nI've heard that you Shado-Pan guys sometimes fight the mantid on Sra'vess. I don't have any way of getting there. If you ever go over there, can you look for my dad?", objectives = "Search for Sentinel Ku-Yao.", progress = "I know he's OK.", completion = "<Ku-Mo doesn't seem to notice you.>" }
WordHunterWoW_QuestEN[30934] = { title = "Criteria Effects Test Quest", description = "Hello friend! Let's test some things, shall we?\n\nClick on the gear!\nChat with the bubble!\nHeal the Green Sparkle!\nKill the kill target!\nClick on the gearbody's corpse!\n\nThe loudspeaker should announce your progress.\n\nAfter each objective, you will explode.\n\n(Sorry about that last bit.)You will receive:", objectives = "Interact with the quest objectives and make sure their icons work." }
WordHunterWoW_QuestEN[30935] = { title = "Fisherman's Tale", description = "The villagers of Zouchin know the coast better than anyone in Kun-Lai. If the Zandalari are hiding on one of the islands, they will know.\n\nMishi will take you as far as Emperor's Path. I will go ahead to speak with the village elders.\n\nFollow the path to Whispercloud Rise. Shin Whispercloud will help you reach the village.", objectives = "Speak with Mishi to travel to the Path of Conquerors. From there find Shin Whispercloud at Whispercloud Rise.", progress = "The Zandalari are nearby, <name>. We must hurry!", completion = "The elders have agreed to help us figure out where the Zandalari have hidden the Thunder King's remains.\n\nThey have a few conditions though..." }
WordHunterWoW_QuestEN[30936] = { title = "UNUSED", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[30941] = { title = "Preparing Zouchin Village", description = "The village elders seem to think the Thunder King's remains are being kept nearby. They have also expressed some concern with our presence here. They fear this will provoke another attack on their village.\n\nWhile our priority is in getting the remains back we cannot leave the villagers defenseless. Speak with Elder Shu and Steelbender Doshu and see what can be done to help.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Assist Elder Shu and Steelbender Doshu in preparing Zouchin Village for battle." }
WordHunterWoW_QuestEN[30942] = { title = "Make A Fighter Out of Me", description = "Shhh! Don't speak so loudly! My father might hear you.\n\n<Shomi gestures to Steelbender Doshu.>\n\nMy father is delusional! He thinks I should be studying my tea pouring while our village is under attack. It's ridiculous! I have just as much courage as any man. I just don't know how to fight... yet.\n\nThat's where you come in. Let me travel with you! I'm a fast learner and I won't get in the way I promise!\n\nPleaseeeeee!\n\nIf we get separated I'll meet you back in the village.", objectives = "Kill 4 Amani Skirmishers, 4 Gurubashi Hexxers, and 3 Drakkari Frostweavers in Zouchin Province.", progress = "I'll show my father he's wrong about me!", completion = "I told you I was a fast learner! I will head back to the village to start training others. Thank you, <name>." }
WordHunterWoW_QuestEN[30943] = { title = "Handle With Care", description = "I've seen the numbers these invaders have brought with them, this will not be an easy victory. I do know of one thing that may help us gain an advantage.\n\nThere is a plant that grows around the village that can be used to make a rather effective explosive liquid. If you can gather enough I can begin brewing the mixture.\n\nThe plant you are looking for is appropriately named volatile bloom. Handle it with care, {class}.", objectives = "Bring Elder Shu 50 Volatile Blooms.", progress = "Were you able to find a suitable amount of volatile blooms?", completion = "These are perfect! Now, I would go wash your hands a few times <class>.\n\nI would also continue to avoid open flames for a few days..." }
WordHunterWoW_QuestEN[30944] = { title = "It Takes A Village", description = "The villagers have been guarding Zouchin since the first attack. They are exhausted and many are injured.\n\nIf the Zandalari attack again the last thing we need is for the defenders to fall asleep on the job.\n\nRelieve them of their posts so that they might have time to heal and see their families.\n\nYou'll find them stationed around the village.", objectives = "Relieve the Exhausted Defenders from their guard posts.", progress = "Are the villagers recovering?", completion = "Very good, <class>! With the villagers rested we may yet stand a chance against the Zandalari." }
WordHunterWoW_QuestEN[30945] = { title = "What's Yours Is Mine", description = "The elders want us to mount a defense? We're not monks, {class}; we need weapons if we hope to fight!\n\nScavenge some arms from those barbarians for me. I should be able to melt them down and make something more suitable for our villagers to fight with.\n\nBring me as many as you can carry and I'll take care of the rest. ", objectives = "Retrieve 6 Stolen Weapons from the Zandalari Invaders.", progress = "We'll need more than luck to get us through this. I hope you found something I can work with.", completion = "Well, these are better than I had anticipated! I can make four spears for every one of their blades.\n\nDon't you worry, I'll make sure the villagers are armed when the time comes." }
WordHunterWoW_QuestEN[30946] = { title = "Revelations", description = "The prisoner is being kept upstairs, {name}. It will be difficult to get information from him, but even the slightest detail about their location will help.\n\nThe elders have begun questioning him already. With their help we should be able to figure out our next move.\n\nGo speak with him and see if he has any useful information.", objectives = "Speak with the Zandalari Prisoner.", progress = "What did the prisoner have to say?", completion = "We cannot dwell on this setback, <name>. Prophet Khar'zul must be dealt with.\n\nEvery member of the Thunder King's forces we are able to destroy brings us one step closer to victory." }
WordHunterWoW_QuestEN[30952] = { title = "The Unending Siege", description = "The mantid continue to attack us. Their numbers ebb and flow, but they do not stop.\n\nIt is no matter. The yak is stamina embodied. We will not bend to them.  We will defend his home forever.\n\nWill you help us?", objectives = "Defeat 12 Sra'thik attackers at Niuzao Temple.", completion = "You fight like you are one of us." }
WordHunterWoW_QuestEN[30953] = { title = "Fallen Sentinels", description = "Our sentinels can fight for days on end, but even they have their limits. Since the mantid swarm began, too many of them have pushed themselves beyond their abilities.\n\nPlease, aid them in whatever way you can. If you are unable to heal them yourself, you may give them some of this. A mouthful of nutritious yak's milk will give them the strength they need.", objectives = "Heal 8 Wounded Niuzao Sentinels above 50% health. You may use the Yak's Milk Flasks or your own healing spells and abilities.", progress = "Things look grim out there.", completion = "In times like these, we must trust in the power and protection of Niuzao. Should things get any worse, he will protect us.\n\nHe always does." }
WordHunterWoW_QuestEN[30954] = { title = "A Blade is a Blade", description = "This is no time to hold to tradition. Our masons' calloused hands bleed and tremble. Our blacksmiths cannot forge weapons as quickly as our sentinels can break them.\n\nIt is time to fight smart.\n\nMany of the mantid come bearing weapons, and when they die, they simply leave them on the battlefield. It would be a shame to see them go to waste.", objectives = "Obtain 10 Sra'thik Weapons.", progress = "Our men are accustomed to fighting with maces and clubs. Unfortunatly, we have little time for customs.", completion = "I will see to it that these are properly distributed. What's more - I'll make sure our blacksmiths get a rest. Niuzao knows they deserve it." }
WordHunterWoW_QuestEN[30955] = { title = "Paying Tribute", description = "Our patron Niuzao is a mountain on wheels... very difficult to move, even more difficult to stop. My point: once we get him moving, the mantid will have their arms full trying to slow him down.\n\nThe easiest way to get him moving is to put food in front of him. Luckily for us, food in our temple is plentiful... even in wartime.\n\nI will send one of my strongarms with you, to shoulder the load.", objectives = "Obtain 6 stores of Niuzao Food. Your Niuzao Strongarm will carry the food for you.", progress = "Niuzao, please... it is time to join the battle...", completion = "He will get up. Soon. Maybe not today, but soon.\n\nAnd when he does...\n\n<A smile grows on Paosha's face.>" }
WordHunterWoW_QuestEN[30956] = { title = "The Siege Swells", description = "Today's mantid swarm is among the worst I've seen. We are lucky to have Niuzao join us in battle.\n\nHelp him, {class}. Return to the courtyard, and join in the defense of our temple.", objectives = "Defeat 25 Sra'thik attackers at Niuzao Temple.", completion = "Look at him, <class>.\n\nNothing can stop Niuzao. Only Niuzao can stop Niuzao." }
WordHunterWoW_QuestEN[30957] = { title = "The Overwhelming Swarm", description = "I command the sentinels of Niuzao. Every defender out there can hold his own against the mantid swarm.\n\nThe kunchong, however, are something different.\n\nThey are massive, violent, and without a question the biggest threat to my sentinels' lives. Only Niuzao stands a chance against them. Niuzao... and perhaps you.", objectives = "Defeat 4 Sra'thik Kunchong.", completion = "Put on our armor, and you'd be indistinguishable from any of the other sentinels out there.\n\nGood fighting, <race>." }
WordHunterWoW_QuestEN[30958] = { title = "In Battle's Shadow", description = "Niuzao's appearance on the battlefield is a blessing... in more ways than one.\n\nWith the distraction that he's caused, our stonemasons have seized the opportunity to build up our crumbling walls. They could use your help.\n\nToss any loose bricks you find up their way. And hurry! Niuzao will not rampage forever.", objectives = "Throw 10 Loose Stones up to Niuzao Stonemasons.", completion = "It looks like the walls are beginning to take shape again. In time, the Temple will be whole again." }
WordHunterWoW_QuestEN[30959] = { title = "The Big Guns", description = "The mantid now surround the Temple with their infernal war wagons. The sooner we are rid of those things, the better. You could destroy them with your own weapons and spells, but this will work much faster.\n\n<Ogo hands you a few small casks of hastily-packed explosives.>\n\nBeware of retaliation from mantid that remain be inside the war wagon when it explodes. In fact, I'd stay as far away from those things as possible.", objectives = "Destroy 3 Sra'thik War Wagons.", progress = "We can push these mantid back. We can outlast them.", completion = "Good, you're back in one piece.\n\nWe hope to be seeing more of you in the future, <race>." }
WordHunterWoW_QuestEN[30960] = { title = "Returning from the Pass", description = "I still have some cleanup to do here in the pass - there are some mantid still making it through. You're a valuable person to have at hand though, and I know Taran wouldn't appreciate me keeping you longer for such basic work.\n\nTaran should still be in the main camp with Gao-Ran. Report back in. I'll catch up with you a bit later.", objectives = "Report in to Taran Zhu at the Gao-Ran Battlefront.", completion = "Welcome back. I heard about the breaches in the eastern pass. It sounds like I put the right people on the job." }
WordHunterWoW_QuestEN[30961] = { title = "Savior of the Inkgill", description = "I will go now to return to my kinsmen. Please visit us back at the southwestern edge of the Mere, so that we may thank you.", objectives = "Speak with Waterspeaker Gorai at the southwestern edge of Jinyu Mere.I will go now to return to my kinsmen. Please visit us back at the southwestern edge of the Mere, so that we may thank you." }
WordHunterWoW_QuestEN[30963] = { title = "The Field Armorer", description = "The Shado-Pan fight. As such, their armor often gets cut, scratched, torn, and burned. And it's my job to repair it.\n\nI'm no armorer, but I can repair a broken piece of mail as long as the hole's not too big.\n\nI prefer to use shell fragments from the tortoises that live in the wild fields to the northeast. Get some for me, and I can keep more Shado-Pan armored and alive.", objectives = "Obtain 120 Rankbite Shell Fragments.", progress = "I refuse to let one of our kind fall just because of a broken set of armor.", completion = "Excellent. I'll get to repairing the armor tonight, once most everyone's returned." }
WordHunterWoW_QuestEN[30964] = { title = "A Proper Poultice", description = "A dry bandage doesn't do much good, other than maybe keeping bugs out of the wound. In some camps, that's the best you can hope for.\n\nNot in my camp, though.\n\nI prefer to make a paste from whatever soothing herbs I can find, and layer that between bandages. The most soothing herbs I've been able to find in the field are the Mao-Willows from the fields in the northeast. If you run into any, bring them back.", objectives = "Obtain 11 Mao-Willows.", progress = "Any luck out there, <name>?", completion = "These will do.\n\nThe Shado-Pan appreciates your work, <name>." }
WordHunterWoW_QuestEN[30965] = { title = "Herding Cats", description = "Xuen trusted me to watch kittens. I like kittens. They are small things and funny.\n\nBut I lost kittens. They are strong and many.\n\nXuen sure to say I can no longer watch kittens. I must find kittens. Will you help?\n\nTake my special cage and it will put them in a safe place.You will receive:", objectives = "Collect 8 Litters of Xuen." }
WordHunterWoW_QuestEN[30967] = { title = "Free the Dissenters", description = "Not all of my fellow villagers from Inkgill are corrupted. Many heeded my warnings and did not drink of the sha-tainted waters.\n\nThey are in hiding, terrified, and intimidated by the guards.\n\nPlease, tell them there is hope! Go into the village to the north. Speak with them and send them to me.", objectives = "Rescue 6 Inkgill Dissenters in Inkgill Mere.", completion = "Though we may not seem like much, from these inauspicious beginnings I know we will rebuild. Thank you, friend." }
WordHunterWoW_QuestEN[30968] = { title = "The Sha of Hatred", description = "The end of our hunt is upon us. We have gathered the strongest the Shado-Pan have to offer, and with your strength to aid us, we will defeat the Sha of Hatred and choke out its influence on the world.\n\nWhen we enter the tunnel, stay close, and keep hatred clear from your heart. The fight ahead will put all of us to the test.\n\nWhatever happens, it has been an honor traveling beside you, {name}.", objectives = "Defeat the Sha of Hatred.", completion = "Defeating a Sha... is not an easy thing. It is a miracle that we came out of this unscathed.\n\nTaran still blames himself for letting his hatred get the best of him and setting this beast loose upon the land. It may take some time for him to come to terms with this, but it is important that he does, lest he be vulnerable again.\n\nWe accomplished a great thing this day, a thing that will not soon be forgotten.\n\nAnd neither shall you for your hand in this.  Thank you." }
WordHunterWoW_QuestEN[30969] = { title = "A New Enemy", description = "The power of these Dark Shaman has attracted many allies, {name}. Former members of the Horde that now work towards some dark purpose.\n\nWe need to make an example of them before we have another twilight's hammer on our hands.\n\nKill any cultist you come across and bring me their insignia.", objectives = "Collect 5 Corrupted Insignia from any cultist in Ragefire Chasm.", progress = "Have you collected the insignia?", completion = "Good work, <name>. This will make it very clear how Garrosh is going to deal with failures..." }
WordHunterWoW_QuestEN[30970] = { title = "Enraged By Hatred", description = "These scorpions are infected with sha. It seems to have driven them out of their hole and into our camp, seething with hatred at invaders in their territory.\n\nWe need to clear the scorpions and secure the camp. Kill any you find.", objectives = "Kill 9 Seething Fleshrippers.", progress = "The Sha of Hatred's passing did this to them. I doubt this is the only thing that will have been affected by its passing.", completion = "Good. What's left of the camp will be a bit safer." }
WordHunterWoW_QuestEN[30971] = { title = "Taking Stock", description = "I was dispatched back to camp to gather pitch-tipped arrows for our archers at the bridge, and this is what I came to. I trained with most of these pandaren... I wasn't prepared for this.\n\nStill, the archers at the bridge need our help. If you could help gather arrows from the wreckage, then maybe we can salvage something from this horror.", objectives = "Gather 120 Shado-Pan Fire Arrows.", progress = "The pandaren at the bridge are depending on us...", completion = "I... you... er, thank you. You didn't have to help, but you did. Thank you." }
WordHunterWoW_QuestEN[30972] = { title = "Joining the Fight", description = "Lao-Chin's archers will need these arrows down at the bridge. Can you bring them?", objectives = "Bring the Quiver of Shado-Pan Fire Arrows to Lao-Chin the Iron Belly at Dusklight Bridge.", progress = "Welcome to the mess.", completion = "Taran Zhu told me what became of my camp. I would have stopped it if I could, but the attacks from the bridge have not let up.\n\nThank you for bringing these arrows - my archers will make good use of them." }
WordHunterWoW_QuestEN[30973] = { title = "Up In Flames", description = "The mantid coming across the bridge have thick carapaces that shrug off most of our attacks. They have a weakness though: fire.\n\nLao-Chen's men brought kegs to the battlefield for exactly this purpose.  Kick the kegs into groups of mantid, and Lao-Chin's archers will light them up.\n\nThey should be easy to finish off from there.", objectives = "Kill 10 Kor'thik Timberhusks with the aid of Lao-Chin's kegs.", progress = "Creative solution.  Lao-Chin impresses.", completion = "We have the added benefit that the mantid will leave with broken morale after watching their brethren burn to death.  Grim, but many lives will be spared if they simply stop pressing our lines." }
WordHunterWoW_QuestEN[30974] = { title = "Raising Spirits", description = "The kegs are full of my worst stock. Good for burning, crap for drinking.\n\nI've broken out some tankards of my best spirits and had them carried out amongst the kegs though - those are for my well-deserving men!  Spirits to raise their spirits after endless, grueling fighting.\n\nWould you be up for spreading the good cheer?", objectives = "Throw 8 Iron Belly Spirits to nearby Dusklight Skirmishers and Dusklight Rangers." }
WordHunterWoW_QuestEN[30975] = { title = "The Taking of Dusklight Bridge", description = "Let's press these insects back across the bridge and break their spirits!\n\nFollow my lead.", objectives = "Help Lao-Chin the Iron Belly hold the far side of the Dusklight Bridge.", completion = "The mantid aren't likely to return soon after a beating like that... and now Lao-Chin is free to join us in the hunt." }
WordHunterWoW_QuestEN[30976] = { title = "Joining the Hunt", description = "We are one stronger. Your help is invaluable.\n\nLet's move on westward to Rensai's Watchpost to find the last member for our party.", objectives = "Ride with Taran Zhu, Taoshi, and Lao-Chin to Rensai's Watchpost.", completion = "We are close. I can feel the unnatural hatred surging.\n\nIt's a testament to the training of the Shado-Pan that the forces here have not been consumed by its influence." }
WordHunterWoW_QuestEN[30977] = { title = "Grounded Welcome", description = "All of my men are down at Farwatch Overlook to the southwest, holding off mantid that are trying to fly across the chasm. As long as my marksmen have arrows, they'll ground any mantid that clear the chasm.\n\nIf you're here to help, I could use some more men clearing the mantid out once they're on the ground. Are you willing, {class}?", objectives = "Kill 12 grounded Kor'thik Fleetwings.", completion = "Your efforts are appreciated, <class>. Even a few more moment's breath between attacks are a relief these days." }
WordHunterWoW_QuestEN[30978] = { title = "Hostile Skies", description = "We're about to get hit hard... \n\nPick up that cannon there and lend a hand, if you would.  There will be no shortage of targets.", objectives = "Shoot down 50 Kor'thik Swarmers and Voress'thalik.", progress = "I could really use you on that cannon...", completion = "Excellent shooting!\n\nI'm pretty sure that big bug survived the fall though..." }
WordHunterWoW_QuestEN[30979] = { title = "Devastation Below", description = "Let's get down there and finish that big bug off, you and I.", objectives = "Defeat Voress'thalik with the aid of Hawkmaster Nurong.", completion = "Where have you been all my life?!  That was amazing!\n\nI'd be proud to fight beside you any day." }
WordHunterWoW_QuestEN[30980] = { title = "Heroes of the Shado-Pan", description = "You said that Taran Zhu is in Townlong and was asking for me?  Must be something important...", objectives = "Return with Hawkmaster Nurong to Taran Zhu at Rensai's Watchpost.", completion = "I like that I can always depend on you. You have the spirit of a true Shado-Pan." }
WordHunterWoW_QuestEN[30981] = { title = "Taoshi and Korvexxis", description = "Taoshi is setting up an ambush for one of the mantid leaders on the south side of Sik'vess. She is tasked with retrieving his crystal so that we can use it to open the door.\n\nTwo are stronger than one. I want you there to make sure it goes smoothly.", objectives = "Kill Korvexxis with the aid of Taoshi.", progress = "Our hunt is nearly over...", completion = "The first crystal is ours..." }
WordHunterWoW_QuestEN[30982] = { title = "Animal Control", description = "The chasm is overrun with flame hounds and lava worms, and they will be entrenched indefinitely with such a large supply of trogg flesh for food.\n\nThis infestation needs to be taken care of now, before they endanger the city. You look like you can handle yourself, <name>.\n\nI want you to clear a path through the beasts and make certain to take out the largest threats, Adjules and Magnaw.", objectives = "Kill Adarogg and Slagmaw.", completion = "Good work, <name>. Who knows what kind of destruction those beasts would have caused." }
WordHunterWoW_QuestEN[30983] = { title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Horde. That's where you come in, {name}.\n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", objectives = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth.", progress = "Yes?", completion = "It would seem that the dark shaman experiments drove Gordoth insane.\n\nHopefully we've seen the last of this, <name>." }
WordHunterWoW_QuestEN[30984] = { title = "No Orc Left Behind", description = "This was supposed to be a routine sweep, {name}. Clean up a few troggs, make sure there is no threat to the city and then be in the tavern by midday.\n\nInstead I've a group of scouts missing, flame hounds pouring out of the chasm and Xorenth going on about \"the next twilight's hammer.\"\n\n<Commander Bagran spits>\n\nGo in there and get my scouts back so we can figure out what is going on down here.", objectives = "Rescue 5 Kor'kron Scouts in Ragefire Chasm.", progress = "Have you found the scouts?", completion = "That's all that survived?\n\nI don't know who these Dark Shaman are working for, but they are going to pay for this." }
WordHunterWoW_QuestEN[30986] = { title = "Ancient Mogu Crypt", description = "Our scouting party got DESTROYED.  Help!", objectives = "Kill the possessed Shado-Pan Leader and cleanse the Pool of Life." }
WordHunterWoW_QuestEN[30987] = { title = "Joining the Alliance", description = "We have a duty, {name}.\n\nIt is our responsibility to spread the Tushui philosophy beyond the edges of the Wandering Isle... and there is no better place to start doing that than here: Stormwind City, heart of the Alliance.\n\nLet's find out who their leader is. We need allies.", objectives = "Speak with King Anduin Wrynn at Stormwind Keep.", completion = "<race>... you're here.\n\nGood." }
WordHunterWoW_QuestEN[30988] = { title = "The Alliance Way", description = "I only recently received word that some of your kind might be coming our way. I'd be glad to call you an ally, if you're willing to join our cause.\n\nWalk with me, <name>.", objectives = "Walk with King Varian Wrynn.", completion = "Before you go, <name> - I have one more thing to discuss with you." }
WordHunterWoW_QuestEN[30989] = { title = "An Old Pit Fighter", description = "I need to know if you can fight. There may come a time where you will be called upon for military matters, and I need to know that you can protect my kingdom.\n\nI've heard stories about pandaren fighting techniques, but I've never seen them in person.\n\nShall we?", objectives = "Spar with King Varian Wrynn.", completion = "You've more than proven your worth, in battle and in heart. Few would be willing to leave their homeland to join the Alliance. Fewer still would be willing to face the King of Stormwind in combat.\n\nYou, and the rest of your people, are welcome among our ranks. Welcome to the Alliance, <name>." }
WordHunterWoW_QuestEN[30990] = { title = "Open the Golden Doors", description = "Defeat the mogu crypt guardian to open the golden doors.", objectives = "Defeat the Mogu Crypt Guardian." }
WordHunterWoW_QuestEN[30991] = { title = "Do a Barrel Roll!", description = "When I trained as a Brewmaster, I didn't expect to use my knowledge like this...\n\nDid you know beer catches fire when lit? Well, with yaungol oil mixed in, it's downright explosive.\n\nI've mixed the oil in with these kegs. Roll them at the yaungol over by the gate, and ignite them when you get close. \n\nIt'll take a few seconds for the keg to blow, but when it does...\n\nWell, let's just say I wouldn't want to be over there.\n\nWhich is why I'll be over here. Mourning the loss of this brew.", objectives = "Pick up a keg near Lao-Chin, roll it downhill at the yaungol, and ignite it near them to destroy 4 Osul Treelaunchers and 50 Osul Invaders.", progress = "Wha? I was just thinking about my poor, poor beer...", completion = "Whoo, that was an explosion! Several, in fact.\n\nSad my beer had to go, but at least we're safe, for now." }
WordHunterWoW_QuestEN[30992] = { title = "Finish This!", description = "We've heard back from Suna, on the wall. Something's going on...\n\nIt looks like they are preparing for their final push. It's time to finish this, friend.", objectives = "Finish the battle for the Ox Gate.", progress = "Lin is captured... we must break Taran Zhu from his complacence!", completion = "Well, their lieutenant is dead. I think we have finally pushed them out of Kun-Lai. \n\nBut at what cost? So many dead, Lin captured... I will not allow Taran Zhu to continue to ignore his charge." }
WordHunterWoW_QuestEN[30993] = { title = "Where are My Reinforcements?", description = "This has simply gone too far. I cannot ignore our abandonment any longer.\n\nAfter all that's happened here, and all you've been through in Firebough, we must travel to the monastery.\n\nWhatever they are doing in there can wait! We can take my balloon up the mountain to the Monastery. It's anchored back by the camp, to the northeast.", objectives = "Speak with Ban Bearheart outside the Shado-Pan Monastery in Kun-Lai Summit.", progress = "Here we are, then.", completion = "Here we are, and now you know why we cannot let our brothers sit idly by." }
WordHunterWoW_QuestEN[30994] = { title = "Lao-Chin's Gambit", description = "Alright. Thanks to you, we have the wall under control. Good job. \n\nI'll stay up here for a little while and make sure no more yaungol get up onto the wall.\n\nYou, though, should go back down and see what Lao-Chin has cooked up. I hate to say it, but maybe he had a good idea after all...", objectives = "Speak with Lao-Chin the Iron Belly at Winter's Blossom in Kun-Lai Summit.", progress = "Ah, hello again. As sad as I am to have to do this, I'm glad I came up with something.", completion = "Good to see you made it back in one piece. Thanks to your help with the barrels, I've managed to brew up a good surprise for our yaungol friends at the front." }
WordHunterWoW_QuestEN[30995] = { title = "No Man Left Behind", description = "I sent recon out over an hour ago and none of them have reported back. And now these damned hounds are pouring out of the chasm.\n\nI don't know what's going on down there, but I'm not going anywhere till I get my men back.\n\nI want you to head in there and find them, {name}, preferably while they are still alive.", objectives = "Rescue 5 SI:7 Rangers in Ragefire Chasm.", progress = "Have you found all the rangers?", completion = "That's all that survived?\n\nThe Horde is going to pay for this in blood." }
WordHunterWoW_QuestEN[30996] = { title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Alliance. And I need your help stopping them, {name}. \n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", objectives = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth.", completion = "It would seem that the dark shaman experiments drove Gordoth insane.\n\nHopefully we've seen the last of this, <name>." }
WordHunterWoW_QuestEN[30997] = { title = "Animal Control", description = "I'm glad you're here, <name>. The horde is amassing an army and I'm not going to wait to find out why.\n\nWe need to strike fast and take down some of the larger beasts they have down here.\n\nI want you to head in there and take care of Adarogg and Slagmaw before the horde can use them as weapons against us.", objectives = "Kill Adarogg and Slagmaw.", completion = "Good work, <name>. Who knows what kind of destruction those beasts would have caused." }
WordHunterWoW_QuestEN[30998] = { title = "A New Enemy", description = "The horde is using dark magic to control beasts and corrupt their brethren down here, {name}.\n\nI intend to put a stop to it, but first I need to know what it is we're fighting against. That's where you come in.\n\nFight through the caverns and collect the insignia that the cultists carry. With them, I can study what type of magic is at work here.", objectives = "Collect 5 Corrupted Insignia from the Dark Shaman cultists.", progress = "Have you collected the insignia?", completion = "Good work, <name>. Now we can figure out what it is they were trying to achieve down here." }
WordHunterWoW_QuestEN[30999] = { title = "Path Less Traveled", description = "The toughest roads often have the most to teach us, {class}. I will no doubt learn a great deal from following the path of Shaohao.\n\nMany years ago Shaohao traveled to the highest peak in Kun-Lai to seek the guidance of the Jade Serpent. I too will travel to Seeker's Point in search of wisdom.\n\nPerhaps you would be interested in a journey such as this? If so speak with Uncle Cloverleaf. He will help you prepare.", objectives = "Speak to Uncle Cloverleaf in Onekeg.", completion = "Travel to Seeker's Point will require much good fortune, <class>. Hopefully you have many lucky trinkets!" }
WordHunterWoW_QuestEN[31000] = { title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you." }
WordHunterWoW_QuestEN[31001] = { title = "Falling Down", description = "It's bad enough trying to hold off the mantid, but now we've got spiders swarming up from the ruins below.\n\nOne of my best marksmen caught a blast of webbing around his leg and got pulled straight down!\n\nWe think he's alive, but I don't have the manpower to send anyone in after him. We're stretched thin up here, {class}.\n\nIf you want to help, use the rope behind me to drop down into the ruins. You're not afraid of heights are you?\n\nHow about spiders?", objectives = "Use the Shado-Pan Rope to descend into the Terrace of Gurthan and search for the fallen Shado-Pan marksman.", completion = "The fall wasn't that bad, actually. I've always had a knack for soft landings.\n\nThat I landed on a pile of spider corpses probably helped, too." }
WordHunterWoW_QuestEN[31002] = { title = "Nope", description = "We're holding, but just barely. Anything you can do to stem the tide of dreadspinners coming up the wall would be a big help.\n\nFeel like tearing open spider eggs one at a time by hand?\n\nI didn't think so. Take one of our dragon guns and light it up down there. I wanna hear those puppies pop.", objectives = "Slay 6 Dreadspinner Tenders and use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in the Terrace of Gurthan.", progress = "Hey, help me out here!", completion = "Nice work with that dragon gun. I did what I could down here, but arrows are only so useful against these things." }
WordHunterWoW_QuestEN[31003] = { title = "Psycho Mantid", description = "You aren't going to believe what I saw! Two mantid fighting each other, whipping some serious magic back and forth.\n\nOne of them didn't look like any mantid I've ever seen. Completely different color and dress to him, like some kind of... oracle or something. The other one was a total psycho, splashing sha energy around like it was a keg of Stormstout Special.\n\nLook, I gotta get back to my post, but those two are still fighting in the cave behind me and I have a feeling it's a big deal. Check it out?", objectives = "Investigate the mantid infighting at the Terrace of Gurthan.", progress = "The empress... is... misguided.", completion = "<This mantid is severely wounded. He barely manages to choke forth his words between wheezing gasps for breath.>\n\nHold, <race>...\n\nWe are... not your enemy." }
WordHunterWoW_QuestEN[31004] = { title = "Preserved in Amber", description = "Take... this...\n\n<The dying mantid struggles to outstretch his arm. In his mangled grasp rests a metal fork with two long, thin prongs and an ornately jeweled handle.>\n\nAwaken... the Wind-Reaver...\n\nIt is the only way... to end the swarm.", objectives = "Use the Klaxxi Tuning Fork on the Ancient Amber Chunk in the Terrace of Gurthan.", completion = "The Klaxxi... call to me." }
WordHunterWoW_QuestEN[31005] = { title = "Wakening Sickness", description = "You will forgive my current state. I have slept for many years.\n\nA Klaxxi'va should have been here to attend my Wakening with kypari sap... but you will have to do.\n\nI sense the buzzing of sapflies to the south. They gorge on the nourishing sap I need. Bring them to me.", objectives = "Bring 100 Sapfly Bits to Kil'ruk the Wind-Reaver in the Terrace of Gurthan.", progress = "Without nourishment, I will die where I stand.", completion = "This will do." }
WordHunterWoW_QuestEN[31006] = { title = "The Klaxxi Council", description = "I must report to the Klaxxi. They would not have woken me unless the situation were dire.\n\nYou have not been entirely useless. For that, I will spare your life.\n\nThe council may even find a use for you.", objectives = "Travel to Klaxxi'vess at the center of the Dread Wastes. You may speak with Kil'ruk the Wind-Reaver in the Terrace of Gurthan for a ride, or travel on your own.", completion = "This is a sacred meeting place for the Klaxxi.\n\nIt would be wise of you to let me do the talking." }
WordHunterWoW_QuestEN[31007] = { title = "The Dread Clutches", description = "The imperial clutches have become an abomination! Clutch-Keepers rush the development of new swarmborn, saturating them in this vile \"sha\" energy before sending them away to the wall.\n\nThe Klaxxi wish to stem the tide of swarmborn production in these dread clutches. Put the keepers to death!", objectives = "Slay 6 Shek'zeer Clutch-Keepers in the Clutches of Shek'zeer.", completion = "A few less traitors for us to feed to the kunchong when the dust settles." }
WordHunterWoW_QuestEN[31008] = { title = "Amber Arms", description = "You! Filth!\n\nYou work for me now!\n\nThe amber blades of the Shek'zeer Bladesworn are the finest weapons in the empire.\n\nIf you are not impaled upon them immediately after leaving here, bring me as many of the blades as you can carry! I want to make sure we have weapons in reserve, should we need them.", objectives = "Gather 6 Amber Blades from Shek'zeer Bladesworn around the Heart of Fear and The Clutches of Shek'zeer.\n\nSpeak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear.", progress = "The bladesworn carry their swords with pride. I want them on my weapon racks!", completion = "If all goes as planned, the Klaxxi will stop the Empress without your help. Still, it is my role to be prepared." }
WordHunterWoW_QuestEN[31009] = { title = "Dead Zone", description = "A Klaxxi'va whispers to the tower. It carries their whisper far; to other towers, to mantid, to paragons. The whisper bounces back, and the Klaxxi hear it.\n\nThis way, they see all.\n\nA tower near the palace is quiet. This will not do. It must sing for the Klaxxi.\n\nIt is my job to fix the tower, but if you serve the Klaxxi, you should serve me as well. You fix the tower, and I will wait here!", objectives = "Use the Klaxxi Resonating Crystal on the Inactive Sonic Relay at the Heart of Fear.\n\nSpeak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear." }
WordHunterWoW_QuestEN[31010] = { title = "In Her Clutch", description = "The crystal sings to the Klaxxi. They sense a paragon in the clutch, east of the tower.\n\nClutch-keepers are trying to pollute this one. The Klaxxi will not permit this.\n\nGo and find the paragon. Place your hands on his chamber, and the Klaxxi will channel their whispers through you to break him free. Protect him if you can.", objectives = "Locate and waken the mantid paragon in The Clutches of Shek'zeer.", completion = "My slumber was interrupted by sudden dreams. Unspeakable nightmares.\n\nThen I awoke.\n\nThe Klaxxi have spoken to me. I have my orders. There is much to be done." }
WordHunterWoW_QuestEN[31011] = { title = "Enemies At Our Door", description = "The Zandalari have begun their attack! You must help defend the village!\n\nIf we can't push them back, we will never find the Thunder King's remains!", objectives = "Defeat 10 Amani Beserkers, 5 Amani Behemoths, and 3 Gurubashi Bloodriders.", progress = "The village must be saved!", completion = "The Zandalari have started to retreat, <name>. This victory will mean a great deal to the villagers.\n\nIn the chaos I was able to capture one of the fighters. Perhaps we can get information from him." }
WordHunterWoW_QuestEN[31012] = { title = "Joining the Horde", description = "Here we are, {name}... Orgrimmar, heart of the Horde.\n\nWe can be helpful beyond the edges of the Wandering Isle. There are innumerable problems out there, just waiting for us to solve them. This is what Master Shang Xi would have wanted.\n\nThere's no better place to start doing that than here, with the aid of the Horde. Let's find out who their leader is. We need allies.", objectives = "Speak with Garrosh Hellscream in Orgrimmar.", completion = "<race>... you're here.\n\nGood." }
WordHunterWoW_QuestEN[31013] = { title = "The Horde Way", description = "I recently received word that some of your kind might be coming our way.\n\nI've recently been trying to bolster the strength of the Horde. A few pandaren might do us good.\n\nWalk with me, {name}.", objectives = "Walk with Garrosh Hellscream.", completion = "Ji. <name>. You're here, good.\n\nLet's keep this moving." }
WordHunterWoW_QuestEN[31014] = { title = "Hellscream's Gift", description = "I need to know if you can fight... that you can kill, and live. Eventually, each of you will be called upon for war, and I need to know that you can be counted on.\n\nI mentioned a gift earlier. It lies here, within the Ring of Valor. Step into the arena, right through this door behind me. I will test your skills.", objectives = "Complete Garrosh's test by defeating Oggax, Gadoon, and Frozengore.", completion = "You've more than proven your worth, in battle and in heart. Few would be willing to leave their homeland to join the Horde. Fewer still would be willing to face a charging magnataur in combat.\n\nYou, and the rest of your people, are welcome among our ranks. Welcome to the Horde, <name>." }
WordHunterWoW_QuestEN[31015] = { title = "Your Private Collection", description = "Pandaria is rich with history, legends, stories, and lore of every sort. While you are traveling throughout the world I would ask that you keep an eye open for artifacts and pieces of information that you feel would be pertinent to our work here.\n\nWhen you accumulate enough knowledge, we will compile it in to a volume for your personal collection here.\n\nYou can, of course, return whenever you like to review the volumes we are making for you.", objectives = "Clean off the Empty Bookshelf.", progress = "So much to learn.", completion = "Ah! Now that that is done we can start to place your collected research here. I look forward to seeing what you find." }
WordHunterWoW_QuestEN[31016] = { title = "The Lorewalkers", description = "Dear {name},\n\nWe have uncovered something tremendous in the Vale of Eternal Blossoms. A great repository of books, scrolls, and lore that has remained untouched since the days of the mogu empire.\n\nPlease, join us at your earliest convenience. You can find this Seat of Knowledge by traveling to the infamous Mogu'shan Vaults, and then flying to the landing just above the entrance.\n\nI look forward to your arrival!\n\nSincerely,\n\nLorewalker Cho", objectives = "Speak with Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms.\n\nProvided item:" }
WordHunterWoW_QuestEN[31017] = { title = "The Humble Grummle", description = "Dear $p,\n\nWe have received your research on the grummles and believe we have a solid idea of their etimology and history.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker ChoYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring The Humble Grummle to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:" }
WordHunterWoW_QuestEN[31018] = { title = "Beneath the Heart of Fear", description = "The Klaxxi have detected the existence of another paragon, Wakener.\n\nThis one was kept well-hidden from us, and for good reason.\n\nThe Empress already has possession of this one, and her adjuncts work to destroy it even now.\n\nThey are performing their sorcery in a chamber deep beneath the palace, and they must be stopped.\n\nWe hold Klaxxi'vess. You must go in our stead. Find the entrance to their chamber from the ledge to the west.", objectives = "Kill Adjunct Ek'vem, Adjunct Ikkess, Adjunct Suruz, and Adjunct Tsikzi, and then free Xaril the Poisoned Mind.", completion = "You have done your duty well, Wakener." }
WordHunterWoW_QuestEN[31019] = { title = "Amber Is Life", description = "In order for our efforts against the mantid empire to continue, we require more amber.\n\nThere is a great deposit of amber underneath the lake to the south, but the area is inhabited by a savage saurok tribe.\n\nI cannot spare anyone else. You must go to the lake and test the tribe's strength. Thin their numbers and eliminate their leader, who is probably hiding in his underground cavern.\n\nSurely this is not too great a task for you?", objectives = "Kill 7 Mistblade Rippers and the Mistblade Scale-Lord.", progress = "The amber looks familiar for some reason...", completion = "The whispers seem to be emanating from within this amber.\n\nCould there be another paragon sleeping within?" }
WordHunterWoW_QuestEN[31020] = { title = "Feeding the Beast", description = "I must join the Klaxxi Council and the other paragons immediately, but I am barely strong enough to stand.\n\nI must feed, Wakener.\n\nI sense the beating hearts of creatures on the northern bank of the lake.\n\nKill them for me, and I shall do the rest.", objectives = "Kill 8 Coldbite Crocolisks.", progress = "I have been sleeping for many thousands of years. I must regain my strength before rejoining the Council.", completion = "I feel the strength returning to my body." }
WordHunterWoW_QuestEN[31021] = { title = "Living Amber", description = "Liquid amber is most efficient for restoring a newly awakened paragon's strength, and is usually provided at a wakening ceremony.\n\nUnfortunately, it seems you did not receive these instructions, so we shall have to improvise.\n\nI can sense a vast quantity of fossilized amber in the lake below us. It will serve, but I am too weak to dig it up myself.\n\nDo this for me, and I will see to it that you are rewarded.", objectives = "Collect 8 Living Amber, then feed them to Korven the Prime.", progress = "Do you understand, Wakener? The amber gives life.", completion = "Thank you, Wakener. That is enough for now." }
WordHunterWoW_QuestEN[31022] = { title = "Kypari Zar", description = "What is that tree on the hill to the west? Can it be... Kypari Zar?\n\n<Korven the Prime lapses into silence.>\n\nWhen I returned from my final ravage, before being elevated to a paragon, I was given the honor of planting that very tree.\n\nI see it has grown into a great kypari, but... it seems something is amiss.\n\nThere is an old sonar tower at the base of the tree. Take me there, Wakener. I can use the tower to take a closer look.", objectives = "Activate the Sonar Tower, then defend Korven the Prime as he examines the tree.", progress = "What has happened to our home? Things feel amiss.", completion = "Once, great rivers of amber coursed through this tree's veins. Now, it is but a dried husk." }
WordHunterWoW_QuestEN[31023] = { title = "Relics of the Swarm", description = "This strange-looking carving is covered in a complex written language that might be mantid in origin.\n\nYou notice more relics strewn carelessly among the camps and inside the lake.\n\nPerhaps the Klaxxi would be interested in examining these artifacts.\n\nWho knows? Perhaps it will earn you some favor.", objectives = "Collect 8 Mantid Relics.", progress = "What do you have there?", completion = "These relics describe the history of Kypari Vos and the nearby amber trees.\n\nI would like to study these.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[31024] = { title = "Kunchong Treats", description = "As Kovok grows, he will require equal parts discipline and reward.\n\nI lack no shortage of discipline, but our supply of meat is almost empty.\n\nTo the south, you will find turtles roaming north of the Lake of Stars and Kypari Zar.\n\nHunt them. Kovok likes the taste of their flesh.", objectives = "Collect 4 Meaty Turtle Haunches.", progress = "What have you brought for Kovok?", completion = "Yes, a worthy feast.\n\nWell done." }
WordHunterWoW_QuestEN[31025] = { title = "Sweet Tooth", description = "We cannot summon a god without a worthy offering.\n\nI have noticed a rare flower growing among the fields to the north.\n\nThe Starshade is a potent flower whose bloom holds a powerfully sweet, intoxicating liquor.\n\nA single taste of this heady substance invigorates and strengthens the body.\n\nSurely, this god will appreciate its worth.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 50 Starshade." }
WordHunterWoW_QuestEN[31026] = { title = "The Root of the Problem", description = "Kypari Zar is dying.\n\nA creature of terrible darkness corrupts it from deep beneath its roots.\n\nThe tree cannot be saved, but at least we can lessen its pain.\n\nLook. The vile creature has carved a path to its own lair. We need only follow it down the hill, just behind this tower.", objectives = "Kill the Coldbite Matriarch.", progress = "The swarm knows not of their terrible folly! These precious trees must be protected at all costs!", completion = "Thank you, Wakener. Kypari Zar can now dream in peace.\n\nHowever, the beast was merely a vessel for the corruption.\n\nNo... the true corruption lies much deeper." }
WordHunterWoW_QuestEN[31027] = { title = "Defeat the Abomination", description = "Now that the pool of life is cleansed, the way to the crypt's interior is open.  Make your way down there and defeat the abomination.", objectives = "Defeat the Abomination of Anger." }
WordHunterWoW_QuestEN[31028] = { title = "Paragon 5", description = "The emanations are growing stronger, <class>.\n\nI feel them coming from the cave below us.\n\nI wish to study the beast that you have slain, so I will grant you the honor of awakening the next paragon.\n\nAfter all, the danger should be past.\n\nGo now, wallstrider, before I change my mind.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover the fifth paragon." }
WordHunterWoW_QuestEN[31030] = { title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", objectives = "Meet Ban Bearheart inside the Shado-Pan Monastery.", completion = "You have come. Good. This is a calamitous situation." }
WordHunterWoW_QuestEN[31031] = { title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", objectives = "Meet Ban Bearheart inside the Shado-Pan Monastery.", completion = "You have come. Good. This is a calamitous situation." }
WordHunterWoW_QuestEN[31032] = { title = "Choking the Skies", description = "Nurong wants me to pass out torches for burning the bodies.\n\nThe flying mantid are fragile, and won't last long in the hot smoke.", objectives = "Burn 10 Kor'thik Fleetwing corpses.", progress = "Some of them can make it through the smoke, but in small enough numbers that we can easily pick them off.", completion = "Your help is appreciated, stranger." }
WordHunterWoW_QuestEN[31033] = { title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Dark Shaman are poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Commander Bagran, head of the defense initiative, to end the threat to Orgrimmar once and for all.", objectives = "Speak with Commander Bagran.The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Dark Shaman are poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Commander Bagran, head of the defense initiative, to end the threat to Orgrimmar once and for all.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31034] = { title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Commander Bagran just inside Ragefire Chasm. He will have further orders for you.", objectives = "Speak with Commander Bagran.", completion = "I've been expecting your arrival, <name>." }
WordHunterWoW_QuestEN[31035] = { title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Searing Blade. <name>, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Stone Guard Kurjack just inside the Chasm. Help him in any way you can, for our fates are intertwined.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Stone Guard Kurjack.Orgrimmar's Ragefire Chasm has been taken by the Searing Blade. <name>, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Stone Guard Kurjack just inside the Chasm. Help him in any way you can, for our fates are intertwined.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31036] = { title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", objectives = "Speak with Commander Bagran.", completion = "I've been expecting your arrival, <name>." }
WordHunterWoW_QuestEN[31037] = { title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Undercity.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", objectives = "Speak with Commander Bagran.", completion = "I've been expecting your arrival, <name>." }
WordHunterWoW_QuestEN[31038] = { title = "The Challenger's Ring: Snow Blossom", description = "News of your feats has been traveling around the camp, {name}.\n\nIn fact, Snow Blossom would like to test your skill in battle.\n\nYou had best prepare yourself, {class}. She is not easily defeated.\n\nIf you can prove your worth to her, you will win a valuable friend.", objectives = "Challenge Snow Blossom and defeat her in the Challenger's Ring.", progress = "How did it go?", completion = "Ahhhh, so you bested Snow Blossom in battle, did you?\n\nShe will be stinging from that loss for a while, I'd wager.\n\nHowever, you have done well to win her to your side.\n\nShe does not warm to strangers quickly, but through time, she will prove to be a loyal and dependable companion." }
WordHunterWoW_QuestEN[31039] = { title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", objectives = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", completion = "The Shan'ze are up to something. Well done, <name>, but we must continue to monitor their actions." }
WordHunterWoW_QuestEN[31040] = { title = "Spiteful Sprites", description = "The Darkwoods sprites on Shan'ze Dao have fallen to the mogu's domination.\n\nThe once sly tricksters are now the full servants of the Shan'ze. They grow bolder each day, stealing and killing to satisfy their masters.\n\nThey must be eliminated, but be careful. They may look harmless, but they are actually quite vicious.", objectives = "Kill 30 Darkwoods Pixies or Darkwoods Charmers.", completion = "Good work, <class>. Left unchecked, the sprites would soon outnumber our entire army." }
WordHunterWoW_QuestEN[31041] = { title = "Egg Rescue!", description = "Eggs. Yes, you heard me right. I said eggs, and these aren't for eating.\n\nHave you ever seen a cloud serpent egg?\n\nThese rare eggs look like jewels, and were once worth their weight in solid gold.\n\nShan'ze Dao to the north normally teems with wild cloud serpents, but the mogu and the sprites have their eggs on lock-down.\n\nWe need to save as many of these precious eggs as we can.\n\nI'm counting on YOU, {name}.", objectives = "Collect 8 Cloudrunner Eggs.", progress = "Did you find any eggs? The serpents lay their eggs in nests on the beach, but the wood sprites are also known to steal them whenever they can.", completion = "Gently, gently!\n\nThank you for recovering these eggs safely, <name>.\n\nI know a few Serpent Riders in the Jade Forest who will take good care of these." }
WordHunterWoW_QuestEN[31042] = { title = "Onyx Hearts", description = "The Shan'ze Serpentbinders dominate the minds of wild cloud serpents, but they also create their own dark creatures from stone, metal, blood, and ancient sorcery.\n\nTheir creations, the Onyx Stormclaws, guard the island to the northwest.\n\nI wish to study the magic binding these creatures. Bring me their hearts, so that I can better understand what sorcery we are up against.", objectives = "Collect 4 Onyx Hearts.", progress = "The Onyx Stormclaws will never disobey their masters.", completion = "These will do well, <name>. Thank you." }
WordHunterWoW_QuestEN[31043] = { title = "Dark Arts", description = "It is said that Shan'ze Dao was once home to a great mogu temple.\n\nThere, the Shan'ze studied and practiced the art of subjugating the dead or inanimate.\n\nMuch of their knowledge still remains on the island to the northwest, buried among the ruins.\n\nWe need to get our hands on their knowledge - both to keep it out of their hands, and to understand the nature of their experiments.", objectives = "Collect 8 Shan'ze Tablets.", progress = "Knowledge is powerful. That is why the mogu are so dangerous.", completion = "Well done, <name>.\n\nWe'll begin deciphering the writing on these tablets at once." }
WordHunterWoW_QuestEN[31044] = { title = "Bronze Claws", description = "Among the Shan'ze's fiercest and most loyal creations are their quilen.\n\nThese beasts will hunt until they kill their prey, or die in the process.\n\nI need you to not only cull their numbers, but also to retrieve their bronze claws.\n\nTheir claws are strong and razor sharp, and we can use them to make weapons and hooks for our cause.", objectives = "Collect 20 Bronze Claws.", progress = "The quilen are fierce, but I see fierceness in your eyes as well.", completion = "These claws will come in handy.\n\nGood work, <class>." }
WordHunterWoW_QuestEN[31045] = { title = "Illusions Of The Past", description = "{class}, I need your strength to eliminate the Shan'ze Illusionists on Shan'ze Dao, to the northwest.\n\nIt wearies me to ask of you this difficult task.\n\nThe illusionists are among the strongest of the Shan'ze's elite sorcerors.\n\nThey will not be easy to defeat, but I know no {class} who is better suited to the task.", objectives = "Kill 3 Shan'ze Illusionists.", progress = "Do not be fooled by their illusions.", completion = "I knew you could do this, <name>!\n\nWith fewer Shan'ze Illusionists to stand against us, our task here will be much easier." }
WordHunterWoW_QuestEN[31046] = { title = "Little Hatchlings", description = "I have seen the cruel experiments that the Shan'ze are performing on their island to the northwest.\n\nThe Shan'ze raise baby serpents from the egg. They keep the young in tiny cages, surrounded by squalor and filth.\n\nThe cruelest gaolers starve and torture them.\n\nWe must save as many hatchlings as we can. You have my full permission to punish any mogu that gets in your way!", objectives = "Free 20 Cloudrunner Hatchlings.", completion = "Those creatures will remember you as their savior.\n\nYou have done well, <name>." }
WordHunterWoW_QuestEN[31047] = { title = "Born Free", description = "Do you know the story of the great cloud serpents of Pandaria, {name}?\n\nSomeday you must hear it. Unfortunately, there is no time to tell it now.\n\nWhat you must know is that the wild cloudrunner serpents of Townlong are in trouble.\n\nThe mogu are capturing wild serpents and corrupting their minds, bending them to their sinister will.\n\nGo to Shan'ze Dao, to the northwest. Free the adult serpents from their chains. Save them!", objectives = "Free 6 Wild Cloudrunners from their chains.", completion = "Good work, <race>. It gladdens me to see that the wild serpents are free once again." }
WordHunterWoW_QuestEN[31048] = { title = "Grave Consequences", description = "We've found ancient mogu burial urns among the ruins on Shan'ze Dao.\n\nThis is normally no problem, except these urns are home to angry mogu spirits.\n\nNot only do these urns pose a danger to anyone unlucky enough to find one, but they could be used for destruction if they were to fall into the wrong hands.\n\nWe must rid Shan'ze Dao of their presence.", objectives = "Kill 24 Shan'ze Ancestors. Shan'ze Ancestors may be found inside Mogu Burial Urns.", progress = "Did the spirits cause you any problems?", completion = "Good riddance, I say! Those mogu ghosts were long past their expiration." }
WordHunterWoW_QuestEN[31049] = { title = "In Sprite Of Everything", description = "The sprites of Shan'ze Dao have always been capricious tricksters, but now they have fallen under the mogu's influence.\n\nEven as we speak, they gather under a new leader.\n\nWe cannot allow this to happen.\n\nTheir mischievous pranks were one thing, but united, their dark magic is too powerful and too dangerous to comprehend.\n\nTake out their leader before it is too late.", objectives = "Kill the Darkwoods Faerie.", progress = "The sprites are easily manipulated, and too dangerous to ignore.", completion = "Good work, <name>.\n\nThe wood sprites may look harmless, but that's what makes them so dangerous." }
WordHunterWoW_QuestEN[31050] = { title = "Chose Fire Mage", description = "", objectives = "" }
WordHunterWoW_QuestEN[31051] = { title = "Chose Frost Mage", description = "", objectives = "" }
WordHunterWoW_QuestEN[31052] = { title = "Chose Priest", description = "", objectives = "" }
WordHunterWoW_QuestEN[31053] = { title = "Tracking Event: Started Shado-Pan Dailies", description = "", objectives = "" }
WordHunterWoW_QuestEN[31054] = { title = "Unlocked Yalia Sagewhisper", description = "", objectives = "" }
WordHunterWoW_QuestEN[31055] = { title = "Between a Saurok and a Hard Place", description = "Dear {name},\n\nWe have received your research on the saurok and believe we have pieced together clues about their past.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring Between a Saurok and a Hard Place to Lorewalker Cho.\n\nProvided item:", completion = "Before your research, I don't think pandarens ever really knew why the saurok were so vicious. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31058] = { title = "The Funky Monkey Brew", description = "Pirates! Our shores have been scoured by the most ill-tempered, ill-mannered, ill-hygienic, and ill-good hozen that ever was found in Pandaria. And to make matters worse, they claim to serve the legendary Captain Ook!\n\nWe see them every night partying and brewing punch on their island Unga Ingoo.\n\n I say we take their brew for a change! I think I can even improve their mix.\n\nGather up some friends and meet me on the southern side of Unga Ingoo. It is time for a Brew Run!", objectives = "Defeat Captain Ook.", progress = "These hozen pack some mean toys and some meaner brews.", completion = "A fine punch! A fine punch indeed! The sort of punch that punches back. Well done, <class>!" }
WordHunterWoW_QuestEN[31060] = { title = "Dawson test POI", description = "", objectives = "" }
WordHunterWoW_QuestEN[31061] = { title = "Riding the Storm", description = "Shan Bu, the leader of the Shan'ze, is performing some kind of dark ritual at the summit of the island to the northwest.\n\nWe believe that the subjugated Shan'ze Cloudrunners are powering the spell. How, we still do not know.\n\nWe believe that the Shan'ze Cloudrunners can still be saved from the corruption that taints them.\n\nTake these bronze claws. Use them to mount the back of a Shan'ze Cloudrunner.\n\nAttack them. Beat some sense back into their heads!", objectives = "Use the Bronze Claws to mount 8 Shan'ze Cloudrunners. Attack them to free them of their corruption.", progress = "How did it go?", completion = "We do not fully understand what the Shan'ze are doing, or the nature of their domination over the wild serpents.\n\nBan's theory is that the only thing that can cut through the mind control is physical pain.\n\nOnce the Shan'ze Cloudrunners feel enough pain, it looses the corruption's hold, and they finally remember who they are." }
WordHunterWoW_QuestEN[31062] = { title = "When The Dead Speak", description = "The Shan'ze's experiments are overseen by a powerful necromancer known as a Shan'ze Deathspeaker.\n\nIf we are to put an end to their operations, we must eliminate their leader.", objectives = "Kill the Shan'ze Deathspeaker.", progress = "What would possess the mogu to perform such hideous experiments?", completion = "Excellent work, <name>.\n\nI expected nothing less." }
WordHunterWoW_QuestEN[31063] = { title = "Lao-Chin and Serevex", description = "Lao-Chin is facing off against the leader just above the entrance in the tree, on the north side of Sik'vess. He is to bring back the second crystal that we need to get into the mantid tunnel.\n\nGo there and lend him your aid.", objectives = "Kill Serevex with the aid of Lao-Chin the Iron Belly.", completion = "We have the second crystal then. Good." }
WordHunterWoW_QuestEN[31064] = { title = "Nurong and Rothek", description = "Hawkmaster Nurong has gone ahead to the northwest of Sik'vess to make sure the last mantid leader cannot escape.\n\nCatch up with him and help him kill the mantid leader. Nurong will bring back the final crystal once you've aided him in this.", objectives = "Kill Rothek with the aid of Hawkmaster Nurong.", progress = "Act swiftly. I do not want the Sha of Hatred to escape our grasp again.", completion = "The final crystal is ours. We are on the doorstep of our final confrontation." }
WordHunterWoW_QuestEN[31065] = { title = "Buried Beneath", description = "Taoshi set up a spyglass on the ridge edge to show me what her scouting uncovered.\n\nGo over and take a look.", objectives = "Look through the spyglass in Rensai's Watchpost.", progress = "Go. Look.", completion = "Our tasks lay before us." }
WordHunterWoW_QuestEN[31066] = { title = "A Cry From Darkness", description = "So, you survived the imperial clutches. You are... resilient.\n\nThe Klaxxi hear another paragon to the north, among the sha-scorched roots of Kypari Vor.\n\nThis one cries out in terror and agony. It cannot be saved.\n\nThe Klaxxi want him put down. Go and defeat him or do not return here.", objectives = "Slay the corrupted paragon at Kypari Vor.", progress = "The order stands. Slay the fallen paragon.", completion = "What?! How did you...\n\nThe Deathcaller was a legendary hero. He must not have been fully wakened.\n\nYou are fortunate." }
WordHunterWoW_QuestEN[31067] = { title = "The Heavens Hum With War", description = "The mantid don't ever make my job easy, but now they've gone too far.\n\nWe can fend off the occasional attack from Kor'vess, but now... now they're starting to surround us. What's worse, they're draining the amber from our tree.\n\nThis will not stand! We need that amber! To make beer!\n\nThey've dug a burrow into the south side of the tree. I'm short-handed here. Could you take care of them for me?", objectives = "Slay Azzix K'tai.", progress = "Azzix, his name was. I think. Azzix K'tai.", completion = "We're not here to hurt anybody. We just want to make a little bit of brew out of this tree sap. Is that too much to ask?" }
WordHunterWoW_QuestEN[31068] = { title = "Sacred Recipe", description = "\"When the horror comes a-rising\nAnd the heavens hum with war\nOur great vessel of salvation\nMust be broken from its core.\"\n\nThe scroll continues on for several stanzas. Perhaps somebody at The Sunset Brewgarden will be able to decipher its cryptic message.", objectives = "Bring the Scroll of Auspice to Lya of Ten Songs at The Sunset Brewgarden.", progress = "Is that some sort of scroll?\n\nWould you mind if I took a look?", completion = "<Lya reads the entirety of the message.>\n\nThis scroll, this... this prophecy...\n\nIt's terrifying!" }
WordHunterWoW_QuestEN[31069] = { title = "Bound With Shade", description = "About that scroll you found...\n\nI keep looking at that line in the second stanza - \"bound with wood and shade\". The \"shade\", in particular, intrigues me.\n\nI must admit, I've often considered taking some of the area's residual sha essence and incorporating it into a brew. I suspect that this is the shade which our recipe calls for.\n\nYou will find large amalgamations of sha to the southeast of our tree... though you may also be able to harvest some from the local wildlife.", objectives = "Harvest 100 drops of Shade by slaying sha creatures and wildlife near The Sunset Brewgarden.", completion = "Beautiful. This will make a fine addition to our brew.\n\nThe most dangerous ingredients are quite often the most delicious." }
WordHunterWoW_QuestEN[31070] = { title = "Daggers of the Great Ones", description = "That recipe said: \"rending daggers of the great ones\"...\n\n<Olon ponders this line.>\n\nMushan! That's it!\n\nThere's plenty of mushan roaming out there with these great, big teeth... they're as long as daggers. That's gotta be what the recipe calls for.", objectives = "Obtain 3 Large Mushan Teeth.", progress = "I wonder how we'll mix those things into the brew? Can't grind them up - that'd be too gritty.\n\nMaybe I'll just soak 'em for a while.", completion = "I never thought of putting mushan teeth in a brew before.\n\nThat scroll's got some wacky ideas." }
WordHunterWoW_QuestEN[31071] = { title = "I Bring Us Great Shame", description = "I have failed my fellow brewers.\n\nI took some supplies out to the clearing, east of our tree... and I left them there. Now, with the sha corrupting the land, and the mantid on the prowl, it is too dangerous for me to bring them back.\n\nIf you would help me look for them, perhaps I could regain some of my lost honor.", objectives = "Find the Lost Keg, the Lost Mugs, and the Lost Picnic Supplies.", progress = "Did you find them? Can it be?", completion = "You have brought me joy, traveler." }
WordHunterWoW_QuestEN[31072] = { title = "Rending Daggers", description = "Forget about them, and forget their BREW. We've got real work to do.\n\nThe scroll mentions \"rending daggers of the great ones\". I've got a feeling I know where to find them.\n\nA pair of mantid lieutenants patrol the Horrid March, to the south. Each one carries a ceremonial dagger.\n\nBring those daggers back here, {name}. We may be on the brink of something big.", objectives = "Obtain the Blade of Kz'Kzik and the Blade of Ilikkax.", progress = "I think I'm starting to understand the next few lines of this prophecy, <name>.\n\nDo you have the daggers yet?", completion = "These daggers, look!\n\n<Lya holds the blades hilt-to-hilt.>\n\nThey were built to fit together! But how to join them...?" }
WordHunterWoW_QuestEN[31073] = { title = "Bound With Wood", description = "<Vu eyes the recipe.>\n\nHmm... \"bound with wood\". We don't typically brew with wood. Sap, yes... but not wood.\n\nWe have, on rare occasions, infused our drinks with corewood from the treants to the west of here. Most of them have fallen to the mantid... but their remains should suffice for our recipe.", objectives = "Obtain 8 pieces of Fragrant Corewood.", progress = "We don't brew with wood here. It gives the brew a harsh, insipid flavor, not unlike that of wine.\n\n<Vu spits.>", completion = "I'll get these pieces prepared.\n\nWe've already gathered quite a few of these ingredients! I'll have to get a pot boiling soon." }
WordHunterWoW_QuestEN[31074] = { title = "Wood and Shade", description = "\"Rending daggers of the great ones shall be bound with WOOD and SHADE.\"  Hmm.\n\nI've learned a lot about the Kor'thik mantid in my time here. I know that they maintain shrines within their settlement, Kor'vess.\n\nOne is a heartroot of the very tree that they inhabit. The other is a dark pillar, connecting them with their queen.\n\nThese shrines are the wood and shade. If my predictions are right... the daggers should react in their presence.", objectives = "Find the Mark of the Empress and the Heartroot of Kypari Kor.", completion = "<name>, look! The daggers - they've bound together, into a forked blade.\n\nWe are on the right track. I knew this wasn't a beer recipe." }
WordHunterWoW_QuestEN[31075] = { title = "Sunset Kings", description = "Olon had a clever idea. He thinks that we should visit the sprites to the west, and ask them if they have any of these ingredients. Some of the elements to this recipe are seeming... strange.\n\nThe Rikkitun sprites have a village to the west of Kor'vess. I hope to see you there, {name}.", objectives = "Meet Sapmaster Vu at Rikkitun Village.", completion = "It's been a while since I brewed on the road." }
WordHunterWoW_QuestEN[31076] = { title = "Fate of the Stormstouts", description = "Greetings, {race}. I am Chen Stormstout.\n\nI'm looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through here? Would you mind helping me ask around?", objectives = "Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts.", progress = "You are brave to have come across the wall, <race>.", completion = "<Chen listens intently.>\n\nBig Dan, Han, Evie, and Mama. I understand.\n\nIt seems like Dan will be safe here. I will go look for Evie, Han, and Mama Stormstout.\n\nTravel well, <name>, and follow the Wanderer's Way." }
WordHunterWoW_QuestEN[31077] = { title = "Evie Stormstout", description = "I was too late. She was so small... and I was too late.\n\nShe should be given a proper burial. A little warrior like her deserves better than this.", objectives = "Meet Chen Stormstout at The Sunset Brewgarden, then listen to his eulogy.", progress = "<Chen is in mourning.>", completion = "<Chen is, for the moment, silent.>" }
WordHunterWoW_QuestEN[31078] = { title = "Han Stormstout", description = "There will be time for mourning later. For now, there are other Stormstouts to be found.\n\nThey say that Han Stormstout was last seen exploring Kor'vess. I suspect he headed into that mantid burrow, just across the way.\n\nYou should meet me down there, {name}. I don't doubt that I can handle a few mantid by myself... but I'd feel better with you by my side.", objectives = "Find Han Stormstout in the Morrowchamber beneath Kor'vess.", progress = "I think I see someone over there, but I can't seem to get across these amber beams.", completion = "First Evie, now Han.\n\nI was too late again." }
WordHunterWoW_QuestEN[31079] = { title = "The Horror Comes A-Rising", description = "We are protected from the mantid. Such was the agreement made so many millennia ago.\n\nThere are forces from which we are not safe, however. The kyparites beneath the ground to the west will haunt us, chase us... even eat us. The mistlurkers eat our kind by the handful.\n\nHelp our people, outsider. Defeat our enemies.", objectives = "Slay 7 Shuffling Mistlurkers and 2 Kyparites.", progress = "We hate being eaten.", completion = "It is good to have someone of your colossal size in our village.\n\nYou have many uses." }
WordHunterWoW_QuestEN[31080] = { title = "Fiery Wings", description = "I think that old paper said something about \"fiery wings.\" Those little dragons around here have wings. They're kind of fiery, in a way.\n\nYou're quicker than me. Try catching some of those dragons... or at least slapping the powder off of them.\n\nNo point in killing a harmless little dragon, if all you want is the sparkle from their wings.", objectives = "Slap Rikkilea Flitterlings, then catch 88 flecks of Flitterling Dust.", progress = "I haven't been able to catch any of those things!", completion = "YEAH!!! FLITTERLING DUST!!!\n\n<Olon throws the powder into the pot.>\n\nThis brew is turning out... strange, and pretty smelly. I'm starting to think maybe Lya was right." }
WordHunterWoW_QuestEN[31081] = { title = "Incantations Fae and Primal", description = "I suspect we are going to need the help of these sprites.\n\nWe have two enchanted daggers, bound together with wood and shade. Now we need someone to perform ancient \"incantations\" on our artifact.\n\nBefore we ask for favors, let's show the sprites that we mean well. I heard their leader talking about a pair of mistlurkers that kidnapped several of their villagers. If we slay these fog beasts... we may get the \"incantation\" we need in return.", objectives = "Slay Ahgunoss and Mygoness.", progress = "I hope we're on the right track...", completion = "Nice work. I've heard the sprites talking about us.\n\nWe're getting their attention." }
WordHunterWoW_QuestEN[31082] = { title = "Great Vessel of Salvation", description = "I know what you and the girl-panda seek. We can perform the rite for you... in time.\n\nFirst, I require aid. The seeds fall from our great mother-tree. It is our responsibility to collect them, even in dangerous times like these.\n\nEscort my chanters to the motherseeds, that they may bring them back to the collection pit.", objectives = "Bring 3 Motherseeds to the collection pit in Rikkitun Village, with the assistance of the Rikkitun Chanters.\n\nYou can use the Rikkitun Bell to re-summon your chanters if you become separated.", progress = "The collection pit is down the hill, just to the west of here.", completion = "Yes, good. The motherseeds are taken care of.\n\nNow, we may speak of your enchantment." }
WordHunterWoW_QuestEN[31083] = { title = "Promises of Gold", description = "As soon as the creature died, a strange group of sprites appeared and took its pearl away.\n\nThe sprites have a village nearby, called Rikkitun Village. Perhaps you should investigate.", objectives = "Report to Chief Rikkitun at Rikkitun Village in Dread Wastes.", completion = "This shinyseed... it was your doing? I already had one shinyseed... but two is better.\n\nWe need only the seed, not the casing. If you like, you can keep." }
WordHunterWoW_QuestEN[31084] = { title = "Bind the Glamour", description = "It has been a very, very long time since our tribe has been called on to perform this rite. I will do the best I can.", objectives = "Allow Chief Rikkitun to enchant the Forked Blade.", progress = "...", completion = "The blade is prepared.\n\nNow, only one task remains: you must use it." }
WordHunterWoW_QuestEN[31085] = { title = "Fires and Fears of Old", description = "We've found the blades, bound them together with wood and shade, and blessed them with an ancient incantation. If I'm not mistaken, it's time to use this thing.\n\nThe sprites spoke of an ancient piece of sap within the Amber Hibernal, a mantid cave near their empress' palace. That must be the \"Blood of Ancients\" that the prophecy spoke of.\n\nWhatever's inside that sap must be important. Good luck, {name}.", objectives = "Use the Ruining Fork on Iyyokuk the Lucid, then protect him until he is able to escape.", progress = "Make sure to bring that forked blade with you.", completion = "There was a... a mantid inside that amber? I never would have thought that the solution to our war on the mantid would be... another mantid.\n\nThere are still many things that I have left to learn, but I do know this: that CERTAINLY wasn't a beer recipe." }
WordHunterWoW_QuestEN[31086] = { title = "Blood of Ancients", description = "Lya and I agree on one thing: \"Blood of Ancients\" is almost certainly the sap from the great trees of the area. I should know - I brew with the stuff all the time.\n\nThe most ancient tree of all is the one that Grand Empress Shek'zeer calls her home, now known as the Heart of Fear. Find some amber from that tree, and our brew should be complete.", objectives = "Obtain a Chunk of Solidified Amber.", progress = "Any luck?", completion = "That should do it! Recipe... complete.\n\nNow let's see how this beer tastes." }
WordHunterWoW_QuestEN[31087] = { title = "Extending Our Coverage", description = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened.\n\nThere is a tower in Amberglow Hollow that has been silent for many years. It must sing; the Klaxxi demand it!\n\nThis time I will go with you. You will help me repair it.\n\nTake the resonating crystal and meet me in Amberglow.", objectives = "Activate the Resonating Beacon in Amberglow Hollow.", progress = "Why are you just standing here?", completion = "It is good you showed up when you did.\n\nPerhaps you are not as useless as I thought...\n\nThe Klaxxi'va sing to the paragon now. Soon they will know where to send you. For now there are other tasks." }
WordHunterWoW_QuestEN[31088] = { title = "Crime and Punishment", description = "The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken.\n\nThe Klaxxi'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters.", objectives = "Kill 8 Ik'thik Harvesters on the Stinging Trail.", completion = "The Klaxxi are pleased with our work, outsider. You have proven to be more resourceful than we thought." }
WordHunterWoW_QuestEN[31089] = { title = "By the Sea, Nevermore", description = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore.\n\nThe lizard men surround him. He cannot fall into their scaly hands.\n\nYou will find him; you will awaken him. Do not return without him!\n\nIf you do this the Klaxxi will be pleased with us.", objectives = "Use the Klaxxi Tuning Fork on the Ocean-Worn Rocks to awaken the paragon.", completion = "What... what sort of creature are you?\n\nHow have you awoken me?" }
WordHunterWoW_QuestEN[31090] = { title = "Better With Age", description = "It is a crime to harvest the young trees, but a much bigger crime to waste the amber.\n\nYoung amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises!\n\nGather the young amber. We will store it until it is aged and can be consumed.", objectives = "Gather 7 Amber-Filled Jars from the Amber Collectors on the Stinging Trail.", progress = "I would go with you to gather amber, but my talents are more useful here.", completion = "Even this raw amber will be of use. We can't afford to be picky in times like these.\n\nThe Klaxxi'va will be glad I thought of this. I will tell them you helped!" }
WordHunterWoW_QuestEN[31091] = { title = "Reunited", description = "You look at me and see I am no great warrior. Why was I chosen to be a Paragon? Not all weapons can be seen, Wakener. One should not judge by appearance alone.\n\nBefore I explain further, I need to know that you are trustworthy.\n\nSomething precious to me was hidden at the time of my preservation. I am nothing without it.\n\nDefend me as I unearth my greatest weapon, and you will have my trust.", objectives = "Assist Kaz'tik the Manipulator as he unearths his greatest weapon.", completion = "Kovok is just as impressive as the last time I saw him. He will ensure great victories for the Klaxxi." }
WordHunterWoW_QuestEN[31092] = { title = "Feed or Be Eaten", description = "After years of working with the Kunchong I developed a theory; raising one from infancy would strengthen the bond and therefore strengthen the sonic connection.\n\nI had just begun training Kovok when I was chosen for encasement. He is still very young and will need diligent training to reach his full potential.\n\nI'm entrusting Kovok to you, but be warned; if any harm comes to him your life is forfeit.\n\nFirst, you must feed him to gain his trust. The turtles in the area should be suitable for this.", objectives = "Begin Kovok's training by feeding him 6 Succulent Turtle Filets found on the Brineshell Snappers in the Briny Muck.", progress = "Once the bond is formed a Kunchong will gladly give its life for you.", completion = "Very good! I had half expected Kovok to just eat you. What a pleasant surprise to see you both in one piece,\n\nPerhaps Kunchong raising is in your blood." }
WordHunterWoW_QuestEN[31093] = { title = "Hozen in the Mist", description = "Dear {name},\n\nYour research into the hozen has proven quite enlightening.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring Hozen in the Mist to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "Hozen are, by their very nature, a rambunctious lot.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31094] = { title = "Fish Tales", description = "Dear {name},\n\nI have thoroughly enjoyed reading your research in to the jinyu. A fascinating people and quite clever too.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring Fish Tails to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "This is a real treat. I always did enjoy the jinyu. Such a peaceful people with a real appreciation for wisdom.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31095] = { title = "The Dark Heart of the Mogu", description = "Dear {name},\n\nWe have always known the mogu to be dark and sinister. Your research however would imply that they are far worse.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring The Dark Heart of the Mogu to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "Mogu. Even the word makes my fur stand on end. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31096] = { title = "What is Worth Fighting For", description = "Dear {name},\n\nYou have recovered the story of our people's freedom from the mogu empire.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring What is Worth Fighting For to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "Who would have thought the freedom of the pandaren people would begin with a single punch.\n\n Wonderful. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31097] = { title = "Heart of the Mantid Swarm", description = "Dear {name},\n\nWhile we appreciate your efforts to investigate the lore of Pandaria, the documents you sent us on the mantid managed to rob me of several nights sleep. Terrifying stuff.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring Heart of the Mantid Swarm to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "When we began this research project I never thought I would learn so much about such a terrifying people.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31098] = { title = "Founding of the Order of the Cloud Serpent", description = "Dear $p,\n\nWe have a wonderful story assembled from the lore you recovered on the Order of the Cloud Serpent.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker ChoYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring Founding of the Order of the Cloud Serpent to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:" }
WordHunterWoW_QuestEN[31099] = { title = "Klaxx Attack", description = "Dear $p,\n\nWe have all been quite disturbed by your findings regarding the Klaxxi.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker ChoYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring Klaxx Attack to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:" }
WordHunterWoW_QuestEN[31100] = { title = "The Song of the Yaungol", description = "Dear {name},\n\nYour research in to the yaungol has proven most insightful.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring The Song of the Yaungol to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "The yaungol are a warring people strengthened by their exile beyond the wall. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31101] = { title = "Legends of the Brewfathers", description = "Dear $p,\n\nYour research in to the Brewfathers has proven most... thirstifying.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker ChoYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring Legends of the Brewfathers to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:" }
WordHunterWoW_QuestEN[31102] = { title = "The Seven Burdens of Shaohao", description = "Dear {name},\n\nIt would seem you have discovered the full tale of Shaohao, the last emperor of Pandaria.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring The Seven Burdens of Shaohao to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "This is a story I have long sought to uncover. Ever since the Sha was released I have felt in my belly that this tale was at the heart of it all.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31103] = { title = "The Ballad of Liu Lang", description = "Dear {name},\n\nAt long last thanks to your research we have the full Ballad of Liu Lang.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring The Ballad of Liu Lang to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "The long lost story of Lou Lang and his Wandering Isle. This is a superb addition to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[31104] = { title = "The Challenger's Ring: Yalia Sagewhisper", description = "The Shado-Pan brothers and sisters continue to whisper of your deeds, {name}.\n\nIn fact, Yalia herself has taken quite an interest in your studies.\n\nShe wishes to challenge you in the training ring.\n\nYou would do well to impress her. If you do, she just may be willing to help you in the future.", objectives = "Challenge Yalia Sagewhisper and defeat her in the Challenger's Ring.", progress = "Did you speak to Yalia?", completion = "You did it! You bested Yalia!\n\nYou have most definitely earned her favor, <race>." }
WordHunterWoW_QuestEN[31105] = { title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", objectives = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", completion = "The Shan'ze are up to something. Well done, <name>, but we must continue to monitor their actions." }
WordHunterWoW_QuestEN[31106] = { title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", objectives = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", completion = "The Shan'ze are up to something. Well done, <name>, but we must continue to monitor their actions." }
WordHunterWoW_QuestEN[31107] = { title = "Citizens of a New Empire", description = "At Shek'zeer's command, the great kypari tree of Kypari Vor was twisted into a totem of horror.\n\nLike those outside of the palace, the clutch nearby is now used to corrupt our swarmborn.\n\nRecover the eggs of the Vor'thik before they are tainted. We shall raise them here. They will be the citizens of a new empire, free from the sha.", objectives = "Gather 10 Vor'thik Eggs from Kypari Vor.", progress = "Kypari Vor was beautiful once. Rich with amber and surrounded by prime hunting grounds.", completion = "They are large. They will hatch soon.\n\nGood. We may need them." }
WordHunterWoW_QuestEN[31108] = { title = "Concentrated Fear", description = "Amber is power. It brings life.\n\nThis... dread amber you brought me has been twisted. It is concentrated fear.\n\nThe Vor'thik know this well. Their kypari has been completely engulfed by sha, and they use the dread amber to quicken their own swarmborn.\n\nBring me the crystals used by the Vor'thik fear-shapers in their rituals. The Klaxxi will study them and decide on a protocol for disposal.", objectives = "Gather 4 Dread Amber Foci from Vor'thik Fear-Shapers at Kypari Vor.", progress = "Do you have the crystals?", completion = "What would happen, I wonder, if you ate one? What would it do to your soft, pink insides?" }
WordHunterWoW_QuestEN[31109] = { title = "Culling the Swarm", description = "The Empress continues to amass her forces. Without intervention, they WILL overrun that wall - even if it means smothering it in the corpses of a million swarmborn.\n\nLet us find a better place for those corpses.\n\nLet me know when you are ready to depart for the clutches - I will gladly drop you in from above.", objectives = "Slay 40 Shek'zeer Mantid in the Clutches of Shek'zeer. Speak with Kil'ruk the Wind-Reaver for an air-drop.", progress = "We must kill faster than they can multiply. It is that simple.", completion = "This will do, for now." }
WordHunterWoW_QuestEN[31110] = { title = "Through the Portal", description = "Ah, just the {class} I wanted to see!\n\nWe've finally figured out why the portal is not working. We need more arcane powder!\n\nIt would take us months to get a shipment sent out to us, but luckily, the mogu on this island carry plenty for their own spells.\n\nThey tend to use some older stuff, so we're going to need a lot of it.", objectives = "Collect 1000 Ancient Arcane Powder.", progress = "Did you find the powders?", completion = "Excellent! Excellent!\n\nThis is just the stuff, <name>.\n\nWe'll get to work right away. I have no doubt we'll be done very soon." }
WordHunterWoW_QuestEN[31111] = { title = "Eradicating the Zan'thik", description = "The warriors of Zan'vess are some of the most feared and respected in the empire, for good reason.\n\nImpalers are unmatched in their mastery of the polearm - no doubt Malik trained among the Zan'thik in his time. Their manipulators command terrifying sonic power with the ease and subtlety of a breath.\n\nBoth will need to be dealt with.", objectives = "Kill 6 Zan'thik Impalers and 6 Zan'thik Manipulators in Zan'vess.", completion = "I will admit, Wakener, I am impressed." }
WordHunterWoW_QuestEN[31112] = { title = "They're So Thorny!", description = "The crate, once full of desperately needed supplies, has been thoroughly pillaged.\n\nA quick scan of the area shows evidence left behind by the thieves. Icy thorns, just like the ones on the water sprites on the shoreline to the east.\n\nThis is a life or death situation for your band of survivors. Those supplies need to be retrieved from these thieving pests and returned to camp.", objectives = "Collect 5 Emergency Supplies from the Water Sprites.", progress = "You manage to get your hands on them supplies, pal?", completion = "Look at that!\n\nThese supplies should keep us kickin' for a few more days.\n\nAnd my boots! Ya managed not to blow 'em up. Way ta go, <name>!" }
WordHunterWoW_QuestEN[31113] = { title = "Assault Fire Camp Gai-Cho", description = "The Yaungol are a constant nuisance, but the group at Fire Camp Gai-Cho, to the northeast, conspired with the Osul yaungol in their recent incursion into Kun-Lai.\n\nWe cannot allow such an incursion to go unpunished.\n\nGo, attack Fire Camp Gai-Cho. We need to make sure they remain occupied, so that they cannot rise up and threaten The Ox Gate again.", objectives = "Kill 16 Gai-Cho Yaungol, Earthtalkers or Pitchthrowers.", progress = "Is your raid on Gai-Cho complete?", completion = "Well - that should certainly deter any attack for a while. Good work, <name>." }
WordHunterWoW_QuestEN[31114] = { title = "Assault Deadtalker's Plateau", description = "We have always left the Deadtalkers alone. For so long, they were just responsible for maintaining the sacred burial grounds of the yaungol tribes.\n\nNow, though, they are practicing dark magic, defiling the corpses of their former clanmates... \n\nI know not where they learned those dark magics, or why they no longer treat their dead with respect, but we do not have time to find out. \n\nWe need to stop them.", objectives = "Kill 8 Deadtalker Corpsedefilers and 1 Deadtalker Crusher.", progress = "Have you defeated the Deadtalkers?", completion = "By conspiring to use these dark magics, the Deadtalkers have given up their rights to protection. Your actions should deter them from their current course, I hope." }
WordHunterWoW_QuestEN[31115] = { title = "FLAG - Freed Han", description = "", objectives = "" }
WordHunterWoW_QuestEN[31116] = { title = "Spirit Dust", description = "The spirits that the Yaungol are entrapping from the remains of their ancestors still have a bit of the essence of life within them. \n\nIf you defeat the spirits in battle, you can collect essence from the spirits as dust, and then return it to the corpses in the area, which will send the spirits, finally, to the next life.\n\nThis is the only way to set right what the Deadtalkers have done. It will also help keep us safe.", objectives = "Return 8 spirits to their remains at the Deadtalker Plateau in Townlong Steppes.", completion = "Good, you have helped right this terrible wrong." }
WordHunterWoW_QuestEN[31117] = { title = "Uruk!", description = "Uruk is the Deadtalker of the Townlong yaungol. Your mission will not be truly complete until you defeat him. Go to it!", objectives = "Kill Uruk at Deadtalker's Plateau in Townlong Steppes.", progress = "How goes the mission?", completion = "Uruk is dead! This threat has subsided, at least for today. Thank you, <name>." }
WordHunterWoW_QuestEN[31118] = { title = "The Deadtalker Cipher", description = "We need to understand what went wrong with the Deadtalkers. \n\nFor so many years, the Deadtalkers were simply responsible for maintaining the burial grounds and holding funerals for fallen warriors.\n\nFrom a recent raid, we've recovered a tablet from the grounds that is clearly written using a cipher, but it isn't one we've encountered before. If you can gather a ciphered scroll from one of the Deadtalkers, we can begin to put together the cypher and understand what's happened.", objectives = "Collect a Scroll of Spiritbinding Rites from the yaungol at Deadtalker's Plateau.", progress = "Did you find something?", completion = "Aha! Show me that.\n\nHmm... we will send this to the monastery for analysis. As we find which of these symbols are most common in their writing, we can begin to understand the meaning of these writings." }
WordHunterWoW_QuestEN[31119] = { title = "The Enemy of My Enemy... Is Still My Enemy!", description = "The mantid are our enemies. As are the yaungol at Fire Camp Gai-Cho.\n\nIt is fortunate, then, that they are also each other's enemies. Mantid from Kri'vess constantly attack the Gai-Cho yaungol, who hold them off at their front gates.\n\nI want you to wreak havoc. \"Borrow\" some highly explosive oil barrels from camp Gai-Cho, and toss them down onto the battlefield from the air.\n\nI don't care which ones you kill, just kill a lot of them.", objectives = "Use Highly Explosive Yaungol Oil Barrels to kill 100 mantid or yaungol on the Gai-Cho Battlefield.", progress = "How goes the battle?", completion = "Ha! Good work. Teaches both of them to make enemies of the Shado-Pan." }
WordHunterWoW_QuestEN[31120] = { title = "Cheng Bo!", description = "Cheng Bo is the Warbringer of Fire Camp Gai-Cho. While you've made a dent in their operations, you now have an opportunity to strike a major blow. \n\nSlay the Warbringer!", objectives = "Kill Cheng-Bo at Fire Camp Gai-Cho in Townlong Steppes.", progress = "How goes the assualt?", completion = "With Cheng Bo subdued, we can refocus our efforts on our other enemies. Your efforts earn you much respect, <name>." }
WordHunterWoW_QuestEN[31121] = { title = "Stay a While, and Listen", description = "Rush rush rush - are your people always in such a hurry?\n\nSit and have some tea with me a moment, and we will discuss your plight.\n\n<Lorewalker Cho's features settle into a patient smile.>", objectives = "Drink from Cho's Teapot.", progress = "I hope I didn't bore you, traveler.", completion = "I will help you, traveler, but first I would like to learn a little about this Horde of yours..." }
WordHunterWoW_QuestEN[31122] = { title = "Chose Prot Warrior", description = "", objectives = "" }
WordHunterWoW_QuestEN[31123] = { title = "Chose Arms Warrior", description = "", objectives = "" }
WordHunterWoW_QuestEN[31124] = { title = "Chose Brewmaster", description = "", objectives = "" }
WordHunterWoW_QuestEN[31125] = { title = "Unlocked Chao", description = "", objectives = "" }
WordHunterWoW_QuestEN[31126] = { title = "Unlocked Lao-Chen", description = "", objectives = "" }
WordHunterWoW_QuestEN[31127] = { title = "The Challenger's Ring: Chao the Voice", description = "It looks like you're quite the fighter, {name}.\n\nChao heard about it, and she's been talking about how she'd kick your...\n\nWell, let's just say I think you should challenge her and try to get her respect.", objectives = "Challenge Chao the Voice, and then defeat her in combat at Shado-Pan Garrison in Townlong Steppes.", progress = "Well? How did it go?", completion = "I'm sure there's no hard feelings. She just loves a good fight.\n\nYou should talk to her next time I have some missions for you. She's quite an able fighter, as I'm sure you saw." }
WordHunterWoW_QuestEN[31128] = { title = "The Challenger's Ring: Lao-Chin the Iron Belly", description = "Lao-Chin seems to have his head in the clouds... or, rather, in his beer.\n\nAfter all of his recent battles, he seems completely obsessed with with trying to develop the perfect brew for fighting. \n\nThat's well and good, but we need him to actually do some fighting!\n\nYou should go challenge him, see if you can snap him out of his rut. \n\nIf you beat him, he'll probably want to go out and help fight just to try to one-up you!", objectives = "Challenge Lao-Chen the Iron Belly and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", progress = "Well?", completion = "Wow, you must have impressed Lao-Chin. He can't stop talking about how excited he is to go out and fight with you. Good work." }
WordHunterWoW_QuestEN[31129] = { title = "Fate of the Stormstouts", description = "{name}! It is so great to see you healthy, and traveling so far. It would seem that our paths are quite tightly intertwined.\n\nI'm here looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through here? Would you mind helping me ask around?", objectives = "Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts.", progress = "You are brave to have come across the wall, tauren.", completion = "<Chen listens intently.>\n\nBig Dan, Han, Evie, and Mama. I understand.\n\nIt seems like Dan will be safe here. I will go look for Evie, Han, and Mama Stormstout.\n\nTake care, <name>." }
WordHunterWoW_QuestEN[31130] = { title = "A Visit with Lorewalker Cho", description = "Stranger, I may be able to help you find your prince. But first, I would like to know a little more about you and your people.\n\nCome, help me with my chores, and we will chat.\n\nYou have the look of a grizzled war veteran, but certainly you have a few minutes to help a bookish Pandaren like myself putter around the house, yes?", objectives = "Befriend Lorewalker Cho by assisting him around his house: Trim his tree, paint his wall, and feed his birds.", progress = "There is nothing like a little manual labor to bring strangers together, don't you think?", completion = "Despite your many years of combat, you've still got an eye for beauty, <name>. I like that about you!\n\nNow, let's find this missing prince of yours." }
WordHunterWoW_QuestEN[31131] = { title = "Whitepetal Lake", description = "Reports suggest that things are quiet at Whitepetal Lake today, but I've dispatched Ren Firetongue and He Softfoot to make sure it stays they way.\n\nIf you want to aid the effort further, head to the west to the lake, meet up with He, and help him keep things secure from any hostile threats.", objectives = "Speak to He Softfoot at Whitepetal Lake.", completion = "<He Softfoot smiles at you as you approach.>" }
WordHunterWoW_QuestEN[31132] = { title = "A Mile in My Shoes", description = "Oh, where have my manners gone? Technically, I suppose I am the host here.\n\nAllow me to tell you a little bit about myself and my people before asking questions of you.", objectives = "Speak to Lorewalker Cho at the Circle of Bone.", completion = "I suppose the best way to explain what a Lorewalker is all about is to show you..." }
WordHunterWoW_QuestEN[31133] = { title = "Kor'thik Aggression", description = "I'm no brewer - just looking at all those heaps of ingredients makes my head spin. Just put the brew in front of me when it's finished, thank you.\n\nNo, I'm here to make sure that the brewers don't get cut in half while they're trying to make that perfect brew. It's not an easy job.\n\nThe Kor'thik mantid across this basin have been attacking us nightly. If you're already heading over there, why don't you return the favor and attack a few of them?", objectives = "Slay 17 Kor'thik Mantid at Kor'vess.", completion = "You've got the makings of a fine brewgarden guard, <race>. Let me know if you ever get tired of the whole \"<class>\" thing." }
WordHunterWoW_QuestEN[31134] = { title = "If These Stones Could Speak", description = "This is a very ancient place, traveler.\n\nOnly recently have I pieced together a method of translating the forgotten language carved into these stones.\n\nOh, the thrill of discovery! This never gets old, I assure you.\n\nHere, you are the guest. You do the honors. I insist.\n\nUse this key to unlock the secrets the stones contain.", objectives = "Use the Stone Monoliths at the Circle of Bone.", progress = "Your assistance is most appreciated, traveler.", completion = "That is enough translating for one day, I think.\n\nThis experience has been an enlightening one, I hope." }
WordHunterWoW_QuestEN[31135] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nXi, Friend of the Small has visited us from a faraway land and will help oversee your training and adjustment to life on the surface. She's waiting for you on the small practice field across the road.", objectives = "Meet with Xi, Friend of the Small in New Tinkertown.", completion = "Why, you look great! I've heard bad things about what happens down there.\n\nWell, are you ready to start your training in the ways of the <class>?" }
WordHunterWoW_QuestEN[31136] = { title = "Behind Our Lines", description = "Scouts bring me reports of a powerful Imperion that slipped through our lines in the south and is now heading for the road in the eastern vale.\n\nI need someone I can trust to stop it. Find it and kill it quickly, {name}.", objectives = "Kill General Temuja.", completion = "Well fought. I hope to see more of you soon." }
WordHunterWoW_QuestEN[31137] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin and the other gnomes have mentioned that memory loss is pretty common for you survivors.\n\nAnyways, High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, <name>. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge." }
WordHunterWoW_QuestEN[31138] = { title = "The Arts of a Monk", description = "When you fight, you grow in skill. As you grow in skill, you will begin to figure out new moves. Go, explore, learn, and show me what you figure out.", objectives = "Reach level 3 to learn Tiger Palm. Once you've learned it, use it twice at a Training Dummy in New Tinkertown.", completion = "You picked that one up quickly. I can't wait to show you some of my other favorite tricks." }
WordHunterWoW_QuestEN[31139] = { title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", objectives = "Kill 6 Blackrock Worgs.", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, <name>, but we've got even bigger problems to deal with now." }
WordHunterWoW_QuestEN[31140] = { title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", objectives = "Kill 8 Blackrock Spies.", progress = "Kill the spies!", completion = "Excellent work, <name>. You've turned out to be quite an asset to this garrison. It's time for you to train!" }
WordHunterWoW_QuestEN[31141] = { title = "Calligraphed Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Bao, a pandaren who is visiting us from a faraway land. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Calligraphed Letter and speak to Bao in Northshire Abbey.", progress = "Ah, you got my letter, <name>... good.\nI've come from afar to teach your people the ways of the <class>.", completion = "I  have come from very far to train you in the ways of our people. Do not hesitate to come to me for training whenever you like." }
WordHunterWoW_QuestEN[31142] = { title = "Palm of the Tiger", description = "Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important.\n\nAs you get more experience, you'll be able to do new techniques you never thought of.\n\nGo, get some experience, learn a new skill, and demonstrate it on one of the training dummies.", objectives = "Reach level 3 to learn Tiger Palm, then practice using it on a Training Dummy south of the entrance to Northshire Abbey.", completion = "You're a quick learner, <name>." }
WordHunterWoW_QuestEN[31143] = { title = "Join the Battle!", description = "I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", objectives = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!" }
WordHunterWoW_QuestEN[31144] = { title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", objectives = "Kill 8 Goblin Assassins.", progress = "Kill the goblin assassins!", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs." }
WordHunterWoW_QuestEN[31145] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!" }
WordHunterWoW_QuestEN[31146] = { title = "Scribbled Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. The pandaren visitor, Ting, sent it for you. Maybe you monks can read this garbage, but I can't. You should go talk to her. She's in the Inn across the way.", objectives = "Read the Elegant Scroll and speak to Ting, Strong of Stomach in Deathknell.", progress = "Oh, yes, I sent that for you. I hope to prove that Forsaken can learn the arts of the <class> - perhaps you can help?", completion = "Yes, you can come to me to learn more about our people and our ways, especially when it comes to the arts of the <class>." }
WordHunterWoW_QuestEN[31147] = { title = "Tiger Palm", description = "As you overcome great challenges in your journey to master struggles both internal and external, you will begin to uncover new abilities hidden inside yourself. Go, now, and develop a mastery of yourself, such that you uncover the Tiger Palm technique. Then, go practice it on a training dummy.", objectives = "Reach level 3 to learn Tiger Palm, then practice using it on a Training Dummy.", completion = "Ah, it's my favorite pupil! I'm going to go ahead to Undercity and try to teach the way of the <class> to some of the Deathguards. You should meet up with me there." }
WordHunterWoW_QuestEN[31148] = { title = "Novice Elreth", description = "Actually, before I go - you should speak with Novice Elreth. She had some work for you, and you would do well to help others and improve your skills.\n\nThe next time you see me, I will be in Undercity.Upon completion of this quest you will gain:", objectives = "Speak to Novice Elreth at Deathknell in Tirisfal Glades.Actually, before I go - you should speak with Novice Elreth. She had some work for you, and you would do well to help others and improve your skills.\n\nThe next time you see me, I will be in Undercity.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[31150] = { title = "Elegant Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from our visitor from afar, Lo. Take a gander at it and go find him inside Anvilmar.", objectives = "Read the Elegant Rune and speak to Lo in Coldridge Valley.", progress = "I like it here, <name>. Your people have quite an appreciation for the finer things!", completion = "Well, it is good to see you. I must say, as much as you learn from me, I think I will learn from your people. Your brews are quite different than mine!" }
WordHunterWoW_QuestEN[31151] = { title = "Kick, Punch, It's All in the Mind", description = "The truth is, you already have the talent and ability to learn what you need to. What I can help you do is show you where to unlock it.\n\nFirst, you must practice until you begin to understand a new technique. The first technique you learn will be the Tiger Palm. Go, learn more until you have unlocked the potential within yourself, and then practice your new move!\n\nRemember - it's all in the mind!", objectives = "Reach level 3 to learn Tiger Palm, then use it on one of the Training Dummies outside the entrance to Anvilmar.", completion = "Ahh, good work. You may return any time you need another lesson from teacher." }
WordHunterWoW_QuestEN[31152] = { title = "Peering Into the Past", description = "Just a moment, now. Allow me to gather my things.\n\nWouldn't want me to lose these notes now, would we? Especially after you risked life and limb for them!\n\nThere, all set. Let us be off, shall we?\n\nI must say, I feel much safer traveling with you after seeing how you handled that saurok!", objectives = "Speak to Lorewalker Cho at the Circle of Stone.", completion = "I am most grateful for the knowledge my forebears have passed on to me.\n\nI stand upon their shoulders." }
WordHunterWoW_QuestEN[31153] = { title = "Tracking Event - Saved Diaani", description = "", objectives = "" }
WordHunterWoW_QuestEN[31154] = { title = "Tracking Event - Saved Zuulo", description = "", objectives = "" }
WordHunterWoW_QuestEN[31155] = { title = "Tracking Event - Saved Arekk", description = "", objectives = "" }
WordHunterWoW_QuestEN[31156] = { title = "Calligraphed Parchment", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from our Pandaren friend, Gato. He visits from afar to grant us the honor of his wisdom, and to teach the ways of the monk. Do not shame your people by failing at his lessons!", objectives = "Read the Calligraphed Parchment and speak with Gato in the Valley of Trials.", progress = "Ahh, you have come.", completion = "We will honor our respective peoples by learning from each other. You will become a great <class>, if I have anything to say about it. And I will learn the ways of your people." }
WordHunterWoW_QuestEN[31157] = { title = "Tiger Palm", description = "As you walk the road of your training, you will begin to discover within yourself the power to unlock new techniques. You need not even learn them from me, or another more experienced monk - you will find that they come to you on their own.\n\nFor now, you should go and practice the basics. Gather more experience, and develop a new technique - once you have, you can practice it on the dummies nearby to master it.", objectives = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy and practice using Tiger Palm 2 times.", completion = "Good, good. Your first challenge surpassed. We will learn much from each other, I can see." }
WordHunterWoW_QuestEN[31158] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", objectives = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya punches - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go." }
WordHunterWoW_QuestEN[31159] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zabrax to the east.", objectives = "Meet with Zabrax in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually look ta be in shape though. Steady hands. Fierce eyes. I may be able ta turn ya into a real <class>.\n\nLets not waste anymore time 'den." }
WordHunterWoW_QuestEN[31160] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese." }
WordHunterWoW_QuestEN[31161] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day." }
WordHunterWoW_QuestEN[31162] = { title = "The Arts of a Monk", description = "As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do.\n\nWanna see? Go, train up some, and learn someting new.\n\n'Den come back and ya can show me.", objectives = "Reach level 3 to learn Tiger Palm. Practice using Tiger Palm against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya." }
WordHunterWoW_QuestEN[31163] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear." }
WordHunterWoW_QuestEN[31165] = { title = "Calligraphed Note", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by our Pandaren visitor, Shoyu. You should read it.", objectives = "Read the Calligraphed Note and speak to Shoyu in Camp Narache.", progress = "Ah, I am pleased to meet you.", completion = "I am honored that Chief Hawkwind would allow me to train you and grant you your rite of passage. While I am a master in the ways of the <class>, I am but a child in the ways of your people." }
WordHunterWoW_QuestEN[31166] = { title = "Tiger Palm", description = "You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before.\n\nYour first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.", objectives = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy in Camp Narache and practice using it.", completion = "You have done well, <name>." }
